-- Migration: Add 2019 summer batch 3 (Sharon's Q26-Q45 minus gaps)
--
-- Source: Batch B.docx. 18 JSON blocks parsed (markers 26-43 and 45;
-- markers 29 + 44 missing from Sharon's output).
--
-- Three of these — Q26, Q27, Q28 — are already in DB from the
-- batch-2 migration (commit 2961a64). The DO $$ blocks here carry
-- the same `IF v_existing_id IS NOT NULL THEN RAISE NOTICE … RETURN`
-- guard, so those three will skip with a notice; only Q30-Q43 and
-- Q45 are net-new inserts (≈15 questions).
--
-- Auto-fixes applied where needed (counts in batch3_report.json):
--   * PENDING external_id → 2019-S-Q{marker}
--   * source_metadata filled / exam_question_number set from marker
--   * display_analysis typo dropped (Q39 source choices ב,ד);
--     display_order derived from letter map when missing
--   * Hebrew-abbrev quote escape applied BEFORE the control-char
--     cleaner (corrected order; the prior batch-2 order broke on
--     Q35 because an unescaped `ע"פ` quote desynced the cleaner)
--
-- Subtopic overrides (needs_review=true):
--   * Q34 ('עבירות קנס' → criminal_appeal)
--   * Q37 + Q38 ('חוקי יסוד' → bgz_jurisdiction_revocation)

-- ============================================================
-- Q26 — 2019-S-Q26 — chapter=criminal_proc subtopic=publication_ban
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q26';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q26 skipped: external_id % already exists', '2019-S-Q26';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'publication_ban';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'publication_ban';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q26', 'e4a16014-22c7-4653-bf0d-89ff4bb34c20', v_subtopic_id,
    'בית משפט השלום בתל אביב ציווה, לבקשת חשוד שאינו עצור ושטרם הוגש נגדו כתב אישום, על איסור פרסום שמו לאחר שנוכח שהדבר עלול לגרום לחשוד נזק חמור ולאחר שמצא שבנסיבות העניין יש להעדיף את מניעת הנזק על פני העניין הציבורי שבפרסום. נורית, כתבת חדשות כאן 11, מבקשת לתקוף את ההחלטה ולהגיש בקשה לביטול צו איסור הפרסום. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 26}'::jsonb,
    'השאלה עוסקת בסמכות לדון בבקשה לביטול צו איסור פרסום, ובפרט בערכאה ובסוג ההרכב שידון בבקשה. היא מתייחסת להוראות סעיף 70ג(א) לחוק בתי המשפט, המהווה חריג לעקרון פומביות הדיון, ומאפשר לכל מי שמעוניין בביטול הצו, לרבות כלי תקשורת, לפנות לבית המשפט שנתן את הצו.',
    'סעיף 70ג(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע במפורש כי "ציווה בית המשפט על איסור פרסום לפי סעיף 70(ד), (ה) או (ה1), רשאי מי שמעוניין בביטול האיסור, לרבות כלי תקשורת, להגיש לבית המשפט שנתן את הצו בקשה לביטולו; בקשת הביטול תידון לפני דן יחיד" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 70ג). הוראה זו מבטיחה כי בקשות לביטול צווי איסור פרסום יידונו באופן יעיל ומהיר על ידי הערכאה המקורית שנתנה את הצו, ובפני שופט יחיד, כדי למנוע סחבת ולהקל על הגישה לערכאות. היא משקפת את האיזון בין עקרון פומביות הדיון לבין הצורך להגן על זכויות הפרט, תוך מתן אפשרות לבחון מחדש את הצו לאור נסיבות משתנות (Verdict: פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020), Reference 5).',
    'הסטודנט עלול לטעות ולחשוב שבקשה לביטול צו איסור פרסום תוגש לערכאת ערעור (כמו בית המשפט המחוזי) או תידון בפני הרכב שופטים, במקום לבית המשפט שנתן את הצו ובפני דן יחיד.',
    '["צו איסור פרסום", "ביטול צו איסור פרסום", "פומביות הדיון", "דן יחיד", "כלי תקשורת", "סעיף 70ג לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — ערכאה מוסמכת:** לאיזה בית משפט תוגש בקשה לביטול צו איסור פרסום? ← לבית המשפט שנתן את הצו (סעיף 70ג(א) לחוק בתי המשפט). **וריאציה 2 — הרכב שיפוטי:** בפני מי תידון בקשה לביטול צו איסור פרסום? ← בפני דן יחיד (סעיף 70ג(א) לחוק בתי המשפט). **וריאציה 3 — מי רשאי להגיש בקשה:** מי רשאי להגיש בקשה לביטול צו איסור פרסום? ← מי שמעוניין בביטול האיסור, לרבות כלי תקשורת (סעיף 70ג(א) לחוק בתי המשפט).',
    'בקשה לביטול צו איסור פרסום תוגש לבית המשפט שנתן את הצו ותידון בפני דן יחיד (סעיף 70ג(א) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 70ג", "פ\"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020)", "ת\"פ (שלום אשקלון) 55402-12-25 רועי ינובסקי כאן 11 נ'' מדינת ישראל (29.1.2026)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בנסיבות המתוארות את הבקשה לביטול איסור פרסום עליה להגיש לבית המשפט המחוזי שבאזור שיפוטו נמצא בית המשפט שנתן את הצו. הבקשה תידון בפני שלושה שופטים.', false, 'בחירה זו שגויה. בקשה לביטול צו איסור פרסום תוגש לבית המשפט שנתן את הצו, והיא תידון בפני דן יחיד, ולא בפני הרכב של שלושה שופטים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בנסיבות המתוארות את הבקשה לביטול איסור פרסום עליה להגיש לבית המשפט המחוזי שבאזור שיפוטו נמצא בית המשפט שנתן את הצו. הבקשה תידון בפני דן יחיד.', false, 'בחירה זו שגויה. בקשה לביטול צו איסור פרסום תוגש לבית המשפט שנתן את הצו, ולא לבית המשפט המחוזי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בנסיבות המתוארות את הבקשה לביטול איסור פרסום עליה להגיש לבית המשפט שנתן את הצו. הבקשה תידון בפני שלושה שופטים.', false, 'בחירה זו שגויה. אף שהבקשה תוגש לבית המשפט שנתן את הצו, היא תידון בפני דן יחיד, ולא בפני הרכב של שלושה שופטים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בנסיבות המתוארות את הבקשה לביטול איסור פרסום עליה להגיש לבית המשפט שנתן את הצו. הבקשה תידון בפני דן יחיד.', true, 'בחירה זו נכונה. סעיף 70ג(א) לחוק בתי המשפט קובע כי בקשה לביטול צו איסור פרסום תוגש לבית המשפט שנתן את הצו ותידון בפני דן יחיד.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'שינוי נסיבות לביטול צו איסור פרסום', 1, 'צו איסור פרסום על שמו של חשוד ניתן לפני מספר חודשים. כעת, הפרקליטות הודיעה על כוונתה להגיש כתב אישום נגד החשוד בכפוף לשימוע. האם החלטה זו מהווה ''נסיבות חדשות'' המצדיקות עיון חוזר בצו איסור הפרסום?',
    'שאלה זו עוסקת במושג ''נסיבות חדשות'' בהקשר של בקשה לביטול צו איסור פרסום, כפי שמופיע בסעיף 70ג(ב) לחוק בתי המשפט. היא בוחנת האם החלטת הפרקליטות להגיש כתב אישום בכפוף לשימוע נחשבת לשינוי נסיבות המצדיק עיון מחודש בצו איסור הפרסום.',
    'סעיף 70ג(ב) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "היה מבקש הביטול כאמור בסעיף קטן (א) צד לבקשה לאיסור הפרסום, עליו להראות נסיבות חדשות המצדיקות את בקשת הביטול; לעניין זה, ''נסיבות חדשות'' – לרבות הזמן שחלף ממועד מתן צו איסור הפרסום" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 70ג). הפסיקה קבעה כי החלטה על הגשת כתב אישום בכפוף לשימוע מהווה ''נסיבות חדשות'' המצדיקות עיון חוזר בצו איסור הפרסום (Verdict: פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020), Reference 5, 6, 7, 9, 10). הרציונל הוא שהחלטה כזו משמעותה שהתביעה הכללית שקלה היטב את חומרי החקירה והגיעה למסקנה כי אלו מבססים יסוד סביר להרשעה, מה שמחזק את האינטרס הציבורי בפרסום ומטה את נקודת האיזון לעבר פומביות הדיון (Verdict: פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020), Reference 9, 10).',
    'הסטודנט עלול לטעות ולחשוב שרק הגשת כתב אישום בפועל מהווה שינוי נסיבות, ולא להבין שהחלטה על הגשת כתב אישום בכפוף לשימוע כבר משנה את נקודת האיזון.',
    '["צו איסור פרסום", "נסיבות חדשות", "שימוע", "הגשת כתב אישום", "פומביות הדיון", "סעיף 70ג לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — הגשת כתב אישום בכפוף לשימוע:** האם החלטה על הגשת כתב אישום בכפוף לשימוע נחשבת ''נסיבות חדשות'' לביטול צו איסור פרסום? ← כן (פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני, רפרנס 5, 6, 7, 9, 10). **וריאציה 2 — רציונל השינוי:** מדוע החלטה כזו מהווה שינוי נסיבות? ← היא משקפת הערכה ראייתית מבוססת יותר ומטה את נקודת האיזון לעבר פומביות הדיון (פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני, רפרנס 9, 10). **וריאציה 3 — סמכות לדון בביטול:** מי דן בבקשה לביטול צו איסור פרסום? ← בית המשפט שנתן את הצו, בפני דן יחיד (סעיף 70ג(א) לחוק בתי המשפט).',
    'החלטה על הגשת כתב אישום בכפוף לשימוע ← ''נסיבות חדשות'' המצדיקות עיון חוזר בצו איסור פרסום (סעיף 70ג(ב) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 70ג", "פ\"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'נטל ההוכחה ל"נזק חמור" באיסור פרסום', 2, 'חשוד מבקש מבית המשפט לאסור את פרסום שמו, בטענה שהדבר יגרום לו נזק חמור. מהו נטל ההוכחה המוטל על החשוד להוכחת קיומו של ''נזק חמור''?',
    'שאלה זו מתמקדת בנטל ההוכחה הכבד המוטל על חשוד המבקש צו איסור פרסום על שמו, ובפרט בהגדרת המונח ''נזק חמור'' כפי שפורש בפסיקה. הבנת רף זה חיונית להבנת החריג לעקרון פומביות הדיון.',
    'סעיף 70(ה1)(1) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע שני תנאים מצטברים לאיסור פרסום שמו של חשוד: האחד, שהדבר עלול לגרום לחשוד ''נזק חמור'', והשני, שבית המשפט סבר כי יש להעדיף את מניעת הנזק על פני העניין הציבורי שבפרסום (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 70). הפסיקה קבעה כי נטל ההוכחה ל''נזק חמור'' הוא משמעותי וכבד. על החשוד להראות כי עלול להיגרם לו, במידה קרובה של ודאות, נזק המתאפיין בחומרה מיוחדת, יוצאת מגדר הרגיל, החורג בחומרתו מהפגיעה הטבעית העלולה להיגרם לכל אדם בעקבות פתיחת חקירה פלילית נגדו (Verdict: מ"י (שלום פתח תקוה) 53541-09-16 עיתון ״כלכליסט״ נ'' פלוני (7.11.2016), Reference 1, 2; Verdict: מ"י (שלום ת"א) 11090-03-20 הלל בבייב נ'' מדינת ישראל (7.3.2020), Reference 11, 12; Verdict: מ"י (שלום ת"א) 13028-08-18 אילנית יהב בלילה נ'' מדינת ישראל (17.3.2019), Reference 14, 15). נזק זה יכול לכלול פגיעה בעיסוקו של החשוד שעיקר עיסוקו כרוך במגע עם אנשים, או שיקולים רלוונטיים למצבו המשפחתי (Verdict: מ"י (שלום פתח תקוה) 53541-09-16 עיתון ״כלכליסט״ נ'' פלוני (7.11.2016), Reference 2).',
    'הסטודנט עלול לטעות ולחשוב שכל פגיעה בשם הטוב או בפרנסה כתוצאה מחקירה פלילית עונה על הגדרת ''נזק חמור'', מבלי להבין את הרף הגבוה שנקבע בפסיקה.',
    '["צו איסור פרסום", "נזק חמור", "נטל הוכחה", "פומביות הדיון", "חריג לכלל", "סעיף 70(ה1)(1) לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — הגדרת ''נזק חמור'':** מהו ''נזק חמור'' המצדיק איסור פרסום? ← נזק בחומרה מיוחדת, החורג מהפגיעה הטבעית של הליך פלילי (רע"פ 7276/13 פינטו, רפרנס 8, 11, 12, 17, 20, 31, 39, 40, 41, 50, 52, 53, 54, 55, 60, 65). **וריאציה 2 — נטל ההוכחה:** מי נושא בנטל להוכחת ''נזק חמור''? ← החשוד, וזהו נטל כבד ומשמעותי (מ"י (שלום פתח תקוה) 53541-09-16 עיתון ״כלכליסט״ נ'' פלוני, רפרנס 1, 2). **וריאציה 3 — שיקולים לבחינת נזק חמור:** אילו שיקולים נבחנים בקביעת ''נזק חמור''? ← נסיבות אישיות ומשפחתיות, אופי עיסוקו של החשוד, עברו הפלילי ומשקל הראיות (בש"ע (שלום ראשל"צ) 34135-09-17 יהלום נ'' ניזאר אעלימי, רפרנס 17).',
    'להוכחת ''נזק חמור'' לאיסור פרסום, על החשוד להראות נזק חריג וקונקרטי, במידה קרובה של ודאות, החורג מהנזק הרגיל של הליך פלילי (רע"פ 7276/13 פינטו).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 70", "מ\"י (שלום פתח תקוה) 53541-09-16 עיתון ״כלכליסט״ נ'' פלוני (7.11.2016)", "מ\"י (שלום ת\"א) 11090-03-20 הלל בבייב נ'' מדינת ישראל (7.3.2020)", "מ\"י (שלום ת\"א) 13028-08-18 אילנית יהב בלילה נ'' מדינת ישראל (17.3.2019)", "בש\"ע (שלום ראשל\"צ) 34135-09-17 יהלום - היחידה הארצית לחקירות ומאבק בפשיעה נ'' ניזאר אעלימי (3.10.2017)", "מ\"י (שלום ת\"א) 33630-10-16 מדינת ישראל נ'' דוד מירזה (18.11.2016)", "בש\"ע (שלום י-ם) 31437-07-21 פלונית נ'' מדינת ישראל רשות המיסים (5.8.2021)", "ת\"פ (שלום אשקלון) 55402-12-25 רועי ינובסקי כאן 11 נ'' מדינת ישראל (29.1.2026)", "מ\"י (שלום חדרה) 39017-03-24 תחנת משטרה - זכרון נ'' אוליה קולטין (20.3.2024)", "ת\"פ (שלום כ\"ס) 10507-03-10 ערן מאיוסט נ'' מדינת ישראל (26.5.2022)", "א\"פ (שלום ראשון לציון) 2439-08-20 פלונית נ'' יאח\"ס, להב 433 (6.8.2020)", "ת\"פ (שלום ק\"ג) 4508-08-23 מדינת ישראל נ'' יאיר וקראט (23.4.2026)", "מ\"י (שלום ת\"א) 65385-09-16 חיים טולדנו נ'' מדינת ישראל (29.9.2016)", "ת\"פ (שלום ק\"ש) 3803-01-14 מדינת ישראל נ'' תמיר יואל (2.1.2017)", "ת\"פ (שלום נצרת) 48570-10-23 מדינת ישראל נ'' דני קריבוש (7.12.2025)", "מ\"ת (שלום י-ם) 13159-01-22 מדינת ישראל נ'' פלוני (8.5.2022)", "בש\"ע (שלום חד'') 50388-08-17 מע\"מ חדרה נ'' פהמי אבו מוח x (26.9.2017)", "ת\"פ (שלום קריות) 18951-12-19 ידיעות תקשורת בע\"מ נ'' שמואל שמש (18.4.2021)", "ת\"פ (שלום ת\"א) 20482-05-17 פלוני נ'' מדינת ישראל (10.4.2020)", "ת\"א (שלום ראשון לציון) 10295-07-19 פלוני נ'' אלה לוי וינריב (7.1.2022)", "ת\"א (שלום נת'') 12612-01-20 ניר חפץ נ'' יאיר נתניהו (5.2.2025)", "מ\"י (שלום ראשל\"צ) 39883-01-19 עופר זלצמן נ'' מדינת ישראל - יאל\"כ להב 433 (20.10.2019)", "צ\"א (שלום ראשון לציון) 10689-11-17 מדינת ישראל נ'' עודד מיליניאק (12.4.2018)", "מ\"י (שלום ראשל\"צ) 31364-01-14 מדינת ישראל נ'' פלוני (15.1.2014)", "ת\"א (שלום ת\"א) 19700-08-12 אברהם עמית נ'' וואלה תקשורת בע\"מ (1.9.2015)", "ת\"פ (שלום חי'') 39077-08-15 ילנה קיריצ''יק נ'' מדינת ישראל (25.5.2025)", "ת\"פ (שלום ת\"א) 51391-07-25 מדינת ישראל נ'' ניר שמשון ירון (12.1.2026)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'איסור פרסום לאחר הגשת כתב אישום', 3, 'נאשם, שנגדו הוגש כתב אישום, מבקש מבית המשפט לאסור את פרסום שמו. מהם התנאים שבית המשפט יבחן בבקשה זו?',
    'שאלה זו בוחנת את ההבחנה בין העילות לאיסור פרסום שמו של חשוד (לפני הגשת כתב אישום) לבין העילות לאיסור פרסום שמו של נאשם (לאחר הגשת כתב אישום). היא מדגישה את שינוי נקודת האיזון עם התקדמות ההליך הפלילי.',
    'הכלל בדבר פומביות הדיון הוא עקרון יסוד במשפט הישראלי, המעוגן בסעיף 3 לחוק יסוד: השפיטה ובסעיף 68(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984 (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 70). עם זאת, קיימים חריגים לכלל זה. כאשר מדובר בבקשה לאיסור פרסום שמו של חשוד שטרם הוגש נגדו כתב אישום, חל סעיף 70(ה1)(1) לחוק בתי המשפט, הדורש הוכחת ''נזק חמור'' והעדפת מניעת הנזק על פני העניין הציבורי (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 70). לעומת זאת, לאחר הגשת כתב אישום, נקודת האיזון משתנה באופן מובהק לעבר פרסום, והכלל הוא פרסום שמו של הנאשם (Verdict: פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020), Reference 9). העילות לאיסור פרסום בשלב זה מצומצמות יותר וקבועות בסעיף 70(ד) לחוק בתי המשפט, המאפשר איסור פרסום לשם הגנה על ביטחונו של בעל דין, עד או אדם אחר, או לשם מניעת פגיעה חמורה בפרטיות של אחד מהם (Law: חוק בתי המשפ [נוסח משולב], תשמ"ד-1984, סעיף 70). הפסיקה מדגישה כי פגיעה פוטנציאלית בפרנסה או בשם הטוב אינה מובילה בהכרח לפגיעה חמורה בפרטיות (Verdict: תא"מ (שלום רח'') 25710-02-20 משה מנשה נ'' חונן קריספל (19.3.2020), Reference 68, 70).',
    'הסטודנט עלול לבלבל בין העילות השונות לאיסור פרסום לפני ואחרי הגשת כתב אישום, ולא להבין את ההבחנה המהותית שקבע המחוקק והפסיקה בין שלבי ההליך הפלילי.',
    '["צו איסור פרסום", "פומביות הדיון", "חשוד מול נאשם", "הגשת כתב אישום", "פגיעה חמורה בפרטיות", "סעיף 70(ד) לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — איסור פרסום חשוד:** מהם התנאים לאיסור פרסום שמו של חשוד? ← נזק חמור והעדפת מניעת הנזק על פני העניין הציבורי (סעיף 70(ה1)(1) לחוק בתי המשפט). **וריאציה 2 — איסור פרסום נאשם:** מהם התנאים לאיסור פרסום שמו של נאשם? ← הגנה על ביטחון או מניעת פגיעה חמורה בפרטיות (סעיף 70(ד) לחוק בתי המשפט). **וריאציה 3 — שינוי נקודת האיזון:** כיצד משתנה נקודת האיזון עם הגשת כתב אישום? ← נוטה באופן מובהק לעבר פרסום (פ"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני, רפרנס 9).',
    'איסור פרסום שמו של נאשם (לאחר כתב אישום) אפשרי רק לשם הגנה על ביטחון או מניעת פגיעה חמורה בפרטיות (סעיף 70(ד) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 70", "פ\"ר (שלום ראשון לציון) 8871-02-18 מדינת ישראל נ'' פלוני (23.2.2020)", "ת\"פ (שלום ק\"ש) 3803-01-14 מדינת ישראל נ'' תמיר יואל (2.1.2017)", "ת\"פ (שלום ת\"א) 30453-04-10 יהושע צולר נ'' מדינת ישראל פמת\"א (מיסוי וכלכלה) (21.12.2016)", "תא\"מ (שלום רח'') 25710-02-20 משה מנשה נ'' חונן קריספל (19.3.2020)", "ת\"פ (שלום ת\"א) 54122-10-21 מדינת ישראל נ'' עודד שכנאי (6.9.2022)", "ת\"פ (שלום ת\"א) 20556-08-16 מדינת ישראל נ'' עומר פורן (5.8.2019)", "ת\"פ (שלום חי'') 39077-08-15 ילנה קיריצ''יק נ'' מדינת ישראל (25.5.2025)", "ת\"פ (שלום ת\"א) 20482-05-17 פלוני נ'' מדינת ישראל (10.4.2020)", "ת\"פ (שלום ראשל\"צ) 13147-01-15 פלוני נ'' מדינת ישראל (2.6.2015)", "מ\"ת (שלום ת\"א) 51232-07-15 מדינת ישראל נ'' זואי מיטל שפיר (26.7.2015)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'איסור פרסום פרטי חקירה הפוגעים בחקירה', 4, 'המשטרה מבקשת מבית המשפט לאסור פרסום פרטים מסוימים מחקירה מתנהלת, בטענה שהדבר עלול לפגוע בחקירה. מה הדין?',
    'שאלה זו עוסקת בעילה נוספת לאיסור פרסום, והיא פגיעה בחקירה מתנהלת. היא מדגישה את האיזון בין עקרון פומביות הדיון לבין הצורך להגן על יעילות החקירה הפלילית.',
    'סעיף 70(ה) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "בית משפט רשאי לאסור פרסום שמו של חשוד שטרם הוגש נגדו כתב אישום, או פרט אחר מפרטי החקירה, אם הדבר עלול לפגוע בחקירה שעל פי דין; אסר בית המשפט כאמור, יפקע האיסור עם הגשת כתב האישום נגד החשוד, אלא אם כן קבע בית המשפט אחרת" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 70). הוראה זו מאפשרת לבית המשפט להגן על שלמות ויעילות החקירה הפלילית, תוך הכרה בכך שפרסום מוקדם של פרטים מסוימים עלול לסכל את מטרותיה. הפסיקה מדגישה כי בשלב החקירה, בקשות רשויות החקירה נדונות, ככלל, במעמד צד אחד ובדלתיים סגורות, וכי איסורי פרסום שניתנו בשלב זה יפקעו מאליהם עם הגשת כתב אישום, אלא אם נקבע אחרת (Verdict: ת"פ (שלום ת"א) 54122-10-21 מדינת ישראל נ'' עודד שכנאי (6.9.2022), Reference 29, 46).',
    'הסטודנט עלול לבלבל בין העילות השונות לאיסור פרסום המנויות בסעיף 70 לחוק בתי המשפט, ולא להבחין בין איסור פרסום שמו של חשוד (סעיף 70(ה1)(1)) לבין איסור פרסום פרטי חקירה (סעיף 70(ה)).',
    '["צו איסור פרסום", "פגיעה בחקירה", "פרטי חקירה", "פומביות הדיון", "שלב החקירה", "סעיף 70(ה) לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — עילה לאיסור פרסום פרטי חקירה:** מתי בית המשפט רשאי לאסור פרסום פרטים מפרטי חקירה? ← אם הדבר עלול לפגוע בחקירה שעל פי דין (סעיף 70(ה) לחוק בתי המשפט). **וריאציה 2 — פקיעת הצו:** מתי יפקע איסור פרסום שניתן לפי סעיף 70(ה)? ← עם הגשת כתב האישום, אלא אם נקבע אחרת (סעיף 70(ה) לחוק בתי המשפט). **וריאציה 3 — אופי הדיון בשלב החקירה:** כיצד נדונות בקשות רשויות החקירה בשלב זה? ← ככלל, במעמד צד אחד ובדלתיים סגורות (ת"פ (שלום ת"א) 54122-10-21 מדינת ישראל נ'' עודד שכנאי, רפרנס 29, 46).',
    'בית המשפט רשאי לאסור פרסום פרטי חקירה אם הדבר עלול לפגוע בחקירה, והצו יפקע עם הגשת כתב האישום (סעיף 70(ה) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 70", "ת\"פ (שלום ת\"א) 54122-10-21 מדינת ישראל נ'' עודד שכנאי (6.9.2022)", "ת\"פ (שלום אשקלון) 55402-12-25 רועי ינובסקי כאן 11 נ'' מדינת ישראל (29.1.2026)", "ת\"פ (שלום נצרת) 3439-02-21 ג''בר חג''אזי נ'' מדינת ישראל (7.2.2021)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'לא, החלטה על הגשת כתב אישום בכפוף לשימוע אינה מהווה ''נסיבות חדשות'', שכן הסטטוס של החשוד לא השתנה באופן מהותי.', false, 'בחירה זו שגויה. הפסיקה קבעה כי החלטה על הגשת כתב אישום בכפוף לשימוע מהווה ''נסיבות חדשות'' המצדיקות עיון חוזר בצו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'כן, החלטה על הגשת כתב אישום בכפוף לשימוע מהווה ''נסיבות חדשות'', שכן היא משקפת הערכה ראייתית מבוססת יותר ומטה את נקודת האיזון לעבר פומביות הדיון.', true, 'בחירה זו נכונה. הפסיקה רואה בהחלטה על הגשת כתב אישום בכפוף לשימוע כ''נסיבות חדשות'' המצדיקות בחינה מחודשת של צו איסור הפרסום, בהתאם לסעיף 70ג(ב) לחוק בתי המשפט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'כן, אך רק אם חלף זמן רב ממועד מתן הצו המקורי, וזאת בנוסף להחלטת הפרקליטות.', false, 'בחירה זו שגויה. חלוף הזמן הוא נסיבה חדשה בפני עצמה, אך החלטת הפרקליטות מהווה נסיבה חדשה גם ללא קשר לחלוף הזמן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לא, אלא אם כן הוגש כתב אישום בפועל, שכן רק אז פוקע הצו מאליו.', false, 'בחירה זו שגויה. אף שהצו פוקע עם הגשת כתב אישום, החלטה על הגשת כתב אישום בכפוף לשימוע מהווה נסיבה חדשה המצדיקה עיון חוזר עוד לפני הגשת כתב האישום בפועל.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'על החשוד להראות כי ייגרם לו נזק, ודי בכך כדי להצדיק איסור פרסום.', false, 'בחירה זו שגויה. לא די בנזק רגיל, אלא נדרש ''נזק חמור'' החורג מהרגיל.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'על החשוד להראות כי עלול להיגרם לו, במידה קרובה של ודאות, נזק המתאפיין בחומרה מיוחדת, החורג בחומרתו מהפגיעה הטבעית העלולה להיגרם לכל אדם בעקבות פתיחת חקירה פלילית נגדו.', true, 'בחירה זו נכונה. הפסיקה קבעה כי נטל ההוכחה ל''נזק חמור'' הוא כבד ודורש הוכחת נזק חריג וקונקרטי, במידה קרובה של ודאות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'על החשוד להראות כי פרסום שמו יפגע בפרנסתו או בשמו הטוב, ובית המשפט יאזן זאת מול האינטרס הציבורי.', false, 'בחירה זו שגויה. פגיעה בפרנסה או בשם הטוב היא נזק אינהרנטי להליך פלילי, ואינה מספיקה כשלעצמה להוכחת ''נזק חמור'' חריג.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'על החשוד להראות כי פרסום שמו יביא לפגיעה בלתי הפיכה בפרטיותו, ורק אז יורה בית המשפט על איסור פרסום.', false, 'בחירה זו שגויה. אף שפגיעה חמורה בפרטיות היא עילה לאיסור פרסום (לפי סעיף 70(ד)), המבחן ל''נזק חמור'' לפי סעיף 70(ה1)(1) רחב יותר ואינו מוגבל רק לפגיעה בלתי הפיכה בפרטיות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'בית המשפט יורה על איסור פרסום רק אם הפרסום עלול לפגוע בחקירה שעל פי דין.', false, 'בחירה זו שגויה. עילה זו רלוונטית לאיסור פרסום בשלב החקירה (סעיף 70(ה)), ולא לאחר הגשת כתב אישום.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'בית המשפט יורה על איסור פרסום אם הדבר נחוץ לשם הגנה על ביטחונו של בעל דין, עד או אדם אחר, או לשם מניעת פגיעה חמורה בפרטיות של אחד מהם.', true, 'בחירה זו נכונה. סעיף 70(ד) לחוק בתי המשפט קובע את העילות לאיסור פרסום לאחר הגשת כתב אישום, והן כוללות הגנה על ביטחון או מניעת פגיעה חמורה בפרטיות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בית המשפט יורה על איסור פרסום אם הפרסום עלול לגרום לנאשם נזק חמור, ובית המשפט סבר כי יש להעדיף את מניעת הנזק על פני העניין הציבורי שבפרסום.', false, 'בחירה זו שגויה. עילה זו רלוונטית לאיסור פרסום בשלב החשד (סעיף 70(ה1)(1)), ולאחר הגשת כתב אישום נקודת האיזון משתנה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לא ניתן לאסור פרסום שמו של נאשם לאחר הגשת כתב אישום, שכן פומביות הדיון היא הכלל המוחלט בשלב זה.', false, 'בחירה זו שגויה. אף שפומביות הדיון היא הכלל, קיימים חריגים המאפשרים איסור פרסום גם לאחר הגשת כתב אישום, כפי שקבוע בסעיף 70(ד).', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'בית המשפט רשאי לאסור פרסום פרטים מפרטי החקירה אם הדבר עלול לפגוע בחקירה שעל פי דין.', true, 'בחירה זו נכונה. סעיף 70(ה) לחוק בתי המשפט מסמיך את בית המשפט לאסור פרסום פרטי חקירה אם הדבר עלול לפגוע בחקירה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'בית המשפט חייב לאסור פרסום פרטים מפרטי החקירה אם המשטרה טוענת לפגיעה בחקירה.', false, 'בחירה זו שגויה. הסמכות היא ''רשאי'' ולא ''חייב'', ונתונה לשיקול דעת בית המשפט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'לא ניתן לאסור פרסום פרטי חקירה, שכן פומביות הדיון גוברת על כל אינטרס אחר בשלב זה.', false, 'בחירה זו שגויה. קיימת עילה מפורשת בחוק לאיסור פרסום פרטי חקירה אם הדבר עלול לפגוע בה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בית המשפט רשאי לאסור פרסום רק אם הפרסום עלול לגרום נזק חמור לחשוד.', false, 'בחירה זו שגויה. עילה זו רלוונטית לאיסור פרסום שמו של חשוד (סעיף 70(ה1)(1)), אך קיימת עילה נפרדת לפגיעה בחקירה (סעיף 70(ה)).', 4);

END $$;

-- ============================================================
-- Q27 — 2019-S-Q27 — chapter=civil_proc subtopic=jurisdiction_subject
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q27';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q27 skipped: external_id % already exists', '2019-S-Q27';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'jurisdiction_subject';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'jurisdiction_subject';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q27', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'עורך דין מטעם ארגון עובדים מעוניין לפעול בשם הארגון ולהגיש תביעה בגין הפרת הוראות הסכם קיבוצי. עורך הדין מעוניין כי התביעה תידון בבית הדין הארצי לעבודה. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 27}'::jsonb,
    'השאלה עוסקת בסמכות העניינית של בתי הדין לעבודה, ובפרט באפשרות להעביר תובענה מבית הדין האזורי לבית הדין הארצי כערכאה ראשונה. סעיף 24(ג) לחוק בית הדין לעבודה קובע חריג לכלל הסמכות של בית הדין האזורי, ומאפשר לנשיא בית הדין הארצי או סגנו להורות על העברה במקרים בעלי חשיבות, דחיפות או רגישות מיוחדת.',
    'הכלל הוא שתובענה בין מי שיכולים להיות צדדים להסכם קיבוצי מיוחד, בעניין קיומו, תחולתו, פירושו, ביצועו או הפרתו של הסכם קיבוצי, נתונה לסמכותו הייחודית של בית הדין האזורי לעבודה, בהתאם לסעיף 24(א)(2) לחוק בית הדין לעבודה, תשכ"ט-1969 (Law: חוק בית הדין לעבודה, תשכ"ט-1969, סעיף 24). עם זאת, סעיף 24(ג) לחוק קובע חריג לכלל זה: "על אף הוראות סעיף קטן (א)(2), רשאי נשיא בית הדין הארצי או סגנו, על פי בקשה של בעל דין או של היועץ המשפטי לממשלה שהוגשה לפני תחילת הדיון או במהלכו, להורות שדיון בתובענה לפי הסעיף הקטן האמור, שהוא בעל חשיבות, דחיפות או רגישות מיוחדת, יתקיים בבית הדין הארצי" (Law: חוק בית הדין לעבודה, תשכ"ט-1969, סעיף 24). במקרה הנדון, עורך הדין מטעם ארגון העובדים הוא ''בעל דין'' לעניין זה, והוא יכול להגיש בקשה לסגן נשיא בית הדין הארצי, אשר מוסמך להורות על העברת הדיון לבית הדין הארצי אם התקיימו התנאים של חשיבות, דחיפות או רגישות מיוחדת (Literature: נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו, עמ'' 10).',
    'הסטודנט עלול לטעות ולחשוב שכל תביעה בגין הפרת הסכם קיבוצי נדונית בבית הדין האזורי, מבלי להכיר את החריג הקבוע בסעיף 24(ג) המאפשר העברה לבית הדין הארצי במקרים מיוחדים.',
    '["סמכות עניינית", "בית הדין הארצי לעבודה", "בית הדין האזורי לעבודה", "הסכם קיבוצי", "העברת דיון", "סעיף 24(ג) לחוק בית הדין לעבודה"]'::jsonb,
    '**וריאציה 1 — סמכות העברה:** מי מוסמך להורות על העברת תובענה מבית הדין האזורי לבית הדין הארצי? ← נשיא בית הדין הארצי או סגנו (סעיף 24(ג) לחוק בית הדין לעבודה). **וריאציה 2 — תנאי העברה:** מהם התנאים להעברת תובענה לבית הדין הארצי? ← חשיבות, דחיפות או רגישות מיוחדת של התובענה (סעיף 24(ג) לחוק בית הדין לעבודה). **וריאציה 3 — יוזם הבקשה:** מי רשאי להגיש בקשה להעברה? ← בעל דין או היועץ המשפטי לממשלה (סעיף 24(ג) לחוק בית הדין לעבודה).',
    'תביעה בגין הפרת הסכם קיבוצי, שאמורה להידון בבית הדין האזורי, יכולה לעבור לבית הדין הארצי אם נשיא בית הדין הארצי או סגנו הורה על כך, לבקשת בעל דין, בשל חשיבות, דחיפות או רגישות מיוחדת (סעיף 24(ג) לחוק בית הדין לעבודה).',
    '["חוק בית הדין לעבודה, תשכ\"ט-1969, סעיף 24", "נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'התביעה תידון בבית הדין הארצי לעבודה אם סגן נשיא בית הדין הארצי לעבודה הורה על כך לאור בקשת עורך הדין.', true, 'בחירה זו נכונה. סעיף 24(ג) לחוק בית הדין לעבודה מאפשר לנשיא בית הדין הארצי או סגנו להורות על העברת תובענה מבית הדין האזורי לבית הדין הארצי, לבקשת בעל דין, אם היא בעלת חשיבות, דחיפות או רגישות מיוחדת.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'התביעה תידון בבית הדין הארצי לעבודה אם הורה על כך נשיא בית הדין האזורי לעבודה שבו הייתה אמורה להיות מוגשת התביעה.', false, 'בחירה זו שגויה. הסמכות להורות על העברת תובענה מבית הדין האזורי לבית הדין הארצי נתונה לנשיא בית הדין הארצי או סגנו, ולא לנשיא בית הדין האזורי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'התביעה תידון בבית הדין הארצי לעבודה אם נשיא בית הדין הארצי לעבודה הורה על כך לאור בקשת נשיא בית הדין האזורי שבו הייתה אמורה להיות מוגשת התביעה.', false, 'בחירה זו שגויה. אף שנשיא בית הדין הארצי מוסמך להורות על העברה, הבקשה יכולה להיות מוגשת ישירות על ידי בעל דין, ולא רק על ידי נשיא בית הדין האזורי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית הדין הארצי לא יוכל לדון בתביעה כערכאה ראשונה.', false, 'בחירה זו שגויה. אף שהכלל הוא שתביעות מסוג זה נדונות בבית הדין האזורי, סעיף 24(ג) לחוק בית הדין לעבודה קובע חריג המאפשר לבית הדין הארצי לדון בהן כערכאה ראשונה במקרים מיוחדים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'סמכות בית הדין הארצי בסכסוך בין ארגוני עובדים', 1, 'ארגון עובדים א'' וארגון עובדים ב'' חלוקים ביניהם בשאלת יציגותם במקום עבודה מסוים. ארגון עובדים א'' מעוניין להגיש תובענה נגד ארגון עובדים ב'' בעניין זה. לאיזה בית דין תוגש התובענה?',
    'שאלה זו בוחנת את הסמכות העניינית הייחודית של בית הדין הארצי לעבודה לדון בסכסוכים בין ארגוני עובדים. היא מדגישה את ההבחנה בין סכסוכים אלו לבין סכסוכים אחרים הנדונים בבית הדין האזורי.',
    'סעיף 25(2) לחוק בית הדין לעבודה, תשכ"ט-1969, קובע כי לבית הדין הארצי תהא הסמכות הייחודית לדון "בתובענות בין ארגון עובדים לארגון עובדים אחר ותובענות בין ארגון מעבידים לארגון מעבידים אחר, הכל אם התובענות נובעות מענינים שביחסי עבודה" (Law: חוק בית הדין לעבודה, תשכ"ט-1969, סעיף 25). סכסוך יציגות בין שני ארגוני עובדים נופל במובהק בגדר עניינים שביחסי עבודה, ולכן הסמכות לדון בו נתונה לבית הדין הארצי לעבודה כערכאה ראשונה (Literature: נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו, עמ'' 13).',
    'הסטודנט עלול לטעות ולחשוב שכל סכסוך הנוגע למקום עבודה ספציפי נדון בבית הדין האזורי, מבלי להבחין בסמכות הייחודית של בית הדין הארצי לסכסוכים בין-ארגוניים.',
    '["סמכות עניינית", "בית הדין הארצי לעבודה", "ארגון עובדים", "סכסוך יציגות", "סעיף 25(2) לחוק בית הדין לעבודה"]'::jsonb,
    '**וריאציה 1 — סכסוך בין ארגוני עובדים:** היכן נדון סכסוך בין ארגון עובדים אחד לארגון עובדים אחר? ← בבית הדין הארצי לעבודה בסמכות ייחודית (סעיף 25(2) לחוק בית הדין לעבודה). **וריאציה 2 — מהות הסכסוך:** האם סכסוך יציגות נחשב ''עניין שביחסי עבודה''? ← כן, ולכן הוא בסמכות בית הדין הארצי (נבו - המתמחה, דיני עבודה, עמ'' 13). **וריאציה 3 — ערכאה ראשונה:** האם בית הדין הארצי דן בכך כערכאה ראשונה? ← כן, זו סמכותו הייחודית כערכאה ראשונה (נבו - המתמחה, דיני עבודה, עמ'' 13).',
    'סכסוך בין ארגוני עובדים בענייני יחסי עבודה נדון בסמכות ייחודית של בית הדין הארצי לעבודה כערכאה ראשונה (סעיף 25(2) לחוק בית הדין לעבודה).',
    '["חוק בית הדין לעבודה, תשכ\"ט-1969, סעיף 25", "נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'מבחני סמכות עניינית של בית הדין לעבודה', 2, 'מהם המבחנים העיקריים לקביעת סמכותו העניינית של בית הדין לעבודה לדון בתובענה?',
    'שאלה זו עוסקת במבחנים הכלליים לקביעת הסמכות העניינית של בתי הדין לעבודה. הבנת מבחנים אלו חיונית להבחנה בין סמכות בתי הדין לעבודה לבין סמכות בתי המשפט האזרחיים.',
    'הסמכות העניינית של בתי הדין לעבודה נקבעת על פי שני מבחנים מצטברים: מבחן הצדדים ומבחן העילה (Literature: נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו, עמ'' 11). מבחן הצדדים בוחן האם מדובר בתובענה בין עובד או חליפו למעסיק או חליפו (לפי סעיף 24(א)(1) לחוק בית הדין לעבודה), או בין גורמים אחרים המנויים בחוק (כגון ארגוני עובדים/מעבידים). מבחן העילה בוחן האם עילת התובענה היא ביחסי עבודה (Literature: נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו, עמ'' 11). רק אם שני המבחנים מתקיימים, קמה לבית הדין לעבודה הסמכות העניינית לדון בתובענה (Verdict: סע"ש (אזורי ת"א) 4426-12-20 בועז דרוקר נ'' אקסאקטק תוכנה ויישום בע"מ (11.8.2024), Reference 23). מרכז הכובד לבחינת הסמכות העניינית הוא ''מהות הסכסוך וייחודו במסגרת משפט העבודה'' (Verdict: סע"ש (אזורי ת"א) 4426-12-20 בועז דרוקר נ'' אקסאקטק תוכנה ויישום בע"מ (11.8.2024), Reference 23).',
    'הסטודנט עלול לטעות ולחשוב שאחד המבחנים מספיק בפני עצמו, או לבלבל בין מבחני הסמכות העניינית של בית הדין לעבודה לבין אלו של בתי המשפט האזרחיים.',
    '["סמכות עניינית", "מבחן הצדדים", "מבחן העילה", "יחסי עבודה", "בית הדין לעבודה", "מבחנים מצטברים"]'::jsonb,
    '**וריאציה 1 — המבחנים העיקריים:** מהם המבחנים לקביעת סמכות עניינית של בית הדין לעבודה? ← מבחן הצדדים ומבחן העילה, במצטבר (נבו - המתמחה, דיני עבודה, עמ'' 11). **וריאציה 2 — מהות הסכסוך:** מהו מרכז הכובד לבחינת הסמכות העניינית? ← מהות הסכסוך וייחודו במסגרת משפט העבודה (סע"ש (אזורי ת"א) 4426-12-20 דרוקר, רפרנס 23). **וריאציה 3 — סמכות ייחודית:** מה משמעות קביעת סמכות לבית הדין לעבודה? ← מופקעת סמכותן של הערכאות האזרחיות הכלליות (סע"ש (אזורי ת"א) 4426-12-20 דרוקר, רפרנס 23).',
    'סמכות עניינית של בית הדין לעבודה נקבעת על פי מבחן הצדדים ומבחן העילה במצטבר, תוך התמקדות במהות הסכסוך (נבו - המתמחה, דיני עבודה, עמ'' 11).',
    '["חוק בית הדין לעבודה, תשכ\"ט-1969, סעיף 24", "סע\"ש (אזורי ת\"א) 4426-12-20 בועז דרוקר נ'' אקסאקטק תוכנה ויישום בע\"מ (11.8.2024)", "נבו - המתמחה, דיני עבודה (2026) | פרק א - סמכויות בית הדין לעבודה והרכבו"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'סמכות בית הדין הארצי להסכם קיבוצי כללי', 3, 'ארגון עובדים מעוניין להגיש תובענה בעניין פירושו של הסכם קיבוצי כללי החל על ענף שלם במשק. לאיזה בית דין תוגש התובענה?',
    'שאלה זו בוחנת את הסמכות העניינית הייחודית של בית הדין הארצי לעבודה לדון בתובענות הנוגעות להסכמים קיבוציים כלליים. היא מדגישה את הרציונל של ריכוז סכסוכים ארציים ובעלי חשיבות בערכאה העליונה של דיני העבודה.',
    'סעיף 25(1) לחוק בית הדין לעבודה, תשכ"ט-1969, קובע כי לבית הדין הארצי תהא הסמכות הייחודית לדון "בתובענה בין מי שיכולים להיות צדדים להסכם קיבוצי כללי כמשמעותו בחוק הסכמים קיבוציים בענין קיומו, תחולתו, פירושו, ביצועו או הפרתו של הסכם קיבוצי, או הסדר קיבוצי אחר, או בכל ענין אחר הנובע מהם, או בענין תחולתו, פירושו, ביצועו או הפרתו של כל דין" (Law: חוק בית הדין לעבודה, תשכ"ט-1969, סעיף 25). הרציונל מאחורי הוראה זו הוא רצונו של המחוקק שסכסוכים ''ארציים'', בעלי היבט מיוחד ורחב היקף, יתבררו ישירות בפני בית הדין הארצי, כערכאה עליונה בתחום משפט העבודה והביטחון הסוציאלי (Verdict: סק"כ (עבודה ארצי) 51/09 "סאוט אלעאמל" - להגנת זכויות העובדים והמובטלים - שר התעשיה המסחר והתעסוקה (3.1.2012), Reference 8, 9).',
    'הסטודנט עלול לבלבל בין סמכות בית הדין האזורי (הסכם קיבוצי מיוחד) לבין סמכות בית הדין הארצי (הסכם קיבוצי כללי), או להתעלם מהסמכות הייחודית של בית הדין הארצי במקרים אלו.',
    '["סמכות עניינית", "בית הדין הארצי לעבודה", "הסכם קיבוצי כללי", "פירוש הסכם קיבוצי", "סעיף 25(1) לחוק בית הדין לעבודה"]'::jsonb,
    '**וריאציה 1 — סמכות להסכם קיבוצי כללי:** היכן נדון סכסוך בעניין פירוש הסכם קיבוצי כללי? ← בבית הדין הארצי לעבודה בסמכות ייחודית (סעיף 25(1) לחוק בית הדין לעבודה). **וריאציה 2 — רציונל הסמכות:** מדוע סכסוכים אלו נדונים בבית הדין הארצי? ← כדי להעביר למסלול הכרעה מהירה סכסוכים ארציים מרכזיים ויוצאי דופן בחשיבותם (סק"כ (עבודה ארצי) 51/09 "סאוט אלעאמל", רפרנס 9). **וריאציה 3 — הרכב בית הדין הארצי:** באיזה הרכב ידון בית הדין הארצי בעניינים אלו? ← בשבעה, שהם שלושה שופטים, שני נציגי עובדים ושני נציגי מעסיקים (סעיף 20(א)(3) לחוק בית הדין לעבודה).',
    'תובענה בעניין הסכם קיבוצי כללי נדונית בסמכות ייחודית של בית הדין הארצי לעבודה כערכאה ראשונה (סעיף 25(1) לחוק בית הדין לעבודה).',
    '["חוק בית הדין לעבודה, תשכ\"ט-1969, סעיף 20", "חוק בית הדין לעבודה, תשכ\"ט-1969, סעיף 25", "סק\"כ (עבודה ארצי) 51/09 \"סאוט אלעאמל\" - להגנת זכויות העובדים והמובטלים - שר התעשיה המסחר והתעסוקה (3.1.2012)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'התערבות בג"ץ בפסקי דין של בתי הדין לעבודה', 4, 'צד להליך בבית הדין הארצי לעבודה אינו מרוצה מפסק הדין שניתן. האם הוא יכול להגיש עתירה לבג"ץ נגד פסק הדין, ומהם התנאים להתערבות בג"ץ?',
    'שאלה זו עוסקת ביחסי הגומלין בין בית המשפט העליון (בג"ץ) לבין בתי הדין לעבודה, ובפרט באמות המידה להתערבות בג"ץ בפסקי דין של בית הדין הארצי לעבודה. היא מדגישה את עקרון אי-ההתערבות של בג"ץ כערכאת ערעור, למעט במקרים חריגים ביותר.',
    'הלכה פסוקה היא כי בג"ץ אינו משמש כערכאת ערעור על החלטות ופסקי דין של בתי הדין לעבודה (Verdict: בג"ץ 5200/23 עו"ד שאול כהן נ'' בית הדין הארצי לעבודה (12.7.2023), Reference 14; Verdict: בג"ץ 5596819 אביב חזיזה נ'' בית הדין הארצי לעבודה (25.10.2021), Reference 20, 21). התערבות בג"ץ בהחלטות אלו שמורה למקרים חריגים ביותר, בהם מתקיימים שני תנאים מצטברים: (1) נפלה טעות משפטית מהותית בהחלטה, ו-(2) שיקולי צדק מחייבים את התערבות בג"ץ בנסיבות העניין (Verdict: בג"ץ 5200/23 עו"ד שאול כהן נ'' בית הדין הארצי לעבודה (12.7.2023), Reference 14). נקודת המוצא היא שבית הדין הארצי לעבודה נחשב לערכאה השיפוטית בעלת המומחיות בתחום משפט העבודה, ועליו הוטל התפקיד של גיבוש ההלכה בתחום זה (Verdict: בג"ץ 5200/23 עו"ד שאול כהן נ'' בית הדין הארצי לעבודה (12.7.2023), Reference 14; Verdict: בג"ץ 5589304 אריה בגו נ'' בית הדין הארצי לעבודה (17.10.2021), Reference 22).',
    'הסטודנט עלול לטעות ולחשוב שבג"ץ הוא ערכאת ערעור רגילה על בתי הדין לעבודה, מבלי להבין את אמות המידה המחמירות והחריגות להתערבותו.',
    '["בג\"ץ", "בית הדין הארצי לעבודה", "ביקורת שיפוטית", "טעות משפטית מהותית", "שיקולי צדק", "מומחיות שיפוטית"]'::jsonb,
    '**וריאציה 1 — מעמד בג"ץ:** האם בג"ץ הוא ערכאת ערעור על בית הדין הארצי לעבודה? ← לא, הוא אינו משמש כערכאת ערעור (בג"ץ 5200/23 עו"ד שאול כהן, רפרנס 14). **וריאציה 2 — תנאי התערבות:** מתי יתערב בג"ץ בפסק דין של בית הדין הארצי? ← במקרים חריגים, אם נפלה טעות משפטית מהותית ושיקולי צדק מחייבים התערבות (בג"ץ 5200/23 עו"ד שאול כהן, רפרנס 14). **וריאציה 3 — מומחיות בית הדין לעבודה:** מדוע בג"ץ מצמצם את התערבותו? ← לבית הדין הארצי מומחיות מיוחדת בתחום משפט העבודה (בג"ץ 5200/23 עו"ד שאול כהן, רפרנס 14).',
    'בג"ץ אינו ערכאת ערעור על בית הדין הארצי לעבודה, ויתערב רק במקרים חריגים של טעות משפטית מהותית ושיקולי צדק (בג"ץ 5200/23 עו"ד שאול כהן).',
    '["בג\"ץ 4737/14 הסתדרות העובדים הלאומית נ'' שר הכלכלה (5.11.2014)", "בג\"ץ 5200/23 עו\"ד שאול כהן נ'' בית הדין הארצי לעבודה (12.7.2023)", "בג\"ץ 5148/18 אור שחם נ'' בית הדין הארצי לעבודה (11.7.2022)", "בג\"ץ 5589304 אריה בגו נ'' בית הדין הארצי לעבודה (17.10.2021)", "בג\"ץ 5596819 אביב חזיזה נ'' בית הדין הארצי לעבודה (25.10.2021)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'לבית הדין האזורי לעבודה, שכן מדובר בסכסוך הנוגע למקום עבודה ספציפי.', false, 'בחירה זו שגויה. סכסוכים בין ארגוני עובדים נדונים בסמכות ייחודית של בית הדין הארצי לעבודה, ללא קשר למקום העבודה הספציפי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'לבית הדין הארצי לעבודה, שכן זוהי תובענה בין ארגון עובדים אחד לארגון עובדים אחר הנובעת מענייני יחסי עבודה.', true, 'בחירה זו נכונה. סעיף 25(2) לחוק בית הדין לעבודה קובע סמכות ייחודית לבית הדין הארצי לדון בתובענות בין ארגון עובדים לארגון עובדים אחר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'לבית המשפט המחוזי, שכן מדובר בסכסוך בעל אופי ציבורי הנוגע לזכויות התאגדות.', false, 'בחירה זו שגויה. סכסוכים בין ארגוני עובדים הם בתחום סמכותו הייחודית של בית הדין לעבודה, ולא של בית המשפט המחוזי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לבית הדין האזורי לעבודה, אלא אם כן נשיא בית הדין הארצי הורה אחרת.', false, 'בחירה זו שגויה. אין צורך בהוראת נשיא בית הדין הארצי במקרה זה, שכן הסמכות הייחודית לבית הדין הארצי קבועה בחוק במפורש לסכסוכים בין ארגוני עובדים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'מבחן הסעד הנתבע בלבד.', false, 'בחירה זו שגויה. מבחן הסעד אינו עומד בפני עצמו, אלא נבחן בשילוב עם מבחן העילה ומבחן הצדדים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'מבחן הצדדים ומבחן העילה, כאשר שניהם צריכים להתקיים במצטבר.', true, 'בחירה זו נכונה. הפסיקה קבעה כי סמכותו העניינית של בית הדין לעבודה נקבעת על פי שני מבחנים מצטברים: מבחן הצדדים ומבחן העילה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'מבחן מהות הסכסוך וייחודו במסגרת משפט העבודה, ללא קשר לזהות הצדדים.', false, 'בחירה זו שגויה. אף ש''מהות הסכסוך'' היא מרכזית, היא נבחנת במסגרת מבחן העילה, וזהות הצדדים היא מבחן נפרד ומצטבר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'מבחן הסעד הנתבע או מבחן העילה, לפי בחירת התובע.', false, 'בחירה זו שגויה. הסמכות העניינית נקבעת על פי דין, ולא לפי בחירת התובע, ודורשת עמידה במבחנים מצטברים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'לבית הדין האזורי לעבודה, שכן הוא הערכאה הראשונה לרוב סכסוכי העבודה.', false, 'בחירה זו שגויה. אף שבית הדין האזורי הוא הערכאה הראשונה לרוב סכסוכי העבודה, סכסוכים הנוגעים להסכם קיבוצי כללי הם בסמכות ייחודית של בית הדין הארצי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'לבית הדין הארצי לעבודה, שכן זוהי סמכותו הייחודית לדון בתובענה בין מי שיכולים להיות צדדים להסכם קיבוצי כללי.', true, 'בחירה זו נכונה. סעיף 25(1) לחוק בית הדין לעבודה מקנה סמכות ייחודית לבית הדין הארצי לדון בתובענות הנוגעות להסכם קיבוצי כללי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'לבית המשפט המחוזי, שכן מדובר בהסכם בעל השלכות רוחב על המשק.', false, 'בחירה זו שגויה. סכסוכים הנוגעים להסכמים קיבוציים הם בתחום סמכותו הייחודית של בית הדין לעבודה, ולא של בית המשפט המחוזי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לבית הדין האזורי לעבודה, אלא אם כן נשיא בית הדין הארצי הורה על העברה.', false, 'בחירה זו שגויה. במקרה של הסכם קיבוצי כללי, הסמכות הייחודית היא מלכתחילה של בית הדין הארצי, ואין צורך בהוראת העברה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'כן, בג"ץ משמש כערכאת ערעור על פסקי דין של בית הדין הארצי לעבודה, ויתערב אם נפלה טעות משפטית.', false, 'בחירה זו שגויה. בג"ץ אינו משמש כערכאת ערעור על בתי הדין לעבודה, והתערבותו שמורה למקרים חריגים ביותר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'כן, אך התערבות בג"ץ שמורה למקרים חריגים בלבד, בהם נפלה טעות משפטית מהותית בהחלטה ושיקולי צדק מחייבים התערבות.', true, 'בחירה זו נכונה. זוהי ההלכה הפסוקה לגבי התערבות בג"ץ בפסקי דין של בתי הדין לעבודה, תוך מתן משקל למומחיותם של בתי הדין לעבודה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'לא, פסקי דין של בית הדין הארצי לעבודה הם סופיים ואינם ניתנים לביקורת שיפוטית נוספת.', false, 'בחירה זו שגויה. אף שפסקי הדין של בית הדין הארצי הם סופיים ברובם, קיימת אפשרות עקרונית לביקורת בג"ץ במקרים חריגים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'כן, אך רק אם פסק הדין של בית הדין הארצי עומד בסתירה להלכה קודמת של בית המשפט העליון.', false, 'בחירה זו שגויה. סתירה להלכה קודמת היא עילה לדיון נוסף בבית המשפט העליון, אך לא התנאי היחיד להתערבות בג"ץ בפסקי דין של בתי הדין לעבודה.', 4);

END $$;

-- ============================================================
-- Q28 — 2019-S-Q28 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q28';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q28 skipped: external_id % already exists', '2019-S-Q28';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q28', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'בתביעה שהגיש אביב בבית המשפט לתביעות קטנות בחדרה ביקש אביב כי בית המשפט ייתן צו לגילוי מסמכים. בית המשפט דחה את הבקשה. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 28}'::jsonb,
    'השאלה עוסקת בסמכויותיו הדיוניות של בית המשפט לתביעות קטנות, ובפרט ביחסו להליכי גילוי מסמכים. בית המשפט לתביעות קטנות אינו כפוף באופן מלא לסדרי הדין הרגילים, ומוסמך לסטות מהם כדי להגיע להכרעה צודקת ומהירה, תוך איזון בין הצורך בגילוי לבין מטרות ההליך המיוחד.',
    'בית המשפט לתביעות קטנות הוא ערכאה ייחודית שנועדה לאפשר לאזרח הקטן גישה מהירה, פשוטה וזולה לצדק (Verdict: רע"א 292/93 אריה סרבוז נ'' ע. אופק בע"מ (8.5.1994), Reference 8; Verdict: ת"ק (תביעות קטנות ת"א) 9010-08-08 נפתלי גדפור נ'' ליאורה שקד לייטנר (1.2.2015), Reference 18). לשם כך, סעיף 62(ב) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "בית משפט לתביעות קטנות אינו קשור בסדרי הדין הנוהגים בבית משפט אחר, ובכפוף לסדרי דין שהתקין שר המשפטים לענין סימן זה, יפעל בדרך הנראית לו מועילה ביותר להכרעה צודקת ומהירה" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 62). תקנה 9 לתקנות שיפוט בתביעות קטנות (סדרי דין), תשל"ז-1976, מוסיפה כי "לבית המשפט יהיו הסמכויות הנתונות לבית משפט שלום בענינים שבסדר דין או שבנוהג... אולם רשאי בית המשפט שלא להשתמש בסמכות מסמכויות אלה אם נראה לו הדבר מועיל יותר להכרעה צודקת ומהירה" (Law: תקנות שיפוט בתביעות קטנות (סדרי דין), תשל"ז-1976, תקנה 9). מכאן שלבית המשפט לתביעות קטנות נתונות הסמכויות של בית משפט שלום, כולל הסמכות ליתן צו לגילוי מסמכים (כפי שקבוע בתקנות סדר הדין האזרחי), אך הוא רשאי שלא להשתמש בהן אם סבר שדחיית הבקשה מועילה יותר להכרעה צודקת ומהירה (Verdict: ת"ק (תביעות קטנות פ"ת) 17980-02-25 מיכאלה אסתר בר נ'' חברת פרטנר תקשורת בע"מ (3.9.2025), Reference 1, 2). הליכי גילוי ועיון מובנים, כפי שקיימים בהליכים אזרחיים רגילים, אינם קיימים בתביעות קטנות, שכן הם מייקרים ומאריכים את ההתדיינות (Literature: יצחק עמית, חסיונות ואינטרסים מוגנים - הליכי גילוי ועיון במשפט האזרחי והפלילי (2021) | ה. תביעות קטנות, עמ'' 4). עם זאת, בית המשפט רשאי לדרוש מבעל דין להמציא מסמכים ספציפיים אם מצא שהם רלוונטיים למחלוקת (Verdict: ת"ק (תביעות קטנות פ"ת) 17980-02-25 מיכאלה אסתר בר נ'' חברת פרטנר תקשורת בע"מ (3.9.2025), Reference 1, 2).',
    'הסטודנט עלול לטעות ולחשוב שבית המשפט לתביעות קטנות אינו מוסמך כלל ליתן צו לגילוי מסמכים, או לחילופין, שהוא חייב להיענות לבקשה כזו כמו בבית משפט שלום רגיל, מבלי להבין את שיקול הדעת הרחב הנתון לו.',
    '["בית משפט לתביעות קטנות", "גילוי מסמכים", "סדרי דין", "הכרעה צודקת ומהירה", "שיקול דעת שיפוטי", "סעיף 62(ב) לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — סמכות כללית:** האם לבית המשפט לתביעות קטנות יש סמכות ליתן צו לגילוי מסמכים? ← כן, יש לו את הסמכויות הנתונות לבית משפט שלום (תקנה 9 לתקנות שיפוט בתביעות קטנות; ת"ק (פ"ת) 17980-02-25 בר, רפרנס 1). **וריאציה 2 — שיקול דעת:** האם בית המשפט חייב להיענות לבקשה לגילוי מסמכים? ← לא, הוא רשאי שלא להשתמש בסמכות זו אם סבר שזה מועיל יותר להכרעה צודקת ומהירה (תקנה 9 לתקנות שיפוט בתביעות קטנות; ת"ק (פ"ת) 17980-02-25 בר, רפרנס 1). **וריאציה 3 — תכלית ההליך:** מדוע ניתנת גמישות כזו? ← כדי לאפשר לאזרח הקטן גישה מהירה, פשוטה וזולה לצדק (רע"א 292/93 סרבוז, רפרנס 8).',
    'בית המשפט לתביעות קטנות מוסמך ליתן צו לגילוי מסמכים, אך רשאי לדחות בקשה כזו אם סבר שדחייתה מועילה יותר להכרעה צודקת ומהירה, בהתאם לאופי ההליך (סעיף 62(ב) לחוק בתי המשפט ותקנה 9 לתקנות שיפוט בתביעות קטנות).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 62", "תקנות שיפוט בתביעות קטנות (סדרי דין), תשל\"ז-1976, תקנה 9", "ת\"ק (תביעות קטנות פ\"ת) 17980-02-25 מיכאלה אסתר בר נ'' חברת פרטנר תקשורת בע\"מ (3.9.2025)", "רע\"א 292/93 אריה סרבוז נ'' ע. אופק בע\"מ, מח(3) 177 (8.5.1994)", "ת\"ק (תביעות קטנות נת'') 54901-11-18 שאול ג''ליקס נ'' רמי שבירו הנדסה בניה והשקעות בע\"מ (6.9.2019)", "יצחק עמית, חסיונות ואינטרסים מוגנים - הליכי גילוי ועיון במשפט האזרחי והפלילי (2021) | פרק יז הליכי גילוי ועיון בסוגים שונים של הליכים אזרחיים, עמ'' 4"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט לתביעות קטנות אינו מוסמך ליתן צו מסוג זה.', false, 'בחירה זו שגויה. לבית המשפט לתביעות קטנות נתונות כל הסמכויות הנתונות לבית משפט שלום, כולל הסמכות ליתן צו לגילוי מסמכים, אלא אם כן שר המשפטים קבע הסדר שונה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על בית המשפט להיענות לבקשה.', false, 'בחירה זו שגויה. לבית המשפט לתביעות קטנות שיקול דעת רחב בנוגע לסדרי הדין, והוא רשאי שלא להיענות לבקשה אם סבר שדחייתה מועילה יותר להכרעה צודקת ומהירה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על בית המשפט לדחות את הבקשה.', false, 'בחירה זו שגויה. בית המשפט אינו חייב לדחות את הבקשה, אלא רשאי לדחותה אם סבר שזה מועיל להכרעה צודקת ומהירה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית המשפט רשאי היה לדחות את הבקשה אם סבר שדחייתה מועילה יותר להכרעה צודקת ומהירה בתביעה.', true, 'בחירה זו נכונה. סעיף 62(ב) לחוק בתי המשפט ותקנה 9 לתקנות שיפוט בתביעות קטנות מעניקים לבית המשפט לתביעות קטנות גמישות רחבה בסדרי הדין, ומאפשרים לו לסטות מהם אם הדבר מועיל להכרעה צודקת ומהירה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'ייצוג עורך דין בתביעות קטנות', 1, 'בתביעה שהגיש ראובן בבית המשפט לתביעות קטנות, הוא מבקש להיות מיוצג על ידי עורך דין. מה הדין?',
    'שאלה זו עוסקת בכלל ובחריגים בנוגע לייצוג משפטי בבית המשפט לתביעות קטנות. מטרת המגבלה על ייצוג היא לפשט את ההליך, להוזיל אותו ולקדם שוויון מהותי בין בעלי הדין, אך החוק מאפשר חריגים במקרים מיוחדים.',
    'סעיף 63(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "בעל דין בבית משפט לתביעות קטנות אינו רשאי להיות מיוצג על ידי עורך דין, אלא ברשות בית המשפט ומטעמים מיוחדים שיירשמו" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 63). הכלל הוא איסור ייצוג, והחריג הוא ייצוג על ידי עורך דין ברשות בית המשפט ומטעמים מיוחדים. מטרת האיסור היא להקטין את עלויות ההליך, לפשט אותו ולאפשר לאזרח הקטן גישה קלה ומהירה לצדק, תוך צמצום פערי הכוחות בין הצדדים (Verdict: רע"א 292/93 אריה סרבוז נ'' ע. אופק בע"מ (8.5.1994), Reference 8; Verdict: ת"ק (תביעות קטנות ת"א) 9010-08-08 נפתלי גדפור נ'' ליאורה שקד לייטנר (1.2.2015), Reference 18). בית המשפט רשאי לנקוט גישה פעילה בניהול ההליך כדי להבטיח שוויון מהותי, גם כאשר אחד הצדדים הוא עורך דין והשני אינו מיוצג (Verdict: רע"א 5234/17 דרייבר ישראל בע"מ נ'' עו"ד אלירן ג''נח (4.7.2018), Reference 17).',
    'הסטודנט עלול לטעות ולחשוב שייצוג עורך דין אסור באופן מוחלט בתביעות קטנות, מבלי להכיר את החריג המאפשר ייצוג ברשות בית המשפט ומטעמים מיוחדים.',
    '["בית משפט לתביעות קטנות", "ייצוג עורך דין", "סעיף 63 לחוק בתי המשפט", "טעמים מיוחדים", "פומביות הדיון", "שוויון מהותי"]'::jsonb,
    '**וריאציה 1 — הכלל בייצוג:** האם בעל דין רשאי להיות מיוצג על ידי עורך דין בתביעות קטנות? ← לא, אלא ברשות בית המשפט ומטעמים מיוחדים (סעיף 63(א) לחוק בתי המשפט). **וריאציה 2 — מטרת האיסור:** מהי מטרת האיסור על ייצוג? ← להקטין עלויות, לפשט הליך, לאפשר גישה לצדק ולצמצם פערי כוחות (רע"א 292/93 סרבוז, רפרנס 8). **וריאציה 3 — תפקיד בית המשפט:** מה תפקיד בית המשפט כשיש פערי כוחות? ← לנקוט גישה פעילה בניהול ההליך כדי להבטיח שוויון מהותי (רע"א 5234/17 דרייבר ישראל, רפרנס 17).',
    'ייצוג עורך דין בתביעות קטנות אסור ככלל, אך מותר ברשות בית המשפט ומטעמים מיוחדים (סעיף 63(א) לחוק בתי המשפט), במטרה לשמור על אופי ההליך.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 63", "רע\"א 292/93 אריה סרבוז נ'' ע. אופק בע\"מ, מח(3) 177 (8.5.1994)", "ת\"ק (תביעות קטנות ת\"א) 9010-08-08 נפתלי גדפור נ'' ליאורה שקד לייטנר (1.2.2015)", "רע\"א 5234/17 דרייבר ישראל בע\"מ נ'' עו\"ד אלירן ג''נח (4.7.2018)", "נבו - המתמחה, מערכת בתי המשפט (2026) | ט. בית משפט לתביעות קטנות, עמ'' 77"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'אמות מידה למתן רשות ערעור', 2, 'צד המבקש לערער על פסק דין של בית משפט לתביעות קטנות. מהן אמות המידה למתן רשות ערעור על פסק דין כזה?',
    'שאלה זו עוסקת באמות המידה המחמירות למתן רשות ערעור על פסקי דין של בית המשפט לתביעות קטנות. אמות מידה אלו נועדו לשמר את תכלית ההליך בתביעות קטנות – דיון מהיר, פשוט וזול – ולמנוע סרבול והתייקרות של ההתדיינות.',
    'ערעור על פסק דין של בית משפט לתביעות קטנות טעון רשות (Verdict: רע"א 292/93 אריה סרבוז נ'' ע. אופק בע"מ (8.5.1994), Reference 8; Verdict: רת"ק (מחוזי ב"ש) 44730-09-22 שרון זעירא נ'' מלכה טטרו (1.12.2022), Reference 10). הפסיקה קבעה כי אמת המידה למתן רשות ערעור על פסקי דינו של בית המשפט לתביעות קטנות היא מחמירה במיוחד, ורשות זו תינתן רק במקרים חריגים ביותר בהם נפל פגם מהותי הדורש את התערבותה של ערכאת הערעור (Verdict: רת"ק (מחוזי ב"ש) 44730-09-22 שרון זעירא נ'' מלכה טטרו (1.12.2022), Reference 10). זאת, כדי לשמור על תכלית הקמתו של בית המשפט לתביעות קטנות – לאפשר דיון מהיר, קצר, פשוט וזול (Verdict: רת"ק (מחוזי ב"ש) 5505360 שלמה אבי עוז נ'' חדוה אפללו (24.6.2021), Reference 12). רשות ערעור לא בהכרח תינתן אף כאשר מתעוררת שאלה משפטית בעלת חשיבות החורגת מעניינם הישיר של הצדדים למחלוקת (Verdict: רת"ק (מחוזי ב"ש) 44730-09-22 שרון זעירא נ'' מלכה טטרו (1.12.2022), Reference 10). כמו כן, ערכאת הערעור לא תתערב ככלל בממצאים עובדתיים וקביעות מהימנות של בית המשפט לתביעות קטנות (Verdict: רע"א 5623/18 עיריית ירושלים נ'' נתנאל מור (9.8.2018), Reference 6; Verdict: רת"ק (מחוזי ב"ש) 37422-05-21 רשל קרין רוזן נ'' חיים גרמן (27.7.2021), Reference 13).',
    'הסטודנט עלול לבלבל בין אמות המידה למתן רשות ערעור על פסקי דין של בית משפט שלום רגיל לבין אלו של בית המשפט לתביעות קטנות, שהן מחמירות יותר באופן משמעותי.',
    '["בית משפט לתביעות קטנות", "רשות ערעור", "פגם מהותי", "תכלית ההליך", "ממצאים עובדתיים", "קביעות מהימנות"]'::jsonb,
    '**וריאציה 1 — סוג הערעור:** האם ערעור על פסק דין של תביעות קטנות הוא בזכות או ברשות? ← ברשות (רת"ק (מחוזי ב"ש) 44730-09-22 זעירא, רפרנס 10). **וריאציה 2 — אמות המידה:** מהן אמות המידה למתן רשות ערעור? ← מחמירות במיוחד, רק במקרים חריגים ביותר בהם נפל פגם מהותי (רת"ק (מחוזי ב"ש) 44730-09-22 זעירא, רפרנס 10). **וריאציה 3 — התערבות בממצאים עובדתיים:** האם ערכאת הערעור תתערב בממצאים עובדתיים? ← ככלל לא, אלא במקרים חריגים ביותר (רע"א 5623/18 עיריית ירושלים, רפרנס 6).',
    'רשות ערעור על פסק דין של תביעות קטנות תינתן במשורה ובמקרים חריגים בלבד של פגם מהותי, כדי לשמר את אופי ההליך (רת"ק (מחוזי ב"ש) 44730-09-22 זעירא).',
    '["רע\"א 292/93 אריה סרבוז נ'' ע. אופק בע\"מ, מח(3) 177 (8.5.1994)", "רע\"א 5623/18 עיריית ירושלים נ'' נתנאל מור (9.8.2018)", "רת\"ק (מחוזי ב\"ש) 44730-09-22 שרון זעירא נ'' מלכה טטרו (1.12.2022)", "רת\"ק (מחוזי ב\"ש) 5505360 שלמה אבי עוז נ'' חדוה אפללו (24.6.2021)", "רת\"ק (מחוזי ב\"ש) 37422-05-21 רשל קרין רוזן נ'' חיים גרמן (27.7.2021)", "רע\"א 5106/23 גג-כל איתום בע\"מ נ'' רינה עמרם (22.10.2023)", "חמי בן-נון, טל חבקין, הערעור האזרחי (2012) | פרק שבעה-עשר - בית משפט לתביעות קטנות, עמ'' 13"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'העברת דיון מבית משפט לתביעות קטנות', 3, 'בתביעה שהוגשה לבית המשפט לתביעות קטנות, התברר כי היא מעוררת שאלות משפטיות מורכבות מתחום המשפט המינהלי. האם בית המשפט רשאי להעביר את הדיון לבית משפט השלום?',
    'שאלה זו בוחנת את סמכותו של בית המשפט לתביעות קטנות להעביר דיון לבית משפט השלום, במיוחד כאשר התביעה מורכבת מדי עבור הפורום הייחודי של תביעות קטנות. סמכות זו נועדה לשמור על אופי ההליך הפשוט והמהיר, תוך הבטחת בירור הולם של תביעות מורכבות.',
    'סעיף 60(ב) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "בית המשפט רשאי לא לדון בתביעה או בתביעה-שכנגד ולהעבירן לבית משפט שלום או לבית המשפט המוסמך לדון בהן, לפי העניין, אם ראה שהדיון בבית משפט לתביעות קטנות אינו מתאים להן" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 60). הפסיקה מפרשת את עילת ''אי התאמה'' ככוללת מקרים בהם מדובר בעניין מורכב וסבוך הדורש בירור מקיף, כגון שאלות משפטיות מורכבות מתחום המשפט המינהלי או תביעות לשון הרע (Verdict: ת"ק (שלום נת'') 62274-11-20 טלי חירותי סובר נ'' גל זנזורי (1.2.2021), Reference 15; Verdict: ת"ק (תביעות קטנות עפ'') 35280-11-24 מי מגידו - חברת הביוב והמים מייסודה של המועצה האזורית מגידו נ'' דנה לישינסקי (24.4.2025), Reference 14). במקרים כאלה, בית המשפט רשאי לפעול מיוזמתו להעברת התיק לבית משפט השלום, וזאת אף אם המבקש לא ביקש זאת בתחילת הדיון (Verdict: ת"ק (שלום נת'') 62274-11-20 טלי חירותי סובר נ'' גל זנזורי (1.2.2021), Reference 15).',
    'הסטודנט עלול לטעות ולחשוב שסמכות ההעברה מוגבלת למקרים של ריבוי תביעות בלבד, ולא להבין שהיא חלה גם על תביעות מורכבות שאינן מתאימות לאופי הפשוט של בית המשפט לתביעות קטנות.',
    '["בית משפט לתביעות קטנות", "העברת דיון", "סמכות עניינית", "מורכבות משפטית", "סעיף 60(ב) לחוק בתי המשפט", "יוזמת בית המשפט"]'::jsonb,
    '**וריאציה 1 — עילת העברה:** מתי בית המשפט לתביעות קטנות רשאי להעביר דיון לבית משפט השלום? ← אם ראה שהדיון אינו מתאים לתביעה (סעיף 60(ב) לחוק בתי המשפט). **וריאציה 2 — דוגמאות לאי-התאמה:** אילו מקרים נחשבים ל''אי-התאמה''? ← תביעות מורכבות, כגון שאלות משפטיות מורכבות או תביעות לשון הרע (ת"ק (שלום נת'') 62274-11-20 חירותי סובר, רפרנס 15). **וריאציה 3 — יוזמת ההעברה:** האם בית המשפט יכול להעביר תיק מיוזמתו? ← כן, גם אם המבקש לא ביקש זאת (ת"ק (שלום נת'') 62274-11-20 חירותי סובר, רפרנס 15).',
    'בית המשפט לתביעות קטנות רשאי להעביר דיון לבית משפט השלום, גם מיוזמתו, אם התביעה מורכבת ואינה מתאימה לאופי ההליך (סעיף 60(ב) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 60", "ת\"ק (תביעות קטנות נת'') 62274-11-20 טלי חירותי סובר נ'' גל זנזורי (1.2.2021)", "ת\"ק (תביעות קטנות עפ'') 35280-11-24 מי מגידו - חברת הביוב והמים מייסודה של המועצה האזורית מגידו נ'' דנה לישינסקי (24.4.2025)", "נבו - המתמחה, מערכת בתי המשפט (2026) | ט. בית משפט לתביעות קטנות, עמ'' 76"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'סמכות מקומית בתביעות קטנות', 4, 'ראובן הגיש תביעה קטנה לבית המשפט בחדרה. הנתבע, שמעון, מתגורר בתל אביב, ובהסכם ביניהם נקבע כי בית המשפט המוסמך לדון בכל מחלוקת הוא בתל אביב. מה הדין לגבי הסמכות המקומית?',
    'שאלה זו עוסקת בכללי הסמכות המקומית הייחודיים לבית המשפט לתביעות קטנות. בניגוד לדין הכללי, בתביעות קטנות לא ניתן להתנות על כללי הסמכות המקומית בהסכם בין הצדדים, וזאת כדי להקל על האזרח הקטן בגישה לערכאות.',
    'תקנה 2(א) לתקנות שיפוט בתביעות קטנות (סדרי דין), תשל"ז-1976, קובעת כי תביעה תוגש לבית המשפט שאזור שיפוטו הוא אחד המקומות המנויים בה, וזאת "על אף האמור בכל הסכם שבין בעלי הדין" (Law: תקנות שיפוט בתביעות קטנות (סדרי דין), תשל"ז-1976, תקנה 2). כללים אלו כוללים, בין היתר, את מקום מגוריו או מקום עסקו של הנתבע, או מקום המעשה או המחדל שבשלו תובעים (Law: תקנות שיפוט בתביעות קטנות (סדרי דין), תשל"ז-1976, תקנה 2). המשמעות היא שבתביעות קטנות, כללי הסמכות המקומית הם קוגנטיים (לא ניתן להתנות עליהם), ואין תוקף להסכם שיפוט בין הצדדים (Verdict: רת"ק (מחוזי ב"ש) 5156-10-24 ברוריה שולה אבקסיס נ'' אירית דימר (29.12.2024), Reference 21; Literature: נבו - המתמחה, מערכת בתי המשפט (2026) | ט. בית משפט לתביעות קטנות, עמ'' 76).',
    'הסטודנט עלול לטעות וליישם את הכללים הרגילים של הסמכות המקומית, המאפשרים התניה בהסכם, מבלי להכיר את החריג הקבוע בתקנות שיפוט בתביעות קטנות.',
    '["בית משפט לתביעות קטנות", "סמכות מקומית", "הסכם שיפוט", "תקנה 2 לתקנות שיפוט בתביעות קטנות", "כללים קוגנטיים", "מקום מגורים/עסק"]'::jsonb,
    '**וריאציה 1 — תוקף הסכם שיפוט:** האם הסכם שיפוט בין הצדדים תקף בתביעות קטנות? ← לא, הסמכות המקומית נקבעת על אף האמור בכל הסכם (תקנה 2(א) לתקנות שיפוט בתביעות קטנות). **וריאציה 2 — כללי הסמכות המקומית:** מהם כללי הסמכות המקומית בתביעות קטנות? ← מקום מגוריו או עסקו של הנתבע, או מקום המעשה/מחדל (תקנה 2(א) לתקנות שיפוט בתביעות קטנות). **וריאציה 3 — רציונל הכלל:** מדוע לא ניתן להתנות על הסמכות המקומית? ← כדי לפתוח את שערי בית המשפט בפני ''האזרח הקטן'' ולהקל עליו (נבו - המתמחה, מערכת בתי המשפט, עמ'' 76).',
    'בתביעות קטנות, הסמכות המקומית נקבעת לפי כללים קוגנטיים (כגון מקום מגורי הנתבע), ואין תוקף להסכם שיפוט בין הצדדים (תקנה 2(א) לתקנות שיפוט בתביעות קטנות).',
    '["תקנות שיפוט בתביעות קטנות (סדרי דין), תשל\"ז-1976, תקנה 2", "רת\"ק (מחוזי ב\"ש) 5156-10-24 ברוריה שולה אבקסיס נ'' אירית דימר (29.12.2024)", "נבו - המתמחה, מערכת בתי המשפט (2026) | ט. בית משפט לתביעות קטנות, עמ'' 76"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'ראובן אינו רשאי להיות מיוצג על ידי עורך דין, שכן ייצוג אסור בתביעות קטנות.', false, 'בחירה זו שגויה. אף שהכלל הוא איסור ייצוג, קיימים חריגים המאפשרים ייצוג על ידי עורך דין ברשות בית המשפט ומטעמים מיוחדים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'ראובן רשאי להיות מיוצג על ידי עורך דין רק ברשות בית המשפט ומטעמים מיוחדים שיירשמו.', true, 'בחירה זו נכונה. סעיף 63(א) לחוק בתי המשפט קובע כי ייצוג על ידי עורך דין בתביעות קטנות מותנה ברשות בית המשפט ומטעמים מיוחדים שיירשמו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'ראובן רשאי להיות מיוצג על ידי עורך דין ללא צורך ברשות, שכן זו זכות יסוד.', false, 'בחירה זו שגויה. זכות הייצוג בתביעות קטנות מוגבלת, ואינה זכות מוחלטת ללא צורך ברשות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'ראובן רשאי להיות מיוצג על ידי עורך דין אם הצד שכנגד מיוצג אף הוא.', false, 'בחירה זו שגויה. אף ששוויון בייצוג הוא שיקול, הוא אינו תנאי אוטומטי לייצוג, ועדיין נדרשת רשות בית המשפט ומטעמים מיוחדים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'רשות ערעור תינתן בזכות, שכן זו זכות יסוד של כל מתדיין.', false, 'בחירה זו שגויה. ערעור על פסק דין של בית משפט לתביעות קטנות טעון רשות, ואינו בזכות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'רשות ערעור תינתן רק במקרים חריגים ביותר בהם נפל פגם מהותי הדורש את התערבותה של ערכאת הערעור, וזאת כדי לשמור על תכלית ההליך הפשוט והמהיר.', true, 'בחירה זו נכונה. הפסיקה קבעה אמות מידה מחמירות למתן רשות ערעור על פסקי דין של תביעות קטנות, כדי לשמר את אופיו של ההליך.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'רשות ערעור תינתן אם מתעוררת שאלה משפטית בעלת חשיבות החורגת מעניינם הישיר של הצדדים למחלוקת.', false, 'בחירה זו שגויה. אף שזהו שיקול במתן רשות ערעור ''רגילה'', בתביעות קטנות הרף מחמיר יותר, ורשות לא בהכרח תינתן גם במקרה כזה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'רשות ערעור תינתן אם בית המשפט לתביעות קטנות שגה בממצאים עובדתיים או בקביעות מהימנות.', false, 'בחירה זו שגויה. ערכאת הערעור לא תתערב ככלל בממצאים עובדתיים וקביעות מהימנות של בית המשפט לתביעות קטנות, אלא במקרים חריגים ביותר.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'לא, בית המשפט לתביעות קטנות אינו מוסמך להעביר דיון לבית משפט השלום.', false, 'בחירה זו שגויה. סעיף 60(ב) לחוק בתי המשפט מעניק לבית המשפט לתביעות קטנות סמכות להעביר דיון לבית משפט השלום.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'כן, בית המשפט רשאי להעביר את הדיון לבית משפט השלום אם ראה שהדיון בבית המשפט לתביעות קטנות אינו מתאים לתביעה, למשל בשל מורכבותה המשפטית.', true, 'בחירה זו נכונה. סעיף 60(ב) לחוק בתי המשפט מאפשר העברת דיון אם הוא אינו מתאים לבית המשפט לתביעות קטנות, ופסיקה מפרשת זאת כמקרים של מורכבות משפטית או עובדתית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'כן, אך רק אם התובע ביקש זאת במפורש בתחילת הדיון.', false, 'בחירה זו שגויה. בית המשפט רשאי להעביר את התיק מיוזמתו, גם אם המבקש לא ביקש זאת בתחילת הדיון.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לא, אלא אם כן התובע הגיש באותה שנה יותר מחמש תביעות באותו בית משפט.', false, 'בחירה זו שגויה. זהו אחד התנאים להעברת דיון לפי סעיף 60(ב), אך לא התנאי היחיד, וקיימת גם עילת ''אי התאמה'' בשל מורכבות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'הסכם השיפוט בין הצדדים גובר, ולכן הסמכות המקומית היא לבית המשפט בתל אביב.', false, 'בחירה זו שגויה. בתביעות קטנות, הסכם שיפוט בין הצדדים אינו בעל תוקף לעניין קביעת הסמכות המקומית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'הסמכות המקומית נקבעת לפי מקום מגוריו או מקום עסקו של הנתבע, וזאת על אף האמור בכל הסכם בין בעלי הדין.', true, 'בחירה זו נכונה. תקנה 2(א) לתקנות שיפוט בתביעות קטנות קובעת כללים קוגנטיים לסמכות מקומית, המבטלים הסכמים בין הצדדים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'הסמכות המקומית היא לבית המשפט בחדרה, שכן התובע רשאי לבחור את מקום הגשת התביעה.', false, 'בחירה זו שגויה. אף שלתובע יש אפשרויות בחירה, הן מוגבלות לכללים הקבועים בתקנה 2, ואינן כוללות בחירה שרירותית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בית המשפט בחדרה רשאי להעביר את הדיון לבית המשפט בתל אביב, אם סבר שזה מועיל להכרעה צודקת ומהירה.', false, 'בחירה זו שגויה. אף שקיימת סמכות העברה, היא אינה נובעת מהסכם שיפוט, אלא משיקולים אחרים של אי-התאמה או ריבוי תביעות.', 4);

END $$;

-- ============================================================
-- Q30 — 2019-S-Q30 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q30';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q30 skipped: external_id % already exists', '2019-S-Q30';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q30', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'בית המשפט העליון החליט במסגרת הליך אזרחי לדחות בקשת רשות ערעור על החלטה של בית משפט מחוזי בשבתו כבית משפט לערעורים. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 30}'::jsonb,
    'השאלה עוסקת בסמכותו של בית המשפט העליון לדחות בקשת רשות ערעור ב''גלגול שלישי'' בנימוק קצר, בהתאם לתקנה 148א לתקנות סדר הדין האזרחי, תשע"ט-2018 (לשעבר תקנה 407א לתקנות תשמ"ד-1984). תקנה זו מאפשרת לבית המשפט לייעל את הדיון בבקשות רשות ערעור שאינן עומדות באמות המידה המחמירות שנקבעו בהלכת ''חניון חיפה''.',
    'תקנה 148א לתקנות סדר הדין האזרחי, תשע"ט-2018 (המקבילה לתקנה 407א לתקנות סדר הדין האזרחי, תשמ"ד-1984, שהייתה בתוקף במועד הבחינה), קובעת כי בית המשפט העליון רשאי לדחות בקשת רשות ערעור בנימוק קצר, וזאת לאחר שמצא כי פסק הדין של בית המשפט המחוזי אינו מעורר כל שאלה משפטית עקרונית החורגת מעניינם של הצדדים, וכי מתן רשות ערעור אינו דרוש כדי למנוע עיוות דין (Law: תקנות סדר הדין האזרחי, תשע"ט-2018, סעיף 148א). תנאים אלו הם מצטברים (השימוש ב''וכי'' ולא ב''או''). סמכות זו נועדה לייעל את הדיון בבקשות רשות ערעור ב''גלגול שלישי'', אשר נבחנות על פי אמות המידה המחמירות של הלכת ''חניון חיפה'' (Verdict: רע"א 5404400 מועצה מקומית מעלה יוסף נ'' המוסד לביטוח לאומי (22.3.2021), Reference 8, 9; Verdict: רע"א 5330498 פלוני נ'' קצין תגמולים (17.1.2021), Reference 16; Verdict: רע"א 5312998 יניב אביאל נ'' קיבוץ איל אגודה שיתופית (31.12.2020), Reference 17; Verdict: רע"א 5170967 חיים ארגי נ'' מדינת ישראל - רשות הפיתוח (2.8.2020), Reference 18; Verdict: רע"א 5338756 נעמי קורצבנד נ'' ג''ני אליס קייל (21.1.2021), Reference 26; Verdict: רע"א 5390635 פלוני נ'' רשת מדיה בע"מ (9.3.2021), Reference 47; Verdict: רע"א 5333211 עזבון המנוחה מלכה עזר ז"ל נ'' פרויקט לוגאנו יהוד בע"מ (18.1.2021), Reference 48; Verdict: רע"א 5354106 מטרולייט בע"מ נ'' עיריית נתניה (4.2.2021), Reference 52; Verdict: בע"מ 4711969 פלוני נ'' פלונית (28.1.2019), Reference 53; Verdict: בע"מ 5367722 פלונית נ'' פלוני (16.2.2021), Reference 54; Verdict: רע"א 5368996 הרוניאן פרויז נ'' אמיר אלעד (18.2.2021), Reference 57; Verdict: בע"מ 5116534 פלוני נ'' האפוטרופוס הכללי מחוז חיפה והצפון (4.6.2020), Reference 58; Verdict: רע"א 5424061 יוסי שקד נ'' מייקל זלמנסון (14.4.2021), Reference 59; Verdict: רע"א 4913983 יוסף אוחנה נ'' רשות מקרקעי ישראל (26.9.2019), Reference 29; Verdict: רע"א 5755053 ציון ברוכים נ'' לילי גאון (10.4.2022), Reference 30; Verdict: רע"א 4802598 פלוני נ'' הוועדה הפסיכיאטרית המיוחדת (19.5.2019), Reference 73; Verdict: רע"א 4978390 צמח בן יונה נ'' עירית תל אביב - יפו (22.12.2019), Reference 74; Verdict: רע"א 4673136 ויקטור רוסיליו נ'' מועצה מקומית חצור הגלילית (20.12.2018), Reference 76; Verdict: רע"א 5139777 יוסף שמואל נ'' עופר חדד (28.6.2020), Reference 77; Verdict: רע"א 4920867 פיוטר וגר נ'' אנה ניקולשין (7.10.2019), Reference 71).',
    'הסטודנט עלול לטעות ולחשוב שבית המשפט העליון חייב לנמק באופן מפורט כל דחיית בקשת רשות ערעור, מבלי להכיר את הסמכות המיוחדת הנתונה לו לפי תקנה 148א (לשעבר 407א) לדחות בקשות כאלה בנימוק קצר, אם אינן עומדות באמות המידה המחמירות.',
    '["רשות ערעור", "גלגול שלישי", "תקנה 148א לתקסד\"א", "שאלה משפטית עקרונית", "עיוות דין", "נימוק קצר"]'::jsonb,
    '**וריאציה 1 — סמכות לדחייה קצרה:** האם בית המשפט העליון רשאי לדחות בקשת רשות ערעור בנימוק קצר? ← כן, לפי תקנה 148א לתקסד"א (לשעבר 407א). **וריאציה 2 — תנאי הדחייה הקצרה:** מהם התנאים לדחייה בנימוק קצר? ← שההחלטה לא מעוררת שאלה משפטית עקרונית וכי מתן רשות ערעור אינו דרוש כדי למנוע עיוות דין (תקנה 148א לתקסד"א). **וריאציה 3 — אופי התנאים:** האם התנאים הם מצטברים או חלופיים? ← מצטברים, כלומר ''וכי'' ולא ''או'' (רע"א 5404400 מועצה מקומית מעלה יוסף, רפרנס 8).',
    'בית המשפט העליון רשאי לדחות בקשת רשות ערעור ב''גלגול שלישי'' בנימוק קצר, אם הקביעות בהחלטה אינן מעוררות שאלה משפטית עקרונית וגם מתן רשות ערעור אינו דרוש כדי למנוע עיוות דין (תקנה 148א לתקסד"א).',
    '["תקנות סדר הדין האזרחי, תשע\"ט-2018, סעיף 148א", "תקנות סדר הדין האזרחי, תשמ\"ד-1984, סעיף 407א", "רע\"א 5404400 מועצה מקומית מעלה יוסף נ'' המוסד לביטוח לאומי (22.3.2021)", "רע\"א 5330498 פלוני נ'' קצין תגמולים (17.1.2021)", "רע\"א 5312998 יניב אביאל נ'' קיבוץ איל אגודה שיתופית (31.12.2020)", "רע\"א 5170967 חיים ארגי נ'' מדינת ישראל - רשות הפיתוח (2.8.2020)", "רע\"א 5338756 נעמי קורצבנד נ'' ג''ני אליס קייל (21.1.2021)", "רע\"א 5390635 פלוני נ'' רשת מדיה בע\"מ (9.3.2021)", "רע\"א 5333211 עזבון המנוחה מלכה עזר ז\"ל נ'' פרויקט לוגאנו יהוד בע\"מ (18.1.2021)", "רע\"א 5354106 מטרולייט בע\"מ נ'' עיריית נתניה (4.2.2021)", "בע\"מ 4711969 פלוני נ'' פלונית (28.1.2019)", "בע\"מ 5367722 פלונית נ'' פלוני (16.2.2021)", "רע\"א 5368996 הרוניאן פרויז נ'' אמיר אלעד (18.2.2021)", "בע\"מ 5116534 פלוני נ'' האפוטרופוס הכללי מחוז חיפה והצפון (4.6.2020)", "רע\"א 5424061 יוסי שקד נ'' מייקל זלמנסון (14.4.2021)", "רע\"א 4913983 יוסף אוחנה נ'' רשות מקרקעי ישראל (26.9.2019)", "רע\"א 5755053 ציון ברוכים נ'' לילי גאון (10.4.2022)", "רע\"א 4802598 פלוני נ'' הוועדה הפסיכיאטרית המיוחדת (19.5.2019)", "רע\"א 4978390 צמח בן יונה נ'' עירית תל אביב - יפו (22.12.2019)", "רע\"א 4673136 ויקטור רוסיליו נ'' מועצה מקומית חצור הגלילית (20.12.2018)", "רע\"א 5139777 יוסף שמואל נ'' עופר חדד (28.6.2020)", "רע\"א 4920867 פיוטר וגר נ'' אנה ניקולשין (7.10.2019)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט רשאי לכלול בהחלטתו רק את קביעתו בדבר דחיית בקשת רשות הערעור, ובלבד שלדעתו הקביעות בהחלטה אינן מעוררות שאלה משפטית עקרונית החורגת מעניינם של הצדדים או כי מתן רשות ערעור אינו דרוש כדי למנוע עיוות דין.', false, 'בחירה זו שגויה. התנאים למתן רשות ערעור ב''גלגול שלישי'' הם מצטברים, כלומר, נדרש שפסק הדין לא יעורר שאלה משפטית עקרונית וגם שלא ייגרם עיוות דין. השימוש ב''או'' במקום ''וכי'' הופך את התנאי למקל מדי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית המשפט רשאי לכלול בהחלטתו רק את קביעתו בדבר דחיית בקשת רשות הערעור, ובלבד שלדעתו הקביעות בהחלטה אינן מעוררות שאלה משפטית עקרונית החורגת מעניינם של הצדדים וכי מתן רשות ערעור אינו דרוש כדי למנוע עיוות דין.', true, 'בחירה זו נכונה. תקנה 148א לתקנות סדר הדין האזרחי, תשע"ט-2018 (המקבילה לתקנה 407א הישנה) מאפשרת לבית המשפט העליון לדחות בקשת רשות ערעור ב''גלגול שלישי'' בנימוק קצר, אם שני התנאים המצטברים מתקיימים: אין שאלה משפטית עקרונית ואין עיוות דין.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על בית המשפט לכלול בהחלטתו רק את קביעתו בדבר דחיית בקשת רשות הערעור, ובלבד שלדעתו הקביעות בהחלטה אינן מעוררות שאלה משפטית עקרונית החורגת מעניינם של הצדדים או כי מתן רשות ערעור אינו דרוש כדי למנוע עיוות דין.', false, 'בחירה זו שגויה. בית המשפט ''רשאי'' לכלול נימוק קצר, ולא ''על בית המשפט'' (חובה). בנוסף, התנאים למתן רשות ערעור ב''גלגול שלישי'' הם מצטברים, כלומר, נדרש שפסק הדין לא יעורר שאלה משפטית עקרונית וגם שלא ייגרם עיוות דין.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'על בית המשפט לכלול בהחלטתו רק את קביעתו בדבר דחיית בקשת רשות הערעור, ובלבד שלדעתו הקביעות בהחלטה אינן מעוררות שאלה משפטית עקרונית החורגת מעניינם של הצדדים וכי מתן רשות ערעור אינו דרוש כדי למנוע עיוות דין.', false, 'בחירה זו שגויה. בית המשפט ''רשאי'' לכלול נימוק קצר, ולא ''על בית המשפט'' (חובה). עם זאת, היא נכונה בכך שהתנאים הם מצטברים (''וכי'').', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'אמות מידה למתן רשות ערעור בגלגול שלישי', 1, 'ראובן הגיש בקשת רשות ערעור לבית המשפט העליון על פסק דין של בית המשפט המחוזי שדחה ערעור על פסק דין של בית משפט השלום. מהם התנאים העיקריים למתן רשות ערעור ב''גלגול שלישי''?',
    'שאלה זו עוסקת באמות המידה המרכזיות למתן רשות ערעור לבית המשפט העליון ב''גלגול שלישי''. הלכת ''חניון חיפה'' קובעת רף מחמיר למתן רשות כזו, במטרה לשמור על מעמדו של בית המשפט העליון כקובע הלכה ולא כערכאת ערעור נוספת.',
    'הלכה פסוקה היא כי בית המשפט העליון ייעתר לבקשת רשות ערעור ב''גלגול שלישי'' רק במקרים חריגים, בהם מתעוררת שאלה משפטית עקרונית החורגת מעניינם הפרטני של הצדדים, או כאשר דחיית הבקשה למתן רשות ערעור תגרום לעיוות דין (Verdict: רע"א 103/82 חניון חיפה בע"מ נ'' מצת אור (הדר חיפה) בע"מ, פ"ד לו(3) 123 (1982)). אמות מידה אלו, המכונות ''הלכת חניון חיפה'', מיושמות באופן עקבי בפסיקת בית המשפט העליון (Verdict: רע"א 10031043 שלום טרבלסי נ'' נעמי צדוק (9.10.2025), Reference 1; Verdict: רע"א 11046116 אברהם זפרני נ'' החברה הכלכלית לפיתוח מגידו בע"מ (20.1.2026), Reference 2; Verdict: רע"א 8755741 עדנה שושנה רוזנשין נ'' בועז רוה (6.5.2025), Reference 10; Verdict: רע"א 6739948 רבין מגידש נ'' יואב מגידש (25.9.2024), Reference 11; Verdict: רע"א 11550449 עדי זהבה נוימן נ'' אריה בנבנישתי (11.3.2026), Reference 12; Verdict: רע"א 8073028 ביג אלום בע"מ נ'' באו-וורקה בע"מ (23.2.2025), Reference 13; Verdict: רע"א 9723586 פלונית נ'' לשכת הרווחה באשקלון (26.8.2025), Reference 14; Verdict: רע"א 4085180 דוד מימוני נ'' ש. שלמה רכב בע"מ (10.5.2017), Reference 15; Verdict: רע"א 5330498 פלוני נ'' קצין תגמולים (17.1.2021), Reference 16; Verdict: רע"א 5312998 יניב אביאל נ'' קיבוץ איל אגודה שיתופית (31.12.2020), Reference 17; Verdict: רע"א 5170967 חיים ארגי נ'' מדינת ישראל - רשות הפיתוח (2.8.2020), Reference 18; Verdict: רע"א 9282932 יוסף עטרי נ'' נופי די זהב יזמות בע"מ (1.7.2025), Reference 19; Verdict: בע"מ 6371497 פלונית נ'' פלוני (11.7.2024), Reference 20; Verdict: רע"א 5417302 פלוני נ'' האפוטרופוס הכללי (7.4.2021), Reference 24; Verdict: רע"א 5338756 נעמי קורצבנד נ'' ג''ני אליס קייל (21.1.2021), Reference 26; Verdict: רע"א 6090929 חאלד חיאדרה נ'' מדינת ישראל רשות מקרקעי ישראל (2.7.2023), Reference 27; Verdict: רע"א 5509839 דקל גבאי נ'' רשות מקרקעי ישראל (30.6.2021), Reference 62; Verdict: רע"א 2521361 אהרון ברוכין, עו"ד נ'' משה סורוצקין (17.10.2012), Reference 63; Verdict: רע"א 4752365 יצחק הוד נ'' בנק לאומי לישראל בע"מ (13.3.2019), Reference 41; Verdict: רע"א 5203852 נבוא פיננסים ומשכנתאות בע"מ נ'' דן אולשטיין (13.9.2020), Reference 42; Verdict: בע"מ 6133266 פלוני נ'' פלונית (31.8.2023), Reference 43; Verdict: רע"א 9749399 פלונית נ'' פלוני (31.8.2025), Reference 44; Verdict: רע"א 6740245 יעקב דידי נ'' עזיזי ברום (25.9.2024), Reference 45; Verdict: רע"א 6153380 ירון דהן נ'' עדי אגודה שיתופית להתיישבות בע"מ (27.9.2023), Reference 46; Verdict: רע"א 5390635 פלוני נ'' רשת מדיה בע"מ (9.3.2021), Reference 47; Verdict: רע"א 5333211 עזבון המנוחה מלכה עזר ז"ל נ'' פרויקט לוגאנו יהוד בע"מ (18.1.2021), Reference 48; Verdict: רע"א 6376109 פלונית נ'' פלוני (16.7.2024), Reference 49; Verdict: רע"א 8245353 אופק ים ספנות בע"מ נ'' פרח מחזור והובלות בע"מ (11.3.2025), Reference 50; Verdict: רע"א 6332143 אורן אפל נ'' אמור קנצפולסקי (21.5.2024), Reference 51; Verdict: רע"א 5354106 מטרולייט בע"מ נ'' עיריית נתניה (4.2.2021), Reference 52; Verdict: בע"מ 4711969 פלוני נ'' פלונית (28.1.2019), Reference 53; Verdict: בע"מ 5367722 פלונית נ'' פלוני (16.2.2021), Reference 54; Verdict: רע"א 5631517 חוסני צאלח משאקי נ'' מדינת ישראל (6.12.2021), Reference 55; Verdict: רע"א 5369585 עמוס גבעון נ'' נעמי וייל (21.2.2021), Reference 56; Verdict: רע"א 5368996 הרוניאן פרויז נ'' אמיר אלעד (18.2.2021), Reference 57; Verdict: בע"מ 5116534 פלוני נ'' האפוטרופוס הכללי מחוז חיפה והצפון (4.6.2020), Reference 58; Verdict: רע"א 5424061 יוסי שקד נ'' מייקל זלמנסון (14.4.2021), Reference 59; Verdict: רע"א 5353807 משה שחרור נ'' האחים ממן שירותי תיירות בע"מ (3.2.2021), Reference 60; Verdict: בע"מ 5826261 פלונית נ'' פלונית (11.7.2022), Reference 61; Verdict: בע"מ 6298819 פלוני נ'' היועץ המשפטי לממשלה (4.4.2024), Reference 33; Verdict: רע"א 6309201 פלוני נ'' פלוני (16.4.2024), Reference 37; Verdict: רע"א 6197498 פלוני נ'' משרד הבריאות (27.11.2023), Reference 38; Verdict: בע"מ 6085726 פלוני נ'' פלונית (25.6.2023), Reference 39; Verdict: רע"א 2599634 המפדה האזרחי בע"מ נ'' אברהם נחמיאס (30.12.2012), Reference 40; Verdict: רע"א 4802598 פלוני נ'' הוועדה הפסיכיאטרית המיוחדת (19.5.2019), Reference 73; Verdict: רע"א 4978390 צמח בן יונה נ'' עירית תל אביב - יפו (22.12.2019), Reference 74; Verdict: רע"א 4673136 ויקטור רוסיליו נ'' מועצה מקומית חצור הגלילית (20.12.2018), Reference 76; Verdict: רע"א 5139777 יוסף שמואל נ'' עופר חדד (28.6.2020), Reference 77; Verdict: רע"א 5616540 דניאל אברהמיאן נ'' ששון אלבק (15.11.2021), Reference 72).',
    'הסטודנט עלול לטעות ולחשוב שכל טעות משפטית או עובדתית בפסק דין של ערכאת ערעור מצדיקה מתן רשות ערעור לבית המשפט העליון, מבלי להבין את הרף הגבוה שנקבע בהלכת ''חניון חיפה''.',
    '["רשות ערעור", "גלגול שלישי", "הלכת חניון חיפה", "שאלה משפטית עקרונית", "עיוות דין", "סמכות בית המשפט העליון"]'::jsonb,
    '**וריאציה 1 — התנאים המצטברים:** מהם התנאים למתן רשות ערעור ב''גלגול שלישי''? ← שאלה משפטית עקרונית החורגת מעניינם הפרטני של הצדדים, או עיוות דין (הלכת חניון חיפה). **וריאציה 2 — מטרת ההלכה:** מדוע נקבע רף מחמיר למתן רשות ערעור ב''גלגול שלישי''? ← כדי לשמור על מעמדו של בית המשפט העליון כקובע הלכה ולא כערכאת ערעור נוספת (רע"א 10031043 טרבלסי, רפרנס 1). **וריאציה 3 — יישום ההלכה:** האם טענות ערעוריות רגילות מספיקות? ← לא, טענות הממוקדות בנסיבותיו הפרטניות של המקרה אינן מצדיקות רשות ערעור (רע"א 8755741 רוזנשין, רפרנס 10).',
    'רשות ערעור ב''גלגול שלישי'' תינתן רק במקרים חריגים של שאלה משפטית עקרונית או עיוות דין, בהתאם להלכת ''חניון חיפה'' (רע"א 103/82 חניון חיפה).',
