  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'אי-התערבות ערכאת ערעור בממצאים עובדתיים', 2, 'ראובן הגיש בקשת רשות ערעור לבית המשפט העליון על פסק דין של בית המשפט המחוזי, בטענה כי בית המשפט המחוזי שגה בקביעותיו העובדתיות. מהי עמדת בית המשפט העליון כלפי התערבות בממצאים עובדתיים ב''גלגול שלישי''?',
    'שאלה זו בוחנת את עקרון אי-ההתערבות של ערכאת הערעור, ובפרט בית המשפט העליון ב''גלגול שלישי'', בממצאים עובדתיים שנקבעו על ידי הערכאות הנמוכות. עקרון זה נובע מהיתרון של הערכאה הדיונית שהתרשמה ישירות מהראיות ומהעדים.',
    'הלכה פסוקה היא כי ערכאת הערעור אינה נוטה להתערב בקביעות העובדתיות של הערכאה הדיונית, וקל וחומר שאין בטענות מסוג זה כדי להצדיק מתן רשות ערעור ב''גלגול שלישי'', אלא במקרים חריגים ונדירים ביותר (Verdict: רע"א 10031043 שלום טרבלסי נ'' נעמי צדוק (9.10.2025), Reference 1; Verdict: רע"א 34132-06-25 פארג'' אלסעדיין נ'' רשות מקרקעי ישראל (8.7.2025), Reference 7; Verdict: בע"מ 6371497 פלונית נ'' פלוני (11.7.2024), Reference 20; Verdict: רע"א 2567/24 פלוני נ'' פלוני (16.4.2024), Reference 37; Verdict: רע"א 3357701 ג''אד בשארה חאג'' נ'' חביב חאג'' (12.3.2015), Reference 31; Verdict: רע"א 622/24 ציון גל טל מובילים 2500 בע"מ נ'' סחלב ייבוא ושיווק נופש בע"מ (21.7.2024), Reference 28; Verdict: רע"א 37401-09-24 שאול דוד פריאנטו נ'' עיניה וינשטיין (3.3.2025), Reference 32; Verdict: רע"א 8245353 אופק ים ספנות בע"מ נ'' פרח מחזור והובלות בע"מ (11.3.2025), Reference 50). זאת, משום שהערכאה הדיונית היא זו ששמעה את העדים והתרשמה מהם באופן בלתי אמצעי. טענות המבקשים הממוקדות בקביעות עובדתיות נטועות עמוק בגדרי עניינם הפרטני של הצדדים, ואינן מעוררות שאלה משפטית עקרונית החורגת מעניינם (Verdict: רע"א 8073028 ביג אלום בע"מ נ'' באו-וורקה בע"מ (23.2.2025), Reference 13).',
    'הסטודנט עלול לטעות ולחשוב שבית המשפט העליון יתערב בממצאים עובדתיים בקלות יחסית, בדומה לערכאת ערעור ראשונה, מבלי להבין את ההבחנה בין ''גלגול שני'' ל''גלגול שלישי'' ואת הרף הגבוה להתערבות בממצאים עובדתיים.',
    '["רשות ערעור", "גלגול שלישי", "ממצאים עובדתיים", "קביעות מהימנות", "אי-התערבות ערכאת ערעור", "שאלה משפטית עקרונית"]'::jsonb,
    '**וריאציה 1 — התערבות בממצאים עובדתיים:** האם בית המשפט העליון מתערב בממצאים עובדתיים ב''גלגול שלישי''? ← ככלל לא, אלא במקרים חריגים ונדירים ביותר (רע"א 10031043 טרבלסי, רפרנס 1). **וריאציה 2 — רציונל אי-ההתערבות:** מדוע בית המשפט העליון ממעט להתערב בממצאים עובדתיים? ← הערכאה הדיונית התרשמה מהעדים באופן בלתי אמצעי (רע"א 34132-06-25 אלסעדיין, רפרנס 7). **וריאציה 3 — טענות ערעוריות:** האם טענות הממוקדות בקביעות עובדתיות מצדיקות רשות ערעור ב''גלגול שלישי''? ← לא, הן נטועות בעניין הפרטני ואינן מעוררות שאלה עקרונית (רע"א 8073028 ביג אלום, רפרנס 13).',
    'בית המשפט העליון ב''גלגול שלישי'' ממעט להתערב בממצאים עובדתיים שנקבעו בערכאות קמא, אלא במקרים חריגים ונדירים ביותר (רע"א 10031043 טרבלסי).',
    '["רע\"א 10031043 שלום טרבלסי נ'' נעמי צדוק (9.10.2025)", "רע\"א 34132-06-25 פארג'' אלסעדיין נ'' רשות מקרקעי ישראל (8.7.2025)", "בע\"מ 6371497 פלונית נ'' פלוני (11.7.2024)", "רע\"א 2567/24 פלוני נ'' פלוני (16.4.2024)", "רע\"א 3357701 ג''אד בשארה חאג'' נ'' חביב חאג'' (12.3.2015)", "רע\"א 622/24 ציון גל טל מובילים 2500 בע\"מ נ'' סחלב ייבוא ושיווק נופש בע\"מ (21.7.2024)", "רע\"א 37401-09-24 שאול דוד פריאנטו נ'' עיניה וינשטיין (3.3.2025)", "רע\"א 8245353 אופק ים ספנות בע\"מ נ'' פרח מחזור והובלות בע\"מ (11.3.2025)", "רע\"א 8073028 ביג אלום בע\"מ נ'' באו-וורקה בע\"מ (23.2.2025)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'דחיית ערעור לפי תקנה 148(ב) לתקסד"א', 3, 'בית המשפט המחוזי דחה ערעור שהוגש אליו על פסק דין של בית משפט השלום, וכלל בנימוקיו רק את קביעתו בדבר דחיית הערעור, בהתאם לתקנה 148(ב) לתקנות סדר הדין האזרחי. המערער מבקש רשות ערעור לבית המשפט העליון בטענה כי דחייה כזו ללא הנמקה מפורטת מהווה עיוות דין. מה הדין?',
    'שאלה זו עוסקת בתקנה 148(ב) לתקנות סדר הדין האזרחי, תשע"ט-2018 (המקבילה לתקנה 460(ב) הישנה), המאפשרת לערכאת הערעור לדחות ערעור בנימוק קצר. היא בוחנת את היחס בין סמכות זו לבין חובת ההנמקה ואת השלכותיה על בקשות רשות ערעור לבית המשפט העליון.',
    'תקנה 148(ב) לתקנות סדר הדין האזרחי, תשע"ט-2018, קובעת כי "על אף האמור בתקנת משנה (א), בית משפט שהחליט לדחות ערעור רשאי לכלול בנימוקיו רק את קביעתו בדבר דחיית הערעור, ובלבד שנוכח כי מתקיימים התנאים האלה לגבי ההחלטה שעליה מערערים: (1) אין מקום לדחות את הממצאים העובדתיים שנקבעו בה; (2) הממצאים שנקבעו בה תומכים במסקנה המשפטית; (3) אין בה טעות שבחוק" (Law: תקנות סדר הדין האזרחי, תשע"ט-2018, סעיף 148). בית המשפט העליון קבע כי דחיית ערעור על יסוד תקנה 148(ב) אינה מהווה כשלעצמה עיוות דין, שכן היא מהווה למעשה אימוץ מלא של ההנמקה אשר שימשה את הכרעת בית המשפט דלמטה, עליה הוגש הערעור (Verdict: רע"א 6739948 רבין מגידש נ'' יואב מגידש (25.9.2024), Reference 11; Verdict: רע"א 8073028 ביג אלום בע"מ נ'' באו-וורקה בע"מ (23.2.2025), Reference 13; Verdict: רע"א 6090929 חאלד חיאדרה נ'' מדינת ישראל רשות מקרקעי ישראל (2.7.2023), Reference 27; Verdict: בע"מ 66852-06-25 פלוני נ'' פלונית (30.6.2025), Reference 23). עם זאת, כאשר בית המשפט דוחה ערעור על הסף ללא תשובה, הוא נדרש לציין את נימוקיו לכך שלערעור אין סיכוי להתקבל (Verdict: רע"א 6294062 עיריית חברון נ'' שר הביטחון (28.3.2024), Reference 35).',
    'הסטודנט עלול לטעות ולחשוב שכל דחיית ערעור בנימוק קצר מהווה פגם דיוני או עיוות דין, מבלי להכיר את ההסדר המיוחד של תקנה 148(ב) ואת תכליתו לייעל את הליכי הערעור.',
    '["תקנה 148(ב) לתקסד\"א", "דחיית ערעור", "חובת הנמקה", "עיוות דין", "אימוץ הנמקה", "גלגול שלישי"]'::jsonb,
    '**וריאציה 1 — תכלית תקנה 148(ב):** מה מאפשרת תקנה 148(ב) לערכאת הערעור? ← לדחות ערעור בנימוק קצר, אם התקיימו תנאים מסוימים (תקנה 148(ב) לתקסד"א). **וריאציה 2 — עיוות דין והנמקה:** האם דחייה לפי תקנה 148(ב) ללא הנמקה מפורטת מהווה עיוות דין? ← לא, היא מהווה אימוץ מלא של הנמקת הערכאה הדיונית ואינה עיוות דין כשלעצמה (רע"א 6739948 מגידש, רפרנס 11). **וריאציה 3 — דחייה על הסף ללא תשובה:** מה נדרש מערכאת הערעור כאשר היא דוחה ערעור על הסף ללא תשובה? ← לציין את נימוקיה לכך שלערעור אין סיכוי להתקבל (רע"א 6294062 עיריית חברון, רפרנס 35).',
    'דחיית ערעור לפי תקנה 148(ב) לתקסד"א, בנימוק קצר, אינה מהווה עיוות דין אם התנאים בתקנה התקיימו, שכן היא נחשבת לאימוץ הנמקת הערכאה הדיונית (רע"א 6739948 מגידש).',
    '["תקנות סדר הדין האזרחי, תשע\"ט-2018, סעיף 148", "רע\"א 6739948 רבין מגידש נ'' יואב מגידש (25.9.2024)", "רע\"א 8073028 ביג אלום בע\"מ נ'' באו-וורקה בע\"מ (23.2.2025)", "רע\"א 6090929 חאלד חיאדרה נ'' מדינת ישראל רשות מקרקעי ישראל (2.7.2023)", "בע\"מ 66852-06-25 פלוני נ'' פלונית (30.6.2025)", "רע\"א 6294062 עיריית חברון נ'' שר הביטחון (28.3.2024)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'ביקורת בג"ץ על החלטות בית המשפט העליון', 4, 'ראובן הגיש עתירה לבג"ץ נגד החלטה של בית המשפט העליון שדחתה בקשת רשות ערעור שהגיש. מהם התנאים להתערבות בג"ץ בהחלטות של בית המשפט העליון?',
    'שאלה זו עוסקת ביחסי הגומלין בין בית המשפט העליון בשבתו כערכאת ערעור אזרחית לבין בית המשפט העליון בשבתו כבית משפט גבוה לצדק (בג"ץ). היא מדגישה את העיקרון לפיו בג"ץ אינו משמש כערכאת ערעור על החלטות שיפוטיות של בית המשפט העליון עצמו, אלא במקרים חריגים ונדירים ביותר.',
    'הלכה פסוקה היא כי בית המשפט העליון בשבתו כבית משפט גבוה לצדק (בג"ץ) אינו יושב כערכאת ערעור על החלטות של ערכאות שיפוטיות אחרות, ובפרט כאשר מדובר בהחלטות שניתנו על ידי בית משפט זה עצמו (Verdict: בג"ץ 60068-12-25 ח''אלד ג''ואמיס נ'' בית המשפט העליון (24.12.2025), Reference 3; Verdict: בג"ץ 6334631 נעימה שחאדה נ'' בית המשפט העליון (26.5.2024), Reference 25; Verdict: דנג"ץ 68/24 הלן אייזן נ'' בית המשפט העליון ו-13 אח'' (7.2.2024), Reference 21). התערבות בג"ץ בהחלטות אלו שמורה למקרים חריגים ונדירים ביותר, בהם מתגלה טעות בסיסית היורדת לשורש ההליך השיפוטי, כמו חריגה מסמכות במובנה הצר או שרירות קיצונית (Verdict: בג"ץ 60068-12-25 ח''אלד ג''ואמיס נ'' בית המשפט העליון (24.12.2025), Reference 3, 4). אף אם נפלה טעות ביישום הדין, אין הדבר בא בגדר אותם מקרים חריגים ונדירים המצדיקים התערבות בג"ץ בהחלטה של בית המשפט העליון (Verdict: בג"ץ 60068-12-25 ח''אלד ג''ואמיס נ'' בית המשפט העליון (24.12.2025), Reference 4).',
    'הסטודנט עלול לטעות ולחשוב שבג"ץ מהווה ערכאת ערעור נוספת על החלטות בית המשפט העליון, מבלי להבין את ההבחנה בין תפקידיו השונים של בית המשפט העליון ואת הרף הגבוה להתערבות בג"ץ בהחלטות שיפוטיות של העליון.',
    '["בג\"ץ", "בית המשפט העליון", "ביקורת שיפוטית", "חריגה מסמכות", "שרירות קיצונית", "טעות היורדת לשורש ההליך"]'::jsonb,
    '**וריאציה 1 — מעמד בג"ץ:** האם בג"ץ משמש כערכאת ערעור על החלטות בית המשפט העליון? ← לא, אלא במקרים חריגים ונדירים ביותר (בג"ץ 60068-12-25 ג''ואמיס, רפרנס 3). **וריאציה 2 — תנאי התערבות:** מתי יתערב בג"ץ בהחלטות בית המשפט העליון? ← רק במקרים של טעות בסיסית היורדת לשורש ההליך, כמו חריגה מסמכות או שרירות קיצונית (בג"ץ 60068-12-25 ג''ואמיס, רפרנס 3). **וריאציה 3 — טעות ביישום הדין:** האם טעות ביישום הדין מצדיקה התערבות בג"ץ בהחלטת העליון? ← לא, אין הדבר בא בגדר אותם מקרים חריגים ונדירים (בג"ץ 60068-12-25 ג''ואמיס, רפרנס 4).',
    'בג"ץ אינו ערכאת ערעור על החלטות בית המשפט העליון, ויתערב רק במקרים חריגים ונדירים של טעות בסיסית היורדת לשורש ההליך, כגון חריגה מסמכות או שרירות קיצונית (בג"ץ 60068-12-25 ג''ואמיס).',
    '["בג\"ץ 60068-12-25 ח''אלד ג''ואמיס נ'' בית המשפט העליון (24.12.2025)", "בג\"ץ 6334631 נעימה שחאדה נ'' בית המשפט העליון (26.5.2024)", "דנג\"ץ 68/24 הלן אייזן נ'' בית המשפט העליון ו-13 אח'' (7.2.2024)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'רשות ערעור תינתן אם נפלה טעות משפטית בפסק הדין של בית המשפט המחוזי.', false, 'בחירה זו שגויה. טעות משפטית כשלעצמה אינה מספיקה למתן רשות ערעור ב''גלגול שלישי'', אלא אם היא עונה על אמות המידה המחמירות שנקבעו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'רשות ערעור תינתן רק במקרים חריגים, בהם מתעוררת שאלה משפטית עקרונית החורגת מעניינם הפרטני של הצדדים, או כאשר דחיית הבקשה תגרום לעיוות דין.', true, 'בחירה זו נכונה. זוהי הלכת ''חניון חיפה'' המהווה את אמת המידה המרכזית למתן רשות ערעור ב''גלגול שלישי''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'רשות ערעור תינתן אם בית המשפט העליון סבור שפסק הדין של בית המשפט המחוזי שגוי.', false, 'בחירה זו שגויה. שגגה בפסק הדין של הערכאה המחוזית אינה עילה מספקת למתן רשות ערעור ב''גלגול שלישי'', אלא אם היא עולה כדי שאלה עקרונית או עיוות דין.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'רשות ערעור תינתן בזכות, שכן זוהי ערכאת הערעור העליונה.', false, 'בחירה זו שגויה. ערעור לבית המשפט העליון על פסק דין של בית משפט מחוזי שניתן בערעור הוא ''רשות ערעור'' ולא ''ערעור בזכות''.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'בית המשפט העליון יתערב בממצאים עובדתיים אם מצא שנפלה בהם טעות.', false, 'בחירה זו שגויה. בית המשפט העליון אינו מתערב בכל טעות עובדתית, אלא רק במקרים חריגים ונדירים ביותר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'בית המשפט העליון לא יתערב ככלל בממצאים עובדתיים שנקבעו בערכאות קמא, אלא במקרים חריגים ונדירים ביותר.', true, 'בחירה זו נכונה. זוהי הלכה פסוקה ועקבית של בית המשפט העליון, הממעט להתערב בקביעות עובדתיות, ובמיוחד ב''גלגול שלישי''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'בית המשפט העליון יתערב בממצאים עובדתיים רק אם הם מבוססים על עדות יחידה.', false, 'בחירה זו שגויה. אף שעדות יחידה עשויה להשפיע על משקל הראיות, אין זה התנאי היחיד או האוטומטי להתערבות בממצאים עובדתיים ב''גלגול שלישי''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'בית המשפט העליון יתערב בממצאים עובדתיים אם הדבר נחוץ למניעת עיוות דין.', false, 'בחירה זו שגויה. אף שעיוות דין הוא תנאי למתן רשות ערעור, התערבות בממצאים עובדתיים ב''גלגול שלישי'' בשל עיוות דין שמורה למקרים קיצוניים ביותר, ולא לכל טעות עובדתית.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'דחיית ערעור לפי תקנה 148(ב) ללא הנמקה מפורטת מהווה עיוות דין המצדיק מתן רשות ערעור בגלגול שלישי.', false, 'בחירה זו שגויה. הפסיקה קבעה כי דחיית ערעור לפי תקנה 148(ב) אינה מהווה עיוות דין כשלעצמה, שכן היא מהווה אימוץ של הנמקת הערכאה הדיונית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'דחיית ערעור לפי תקנה 148(ב) אינה מהווה כשלעצמה עיוות דין, שכן היא מהווה אימוץ מלא של הנמקת הערכאה הדיונית, ובלבד שהתקיימו התנאים המנויים בתקנה.', true, 'בחירה זו נכונה. תקנה 148(ב) מאפשרת לערכאת הערעור לדחות ערעור בנימוק קצר, ובית המשפט העליון קבע כי אין בכך עיוות דין אם התנאים בתקנה התקיימו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בית המשפט המחוזי אינו רשאי לדחות ערעור לפי תקנה 148(ב) ללא הנמקה מפורטת.', false, 'בחירה זו שגויה. בית המשפט המחוזי רשאי לדחות ערעור לפי תקנה 148(ב) בנימוק קצר, אם התקיימו התנאים המפורטים בתקנה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'בית המשפט העליון יתערב רק אם המערער יוכיח שההחלטה ניתנה בחוסר סמכות.', false, 'בחירה זו שגויה. חוסר סמכות הוא עילה להתערבות בג"ץ, אך לא התנאי היחיד להתערבות בית המשפט העליון בהחלטה שניתנה לפי תקנה 148(ב).', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'בג"ץ ישמש כערכאת ערעור על החלטות בית המשפט העליון אם נפלה טעות משפטית.', false, 'בחירה זו שגויה. בג"ץ אינו משמש כערכאת ערעור על החלטות שיפוטיות של בית המשפט העליון, אלא במקרים חריגים ביותר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'בג"ץ יתערב רק במקרים חריגים ונדירים ביותר, בהם מתגלה טעות בסיסית היורדת לשורש ההליך השיפוטי, כמו חריגה מסמכות במובנה הצר או שרירות קיצונית.', true, 'בחירה זו נכונה. זוהי ההלכה הפסוקה המצמצמת מאוד את התערבות בג"ץ בהחלטות של בית המשפט העליון עצמו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'בג"ץ יתערב אם ההחלטה של בית המשפט העליון סותרת הלכה קודמת של בג"ץ.', false, 'בחירה זו שגויה. אף שסתירה להלכה קודמת עשויה להיות עילה לדיון נוסף, אין זה התנאי היחיד או האוטומטי להתערבות בג"ץ בהחלטות של בית המשפט העליון.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בג"ץ יתערב אם ההחלטה של בית המשפט העליון גורמת לעיוות דין חמור.', false, 'בחירה זו שגויה. עיוות דין הוא תנאי למתן רשות ערעור ב''גלגול שלישי'', אך לא מספיק להתערבות בג"ץ בהחלטות של בית המשפט העליון עצמו, שם הרף גבוה בהרבה.', 4);

END $$;

-- ============================================================
-- Q31 — 2019-S-Q31 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q31';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q31 skipped: external_id % already exists', '2019-S-Q31';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q31', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'רונן מעוניין לבקש מבית המשפט לעניינים מינהליים להעיד עד שאינו מצהיר במסגרת עתירתו המינהלית. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 31}'::jsonb,
    'השאלה עוסקת בסדרי הדין והראיות הייחודיים לבית המשפט לעניינים מינהליים, ובפרט בסמכותו להרשות השמעת עד שאינו מצהיר. היא מדגישה את הכלל לפיו הדיון מתבסס על תצהירים, ואת החריג המאפשר בירור עובדתי במקרים חריגים, תוך שמירה על אופי ההליך המינהלי.',
    'תקנה 15(ה) לתקנות בתי משפט לענינים מינהליים (סדרי דין), תשס"א-2000, קובעת כי "ראה בית המשפט שהדבר דרוש לשם הכרעה בעתירה, רשאי הוא, לאחר שנתן לשאר בעלי הדין הזדמנות להגיב לבקשה, ומטעמים מיוחדים שיירשמו, להרשות השמעת עד שאינו מצהיר בנושא ובהיקף שיקבע בית המשפט" (Law: תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס"א-2000, סעיף 15). הוראה זו משקפת את הכלל לפיו סדרי הדיון והראיות בבית המשפט לעניינים מינהליים דומים לאלה הנהוגים בבג"ץ, וברגיל יתמצו ההליכים בהגשת תצהירים בלי לשמוע עדים ולנהל הליכי חקירה שכנגד (Verdict: עת"מ (מינהליים ת"א) 53721-12-23 יהלום חממי נ'' משרד הבינוי והשיכון/אגף איכלוס (8.2.2024), Reference 1, 2; Verdict: עע"מ 10811/04 מוחמד עבדאללה סורחי ו-20 אח'' נ'' משרד הפנים (17.3.2005), Reference 5). השמעת עד שאינו מצהיר היא הליך חריג ביותר, והיא תותר רק אם הדבר דרוש לשם הכרעה בעתירה ומטעמים מיוחדים שיירשמו (Verdict: עת"מ (מינהליים ת"א) 4375102 קלוד שרקאוי נ'' עיריית תל-אביב (14.2.2018), Reference 17; Literature: יצחק זמיר, הסמכות המינהלית, כרך ד - סדרי הביקורת המשפטית (2017) | פרק 74: דיני ראיות, עמ'' 58). הנטל להוכיח את נחיצות החקירה מוטל על המבקש (Verdict: עת"מ (מינהליים י-ם) 6516-10-25 מד פארק בע"מ נ'' המועצה הדתית ירושלים (22.1.2026), Reference 23).',
    'הסטודנט עלול לטעות ולחשוב ששמיעת עדים שאינם מצהירים היא הליך שגרתי בעתירה מינהלית, או שבית המשפט חייב להיענות לבקשה כזו, מבלי להבין את אופיו החריג של הליך זה ואת שיקול הדעת הרחב הנתון לבית המשפט.',
    '["עתירה מינהלית", "עד שאינו מצהיר", "תקנה 15(ה) לתקנות בתי משפט לענינים מינהליים", "שיקול דעת שיפוטי", "טעמים מיוחדים", "הכרעה צודקת ומהירה"]'::jsonb,
    '**וריאציה 1 — הכלל:** האם בית המשפט המינהלי שומע עדים שאינם מצהירים כדבר שבשגרה? ← לא, הדיון מתמצה ברגיל בתצהירים (תקנה 15(ה) לתקנות בתי משפט לענינים מינהליים). **וריאציה 2 — החריג:** מתי בית המשפט רשאי להרשות השמעת עד שאינו מצהיר? ← אם ראה שהדבר דרוש לשם הכרעה בעתירה, לאחר תגובת הצדדים ומטעמים מיוחדים שיירשמו (תקנה 15(ה) לתקנות בתי משפט לענינים מינהליים). **וריאציה 3 — נטל ההוכחה:** על מי מוטל הנטל להוכיח את נחיצות העדות? ← על המבקש להתיר את העדות (עת"מ (י-ם) 6516-10-25 מד פארק, רפרנס 23).',
    'בית המשפט לעניינים מינהליים רשאי להעיד עד שאינו מצהיר, אך זאת במקרים חריגים ביותר, אם הדבר דרוש להכרעה בעתירה, לאחר שנתן לשאר בעלי הדין הזדמנות להגיב לבקשה, ומטעמים מיוחדים שיירשמו (תקנה 15(ה) לתקנות בתי משפט לענינים מינהליים).',
    '["תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס\"א-2000, סעיף 15", "עת\"מ (מינהליים ת\"א) 53721-12-23 יהלום חממי נ'' משרד הבינוי והשיכון/אגף איכלוס (8.2.2024)", "עע\"מ 10811/04 מוחמד עבדאללה סורחי ו-20 אח'' נ'' משרד הפנים, נט(6) 411 (17.3.2005)", "עת\"מ (מינהליים ת\"א) 4375102 קלוד שרקאוי נ'' עיריית תל-אביב (14.2.2018)", "עת\"מ (מינהליים י-ם) 6516-10-25 מד פארק בע\"מ נ'' המועצה הדתית ירושלים (22.1.2026)", "יצחק זמיר, הסמכות המינהלית, כרך ד - סדרי הביקורת המשפטית (2017) | פרק 74: דיני ראיות, עמ'' 58"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'בית המשפט לעניינים מינהליים אינו רשאי להעיד עד שאינו מצהיר במסגרת עתירה מינהלית.', false, 'בחירה זו שגויה. בית המשפט לעניינים מינהליים רשאי להעיד עד שאינו מצהיר, אך זאת במקרים חריגים ובהתאם לתנאים הקבועים בתקנה 15(ה) לתקנות בתי משפט לענינים מינהליים (סדרי דין).', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית המשפט לעניינים מינהליים אינו רשאי להעיד עד שאינו מצהיר זולת אם ניתנה לכך הסכמת הצדדים.', false, 'בחירה זו שגויה. הסכמת הצדדים אינה תנאי הכרחי להעדת עד שאינו מצהיר, אלא נדרשת הזדמנות לשאר בעלי הדין להגיב לבקשה, וכן טעמים מיוחדים שיירשמו.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית המשפט לעניינים מינהליים חייב להעיד עד שאינו מצהיר אם ראה כי הדבר דרוש לשם הכרעה בעתירה, ורשאי לקבוע את הנושא וההיקף.', false, 'בחירה זו שגויה. בית המשפט ''רשאי'' להעיד עד שאינו מצהיר, ולא ''חייב'', וזאת מטעמים מיוחדים שיירשמו, בנוסף לכך שהדבר דרוש לשם הכרעה בעתירה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'בית המשפט לעניינים מינהליים רשאי להעיד עד שאינו מצהיר לאחר שנתן לשאר בעלי הדין הזדמנות להגיב לבקשה, ובנושא ובהיקף שיקבע בית המשפט.', true, 'בחירה זו נכונה. תקנה 15(ה) לתקנות בתי משפט לענינים מינהליים (סדרי דין) קובעת כי בית המשפט רשאי להרשות השמעת עד שאינו מצהיר, אם הדבר דרוש לשם הכרעה בעתירה, לאחר שנתן לשאר בעלי הדין הזדמנות להגיב לבקשה, ומטעמים מיוחדים שיירשמו, ובנושא ובהיקף שיקבע.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'חקירת מצהיר בעתירה מינהלית', 1, 'רונן מעוניין לבקש מבית המשפט לעניינים מינהליים לחקור מצהיר של הצד שכנגד במסגרת עתירתו המינהלית. מה הדין?',
    'שאלה זו עוסקת בסמכותו של בית המשפט לעניינים מינהליים להתיר חקירת מצהיר של בעל דין שכנגד. היא מדגישה את הכלל לפיו הדיון בעתירה מינהלית מתבסס על תצהירים, ואת החריג המאפשר חקירה במקרים בהם היא חיונית להכרעה.',
    'תקנה 15(א) לתקנות בתי משפט לענינים מינהליים (סדרי דין), תשס"א-2000, קובעת כי "בית המשפט ידון בעתירה על פי ראיות שיובאו בתצהירים, ואולם רשאי הוא, לבקשת בעל דין, להתיר חקירת מצהיר של בעל הדין שכנגד, אם ראה כי הדבר דרוש לשם הכרעה בעתירה" (Law: תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס"א-2000, סעיף 15). הכלל הוא שהדיון מתמצה בהגשת תצהירים, וחקירת מצהירים היא חריג לכלל זה (Verdict: עת"מ (מינהליים ת"א) 53721-12-23 יהלום חממי נ'' משרד הבינוי והשיכון/אגף איכלוס (8.2.2024), Reference 1, 2). הנטל להוכיח את נחיצות החקירה מוטל על המבקש (Verdict: עת"מ (מינהליים י-ם) 6516-10-25 מד פארק בע"מ נ'' המועצה הדתית ירושלים (22.1.2026), Reference 23). בית המשפט יתיר חקירה במקרים בהם קיימת מחלוקת עובדתית מהותית, שאינה ניתנת לפתרון על יסוד התצהירים והמסמכים, וכאשר החקירה חיונית לבירור האמת (Verdict: עת"מ (מינהליים י-ם) 6516-10-25 מד פארק בע"מ נ'' המועצה הדתית ירושלים (22.1.2026), Reference 23).',
    'הסטודנט עלול לטעות ולחשוב שחקירת מצהירים בעתירה מינהלית היא הליך שגרתי, בדומה להליך אזרחי רגיל, מבלי להבין את אופיו הייחודי של ההליך המינהלי ואת היותה של חקירת מצהירים חריג לכלל.',
    '["עתירה מינהלית", "חקירת מצהיר", "תקנה 15(א) לתקנות בתי משפט לענינים מינהליים", "ראיות בתצהירים", "חריג לכלל", "מחלוקת עובדתית מהותית"]'::jsonb,
    '**וריאציה 1 — הכלל:** האם חקירת מצהיר היא הליך שגרתי בעתירה מינהלית? ← לא, הדיון מתמצה ברגיל בהגשת תצהירים (תקנה 15(א) לתקנות בתי משפט לענינים מינהליים). **וריאציה 2 — החריג:** מתי בית המשפט יתיר חקירת מצהיר? ← אם ראה כי הדבר דרוש לשם הכרעה בעתירה (תקנה 15(א) לתקנות בתי משפט לענינים מינהליים). **וריאציה 3 — נטל ההוכחה:** על מי מוטל הנטל להוכיח את נחיצות החקירה? ← על המבקש להתיר את החקירה (עת"מ (י-ם) 6516-10-25 מד פארק, רפרנס 23).',
    'בית המשפט לעניינים מינהליים רשאי להתיר חקירת מצהיר של בעל דין שכנגד, אם ראה כי הדבר דרוש לשם הכרעה בעתירה, אך זהו חריג לכלל הדיון בתצהירים (תקנה 15(א) לתקנות בתי משפט לענינים מינהליים).',
    '["תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס\"א-2000, סעיף 15", "עת\"מ (מינהליים ת\"א) 53721-12-23 יהלום חממי נ'' משרד הבינוי והשיכון/אגף איכלוס (8.2.2024)", "עת\"מ (מינהליים י-ם) 6516-10-25 מד פארק בע\"מ נ'' המועצה הדתית ירושלים (22.1.2026)", "נבו - המתמחה, מערכת בתי המשפט (2026) | עתירה מינהלית, עמ'' 69"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'אופי הדיון וסדרי הראיות בעתירה מינהלית', 2, 'מהם העקרונות המנחים את סדרי הדיון והראיות בבית המשפט לעניינים מינהליים, וכיצד הם שונים מהליך אזרחי רגיל?',
    'שאלה זו מתמקדת באופי הייחודי של הדיון וסדרי הראיות בבית המשפט לעניינים מינהליים, המושפעים מסדרי הדין בבג"ץ. היא מדגישה את הכלל של דיון בתצהירים ואת החריגים המאפשרים בירור עובדתי במקרים מסוימים.',
    'סעיף 8 לחוק בתי משפט לענינים מינהליים, תש"ס-2000, קובע כי בית המשפט לעניינים מינהליים ידון בעתירה מינהלית "בהתאם לעילות, לסמכויות ולסעדים שלפיהם דן בית המשפט העליון בשבתו כבית משפט גבוה לצדק, בשינויים המחויבים" (Verdict: עע"מ 10811/04 מוחמד עבדאללה סורחי ו-20 אח'' נ'' משרד הפנים (17.3.2005), Reference 5). על כן, סדרי הדיון והראיות בבית המשפט המינהלי דומים לאלה הנהוגים בבג"ץ, וברגיל יתמצו ההליכים בהגשת תצהירים בלי לשמוע עדים ולנהל הליכי חקירה שכנגד (Verdict: עת"מ (מינהליים ת"א) 53721-12-23 יהלום חממי נ'' משרד הבינוי והשיכון/אגף איכלוס (8.2.2024), Reference 1, 2; Verdict: עע"מ 10811/04 מוחמד עבדאללה סורחי ו-20 אח'' נ'' משרד הפנים (17.3.2005), Reference 5; Verdict: עת"מ (מינהליים חי'') 26997-12-23 אקספרס טכנולוגיות בע"מ נ'' ועדת המכרזים - המועצה המקומית ג''ת (3.3.2024), Reference 6; Verdict: עע"מ 7801/02 יצחק (אקא) מזרחי נ'' מלון חוף רון בע"מ (22.4.2004), Reference 8). תכליתו של בית המשפט לעניינים מינהליים לא הייתה הקמה של ערכאה דיונית שתפקידה לקבוע ממצאים עובדתיים בסכסוכים בין הפרט לרשות המינהלית, אלא לבחון את חוקיות החלטות הרשות (Verdict: עע"מ 10811/04 מוחמד עבדאללה סורחי ו-20 אח'' נ'' משרד הפנים (17.3.2005), Reference 5; Verdict: עת"מ (מינהליים חי'') 2704608 טכנולוגית להבים בע"מ נ'' עיריית נהריה (20.3.2013), Reference 18). עם זאת, בית המשפט רשאי להתיר חקירת מצהיר או השמעת עד שאינו מצהיר אם הדבר דרוש לשם הכרעה בעתירה, אך מדובר בחריג לכלל (Verdict: עת"מ (מינהליים ת"א) 53721-12-23 יהלום חממי נ'' משרד הבינוי והשיכון/אגף איכלוס (8.2.2024), Reference 1, 2; Law: תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס"א-2000, סעיף 15).',
    'הסטודנט עלול לטעות ולייחס לבית המשפט לעניינים מינהליים את אופי הדיון של בית משפט אזרחי רגיל, הכולל בירור עובדתי נרחב ושמיעת עדים כדבר שבשגרה, מבלי להבין את הדמיון לבג"ץ ואת הכלל של דיון בתצהירים.',
    '["עתירה מינהלית", "סדרי דין", "דיני ראיות", "בג\"ץ", "תצהירים", "חוק בתי משפט לענינים מינהליים"]'::jsonb,
    '**וריאציה 1 — אופי הדיון:** כיצד מתנהל הדיון בעתירה מינהלית ברגיל? ← בהגשת תצהירים ומסמכים, ללא שמיעת עדים וחקירות (תקנה 15 לתקנות בתי משפט לענינים מינהליים). **וריאציה 2 — הדמיון לבג"ץ:** למי דומים סדרי הדין והראיות בבית המשפט המינהלי? ← לאלה הנהוגים בבג"ץ (סעיף 8 לחוק בתי משפט לענינים מינהליים). **וריאציה 3 — תכלית בית המשפט המינהלי:** האם בית המשפט המינהלי הוא ערכאה דיונית לקביעת ממצאים עובדתיים? ← לא, תכליתו היא לבחון את חוקיות החלטות הרשות (עע"מ 10811/04 סורחי, רפרנס 5).',
    'סדרי הדיון והראיות בבית המשפט לעניינים מינהליים דומים לאלה שבבג"ץ, ומתמצים ברגיל בהגשת תצהירים, עם אפשרות חריגה לשמיעת עדים וחקירות אם הדבר דרוש להכרעה (סעיף 8 לחוק בתי משפט לענינים מינהליים ותקנה 15 לתקנות).',
    '["חוק בתי משפט לענינים מינהליים, תש\"ס-2000, סעיף 8", "תקנות בתי משפט לענינים מינהליים (סדרי דין), תשס\"א-2000, סעיף 15", "עת\"מ (מינהליים ת\"א) 53721-12-23 יהלום חממי נ'' משרד הבינוי והשיכון/אגף איכלוס (8.2.2024)", "עע\"מ 10811/04 מוחמד עבדאללה סורחי ו-20 אח'' נ'' משרד הפנים, נט(6) 411 (17.3.2005)", "עת\"מ (מינהליים חי'') 26997-12-23 אקספרס טכנולוגיות בע\"מ נ'' ועדת המכרזים - המועצה המקומית ג''ת (3.3.2024)", "עע\"מ 7801/02 יצחק (אקא) מזרחי נ'' מלון חוף רון בע\"מ, נח(4) 728 (22.4.2004)", "עת\"מ (מינהליים חי'') 2704608 טכנולוגית להבים בע\"מ נ'' עיריית נהריה (20.3.2013)", "יצחק זמיר, הסמכות המינהלית, כרך ד - סדרי הביקורת המשפטית (2017) | פרק 74: דיני ראיות, עמ'' 55"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'סמכות בית המשפט המינהלי לבירור עובדתי', 3, 'באיזה אופן ובאילו נסיבות יידרש בית המשפט לעניינים מינהליים לבחון באופן עצמאי ראיות ולקבוע ממצאים עובדתיים, חרף הכלל של דיון בתצהירים?',
    'שאלה זו בוחנת את היקף סמכותו של בית המשפט לעניינים מינהליים לבירור עובדתי. היא מדגישה את האיזון העדין בין אופי הביקורת השיפוטית המינהלית, המתמקדת בחוקיות החלטות הרשות, לבין הצורך לאפשר בירור עובדתי במקרים חריגים וחיוניים.',
    'אף שבית המשפט לעניינים מינהליים אינו ערכאה דיונית רגילה שתפקידה לקבוע ממצאים עובדתיים, לא מן הנמנע כי ייתכנו מקרים שבהם יידרש בית המשפט המינהלי לבחון באופן עצמאי את הראיות שעמדו בפני הרשות המינהלית, לשמוע עדויות ולקבוע ממצאים לגביהן (Verdict: עת"מ (מינהליים ת"א) 53721-12-23 יהלום חממי נ'' משרד הבינוי והשיכון/אגף איכלוס (8.2.2024), Reference 1; Verdict: עע"מ 10811/04 מוחמד עבדאללה סורחי ו-20 אח'' נ'' משרד הפנים (17.3.2005), Reference 3, 5). התערבות בממצאים שנקבעו על ידי הרשות, הגם שהיא אפשרית, תיעשה במשורה, בנסיבות מיוחדות ובשימת לב לרציונל של מעמד הרשות המינהלית כרשות מקצועית האמונה על העניינים שבסמכותה (Verdict: עת"מ (מינהליים ת"א) 53721-12-23 יהלום חממי נ'' משרד הבינוי והשיכון/אגף איכלוס (8.2.2024), Reference 1; Verdict: עע"מ 10811/04 מוחמד עבדאללה סורחי ו-20 אח'' נ'' משרד הפנים (17.3.2005), Reference 3). מקרים חריגים אלו כוללים, למשל, מחלוקת עובדתית מהותית שאינה ניתנת לפתרון על יסוד התצהירים והמסמכים, וכאשר החקירה חיונית לבירור האמת (Verdict: עת"מ (מינהליים י-ם) 6516-10-25 מד פארק בע"מ נ'' המועצה הדתית ירושלים (22.1.2026), Reference 23).',
    'הסטודנט עלול לטעות ולחשוב שבית המשפט המינהלי לעולם אינו מתערב בממצאים עובדתיים, או לחילופין, שהוא מתערב בהם בקלות יחסית, מבלי להבין את הרף הגבוה והנסיבות המיוחדות הנדרשות לכך.',
    '["בית המשפט לעניינים מינהליים", "בירור עובדתי", "ביקורת שיפוטית", "ממצאים עובדתיים", "חריג לכלל", "רציונל הרשות המינהלית"]'::jsonb,
    '**וריאציה 1 — הכלל:** האם בית המשפט המינהלי קובע ממצאים עובדתיים כערכאה דיונית? ← לא, תכליתו אינה הקמת ערכאה דיונית לקביעת ממצאים עובדתיים (עע"מ 10811/04 סורחי, רפרנס 5). **וריאציה 2 — החריג:** מתי בכל זאת יבחן בית המשפט המינהלי ראיות ויקבע ממצאים? ← במשורה, בנסיבות מיוחדות, כשיש מחלוקת עובדתית מהותית וחיונית לבירור האמת (עת"מ (ת"א) 53721-12-23 חממי, רפרנס 1; עת"מ (י-ם) 6516-10-25 מד פארק, רפרנס 23). **וריאציה 3 — רציונל ההתערבות:** מהו הרציונל המנחה התערבות בממצאים של הרשות? ← שימת לב למעמד הרשות המינהלית כרשות מקצועית האמונה על העניינים שבסמכותה (עע"מ 10811/04 סורחי, רפרנס 3).',
    'בית המשפט לעניינים מינהליים אינו ערכאה דיונית לקביעת ממצאים עובדתיים, אך רשאי, במשורה ובנסיבות מיוחדות, לבחון ראיות ולקבוע ממצאים כאשר הדבר חיוני להכרעה בעתירה (עע"מ 10811/04 סורחי).',
    '["עת\"מ (מינהליים ת\"א) 53721-12-23 יהלום חממי נ'' משרד הבינוי והשיכון/אגף איכלוס (8.2.2024)", "עע\"מ 10811/04 מוחמד עבדאללה סורחי ו-20 אח'' נ'' משרד הפנים, נט(6) 411 (17.3.2005)", "עת\"מ (מינהליים י-ם) 6516-10-25 מד פארק בע\"מ נ'' המועצה הדתית ירושלים (22.1.2026)", "עע\"מ 2611/08 שאול בנימין נ'' עיריית תל-אביב (5.5.2010), Reference 13", "עת\"מ (מינהליים חי'') 4188701 רמת טבעון-מעונות הורים בע\"מ רמת טבעון-מעונות הורים בע\"מ נ'' עיריית עכו (14.8.2017), Reference 22"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'סעד כספי בעתירה מינהלית', 4, 'ראובן הגיש עתירה מינהלית נגד החלטת רשות מקומית, ובמסגרתה הוא מבקש גם סעד כספי של השבת כספים ששילם. מה הדין לגבי הסעד הכספי?',
    'שאלה זו עוסקת בהבחנה בין סמכות בית המשפט לעניינים מינהליים לדון בחוקיות החלטות מינהליות לבין סמכותו לדון בסעדים כספיים. היא מדגישה את הכלל לפיו סעדים כספיים, ובפרט השבה, נדונים בבית המשפט האזרחי, למעט חריגים מפורשים בחוק.',
    'הלכה פסוקה היא כי לא ניתן לכרוך סעד כספי בעתירה מינהלית (Verdict: רע"א 11224/04 המועצה המקומית פרדסיה נ'' מוריס בלונדר (16.2.2005), Reference 15; Verdict: בר"מ 7511/14 מנהל הארנונה בעיריית תל אביב-יפו נ'' א.ק. יוניברס בע"מ (22.11.2016), Reference 25). כאשר הסעד המבוקש הוא סעד כספי, הסמכות העניינית נתונה לבית המשפט האזרחי (שלום או מחוזי, בהתאם לסכום התביעה) בדרך של הגשת תביעה כספית (Verdict: עת"מ (מינהליים חי'') 38793-08-20 ככר העיר ייזום והשקעות בע"מ נ'' ועדה מרחבית מורדות הכרמל (27.12.2020), Reference 20; Verdict: עת"מ (מינהליים מרכז) 4620832 מכון ויצמן למדע נ'' עיריית רחובות (4.11.2018), Reference 26). זאת, למעט מקרים פרטניים המנויים בסעיף 5(3) לחוק בתי משפט לענינים מינהליים, שבהם הותרה הגשת תובענה מינהלית לפיצויים (Verdict: עת"מ (מינהליים חי'') 38793-08-20 ככר העיר ייזום והשקעות בע"מ נ'' ועדה מרחבית מורדות הכרמל (27.12.2020), Reference 20). בית המשפט המינהלי אינו מיועד לתפקד כערכאה דיונית הקובעת ממצאים עובדתיים בסכסוכים כספיים (Verdict: עת"מ (מינהליים מרכז) 4620832 מכון ויצמן למדע נ'' עיריית רחובות (4.11.2018), Reference 26).',
    'הסטודנט עלול לטעות ולחשוב שכל סעד הקשור להחלטה מינהלית, כולל סעד כספי, נדון בבית המשפט לעניינים מינהליים, מבלי להבחין בין תקיפה ישירה של החלטה מינהלית לבין תביעה כספית.',
    '["עתירה מינהלית", "סעד כספי", "סמכות עניינית", "תביעה אזרחית", "תובענה מינהלית", "השבה"]'::jsonb,
    '**וריאציה 1 — סעד כספי בעתירה מינהלית:** האם ניתן לכרוך סעד כספי בעתירה מינהלית? ← ככלל לא (בר"מ 7511/14 מנהל הארנונה, רפרנס 25). **וריאציה 2 — סמכות לדון בסעד כספי:** היכן נדון סעד כספי של השבה? ← בבית המשפט האזרחי (עת"מ (חי'') 38793-08-20 ככר העיר, רפרנס 20). **וריאציה 3 — חריג לתביעה כספית:** מתי בית המשפט המינהלי מוסמך לדון בסעד כספי? ← במקרים ספציפיים של תובענה מינהלית לפיצויים המנויים בחוק (סעיף 5(3) לחוק בתי משפט לענינים מינהליים; עת"מ (חי'') 38793-08-20 ככר העיר, רפרנס 20).',
    'סעד כספי של השבה אינו נדון בעתירה מינהלית, אלא בתביעה נפרדת בבית המשפט האזרחי, למעט תובענות מינהליות לפיצויים המנויות בחוק (בר"מ 7511/14 מנהל הארנונה).',
    '["רע\"א 11224/04 המועצה המקומית פרדסיה נ'' מוריס בלונדר, נט(5) 473 (16.2.2005)", "בר\"מ 7511/14 מנהל הארנונה בעיריית תל אביב-יפו נ'' א.ק. יוניברס בע\"מ (22.11.2016)", "עת\"מ (מינהליים חי'') 38793-08-20 ככר העיר ייזום והשקעות בע\"מ נ'' ועדה מרחבית מורדות הכרמל (27.12.2020)", "עת\"מ (מינהליים מרכז) 4620832 מכון ויצמן למדע נ'' עיריית רחובות (4.11.2018)", "נבו - המתמחה, מערכת בתי המשפט (2026) | עתירה מינהלית, עמ'' 57"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'בית המשפט לעניינים מינהליים אינו רשאי להתיר חקירת מצהיר במסגרת עתירה מינהלית.', false, 'בחירה זו שגויה. בית המשפט לעניינים מינהליים רשאי להתיר חקירת מצהיר, אך זאת במקרים חריגים ובהתאם לתנאים הקבועים בתקנה 15(א) לתקנות בתי משפט לענינים מינהליים (סדרי דין).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'בית המשפט רשאי להתיר חקירת מצהיר אם ראה כי הדבר דרוש לשם הכרעה בעתירה.', true, 'בחירה זו נכונה. תקנה 15(א) לתקנות בתי משפט לענינים מינהליים (סדרי דין) קובעת כי בית המשפט רשאי להתיר חקירת מצהיר של בעל הדין שכנגד, אם ראה כי הדבר דרוש לשם הכרעה בעתירה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'בית המשפט חייב להתיר חקירת מצהיר אם הדבר דרוש לשם הכרעה בעתירה.', false, 'בחירה זו שגויה. בית המשפט ''רשאי'' להתיר חקירת מצהיר, ולא ''חייב'', וזאת נתון לשיקול דעתו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'בית המשפט רשאי להתיר חקירת מצהיר רק אם הצדדים הסכימו לכך.', false, 'בחירה זו שגויה. הסכמת הצדדים אינה תנאי הכרחי להתיר חקירת מצהיר, אלא שיקול דעתו של בית המשפט אם הדבר דרוש לשם הכרעה בעתירה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'הדיון בעתירה מינהלית מתנהל כהליך אזרחי רגיל, עם שמיעת עדים וחקירות נגדיות כדבר שבשגרה.', false, 'בחירה זו שגויה. סדרי הדין בעתירה מינהלית שונים מהליך אזרחי רגיל, ומתמצים ברגיל בהגשת תצהירים ללא שמיעת עדים וחקירות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'הדיון מתמצה ברגיל בהגשת תצהירים ומסמכים ללא שמיעת עדים וחקירות, בדומה לסדרי הדין בבג"ץ, אך בית המשפט רשאי לסטות מכך במקרים חריגים.', true, 'בחירה זו נכונה. סעיף 8 לחוק בתי משפט לענינים מינהליים ותקנה 15 לתקנות בתי משפט לענינים מינהליים (סדרי דין) קובעים כי סדרי הדין דומים לאלה הנהוגים בבג"ץ, ומתמצים בתצהירים, עם אפשרות חריגה לשמיעת עדים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'בית המשפט לעניינים מינהליים הוא ערכאה דיונית שתפקידה לקבוע ממצאים עובדתיים בסכסוכים בין הפרט לרשות המינהלית.', false, 'בחירה זו שגויה. תכליתו של בית המשפט לעניינים מינהליים אינה להיות ערכאה דיונית לקביעת ממצאים עובדתיים, אלא לבחון את חוקיות החלטות הרשות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'סדרי הדין בעתירה מינהלית זהים לחלוטין לסדרי הדין בבג"ץ, ללא כל שינויים או גמישות.', false, 'בחירה זו שגויה. אף שסדרי הדין דומים, הם כוללים ''שינויים המחויבים'' וגמישות מסוימת, במיוחד בכל הנוגע לאפשרות לבירור עובדתי במקרים דרושים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'בית המשפט המינהלי אינו מוסמך כלל לבחון באופן עצמאי ראיות ולקבוע ממצאים עובדתיים, שכן תפקידו הוא ביקורת שיפוטית בלבד.', false, 'בחירה זו שגויה. אף שתפקידו העיקרי הוא ביקורת שיפוטית, בית המשפט המינהלי רשאי, במקרים חריגים, לבחון ראיות ולקבוע ממצאים עובדתיים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'התערבות בממצאים שנקבעו על ידי הרשות תיעשה במשורה, בנסיבות מיוחדות, כאשר קיימת מחלוקת עובדתית מהותית שאינה ניתנת לפתרון על יסוד התצהירים והמסמכים, וכאשר החקירה חיונית לבירור האמת.', true, 'בחירה זו נכונה. הפסיקה קבעה כי התערבות בממצאים עובדתיים של הרשות תיעשה במשורה ובנסיבות מיוחדות, תוך שמירה על הרציונל של מעמד הרשות המינהלית כרשות מקצועית.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בית המשפט המינהלי יבחן ראיות ויקבע ממצאים עובדתיים בכל מקרה בו בעל דין טוען למחלוקת עובדתית.', false, 'בחירה זו שגויה. טענה למחלוקת עובדתית כשלעצמה אינה מספיקה, אלא נדרשת מחלוקת מהותית וחיוניות החקירה לבירור האמת, וזאת במשורה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'בית המשפט המינהלי יבחן ראיות ויקבע ממצאים עובדתיים רק בענייני מכרזים, לפי סעיף 5 לתוספת הראשונה לחוק.', false, 'בחירה זו שגויה. אף שבענייני מכרזים נדרש לעיתים בירור עובדתי, זו אינה המגבלה היחידה, והאפשרות קיימת גם במקרים חריגים אחרים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'בית המשפט לעניינים מינהליים מוסמך לדון בסעד כספי של השבה, שכן הוא נלווה לעתירה המינהלית.', false, 'בחירה זו שגויה. ככלל, לא ניתן לכרוך סעד כספי בעתירה מינהלית, למעט מקרים ספציפיים של תובענה מינהלית לפיצויים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'בית המשפט לעניינים מינהליים אינו מוסמך לדון בסעד כספי של השבה, ויש להגיש תביעה נפרדת לבית המשפט האזרחי.', true, 'בחירה זו נכונה. כאשר הסעד המבוקש הוא סעד כספי, הסמכות העניינית נתונה לבית המשפט האזרחי, אלא אם כן מדובר בתובענה מינהלית לפיצויים המנויה בחוק.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'בית המשפט לעניינים מינהליים מוסמך לדון בסעד כספי של השבה רק אם התשלום בוצע לאחר הגשת העתירה.', false, 'בחירה זו שגויה. אף שסמכות בית המשפט המינהלי אינה נשללת בדיעבד אם התשלום בוצע במהלך העתירה, זה מתייחס לתקיפת דרישת התשלום עצמה, ולא לסעד כספי של השבה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בית המשפט לעניינים מינהליים מוסמך לדון בסעד כספי של השבה רק אם מדובר בתקיפה עקיפה של דרישת התשלום.', false, 'בחירה זו שגויה. תקיפה עקיפה של דרישת תשלום מתבצעת בבית המשפט האזרחי, במסגרת תביעת השבה, ולא בבית המשפט המינהלי.', 4);

END $$;

-- ============================================================
-- Q32 — 2019-S-Q32 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q32';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q32 skipped: external_id % already exists', '2019-S-Q32';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q32', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'יעקב תבע את עשו בבית המשפט לתביעות קטנות. עשו הגיש כתב הגנה, ובדעתו להגיש גם כתב תביעה שכנגד בסכום של 100,000 ש"ח נגד יעקב. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 32}'::jsonb,
    'השאלה עוסקת בסמכותו של בית המשפט לתביעות קטנות לדון בתביעה שכנגד, ובפרט באפשרות של נתבע לפצל את תביעתו כאשר סכום התביעה שכנגד חורג מסמכותו העניינית של בית משפט זה. היא מדגישה את ההקלות הניתנות לנתבע בבית המשפט לתביעות קטנות, בניגוד למגבלות החלות על התובע.',
    'סעיף 61 לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "האמור בסעיף 60 אין בו כדי למנוע... (2) נתבע שהגיש תביעה-שכנגד לבית משפט לתביעות קטנות - מהגיש תביעה נפרדת לעודף תביעתו, בין לבית משפט לתביעות קטנות ובין לבית משפט אחר" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 61). הוראה זו מאפשרת לנתבע בבית המשפט לתביעות קטנות לפצל את תביעתו שכנגד: להגיש חלק ממנה (עד לתקרת הסמכות העניינית של בית המשפט לתביעות קטנות, שהייתה 33,900 ש"ח במועד השאלה וכיום 36,400 ש"ח) בבית המשפט לתביעות קטנות, ואת היתרה לתבוע בבית משפט השלום, וזאת ללא צורך בקבלת רשות לפיצול סעדים (Verdict: ת"ק (תביעות קטנות ראשל"צ) 25309-02-24 נתן שווימר נ'' משה נחימוביץ (6.4.2025), Reference 65, 67; Verdict: ת"ק (תביעות קטנות פ"ת) 3236/04 סקיטל ליאור נ'' משורר יובל (17.11.2005), Reference 75). הקלה זו לנתבע עומדת בניגוד למגבלה החלה על התובע, שאינו רשאי לפצל את תביעתו (Verdict: ת"ק (שלום פתח תקוה) 2558/05 שירלי חזן נ'' חב'' הדקה ה 90 בע"מ (17.1.2006), Reference 1, 2; Verdict: ת"ק (שלום פתח תקוה) 2562/06 שאול אהרן נ'' סקאל דיוטי פרי בע"מ (10.12.2006), Reference 5, 7).',
    'הסטודנט עלול לטעות ולחשוב שהכללים לפיצול סעדים זהים לתובע ולנתבע בבית המשפט לתביעות קטנות, מבלי להכיר את ההבחנה המפורשת בחוק המקלה עם הנתבע.',
    '["בית משפט לתביעות קטנות", "תביעה שכנגד", "פיצול סעדים", "סמכות עניינית", "חוק בתי המשפט", "הקלות לנתבע"]'::jsonb,
    '**וריאציה 1 — פיצול תביעה שכנגד:** האם נתבע בבית המשפט לתביעות קטנות רשאי לפצל תביעה שכנגד שסכומה חורג מהסמכות? ← כן, הוא רשאי להגיש חלק בבית המשפט לתביעות קטנות ואת היתרה בבית משפט אחר (סעיף 61(2) לחוק בתי המשפט). **וריאציה 2 — צורך ברשות:** האם נדרשת רשות לפיצול סעדים במקרה זה? ← לא, סעיף 61(2) לחוק בתי המשפט פוטר מכך. **וריאציה 3 — השוואה לתובע:** האם תובע רשאי לפצל תביעה באותו אופן? ← לא, התובע אינו רשאי לפצל את תביעתו (ת"ק (פ"ת) 2558/05 חזן, רפרנס 1).',
    'נתבע בבית המשפט לתביעות קטנות רשאי לפצל תביעה שכנגד שסכומה חורג מהסמכות, ולהגיש חלק ממנה בבית המשפט לתביעות קטנות ואת היתרה בבית משפט השלום, ללא צורך בבקשה לפיצול סעדים (סעיף 61(2) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 61", "ת\"ק (תביעות קטנות ראשל\"צ) 25309-02-24 נתן שווימר נ'' משה נחימוביץ (6.4.2025)", "ת\"ק (תביעות קטנות פ\"ת) 3236/04 סקיטל ליאור נ'' משורר יובל (17.11.2005)", "ת\"ק (שלום פתח תקוה) 2558/05 שירלי חזן נ'' חב'' הדקה ה 90 בע\"מ (17.1.2006)", "ת\"ק (שלום פתח תקוה) 2562/06 שאול אהרן נ'' סקאל דיוטי פרי בע\"מ (10.12.2006)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'עשו רשאי להגיש את כתב התביעה שכנגד לבית משפט השלום בלבד, מאחר שהסעד המבוקש אינו מצוי בתחום סמכותו של בית המשפט לתביעות קטנות.', false, 'בחירה זו שגויה. אף שהסכום המבוקש חורג מסמכות בית המשפט לתביעות קטנות, סעיף 61(2) לחוק בתי המשפט מאפשר לנתבע לפצל את תביעתו ולהגיש חלק ממנה בבית המשפט לתביעות קטנות.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'עשו רשאי להגיש את כתב התביעה שכנגד לבית המשפט לתביעות קטנות, מאחר שזוהי תביעה שכנגד שהוגשה במענה לכתב התביעה נגדו.', false, 'בחירה זו שגויה. הנתבע רשאי להגיש תביעה שכנגד בבית המשפט לתביעות קטנות, אך רק עד לתקרת הסמכות העניינית של בית משפט זה, ולא על סכום של 100,000 ש"ח.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'עשו רשאי להגיש כתב תביעה שכנגד לבית המשפט לתביעות קטנות על סכום של 33,900 ₪, וכן תביעה נפרדת לבית משפט השלום על יתרת הסכום, וזאת בלא צורך בבקשה לפיצול הסעד.', true, 'בחירה זו נכונה. סעיף 61(2) לחוק בתי המשפט [נוסח משולב] מאפשר לנתבע בבית המשפט לתביעות קטנות לפצל את תביעתו, להגיש תביעה שכנגד בסכום המקסימלי שבסמכות בית המשפט לתביעות קטנות (33,900 ש"ח לפי נתוני השאלה, כיום 36,400 ש"ח), ולתבוע את היתרה בבית משפט אחר, ללא צורך בבקשה לפיצול סעדים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'עשו רשאי להגיש כתב תביעה נפרד לבית משפט השלום בלבד, מאחר שבית המשפט לתביעות קטנות אינו מוסמך לדון בתביעה שכנגד.', false, 'בחירה זו שגויה. בית המשפט לתביעות קטנות מוסמך לדון בתביעה שכנגד, וסעיף 61(2) לחוק בתי המשפט מאפשר לנתבע לפצל את תביעתו בין בית המשפט לתביעות קטנות לבית משפט אחר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'הגשת תביעה שכנגד על ידי תאגיד בבית משפט לתביעות קטנות', 1, 'חברת ''אלפא בע"מ'' נתבעה בבית המשפט לתביעות קטנות על ידי לקוח. החברה מעוניינת להגיש תביעה שכנגד נגד הלקוח. מה הדין?',
    'שאלה זו עוסקת במגבלת הסמכות של בית המשפט לתביעות קטנות, לפיה רק ''יחיד'' רשאי להגיש תביעה. היא בוחנת את השלכת מגבלה זו על תאגידים המבקשים להגיש תביעה שכנגד, ומדגישה את תכלית הקמתו של בית משפט זה.',
    'סעיף 60 לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי בית המשפט לתביעות קטנות דן "בתביעות של יחיד". הפסיקה, ובפרט זו של השופט גבריאל שטרסמן, קבעה באופן עקבי כי תביעה שכנגד, כמוה כהודעת צד ג'', היא "תובענה לכל דבר ועניין" (Verdict: ת"ק (שלום פתח תקוה) 2558/05 שירלי חזן נ'' חב'' הדקה ה 90 בע"מ (17.1.2006), Reference 1, 2; Verdict: ת"ק (שלום פתח תקוה) 2562/06 שאול אהרן נ'' סקאל דיוטי פרי בע"מ (10.12.2006), Reference 5, 6; Verdict: ת"ק (שלום פתח תקוה) 3067/06 עאמר עבד אלחכים נ'' דוד בוכבינדר (29.1.2007), Reference 10, 11). לפיכך, תאגיד אינו רשאי להגיש תביעה שכנגד בבית המשפט לתביעות קטנות, שכן הדבר מנוגד ללשון החוק ולתכלית הקמתו של בית משפט זה, שנועד לאפשר ליחיד להתדיין ללא ייצוג משפטי מול גופים חזקים יותר (Verdict: ת"ק (שלום פתח תקוה) 2558/05 שירלי חזן נ'' חב'' הדקה ה 90 בע"מ (17.1.2006), Reference 1, 2; Verdict: ת"ק (שלום פתח תקוה) 2467/05 צבי קנר נ'' מועצת שהם (16.1.2006), Reference 50, 51).',
    'הסטודנט עלול לטעות ולחשוב שמעמד של נתבע מקנה לתאגיד זכות להגיש תביעה שכנגד בבית המשפט לתביעות קטנות, מבלי להבחין בין מעמד הנתבע למעמד התובע בבית משפט זה.',
    '["בית משפט לתביעות קטנות", "תביעה שכנגד", "תאגיד", "יחיד", "סעיף 60 לחוק בתי המשפט", "תכלית חקיקה"]'::jsonb,
    '**וריאציה 1 — תאגיד כתובע:** האם תאגיד רשאי להגיש תביעה בבית המשפט לתביעות קטנות? ← לא, בית המשפט דן רק בתביעות של יחיד (סעיף 60 לחוק בתי המשפט). **וריאציה 2 — תביעה שכנגד כתובענה:** האם תביעה שכנגד נחשבת לתובענה? ← כן, לכל דבר ועניין (ת"ק (פ"ת) 2558/05 חזן, רפרנס 1). **וריאציה 3 — השלכה על תאגיד:** האם תאגיד רשאי להגיש תביעה שכנגד בבית המשפט לתביעות קטנות? ← לא, שכן תביעה שכנגד היא תובענה, ותאגיד אינו יחיד (ת"ק (פ"ת) 2562/06 אהרן, רפרנס 5).',
    'תאגיד אינו רשאי להגיש תביעה שכנגד בבית המשפט לתביעות קטנות, שכן בית משפט זה דן אך ורק בתביעות של יחיד, ותביעה שכנגד נחשבת לתובענה (סעיף 60 לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 60", "ת\"ק (שלום פתח תקוה) 2558/05 שירלי חזן נ'' חב'' הדקה ה 90 בע\"מ (17.1.2006)", "ת\"ק (שלום פתח תקוה) 2562/06 שאול אהרן נ'' סקאל דיוטי פרי בע\"מ (10.12.2006)", "ת\"ק (שלום פתח תקוה) 3067/06 עאמר עבד אלחכים נ'' דוד בוכבינדר (29.1.2007)", "ת\"ק (שלום פתח תקוה) 2467/05 צבי קנר נ'' מועצת שהם (16.1.2006)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'תכלית הקמת בית המשפט לתביעות קטנות', 2, 'מהי התכלית העיקרית העומדת בבסיס הקמתו של בית המשפט לתביעות קטנות, וכיצד היא משפיעה על סדרי הדין בו?',
    'שאלה זו בוחנת את הרציונל והעקרונות המנחים את פעילותו של בית המשפט לתביעות קטנות. היא מדגישה את אופיו המיוחד של בית משפט זה, שנועד לספק מענה מהיר ונגיש לאזרח הפשוט, תוך סטייה מסדרי דין וראיות רגילים.',
    'הסיבה להקמת בית המשפט לתביעות קטנות נעוצה בתכלית לאפשר ליחיד להתדיין כתובע בדרך יעילה, זולה ומהירה (Verdict: ת"ק (שלום פתח תקוה) 2558/05 שירלי חזן נ'' חב'' הדקה ה 90 בע"מ (17.1.2006), Reference 1, 2; Verdict: ת"ק (שלום פתח תקוה) 2562/06 שאול אהרן נ'' סקאל דיוטי פרי בע"מ (10.12.2006), Reference 5, 7). מוסד זה נועד ליצור מכשיר זמין, לא יקר ומהיר לבירור תביעות בסדרי גודל קטנים יחסית, בעיקר בתחום הצרכנות, שאילו נדונו בדרך הרגילה, היו נעשות בלתי כדאיות (Verdict: ת"ק (תביעות קטנות ת"א) 37489-01-20 משה שומר נ'' עו"ד אלון שליכטר (22.4.2020), Reference 72, 73). הדיון בו מתנהל ללא עורכי דין (אלא ברשות מיוחדת), תוך הסרת מחסומים של דיני ראיות וסדר דין (סעיף 62 לחוק בתי המשפט) (Verdict: ת"ק (שלום פתח תקוה) 2558/05 שירלי חזן נ'' חב'' הדקה ה 90 בע"מ (17.1.2006), Reference 1, 2; Verdict: ת"ק (שלום פתח תקוה) 2562/06 שאול אהרן נ'' סקאל דיוטי פרי בע"מ (10.12.2006), Reference 5, 7). בית המשפט העליון הדגיש את מעמדו המיוחד של בית המשפט לתביעות קטנות כ"מחלקה בפני עצמה, בעלת תפקיד וסמכויות מוגדרים, הפועלת על-פי סדרי דין משלה, והיא בעלת צביון ייחודי, שונה משל בתי-משפט השלום הרגילים" (ע"א 292/93 סרבוז נ. אופק בע"מ, פ"ד מח, 3, 177) (Verdict: ת"ק (שלום פתח תקוה) 2558/05 שירלי חזן נ'' חב'' הדקה ה 90 בע"מ (17.1.2006), Reference 3, 4; Verdict: ת"ק (שלום פתח תקוה) 2562/06 שאול אהרן נ'' סקאל דיוטי פרי בע"מ (10.12.2006), Reference 5, 7).',
    'הסטודנט עלול לטעות ולחשוב שבית המשפט לתביעות קטנות הוא רק שלוחה של בית משפט השלום עם סמכות כספית מוגבלת, מבלי להבין את אופיו הייחודי והמטרות החברתיות-משפטיות שהביאו להקמתו.',
    '["בית משפט לתביעות קטנות", "תכלית חקיקה", "נגישות לצדק", "סדרי דין גמישים", "ייצוג משפטי", "סעיף 62 לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — מטרת ההקמה:** מהי המטרה העיקרית של בית המשפט לתביעות קטנות? ← לאפשר ליחיד להתדיין בדרך יעילה, זולה ומהירה (ת"ק (פ"ת) 2558/05 חזן, רפרנס 1). **וריאציה 2 — מאפייני הדיון:** כיצד מתנהל הדיון בבית המשפט לתביעות קטנות? ← ללא עורכי דין, תוך הסרת מחסומים של דיני ראיות וסדר דין (סעיף 62 לחוק בתי המשפט). **וריאציה 3 — מעמד ייחודי:** מהו מעמדו של בית המשפט לתביעות קטנות? ← מחלקה בפני עצמה, בעלת צביון ייחודי ושונה מבתי משפט השלום הרגילים (ע"א 292/93 סרבוז, רפרנס 3).',
    'בית המשפט לתביעות קטנות הוקם כדי לאפשר לאזרח הפשוט להתדיין בדרך יעילה, זולה ומהירה, ללא ייצוג משפטי, תוך הסרת מחסומים של דיני ראיות וסדר דין (סעיף 62 לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 59", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 62", "ת\"ק (שלום פתח תקוה) 2558/05 שירלי חזן נ'' חב'' הדקה ה 90 בע\"מ (17.1.2006)", "ת\"ק (שלום פתח תקוה) 2562/06 שאול אהרן נ'' סקאל דיוטי פרי בע\"מ (10.12.2006)", "ת\"ק (תביעות קטנות ת\"א) 37489-01-20 משה שומר נ'' עו\"ד אלון שליכטר (22.4.2020)", "ע\"א 292/93 סרבוז נ. אופק בע\"מ, פ\"ד מח, 3, 177"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'מעשה בית דין בתביעות קטנות', 3, 'ראובן הגיש תביעה בבית משפט לתביעות קטנות נגד שמעון בגין נזק לרכבו וזכה בפסק דין. כעת הוא מעוניין להגיש תביעה נוספת בבית משפט השלום נגד שמעון בגין נזקי גוף שנגרמו לו באותה תאונה. האם פסק הדין בתביעות קטנות יוצר מעשה בית דין החוסם את התביעה החדשה?',
    'שאלה זו עוסקת בעקרונות מעשה בית דין (השתק עילה והשתק פלוגתא) בהקשר של פסקי דין שניתנו בבית המשפט לתביעות קטנות. היא מדגישה את ההבחנה בין שני סוגי ההשתק ואת הגמישות הנדרשת בהחלת השתק עילה, לאור אופיו הייחודי של בית משפט זה.',
    'הלכה פסוקה היא כי עקרונות מעשה בית דין, הן השתק עילה והן השתק פלוגתא, חלים באופן עקרוני גם לגבי הליך של תביעות קטנות (Verdict: תאד"מ (שלום עכו) 13628-09-22 אדוארד ויינריב נ'' יעקב בוגנים (4.1.2024), Reference 68, 69; Verdict: רע"א 1958/06 סויסה נ'' חב'' צ''מפיון מוטורוס (ישראל) בע"מ (28.10.2012), Reference 69). עם זאת, הפסיקה מבחינה בין השתק פלוגתא, החל ללא קושי, לבין השתק עילה, שהחלתו מורכבת יותר. במקרים חריגים, כאשר נהיר לבית המשפט כי התובע בתביעות קטנות הגיש תביעה חלקית מתוך חוסר ידיעה או טיפל בנושא מתוחם, ניתן לפרש את השתק העילה באופן גמיש יותר (Verdict: רע"א 1958/06 סויסה נ'' חב'' צ''מפיון מוטורוס (ישראל) בע"מ (28.10.2012), Reference 69). במקרה של נזקי רכוש ונזקי גוף מאותה תאונה, מדובר בעילות תביעה שונות, ולכן השתק עילה לא יחול באופן אוטומטי על תביעת נזקי הגוף, במיוחד אם התובע לא יכול היה לכלול אותם בתביעה הקטנה או לא היה מודע להיקפם המלא.',
    'הסטודנט עלול לטעות ולחשוב שפסק דין בתביעות קטנות תמיד חוסם תביעות עתידיות באותה עילה, מבלי להכיר את הגמישות שנקבעה בפסיקה לגבי השתק עילה, במיוחד לאור אופיו הייחודי של בית המשפט לתביעות קטנות.',
    '["מעשה בית דין", "השתק עילה", "השתק פלוגתא", "בית משפט לתביעות קטנות", "גמישות שיפוטית", "רע\"א 1958/06 סויסה"]'::jsonb,
    '**וריאציה 1 — השתק פלוגתא:** האם השתק פלוגתא חל על פסקי דין בתביעות קטנות? ← כן, ללא קושי (רע"א 1958/06 סויסה, רפרנס 69). **וריאציה 2 — השתק עילה:** האם השתק עילה חל על פסקי דין בתביעות קטנות? ← עקרונית כן, אך בית המשפט ינהג בגמישות במקרים חריגים (רע"א 1958/06 סויסה, רפרנס 69). **וריאציה 3 — מקרים חריגים להשתק עילה:** אילו מקרים יצדיקו גמישות בהחלת השתק עילה? ← כאשר התובע הגיש תביעה חלקית מחוסר ידיעה או טיפל בנושא מתוחם (רע"א 1958/06 סויסה, רפרנס 69).',
    'פסק דין בתביעות קטנות יוצר מעשה בית דין. השתק פלוגתא חל ללא קושי, אך לגבי השתק עילה, בית המשפט ינהג בגמישות במקרים חריגים, כגון חוסר ידיעה של התובע (רע"א 1958/06 סויסה).',
    '["רע\"א 1958/06 סויסה נ'' חב'' צ''מפיון מוטורוס (ישראל) בע\"מ (28.10.2012)", "תאד\"מ (שלום עכו) 13628-09-22 אדוארד ויינריב נ'' יעקב בוגנים (4.1.2024)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'הגשת הודעת צד ג'' על ידי תאגיד בבית משפט לתביעות קטנות', 4, 'חברת ''בטא בע"מ'' נתבעה בבית המשפט לתביעות קטנות על ידי לקוח. החברה מעוניינת לשלוח הודעת צד ג'' לחברה אחרת, בטענה שהיא האחראית לנזק. מה הדין?',
    'שאלה זו בוחנת את סמכותו של בית המשפט לתביעות קטנות לדון בהודעות צד ג'' המוגשות על ידי תאגידים. היא מדגישה את העיקרון לפיו הודעת צד ג'' נחשבת לתובענה, ולכן כפופה למגבלת ''תביעות של יחיד'' הקבועה בחוק.',
    'הפסיקה קבעה באופן עקבי כי הודעת צד ג'', כמוה כתביעה שכנגד, היא "תובענה לכל דבר ועניין" (Verdict: ת"ק (שלום פתח תקוה) 2558/05 שירלי חזן נ'' חב'' הדקה ה 90 בע"מ (17.1.2006), Reference 1, 2; Verdict: ת"ק (שלום פתח תקוה) 2562/06 שאול אהרן נ'' סקאל דיוטי פרי בע"מ (10.12.2006), Reference 5, 7; Verdict: ת"ק (שלום פתח תקוה) 2961/05 צבי חיימוביץ נ'' סנטורס סוכנות נסיעות ותיירות בע"מ (26.2.2006), Reference 19, 20). מאחר שסעיף 60 לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי בית המשפט לתביעות קטנות דן "בתביעות של יחיד" בלבד, תאגיד אינו רשאי לשלוח הודעת צד ג'' בבית משפט זה (Verdict: ת"ק (שלום פתח תקוה) 2558/05 שירלי חזן נ'' חב'' הדקה ה 90 בע"מ (17.1.2006), Reference 1, 2; Verdict: ת"ק (שלום פתח תקוה) 2467/05 צבי קנר נ'' מועצת שהם (16.1.2006), Reference 50, 51). מתן אפשרות לתאגידים להגיש הודעות צד ג'' בבית המשפט לתביעות קטנות היה מסכל את כוונת המחוקק, שביקש לאפשר ליחיד להתדיין ללא ייצוג משפטי מול גופים חזקים יותר (Verdict: ת"ק (שלום פתח תקוה) 2558/05 שירלי חזן נ'' חב'' הדקה ה 90 בע"מ (17.1.2006), Reference 3, 4).',
    'הסטודנט עלול לטעות ולחשוב שהודעת צד ג'' היא הליך הגנתי גרידא, ולכן תאגיד רשאי להגישה, מבלי להבין את מעמדה המשפטי כתובענה ואת מגבלת ''היחיד'' בבית המשפט לתביעות קטנות.',
    '["בית משפט לתביעות קטנות", "הודעת צד ג''", "תאגיד", "יחיד", "סעיף 60 לחוק בתי המשפט", "תובענה"]'::jsonb,
    '**וריאציה 1 — מעמד הודעת צד ג'':** האם הודעת צד ג'' נחשבת לתובענה? ← כן, לכל דבר ועניין (ת"ק (פ"ת) 2558/05 חזן, רפרנס 1). **וריאציה 2 — תאגיד כשולח הודעה:** האם תאגיד רשאי לשלוח הודעת צד ג'' בבית המשפט לתביעות קטנות? ← לא, שכן בית המשפט דן רק בתביעות של יחיד (סעיף 60 לחוק בתי המשפט). **וריאציה 3 — תכלית המגבלה:** מדוע נאסר על תאגידים לשלוח הודעות צד ג'' בבית המשפט לתביעות קטנות? ← כדי לא לסכל את כוונת המחוקק לאפשר ליחיד להתדיין ללא ייצוג מול גופים חזקים (ת"ק (פ"ת) 2558/05 חזן, רפרנס 3).',
    'תאגיד אינו רשאי לשלוח הודעת צד ג'' בבית המשפט לתביעות קטנות, שכן הודעה זו נחשבת לתובענה, ובית משפט זה דן אך ורק בתביעות של יחיד (סעיף 60 לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 60", "ת\"ק (שלום פתח תקוה) 2558/05 שירלי חזן נ'' חב'' הדקה ה 90 בע\"מ (17.1.2006)", "ת\"ק (שלום פתח תקוה) 2562/06 שאול אהרן נ'' סקאל דיוטי פרי בע\"מ (10.12.2006)", "ת\"ק (שלום פתח תקוה) 2961/05 צבי חיימוביץ נ'' סנטורס סוכנות נסיעות ותיירות בע\"מ (26.2.2006)", "ת\"ק (שלום פתח תקוה) 2467/05 צבי קנר נ'' מועצת שהם (16.1.2006)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'החברה רשאית להגיש תביעה שכנגד, שכן היא נתבעת בהליך וזכאית להגנה מלאה.', false, 'בחירה זו שגויה. אף שהחברה נתבעת, סמכות בית המשפט לתביעות קטנות מוגבלת לתביעות של יחיד, ותביעה שכנגד נחשבת לתובענה לכל דבר ועניין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'החברה אינה רשאית להגיש תביעה שכנגד בבית המשפט לתביעות קטנות, שכן בית משפט זה דן אך ורק בתביעות של יחיד.', true, 'בחירה זו נכונה. סעיף 60 לחוק בתי המשפט קובע כי בית המשפט לתביעות קטנות דן בתביעות של יחיד בלבד, ותביעה שכנגד נחשבת לתובענה, ולכן תאגיד אינו יכול להגישה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'החברה רשאית להגיש תביעה שכנגד, אך רק אם קיבלה רשות מיוחדת מבית המשפט.', false, 'בחירה זו שגויה. אין בחוק הוראה המאפשרת לבית המשפט לתת רשות לתאגיד להגיש תביעה שכנגד בבית המשפט לתביעות קטנות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'החברה רשאית להגיש תביעה שכנגד, אך היא תידון בבית משפט השלום ולא בבית המשפט לתביעות קטנות.', false, 'בחירה זו שגויה. אם החברה מעוניינת לתבוע, עליה להגיש תביעה נפרדת בבית משפט השלום, ולא תביעה שכנגד בבית המשפט לתביעות קטנות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'הקמת בית המשפט לתביעות קטנות נועדה להקל על עומס בתי המשפט הרגילים, ולכן סדרי הדין בו זהים לסדרי הדין בבית משפט השלום.', false, 'בחירה זו שגויה. אף שהקלה על העומס היא תוצאה אפשרית, התכלית העיקרית היא לאפשר לאזרח הפשוט להתדיין, וסדרי הדין בו שונים ומיוחדים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'התכלית היא לאפשר לאזרח הפשוט להתדיין בדרך יעילה, זולה ומהירה, ללא ייצוג משפטי, תוך הסרת מחסומים של דיני ראיות וסדר דין.', true, 'בחירה זו נכונה. זוהי התכלית המפורשת של הקמת בית המשפט לתביעות קטנות, כפי שבא לידי ביטוי בדברי ההסבר לחוק ובפסיקה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'בית המשפט לתביעות קטנות נועד לפתור סכסוכים מורכבים בין יחידים לתאגידים, ולכן הוא מאפשר ייצוג משפטי חופשי לכל הצדדים.', false, 'בחירה זו שגויה. בית המשפט לתביעות קטנות נועד לפתור סכסוכים פשוטים יחסית, והייצוג המשפטי בו מוגבל מאוד, כדי לשמור על אופיו הלא-פורמלי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'התכלית היא להבטיח שכל תביעה, ללא קשר לסכום, תזכה לבירור משפטי מלא ומעמיק, ולכן הוא פועל כערכאה דיונית לכל דבר ועניין.', false, 'בחירה זו שגויה. בית המשפט לתביעות קטנות נועד לבירור מהיר ופחות מעמיק, ומוגבל בסכום התביעה, כדי לאפשר גישה קלה לצדק.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'כן, פסק דין בתביעות קטנות יוצר השתק עילה מלא, ולכן התביעה החדשה תיחסם.', false, 'בחירה זו שגויה. אף שהשתק עילה חל עקרונית, הפסיקה מכירה במורכבות החלתו בתביעות קטנות ומאפשרת גמישות במקרים חריגים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'לא, פסק דין בתביעות קטנות אינו יוצר מעשה בית דין כלל, בשל אופיו הלא-פורמלי של ההליך.', false, 'בחירה זו שגויה. הכלל הוא שמעשה בית דין חל גם על הליכים בתביעות קטנות, אך עם גמישות מסוימת בהשתק עילה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'פסק דין בתביעות קטנות יוצר השתק פלוגתא ללא קושי, אך לגבי השתק עילה, בית המשפט ינהג בגמישות במקרים חריגים, כגון כאשר התובע לא תבע את מלוא נזקיו מחוסר ידיעה.', true, 'בחירה זו נכונה. הפסיקה מבחינה בין השתק פלוגתא להשתק עילה בהקשר של תביעות קטנות, ומאפשרת גמישות בהחלת השתק עילה במקרים מסוימים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'התביעה החדשה תיחסם רק אם התובע יוכיח כי לא יכול היה לכלול את נזקי הגוף בתביעה המקורית.', false, 'בחירה זו שגויה. הנטל להוכחת חריג להשתק עילה מוטל על התובע, אך התנאי אינו רק ''אי יכולת'' אלא גם ''חוסר ידיעה'' או ''טיפול בנושא מתוחם''.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'החברה רשאית לשלוח הודעת צד ג'', שכן זוהי פעולת הגנה ולא תביעה.', false, 'בחירה זו שגויה. הפסיקה קבעה כי הודעת צד ג'' היא תובענה לכל דבר ועניין, ולא רק פעולת הגנה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'החברה אינה רשאית לשלוח הודעת צד ג'' בבית המשפט לתביעות קטנות, שכן הודעת צד ג'' נחשבת לתובענה, ובית משפט זה דן אך ורק בתביעות של יחיד.', true, 'בחירה זו נכונה. סעיף 60 לחוק בתי המשפט מגביל את התובעים בבית המשפט לתביעות קטנות ליחידים, והודעת צד ג'' נחשבת לתובענה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'החברה רשאית לשלוח הודעת צד ג'', אך רק אם הצד השלישי הוא גם יחיד.', false, 'בחירה זו שגויה. הבעיה אינה בזהות הצד השלישי, אלא בזהות שולח ההודעה (התאגיד) שאינו רשאי להגיש תובענה בבית משפט לתביעות קטנות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'החברה רשאית לשלוח הודעת צד ג'', אך בית המשפט רשאי להעביר את הדיון כולו לבית משפט השלום.', false, 'בחירה זו שגויה. בית המשפט לא יאפשר מלכתחילה הגשת הודעת צד ג'' על ידי תאגיד, שכן אין לו סמכות לדון בה.', 4);

END $$;

-- ============================================================
-- Q33 — 2019-S-Q33 — chapter=criminal_proc subtopic=search_seizure
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q33';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q33 skipped: external_id % already exists', '2019-S-Q33';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'search_seizure';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'search_seizure';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q33', 'e4a16014-22c7-4653-bf0d-89ff4bb34c20', v_subtopic_id,
    'במהלך חיפוש שלא לפי צו חיפוש אצל רמי החשוד בעבירה עלה חשד שרמי שמר על מחשבו האישי קובץ שנחוץ לפענוח העבירה. לצורך עריכת החיפוש במחשב הוזעק השוטר יצחק, שהוא בעל תפקיד מיומן במשטרת ישראל בכל הנוגע לחומר מחשב. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 33}'::jsonb,
    'השאלה עוסקת בסמכות לביצוע חיפוש בחומר מחשב, ובפרט בדרישה לצו שיפוטי. היא מדגישה את ההסדר הייחודי והמחמיר שקבע המחוקק בסעיף 23א לפקודת סדר הדין הפלילי (מעצר וחיפוש), לפיו חיפוש בחומר מחשב ייעשה אך ורק על פי צו שופט, ללא חריגים, וזאת בשל הפגיעה העמוקה והייחודית בפרטיות הכרוכה בחיפוש מסוג זה.',
    'סעיף 23א(ב) לפקודת סדר הדין הפלילי (מעצר וחיפוש) [נוסח חדש], תשכ"ט-1969, קובע באופן חד משמעי כי "על אף הוראות פרק זה, לא ייערך חיפוש כאמור בסעיף קטן (א), אלא על-פי צו של שופט". הוראה זו, שהוספה לפקודה ותוקנה בשנת 2005, משקפת את תפיסת המחוקק והפסיקה לפיה חיפוש בחומר מחשב (כולל טלפונים ניידים) מהווה פגיעה חמורה וייחודית בזכות לפרטיות, המעוגנת בסעיף 7 לחוק-יסוד: כבוד האדם וחירותו (Verdict: דנ"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022), Reference 4, 18, 21, 24, 27, 30, 31, 35, 39, 40, 41, 42, 43, 45, 46, 47, 49, 50, 51, 52; Verdict: בש"פ 7917/19 יונתן אוריך נ'' מדינת ישראל (25.12.2019), Reference 36, 37). בניגוד לחיפוש בחצרים, שיכול להתבצע בנסיבות מסוימות ללא צו (סעיף 25 לפקודה), הדרישה לצו שיפוטי לחיפוש בחומר מחשב היא קטגורית ובלעדית, ואין לה חריגים (Verdict: דנ"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022), Reference 9, 18, 20, 24, 28, 31, 34, 36, 38, 44, 46, 47, 51, 52). גם מיומנות השוטר אינה מכשירה חיפוש ללא צו, אלא היא תנאי לביצוע החיפוש *לאחר* קבלת הצו (סעיף 23א(א) לפקודה).',
    'הסטודנט עלול לטעות ולחשוב שקיימים חריגים לדרישת הצו השיפוטי לחיפוש בחומר מחשב, בדומה לחריגים הקיימים לחיפוש בחצרים (כגון חשד סביר, דחיפות או חומרת העבירה), מבלי להבין את אופיו המוחלט של סעיף 23א(ב) לפקודה ואת הרציונל שמאחוריו.',
    '["חיפוש בחומר מחשב", "צו שיפוטי", "פקודת סדר הדין הפלילי (מעצר וחיפוש)", "הגנת הפרטיות", "חוקיות המינהל", "סעיף 23א(ב) לפקודה"]'::jsonb,
    '**וריאציה 1 — דרישת צו:** האם חיפוש בחומר מחשב דורש צו שיפוטי? ← כן, תמיד, ללא חריגים (סעיף 23א(ב) לפקודה; דנ"פ 1062/21 אוריך, רפרנס 4). **וריאציה 2 — חומרת עבירה:** האם חומרת העבירה מכשירה חיפוש בחומר מחשב ללא צו? ← לא, הדרישה לצו היא מוחלטת ואינה תלויה בסוג או חומרת העבירה (דנ"פ 1062/21 אוריך, רפרנס 9). **וריאציה 3 — מיומנות השוטר:** האם מיומנות השוטר מחליפה את הצורך בצו? ← לא, מיומנות נדרשת לביצוע החיפוש, אך לא כתחליף לצו השיפוטי (סעיף 23א(א) לפקודה).',
    'חיפוש בחומר מחשב, לרבות טלפון נייד, אינו חוקי אלא אם כן בוצע על פי צו של שופט, וזאת ללא כל חריגים, בשל הפגיעה החמורה והייחודית בפרטיות (סעיף 23א(ב) לפקודת סדר הדין הפלילי, דנ"פ 1062/21 אוריך).',
    '["פקודת סדר הדין הפלילי (מעצר וחיפוש) [נוסח חדש], תשכ\"ט-1969, סעיף 23א", "דנ\"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022)", "בג\"ץ 8298/22 הסנגוריה הציבורית נ'' היועצת המשפטית לממשלה (31.8.2025)", "בש\"פ 7917/19 יונתן אוריך נ'' מדינת ישראל (25.12.2019)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'החיפוש חוקי רק אם העבירה שבה רמי חשוד היא מסוג פשע חמור.', false, 'בחירה זו שגויה. חומרת העבירה אינה מכשירה חיפוש בחומר מחשב ללא צו שיפוטי. הדרישה לצו היא מוחלטת, ללא קשר לסוג העבירה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'החיפוש חוקי רק אם העבירה שבה רמי חשוד היא מסוג פשע.', false, 'בחירה זו שגויה. סוג העבירה אינו מהווה חריג לדרישת הצו השיפוטי לחיפוש בחומר מחשב. הדרישה לצו היא קטגורית.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'החיפוש חוקי רק אם העבירה שבה רמי חשוד היא מסוג עוון או פשע.', false, 'בחירה זו שגויה. אין בחוק או בפסיקה כל הוראה המאפשרת חיפוש בחומר מחשב ללא צו שיפוטי, גם אם מדובר בעבירות מסוג עוון או פשע. הדרישה לצו היא בלעדית.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'החיפוש אינו חוקי.', true, 'בחירה זו נכונה. סעיף 23א(ב) לפקודת סדר הדין הפלילי (מעצר וחיפוש) קובע במפורש כי חיפוש בחומר מחשב ייערך אך ורק על פי צו של שופט, ללא חריגים.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'סמכות חיפוש בחומר מחשב בהסכמה', 1, 'שוטר מבקש לערוך חיפוש במכשיר הטלפון הנייד של חשוד, והחשוד מסכים לכך מדעת. האם חיפוש זה חוקי ללא צו שיפוטי?',
    'שאלה זו עוסקת בסוגיית חיפוש בחומר מחשב (כולל טלפונים ניידים) בהסכמה, ללא צו שיפוטי. היא בוחנת את ההבחנה בין הלכת בן חיים, המאפשרת חיפוש בהסכמה במקרים מסוימים, לבין הדרישה הקטגורית לצו שיפוטי לחיפוש בחומר מחשב, כפי שנקבעה בהלכת הסנגוריה הציבורית.',
    'סעיף 23א(ב) לפקודת סדר הדין הפלילי (מעצר וחיפוש) [נוסח חדש], תשכ"ט-1969, קובע במפורש כי "לא ייערך חיפוש כאמור בסעיף קטן (א), אלא על-פי צו של שופט". בג"ץ 8298/22 הסנגוריה הציבורית נ'' היועצת המשפטית לממשלה (2025) (הלכת הסנגוריה הציבורית) קבע באופן חד משמעי כי הוראה זו שוללת את סמכות המשטרה לערוך חיפוש בחומר מחשב בהסכמת הנחקר, ללא צו שיפוטי (Verdict: בג"ץ 8298/22 הסנגוריה הציבורית נ'' היועצת המשפטית לממשלה (31.8.2025), Reference 7, 8, 14). בית המשפט הדגיש כי בניגוד להלכת בן חיים (רע"פ 10141/09 בן חיים נ'' מדינת ישראל (2012)), שהכירה בהסכמה מדעת כתחליף לדרישת חשד סביר בחיפושים מסוימים (כגון בגוף או בכליו של אדם), סעיף 23א(ב) אינו מותיר מקום לחריגים, בשל הפגיעה החמורה והייחודית בפרטיות הכרוכה בחיפוש בחומר מחשב (Verdict: בג"ץ 8298/22 הסנגוריה הציבורית נ'' היועצת המשפטית לממשלה (31.8.2025), Reference 12, 14).',
    'הסטודנט עלול לטעות וליישם את הלכת בן חיים (חיפוש בהסכמה) באופן גורף על כל סוגי החיפושים, מבלי להבחין במגבלה המפורשת והייחודית הקבועה בסעיף 23א(ב) לפקודה לגבי חיפוש בחומר מחשב.',
    '["חיפוש בחומר מחשב", "צו שיפוטי", "הסכמה מדעת", "הלכת בן חיים", "הלכת הסנגוריה הציבורית", "סעיף 23א(ב) לפקודה"]'::jsonb,
    '**וריאציה 1 — חיפוש בהסכמה:** האם הסכמת חשוד לחיפוש בטלפון הנייד שלו מכשירה את החיפוש ללא צו? ← לא, סעיף 23א(ב) לפקודה דורש צו שופט באופן בלעדי (בג"ץ 8298/22 הסנגוריה הציבורית, רפרנס 7). **וריאציה 2 — הלכת בן חיים:** האם הלכת בן חיים חלה על חיפוש בחומר מחשב? ← לא, הלכת בן חיים חלה על חיפוש בגוף, בכליו או בחצרים, אך לא על חומר מחשב (בג"ץ 8298/22 הסנגוריה הציבורית, רפרנס 12). **וריאציה 3 — רציונל המגבלה:** מדוע נדרש צו שיפוטי לחיפוש בחומר מחשב גם בהסכמה? ← בשל הפגיעה החמורה והייחודית בפרטיות הכרוכה בחיפוש מסוג זה (דנ"פ 1062/21 אוריך, רפרנס 4).',
    'חיפוש בחומר מחשב דורש צו שיפוטי בכל מקרה, ואין הסכמת חשוד יכולה להחליף דרישה זו, בניגוד לחיפושים אחרים (בג"ץ 8298/22 הסנגוריה הציבורית, סעיף 23א(ב) לפקודה).',
    '["פקודת סדר הדין הפלילי (מעצר וחיפוש) [נוסח חדש], תשכ\"ט-1969, סעיף 23א(ב)", "בג\"ץ 8298/22 הסנגוריה הציבורית נ'' היועצת המשפטית לממשלה (31.8.2025)", "דנ\"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022)", "רע\"פ 10141/09 בן חיים נ'' מדינת ישראל, פ\"ד סה(3) 305 (6.3.2012)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'תנאים למתן צו חיפוש בחומר מחשב', 2, 'מהם התנאים המצטברים שעל בית המשפט לבחון בבואו להוציא צו חיפוש בחומר מחשב?',
    'שאלה זו מתמקדת בתנאים המהותיים למתן צו חיפוש בחומר מחשב, כפי שנקבעו בסעיף 23א לפקודת סדר הדין הפלילי וכפי שפורשו בפסיקת בית המשפט העליון. היא מדגישה את האיזון העדין בין צרכי החקירה לבין הזכות לפרטיות.',
    'סעיף 23א(ב) לפקודת סדר הדין הפלילי (מעצר וחיפוש) [נוסח חדש], תשכ"ט-1969, קובע שני תנאים מצטברים למתן צו חיפוש בחומר מחשב (כולל טלפון חכם): הראשון, כי החיפוש "נחוץ" כדי להבטיח את הצגת ממצאיו במשפט או בהליך אחר (כפי שנגזר מסעיף 23 לפקודה); והשני, הייחודי לחיפוש בחומר מחשב, הוא כי מטרות החיפוש ותנאיו ייקבעו בצו עצמו ויבטיחו כי הפגיעה בפרטיותו של אדם לא תהא "מעבר לנדרש" (Verdict: דנ"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022), Reference 4, 5, 17, 18, 20, 21, 24, 27, 29, 31, 33, 34, 37, 38, 40, 41, 42, 43, 45, 47, 49, 50, 51, 52; Verdict: בש"פ 7917/19 יונתן אוריך נ'' מדינת ישראל (25.12.2019), Reference 37, 38). תנאי זה מוסיף נדבך משמעותי ביחס לאמות המידה למתן צו חיפוש בחצרים, ומטיל על השופט מלאכה מורכבת של איזון בין זכות הפרטיות לאינטרס הציבורי בקידום החקירה (Verdict: דנ"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022), Reference 4, 21, 34, 38).',
    'הסטודנט עלול להתבלבל בין התנאים למתן צו חיפוש בחצרים (נחיצות בלבד) לבין התנאים המחמירים יותר לחיפוש בחומר מחשב, הכוללים גם את דרישת המידתיות המפורשת.',
    '["חיפוש בחומר מחשב", "צו שיפוטי", "נחיצות החיפוש", "מידתיות הפגיעה בפרטיות", "סעיף 23א(ב) לפקודה", "איזון זכויות"]'::jsonb,
    '**וריאציה 1 — התנאים המצטברים:** מהם שני התנאים המצטברים למתן צו חיפוש בחומר מחשב? ← נחיצות החיפוש ומידתיות הפגיעה בפרטיות (סעיף 23א(ב) לפקודה; דנ"פ 1062/21 אוריך, רפרנס 4). **וריאציה 2 — ייחודיות התנאי השני:** מה מייחד את התנאי השני לחיפוש בחומר מחשב? ← הוא דורש שהפגיעה בפרטיות לא תהא ''מעבר לנדרש'', בניגוד לחיפוש בחצרים (דנ"פ 1062/21 אוריך, רפרנס 4). **וריאציה 3 — תפקיד השופט:** מה תפקידו של השופט בבחינת התנאים? ← להפעיל שיקול דעת עצמאי ולאזן בין צרכי החקירה לזכות לפרטיות (דנ"פ 1062/21 אוריך, רפרנס 5).',
    'למתן צו חיפוש בחומר מחשב נדרשים שני תנאים מצטברים: נחיצות החיפוש והבטחה כי מטרותיו ותנאיו לא יפגעו בפרטיות מעבר לנדרש (סעיף 23א(ב) לפקודה, דנ"פ 1062/21 אוריך).',
    '["פקודת סדר הדין הפלילי (מעצר וחיפוש) [נוסח חדש], תשכ\"ט-1969, סעיף 23א(ב)", "דנ\"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022)", "בש\"פ 7917/19 יונתן אוריך נ'' מדינת ישראל (25.12.2019)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'השלכות חיפוש בלתי חוקי בחומר מחשב', 3, 'שוטר ערך חיפוש בלתי חוקי במכשיר טלפון נייד של חשוד, והשיג מידע רלוונטי לחקירה. כעת המשטרה מבקשת צו חיפוש חוקי לאותו מכשיר. מהן ההשלכות של החיפוש הבלתי חוקי על קבילות הראיות ועל מתן הצו המבוקש?',
    'שאלה זו עוסקת בהשלכות של חיפוש בלתי חוקי בחומר מחשב, ובפרט על קבילות הראיות שהושגו ועל האפשרות למתן צו חיפוש מאוחר יותר. היא מתייחסת למבחן הדו-שלבי שנקבע בהלכת אוריך, המאזן בין הפגיעה בזכויות הפרט לבין האינטרס הציבורי בחקר האמת.',
    'הלכת אוריך (בש"פ 7917/19 יונתן אוריך נ'' מדינת ישראל (25.12.2019) ודנ"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022)) קבעה כי יש ליתן משקל מיוחד לחיפוש מוקדם שבוצע שלא כדין במכשיר טלפון נייד או מחשב. בית המשפט יבחן את מידת ההשפעה של חיפוש כזה על בקשה למתן צו לחיפוש נוסף במבחן דו-שלבי: השלב הראשון בוחן את הזיקה בין המידע שאותר בחיפוש שלא כדין לבין הצו המבוקש. ככל שהבקשה מבוססת על מידע שהושג בפגם, כך הזיקה מתהדקת. השלב השני דן בשאלה האם מוצדק ליתן את צו החיפוש חרף הפגם, תוך איזון בין הפגיעה בפרטיות לבין האינטרס הציבורי שבמיצוי החקירה הפלילית, ובכלל זה בחינת חומרת הפגם, חומרת החשדות, נחיצות הצו וזיקת בעל המחשב לחשדות (Verdict: דנ"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022), Reference 5, 6, 22, 37; Verdict: בש"פ 7917/19 יונתן אוריך נ'' מדינת ישראל (25.12.2019), Reference 36, 37).',
    'הסטודנט עלול לטעות ולחשוב שכל חיפוש בלתי חוקי מוביל לפסילה אוטומטית של הראיות, או לחילופין, שאין לו כל השפעה, מבלי להכיר את המבחן המורכב שנקבע בפסיקה לאיזון בין זכויות הפרט לצרכי החקירה.',
    '["חיפוש בלתי חוקי", "קבילות ראיות", "הלכת אוריך", "הלכת יששכרוב", "מבחן דו-שלבי", "איזון אינטרסים"]'::jsonb,
    '**וריאציה 1 — השפעת חיפוש בלתי חוקי:** האם חיפוש בלתי חוקי בחומר מחשב משפיע על קבילות ראיות ומתן צו נוסף? ← כן, יש ליתן לו משקל מיוחד (דנ"פ 1062/21 אוריך, רפרנס 37). **וריאציה 2 — המבחן הדו-שלבי:** מהם שלבי המבחן לבחינת השלכות חיפוש בלתי חוקי? ← בחינת הזיקה בין המידע לפגם, ואיזון בין הפגיעה בפרטיות לאינטרס הציבורי (דנ"פ 1062/21 אוריך, רפרנס 37). **וריאציה 3 — שיקולים באיזון:** אילו שיקולים נכללים באיזון בשלב השני? ← חומרת הפגם, חומרת החשדות, נחיצות הצו וזיקת בעל המחשב לחשדות (דנ"פ 1062/21 אוריך, רפרנס 37).',
    'חיפוש בלתי חוקי בחומר מחשב מחייב בחינה דו-שלבית של הזיקה בין המידע לפגם ואיזון בין הפגיעה בפרטיות לאינטרס הציבורי, בטרם יוחלט על קבילות ראיות ומתן צו חיפוש נוסף (הלכת אוריך).',
    '["דנ\"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022)", "בש\"פ 7917/19 יונתן אוריך נ'' מדינת ישראל (25.12.2019)", "ת\"פ (שלום נת'') 54680-10-19 מדינת ישראל נ'' אבי טקלו (6.8.2020)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'חיפוש בחצרים לעומת חיפוש בחומר מחשב', 4, 'מהו ההבדל המהותי בין חיפוש בחצרים (כגון בבית) לבין חיפוש בחומר מחשב, בכל הנוגע לדרישת הצו השיפוטי?',
    'שאלה זו עוסקת בהבחנה המהותית בין סוגי חיפושים שונים, ובפרט בין חיפוש בחצרים לחיפוש בחומר מחשב, בכל הנוגע לדרישת הצו השיפוטי. היא מדגישה את ההסדר הייחודי והמחמיר שקבע המחוקק לחיפוש בחומר מחשב, בשל הפגיעה העמוקה בפרטיות הכרוכה בו.',
    'המחוקק קבע הסדר שונה ומחמיר יותר לחיפוש בחומר מחשב לעומת חיפוש בחצרים. סעיף 23א(ב) לפקודת סדר הדין הפלילי (מעצר וחיפוש) [נוסח חדש], תשכ"ט-1969, קובע כי "על אף הוראות פרק זה, לא ייערך חיפוש כאמור בסעיף קטן (א), אלא על-פי צו של שופט". משמעות הדבר היא שחיפוש בחומר מחשב דורש צו שיפוטי בכל מקרה, ללא חריגים (Verdict: דנ"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022), Reference 4, 9, 18, 20, 24, 27, 28, 31, 34, 38, 44, 45, 47, 51, 52). לעומת זאת, חיפוש בחצרים (כגון בבית) יכול להתבצע בנסיבות מסוימות גם ללא צו שיפוטי, למשל במקרים של חשד סביר לביצוע פשע או דחיפות (סעיף 25 לפקודה) (Verdict: דנ"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022), Reference 16, 19, 24, 27, 44, 46). ההבדל נובע מרגישותו הרבה והייחודית של המידע השמור במחשבים והפגיעה הקשה והייחודית בזכות לפרטיות הכרוכה בחיפוש בהם (Verdict: דנ"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022), Reference 4, 18, 21, 24, 27).',
    'הסטודנט עלול לטעות ולחשוב שכללי החיפוש זהים לכל סוגי החיפושים, מבלי להבין את ההסדר הייחודי והמחמיר שקבע המחוקק לחיפוש בחומר מחשב, המבטא את חשיבות ההגנה על הפרטיות בעידן הדיגיטלי.',
    '["חיפוש בחומר מחשב", "חיפוש בחצרים", "צו שיפוטי", "סעיף 23א לפקודה", "סעיף 25 לפקודה", "הגנת הפרטיות"]'::jsonb,
    '**וריאציה 1 — דרישת צו לחיפוש בחומר מחשב:** האם חיפוש בחומר מחשב דורש צו שיפוטי בכל מקרה? ← כן, סעיף 23א(ב) לפקודה קובע זאת במפורש (דנ"פ 1062/21 אוריך, רפרנס 4). **וריאציה 2 — דרישת צו לחיפוש בחצרים:** האם חיפוש בחצרים דורש צו שיפוטי בכל מקרה? ← לא, הוא יכול להתבצע גם ללא צו בנסיבות מסוימות (סעיף 25 לפקודה; דנ"פ 1062/21 אוריך, רפרנס 16). **וריאציה 3 — רציונל ההבדל:** מדוע קיים הבדל בדרישת הצו בין חיפוש בחצרים לחיפוש בחומר מחשב? ← בשל הפגיעה החמורה והייחודית בפרטיות הכרוכה בחיפוש בחומר מחשב (דנ"פ 1062/21 אוריך, רפרנס 4).',
    'חיפוש בחומר מחשב דורש צו שיפוטי בכל מקרה, ללא חריגים, בעוד שחיפוש בחצרים יכול להתבצע גם ללא צו בנסיבות מסוימות, וזאת בשל הפגיעה העמוקה בפרטיות הכרוכה בחיפוש דיגיטלי (סעיף 23א(ב) לפקודה, דנ"פ 1062/21 אוריך).',
    '["פקודת סדר הדין הפלילי (מעצר וחיפוש) [נוסח חדש], תשכ\"ט-1969, סעיף 23א(ב)", "פקודת סדר הדין הפלילי (מעצר וחיפוש) [נוסח חדש], תשכ\"ט-1969, סעיף 25", "דנ\"פ 1062/21 יונתן אוריך נ'' מדינת ישראל (11.1.2022)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'כן, הסכמה מדעת של החשוד מהווה מקור סמכות עצמאי לביצוע חיפוש בחומר מחשב, בדומה לחיפוש בגוף או בחצרים.', false, 'בחירה זו שגויה. הלכת בן חיים, המכירה בהסכמה כמקור סמכות לחיפוש בגוף או בחצרים, אינה חלה על חיפוש בחומר מחשב, בשל אופיו הייחודי והפגיעה החמורה בפרטיות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'לא, אין למשטרה סמכות לערוך חיפוש בחומר מחשב בהסכמה ללא צו שיפוטי, שכן סעיף 23א(ב) לפקודה דורש צו שופט באופן מפורש ובלעדי.', true, 'בחירה זו נכונה. בג"ץ 8298/22 (הלכת הסנגוריה הציבורית) קבע כי סעיף 23א(ב) לפקודה שולל את סמכות המשטרה לערוך חיפוש בחומר מחשב בהסכמה ללא צו שיפוטי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'כן, בתנאי שהחשוד הוזהר כי הוא רשאי לסרב לחיפוש וכי סירובו לא ייזקף לחובתו.', false, 'בחירה זו שגויה. אף שהבהרת זכות הסירוב היא תנאי להסכמה מדעת, היא אינה מכשירה חיפוש בחומר מחשב ללא צו שיפוטי, שכן אין סמכות חוקית לכך מלכתחילה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'כן, אם החיפוש מבוצע על ידי בעל תפקיד מיומן ומוגבל לנושאים הרלוונטיים לחקירה.', false, 'בחירה זו שגויה. מיומנות החוקר ותיחום החיפוש הם תנאים לביצוע חיפוש *על פי צו*, אך אינם מהווים תחליף לדרישת הצו השיפוטי עצמה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'החיפוש נחוץ כדי להבטיח הצגת ממצאיו במשפט או הליך אחר, וכן קיימת הסכמה של בעל המחשב.', false, 'בחירה זו שגויה. הסכמת בעל המחשב אינה תנאי למתן צו חיפוש, ואינה מהווה תחליף לצו. התנאים הם נחיצות ומידתיות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'החיפוש נחוץ כדי להבטיח הצגת ממצאיו במשפט או הליך אחר, וכן מטרות החיפוש ותנאיו ייקבעו באופן שלא יפגעו בפרטיותו של אדם מעבר לנדרש.', true, 'בחירה זו נכונה. אלו הם שני התנאים המצטברים הקבועים בסעיף 23א(ב) לפקודה, כפי שפורשו בפסיקת בית המשפט העליון (הלכת אוריך).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'החיפוש נחוץ כדי להבטיח הצגת ממצאיו במשפט או הליך אחר, וכן חומרת העבירה מצדיקה את הפגיעה בפרטיות.', false, 'בחירה זו שגויה. חומרת העבירה היא שיקול רלוונטי, אך אינה תנאי מצטבר בפני עצמו, אלא נכללת במסגרת איזון המידתיות. התנאי השני הוא מידתיות הפגיעה בפרטיות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'החיפוש נחוץ כדי להבטיח הצגת ממצאיו במשפט או הליך אחר, וכן החיפוש מבוצע על ידי בעל תפקיד מיומן.', false, 'בחירה זו שגויה. מיומנות החוקר היא תנאי לביצוע החיפוש בפועל (סעיף 23א(א)), אך אינה אחד משני התנאים המצטברים למתן הצו השיפוטי עצמו.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'המידע שהושג בחיפוש הבלתי חוקי קביל כראיה, ובלבד שהיה רלוונטי לחקירה, ואין מניעה למתן צו חיפוש נוסף.', false, 'בחירה זו שגויה. קבילות ראיות שהושגו שלא כדין אינה אוטומטית, והיא נבחנת לפי הלכת יששכרוב. כמו כן, חיפוש בלתי חוקי משפיע על מתן צו חיפוש נוסף.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'המידע שהושג בחיפוש הבלתי חוקי ייפסל באופן אוטומטי, ולא יינתן צו חיפוש נוסף למכשיר.', false, 'בחירה זו שגויה. פסילת ראיות אינה אוטומטית, אלא נבחנת לפי מבחני הלכת יששכרוב. כמו כן, צו חיפוש נוסף יכול להינתן, אך תוך התחשבות בפגם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'יש ליתן משקל מיוחד לחיפוש המוקדם שבוצע שלא כדין, ובית המשפט יבחן במבחן דו-שלבי את הזיקה בין המידע שהושג לפגם, ואת האיזון בין הפגיעה בפרטיות לאינטרס הציבורי, בטרם יחליט על קבילות הראיות ומתן הצו.', true, 'בחירה זו נכונה. הלכת אוריך קבעה מבחן דו-שלבי מפורט לבחינת השלכות חיפוש בלתי חוקי בחומר מחשב על קבילות ראיות ומתן צו חיפוש נוסף.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'החיפוש הבלתי חוקי אינו משפיע על קבילות הראיות, אך הוא מונע מתן צו חיפוש נוסף לאותו מכשיר.', false, 'בחירה זו שגויה. החיפוש הבלתי חוקי בהחלט משפיע על קבילות הראיות, ואינו מונע בהכרח מתן צו חיפוש נוסף, אלא מחייב בחינה מעמיקה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'אין הבדל מהותי; בשני המקרים נדרש צו שיפוטי, אלא אם כן קיימת הסכמה של בעל המקום/המחשב.', false, 'בחירה זו שגויה. קיים הבדל מהותי בדרישת הצו, והסכמה אינה מכשירה חיפוש בחומר מחשב ללא צו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'חיפוש בחצרים דורש צו שיפוטי בכל מקרה, בעוד שחיפוש בחומר מחשב יכול להתבצע גם ללא צו בנסיבות מסוימות.', false, 'בחירה זו שגויה. ההיפך הוא הנכון: חיפוש בחומר מחשב דורש צו בכל מקרה, בעוד שחיפוש בחצרים יכול להתבצע ללא צו בנסיבות מסוימות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'חיפוש בחומר מחשב דורש צו שיפוטי בכל מקרה, ללא חריגים, בעוד שחיפוש בחצרים יכול להתבצע גם ללא צו בנסיבות מסוימות (כגון חשד סביר או דחיפות).', true, 'בחירה זו נכונה. סעיף 23א(ב) לפקודה קובע דרישה קטגורית לצו שיפוטי לחיפוש בחומר מחשב, בניגוד לסעיף 25 לפקודה המאפשר חיפוש בחצרים ללא צו בנסיבות מסוימות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בשני המקרים, צו שיפוטי נדרש רק אם החיפוש עלול לפגוע בפרטיות מעבר לנדרש.', false, 'בחירה זו שגויה. דרישת המידתיות היא תנאי לתוכן הצו, אך אינה קובעת את עצם הצורך בצו. הצורך בצו לחיפוש בחומר מחשב הוא מוחלט.', 4);

END $$;

-- ============================================================
-- Q34 — 2019-S-Q34 — chapter=criminal_proc subtopic=criminal_appeal
-- notes: needs_review=true | subtopic_mapping_review: original='עבירות קנס' → mapped='criminal_appeal'
