  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'criminal_appeal';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'criminal_appeal';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q34', 'e4a16014-22c7-4653-bf0d-89ff4bb34c20', v_subtopic_id,
    'לציון הומצאה כדין הודעת תשלום קנס בעבירה של ברירת משפט. בידיו של ציון ראיות לכך שלא הוא ביצע את העבירה, לכן ברצונו להישפט עליה. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 34}'::jsonb,
    'השאלה עוסקת באפשרויות העומדות בפני אדם שקיבל הודעת תשלום קנס בעבירה מסוג ''ברירת משפט'', ובפרט במועדים להודעה על רצון להישפט. היא מדגישה את ההבחנה בין תשלום הקנס לבין בקשה להישפט, ואת העובדה כי אין חובה לשלם את הקנס אם בוחרים להישפט.',
    'סעיף 229(א) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, קובע כי מי שנמסרה לו הודעת תשלום קנס, ישלם את הקנס תוך תשעים ימים מיום ההמצאה, "זולת אם פעל באחת מדרכים אלה: ... (2) הודיע, תוך תשעים ימים מיום ההמצאה, בדרך שנקבעה בתקנות, שיש ברצונו להישפט על העבירה" (Law: חוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, סעיף 229). מכאן עולה כי עומדות בפני הנקנס שתי חלופות עיקריות: לשלם את הקנס, או להודיע על רצונו להישפט. אם בחר הנקנס להודיע על רצונו להישפט, אין עליו חובה לשלם את הקנס בינתיים. הודעה על רצון להישפט היא דרך פעולה חלופית לתשלום הקנס (Verdict: המ"ש (תעבורה י-ם) 5681-02-26 אליהו קלפהולץ נ'' מדינת ישראל (28.2.2026), Reference 1, 10). במקרה כזה, תישלח לנקנס הזמנה למשפט (Law: חוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, סעיף 230).',
    'הסטודנט עלול לטעות ולחשוב שחובה לשלם את הקנס גם אם מעוניינים להישפט, או לבלבל בין המועדים השונים להגשת בקשה לביטול קנס לבין המועד להודעה על רצון להישפט.',
    '["עבירת ברירת משפט", "הודעת תשלום קנס", "בקשה להישפט", "מועדים", "סעיף 229 לחוק סדר הדין הפלילי", "זכות להישפט"]'::jsonb,
    '**וריאציה 1 — מועד להודעה על רצון להישפט:** תוך כמה זמן יש להודיע על רצון להישפט? ← 90 יום מיום המצאת הודעת הקנס (סעיף 229(א)(2) לחוק סדר הדין הפלילי). **וריאציה 2 — חובת תשלום בינתיים:** האם חובה לשלם את הקנס אם בוחרים להישפט? ← לא, זוהי דרך פעולה חלופית לתשלום הקנס (המ"ש (תעבורה י-ם) 5681-02-26 קלפהולץ, רפרנס 1, 10). **וריאציה 3 — השלכות אי-פעולה:** מה קורה אם לא משלמים ולא מודיעים על רצון להישפט? ← הקנס הופך חלוט, ורואים את הנקנס כמי שהורשע ונגזר דינו (נבו - המתמחה, סדר הדין הפלילי, עמ'' 109).',
    'לציון עומדת הברירה להודיע על רצונו להישפט על העבירה בתוך 90 יום מיום המצאת הודעת תשלום הקנס, ואין עליו חובה לשלם את הקנס בינתיים (סעיף 229(א) לחוק סדר הדין הפלילי).',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 229", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 230", "המ\"ש (תעבורה י-ם) 5681-02-26 אליהו קלפהולץ נ'' מדינת ישראל (28.2.2026)", "נבו - המתמחה, סדר הדין הפלילי (2026) | פרק טו - הוראות נוהל, עמ'' 109"]'::jsonb,
    'needs_review=true | subtopic_mapping_review: original=''עבירות קנס'' → mapped=''criminal_appeal''',
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'על ציון להודיע שברצונו להישפט על העבירה בתוך 90 יום מיום ההמצאה, ועליו לשלם בינתיים את הקנס.', false, 'בחירה זו שגויה. אף שהמועד להודיע על רצון להישפט הוא 90 יום, אין חובה לשלם את הקנס בינתיים. תשלום הקנס כמוהו כהודאה באשמה.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על ציון להודיע שברצונו להישפט על העבירה בתוך 90 יום מיום ההמצאה, אך אינו חייב לשלם בינתיים את הקנס.', true, 'בחירה זו נכונה. סעיף 229(א)(2) לחוק סדר הדין הפלילי קובע כי מי שנמסרה לו הודעת תשלום קנס רשאי להודיע על רצונו להישפט תוך 90 ימים, ואין חובה לשלם את הקנס במקרה זה.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על ציון להודיע שברצונו להישפט על העבירה בתוך 30 יום מיום ההמצאה, ועליו לשלם בינתיים את הקנס.', false, 'בחירה זו שגויה. המועד להודיע על רצון להישפט הוא 90 יום, ולא 30 יום. כמו כן, אין חובה לשלם את הקנס בינתיים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'על ציון להודיע שברצונו להישפט על העבירה בתוך 30 יום מיום ההמצאה, אך אינו חייב לשלם בינתיים את הקנס.', false, 'בחירה זו שגויה. המועד להודיע על רצון להישפט הוא 90 יום, ולא 30 יום. המועד של 30 יום רלוונטי לבקשה לביטול קנס, ולא לבקשה להישפט.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'השלכות תשלום קנס בעבירת ברירת משפט', 1, 'לציון הומצאה כדין הודעת תשלום קנס בעבירה של ברירת משפט. ציון שילם את הקנס במועד, וכעת הוא מעוניין להישפט על העבירה. מה הדין?',
    'שאלה זו עוסקת בהשלכות המשפטיות של תשלום קנס בעבירת ברירת משפט. היא מדגישה את הכלל הקבוע בחוק לפיו תשלום קנס כמוהו כהודאה באשמה, הרשעה ונשיאת עונש, ואת החריגים המצומצמים לכלל זה.',
    'סעיף 229(ח) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, קובע כי "שילם אדם את הקנס רואים אותו כאילו הודה באשמה בפני בית המשפט, הורשע ונשא את עונשו" (Law: חוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, סעיף 229). משמעות הדבר היא שתשלום הקנס מסיים את ההליך הפלילי, והנאשם מוותר על זכותו להישפט (Verdict: המ"ש (תעבורה י-ם) 5681-02-26 אליהו קלפהולץ נ'' מדינת ישראל (28.2.2026), Reference 1, 8). הפסיקה הבהירה כי בקשה להישפט היא דרך פעולה חלופית לתשלום הקנס, ומששולם הקנס, מגבלת הזמנים להגשת בקשה להישפט אינה חלה עוד בעניינו של המבקש (Verdict: המ"ש (תעבורה י-ם) 5681-02-26 אליהו קלפהולץ נ'' מדינת ישראל (28.2.2026), Reference 1, 10). קיימים שני חריגים לכלל זה: אם התובע ביטל את הודעת תשלום הקנס, או אם בית המשפט החליט לקיים את משפטו של הנאשם אף על פי שהודיע באיחור על רצונו להישפט כאמור בסעיף 230 לחוק (Law: חוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, סעיף 229). על פי ההלכה, אין נדרשת בחינת הנסיבות בהן שולם הקנס (Verdict: המ"ש (תעבורה י-ם) 5681-02-26 אליהו קלפהולץ נ'' מדינת ישראל (28.2.2026), Reference 1, 11).',
    'הסטודנט עלול לטעות ולחשוב שתשלום קנס הוא רק אמצעי זמני למנוע צבירת קנסות, וכי ניתן לחזור בו מהתשלום ולבקש להישפט בקלות, מבלי להבין את המשמעות המכרעת של התשלום כהודאה באשמה.',
    '["עבירת ברירת משפט", "תשלום קנס", "הודאה באשמה", "סעיף 229(ח) לחוק סדר הדין הפלילי", "חריגים לכלל", "סופיות הדיון"]'::jsonb,
    '**וריאציה 1 — משמעות התשלום:** מה קורה כשמשלמים קנס ברירת משפט? ← רואים את המשלם כאילו הודה באשמה, הורשע ונשא את עונשו (סעיף 229(ח) לחוק סדר הדין הפלילי). **וריאציה 2 — אפשרות להישפט לאחר תשלום:** האם ניתן להישפט לאחר תשלום קנס? ← רק בשני חריגים: אם התובע ביטל את הקנס, או אם בית המשפט החליט לקיים משפט באיחור מטעמים מיוחדים (סעיף 229(ח) לחוק סדר הדין הפלילי). **וריאציה 3 — בחינת נסיבות התשלום:** האם בית המשפט בוחן את נסיבות תשלום הקנס? ← על פי ההלכה, אין נדרשת בחינת הנסיבות בהן שולם הקנס (רע"פ 2937/17 פלדמן, רפרנס 11447064, 11).',
    'תשלום קנס בעבירת ברירת משפט כמוהו כהודאה באשמה, הרשעה ונשיאת עונש, ומבטל את האפשרות להישפט, למעט חריגים מצומצמים הקבועים בחוק (סעיף 229(ח) לחוק סדר הדין הפלילי).',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 229", "המ\"ש (תעבורה י-ם) 5681-02-26 אליהו קלפהולץ נ'' מדינת ישראל (28.2.2026)", "המ\"ש (תעבורה י-ם) 6340-02-26 אליהו קלפהולץ נ'' מדינת ישראל (20.2.2026)", "המ\"ש (תעבורה י-ם) 6946-02-26 אליהו קלפהולץ נ'' מדינת ישראל (28.2.2026)", "רע\"פ 641/19 אייל מילר נ'' מדינת ישראל (10.4.2019)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'תנאים להארכת מועד להישפט לאחר תשלום קנס', 2, 'ציון שילם בטעות קנס ברירת משפט, וכעת הוא מבקש מבית המשפט להאריך את המועד להישפט. מהם התנאים שבית המשפט יבחן בבואו להחליט בבקשתו?',
    'שאלה זו בוחנת את שיקול הדעת של בית המשפט בהארכת מועד להישפט לאחר תשלום קנס. היא מתמקדת בתנאים המצטברים הקבועים בסעיף 230 לחוק סדר הדין הפלילי, ובפרשנות המצמצמת של הפסיקה לגביהם, במיוחד לאור עקרון סופיות הדיון.',
    'סעיף 230 לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, מעניק לבית המשפט סמכות להאריך את המועד להישפט בהתקיים התנאים הקבועים בסעיף 229(ה) לחוק, בשינויים המחויבים, או מטעמים מיוחדים שיירשמו (Law: חוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, סעיף 230). ההלכה היא כי יש לנקוט בעניין זה על דרך הצמצום, בדומה לבחינת בקשה לביטול פסק דין, כשיש סיבה מוצדקת לאי התייצבות או אם הדבר דרוש למניעת עיוות דין (Verdict: המ"ש (תעבורה י-ם) 5681-02-26 אליהו קלפהולץ נ'' מדינת ישראל (28.2.2026), Reference 1, 12). התנאים המרכזיים הם שהבקשה לא הוגשה במועד בשל סיבות שלא היו תלויות במבקש ושמנעו ממנו להגישה במועד, ושהיא הוגשה מיד לאחר שהוסרה המניעה (Law: חוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, סעיף 229(ה)). במקרים בהם שולם הדו"ח, נדרשות נסיבות חריגות כדי לפתוח שוב את שערי בית המשפט בפני הנהג, וזאת נוכח עקרון סופיות הדיון (Verdict: עפ"ת (מחוזי חי'') 27382-01-23 קובי סרויה נ'' מדינת ישראל (29.3.2023), Reference 11, 11). טענות כמו טעות אנוש, שכחה, חוסר תשומת לב או בלבול, אינן מהוות טעם מוצדק (Verdict: המ"ש (תעבורה י-ם) 9729-06-24 יניב אור בוקשאנסקי נ'' מדינת ישראל (29.6.2024), Reference 6, 9).',
    'הסטודנט עלול לטעות ולחשוב שכל טעות או אי-נוחות מצדיקה הארכת מועד להישפט לאחר תשלום קנס, מבלי להבין את הרף הגבוה שנקבע בפסיקה ואת החשיבות של עקרון סופיות הדיון.',
    '["הארכת מועד להישפט", "סעיף 230 לחוק סדר הדין הפלילי", "סיבות שאינן תלויות במבקש", "מניעת עיוות דין", "סופיות הדיון", "שיקול דעת שיפוטי"]'::jsonb,
    '**וריאציה 1 — תנאים להארכה:** מהם התנאים להארכת מועד להישפט לאחר תשלום קנס? ← סיבות שלא היו תלויות במבקש והבקשה הוגשה מיד לאחר הסרת המניעה, או מנימוקים מיוחדים אחרים (סעיף 230 לחוק סדר הדין הפלילי). **וריאציה 2 — פרשנות הפסיקה:** כיצד מפרשת הפסיקה את התנאים הללו? ← בדרך של צמצום, בדומה לבקשה לביטול פסק דין, ונדרשות נסיבות חריגות (המ"ש (תעבורה י-ם) 5681-02-26 קלפהולץ, רפרנס 1, 12). **וריאציה 3 — טענות שאינן מתקבלות:** אילו טענות אינן נחשבות לטעם מוצדק? ← שכחה, טעות, חוסר תשומת לב או בלבול במועד (המ"ש (תעבורה י-ם) 9729-06-24 בוקשאנסקי, רפרנס 6, 9).',
    'בית המשפט יאריך מועד להישפט לאחר תשלום קנס רק במקרים חריגים, אם הוכח שהאיחור נבע מסיבות שאינן תלויות במבקש והבקשה הוגשה מיד, או מנימוקים מיוחדים למניעת עיוות דין, וזאת בפרשנות מצמצמת (סעיף 230 לחוק סדר הדין הפלילי).',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 229", "חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 230", "המ\"ש (תעבורה י-ם) 5681-02-26 אליהו קלפהולץ נ'' מדינת ישראל (28.2.2026)", "עפ\"ת (מחוזי חי'') 27382-01-23 קובי סרויה נ'' מדינת ישראל (29.3.2023)", "המ\"ש (תעבורה י-ם) 9729-06-24 יניב אור בוקשאנסקי נ'' מדינת ישראל (29.6.2024)", "ע\"פ 40599/07 רואמי אברהם נ'' מדינת ישראל (3.12.2007)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'בקשה לביטול קנס בעבירת ברירת משפט', 3, 'לציון הומצאה כדין הודעת תשלום קנס בעבירה של ברירת משפט. ציון סבור שהעבירה לא בוצעה על ידו. מה עליו לעשות כדי לבטל את הקנס?',
    'שאלה זו מתמקדת באפשרות להגיש בקשה לביטול קנס בעבירת ברירת משפט, ובמועדים הקבועים לכך. היא מבהירה את סמכות התובע לבטל קנס ואת זכות הנקנס להישפט אם בקשתו נדחית.',
    'סעיף 229(א)(1) לחוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, קובע כי מי שנמסרה לו הודעת תשלום קנס רשאי להגיש לתובע, תוך שלושים ימים מיום ההמצאה, בקשה לביטול הקנס (Law: חוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, סעיף 229). התובע רשאי לבטל את הודעת תשלום הקנס אם נוכח כי לא נעברה עבירה, או כי היא נעברה שלא בידי מי שקיבל את ההודעה, או אם סבר שנסיבות העניין בכללותן אינן מתאימות להמשך קיום ההליכים (Law: חוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, סעיף 229(ג)). אם התובע החליט שלא לבטל את הודעת תשלום הקנס, ימציא למבקש הודעה על כך, ואז רשאי הנקנס להודיע על רצונו להישפט בתוך שלושים ימים מיום המצאת ההודעה על החלטת התובע בעניין הביטול (Law: חוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, סעיף 229(א)). הגשת בקשה לביטול אינה דוחה את המועד לתשלום הקנס (Literature: נבו - המתמחה, סדר הדין הפלילי (2026) | פרק טו - הוראות נוהל, עמ'' 112).',
    'הסטודנט עלול לבלבל בין המועדים להגשת בקשה לביטול קנס (30 יום) לבין המועדים להודעה על רצון להישפט (90 יום), או לחשוב שהגשת בקשה לביטול דוחה את מועד התשלום.',
    '["בקשה לביטול קנס", "עבירת ברירת משפט", "מועדים להגשה", "סמכות התובע", "סעיף 229 לחוק סדר הדין הפלילי", "הודעה על רצון להישפט"]'::jsonb,
    '**וריאציה 1 — מועד לבקשת ביטול:** תוך כמה זמן יש להגיש בקשה לביטול קנס לתובע? ← 30 יום מיום המצאת ההודעה (סעיף 229(א)(1) לחוק סדר הדין הפלילי). **וריאציה 2 — מה קורה אם הבקשה נדחית?** ← הנקנס רשאי להודיע על רצונו להישפט תוך 30 יום מיום המצאת ההודעה על הדחייה (סעיף 229(א) לחוק סדר הדין הפלילי). **וריאציה 3 — השפעת הבקשה על התשלום:** האם הגשת בקשה לביטול דוחה את מועד תשלום הקנס? ← לא (נבו - המתמחה, סדר הדין הפלילי, עמ'' 112).',
    'כדי לבטל קנס ברירת משפט, יש להגיש בקשה לתובע תוך 30 יום. אם הבקשה נדחית, ניתן להודיע על רצון להישפט תוך 30 יום נוספים. הגשת הבקשה אינה דוחה את מועד תשלום הקנס (סעיף 229 לחוק סדר הדין הפלילי).',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 229", "תקנות סדר הדין הפלילי, תשל\"ד-1974, סעיף 42א", "נבו - המתמחה, סדר הדין הפלילי (2026) | פרק טו - הוראות נוהל, עמ'' 112"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'הבדל בין עבירת ברירת משפט לעבירה מינהלית', 4, 'מהו ההבדל המהותי בין עבירת ברירת משפט (כמו עבירת תעבורה קלה) לבין עבירה מינהלית (כמו עבירה על חוקי עבודה מסוימים), בהקשר של תשלום קנס ובקשה להישפט?',
    'שאלה זו עוסקת בהבחנה המהותית בין עבירות ברירת משפט לעבירות מינהליות, שהיא קריטית להבנת סדרי הדין וההשלכות המשפטיות של כל אחת מהן. היא מדגישה את אופיו הפלילי של מסלול ברירת המשפט לעומת אופיו המינהלי של מסלול העבירה המינהלית.',
    'ההבחנה בין הליך ברירת קנס (או ברירת משפט) לבין הליך של הטלת קנס מינהלי היא ברורה: הליך של קנס מינהלי הוא במסלול המינהלי, להבדיל מהליך ברירת המשפט אשר מצוי במסלול הפלילי (Literature: יאיר ניידורף, הליכים במס הכנסה - כרך ב (2025) | פרק שמונה-עשר עבירות מנהליות, עמ'' 30). בעבירת ברירת משפט, אי-תשלום הקנס תוך התקופה הקבועה בחוק מעלה את הדיון למסלול של הליך פלילי, וההזמנה שניתנה תיחשב כהזמנה לדין פלילי. תשלום הקנס רואה את מי שקיבל את ברירת הקנס כאילו הודה באשמה בפני בית המשפט, הורשע ונשא את עונשו (Literature: יאיר ניידורף, הליכים במס הכנסה - כרך ב (2025) | פרק שמונה-עשר עבירות מנהליות, עמ'' 30; Law: חוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, סעיף 229). לעומת זאת, במקרה של עבירה מינהלית, אי-תשלום קנס מינהלי אינו מעלה את העבירה למסלול פלילי, אלא גורר תוספת הפרשי הצמדה ותוספת פיגור, וגבייתו נעשית באמצעי אכיפה מינהליים. המסלול הפלילי קיים במקרה של עבירות מינהליות רק אם מי שמייחסים לו עבירה כזו בוחר במסלול הפלילי על ידי הודעה על רצונו להישפט (Literature: יאיר ניידורף, הליכים במס הכנסה - כרך ב (2025) | פרק שמונה-עשר עבירות מנהליות, עמ'' 30; Law: חוק העבירות המינהליות, תשמ"ו-1985, סעיף 13).',
    'הסטודנט עלול לטעות ולייחס את אותן השלכות משפטיות לאי-תשלום קנס בשני סוגי העבירות, מבלי להבחין בין אופיו הפלילי של מסלול ברירת המשפט לבין אופיו המינהלי של מסלול העבירה המינהלית.',
    '["עבירת ברירת משפט", "עבירה מינהלית", "מסלול פלילי", "מסלול מינהלי", "תשלום קנס", "אי-תשלום קנס"]'::jsonb,
    '**וריאציה 1 — אופי המסלול:** מהו אופי המסלול של עבירת ברירת משפט לעומת עבירה מינהלית? ← ברירת משפט היא במסלול הפלילי, עבירה מינהלית היא במסלול המינהלי (יאיר ניידורף, הליכים במס הכנסה, עמ'' 30). **וריאציה 2 — השלכות אי-תשלום:** מה קורה באי-תשלום קנס ברירת משפט לעומת קנס מינהלי? ← ברירת משפט: הליך פלילי. קנס מינהלי: גבייה מינהלית (יאיר ניידורף, הליכים במס הכנסה, עמ'' 30). **וריאציה 3 — תשלום קנס כהודאה:** מהי משמעות תשלום קנס בשני הסוגים? ← ברירת משפט: הודאה באשמה, הרשעה ונשיאת עונש. קנס מינהלי: העבירה כופרה (סעיף 229(ח) לחוק סדר הדין הפלילי; נבו - המתמחה, סדר הדין הפלילי, עמ'' 111).',
    'עבירת ברירת משפט היא במסלול הפלילי, ואי-תשלום הקנס מוביל להליך פלילי. עבירה מינהלית היא במסלול המינהלי, ואי-תשלום הקנס מוביל לגבייה מינהלית, אלא אם הנקנס בוחר להישפט (יאיר ניידורף, הליכים במס הכנסה).',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 229", "חוק העבירות המינהליות, תשמ\"ו-1985, סעיף 13", "יאיר ניידורף, הליכים במס הכנסה - כרך ב (2025) | פרק שמונה-עשר עבירות מנהליות, עמ'' 30", "נבו - המתמחה, סדר הדין הפלילי (2026) | פרק טו - הוראות נוהל, עמ'' 111"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'ציון רשאי להגיש בקשה להישפט בתוך 90 יום מיום התשלום, שכן זכותו להישפט אינה נפגעת.', false, 'בחירה זו שגויה. תשלום הקנס כמוהו כהודאה באשמה, הרשעה ונשיאת עונש, והוא מבטל את האפשרות להישפט, למעט חריגים מצומצמים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'תשלום הקנס כמוהו כהודאה באשמה, הרשעה ונשיאת עונש, ולכן ציון אינו רשאי עוד להישפט על העבירה, אלא אם כן התובע ביטל את הודעת הקנס או שבית המשפט החליט לקיים את משפטו באיחור מטעמים מיוחדים.', true, 'בחירה זו נכונה. סעיף 229(ח) לחוק סדר הדין הפלילי קובע את הכלל בדבר תשלום קנס כהודאה, ואת שני החריגים המאפשרים בכל זאת קיום משפט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'ציון רשאי להגיש בקשה לביטול הקנס לתובע בתוך 30 יום מיום התשלום, ורק אם בקשתו תידחה, יוכל להישפט.', false, 'בחירה זו שגויה. בקשה לביטול קנס מוגשת בתוך 30 יום מיום המצאת ההודעה, ולא מיום התשלום. לאחר התשלום, הכלל הוא שאין אפשרות להישפט.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'תשלום הקנס אינו משפיע על זכותו של ציון להישפט, והוא רשאי להגיש בקשה להישפט בכל עת.', false, 'בחירה זו שגויה. תשלום הקנס משפיע באופן דרמטי על זכותו של ציון להישפט, והוא אינו רשאי להגיש בקשה להישפט בכל עת.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'בית המשפט יאריך את המועד רק אם ציון יוכיח שהתשלום בוצע מסיבות שאינן תלויות בו, וכי הבקשה הוגשה מיד לאחר שהוסרה המניעה, או מנימוקים מיוחדים אחרים שיפרט בית המשפט.', true, 'בחירה זו נכונה. סעיף 230 לחוק סדר הדין הפלילי קובע את התנאים להארכת מועד להישפט, והפסיקה מפרשת אותם בצמצום, במיוחד לאחר תשלום קנס.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'בית המשפט יאריך את המועד אם ציון יוכיח כי לא הוא ביצע את העבירה, וזאת כדי למנוע עיוות דין.', false, 'בחירה זו שגויה. עצם הכפירה בעבירה אינה מספיקה להארכת מועד לאחר תשלום קנס, אלא נדרשת תשתית ראייתית בעלת משקל המצביעה על פוטנציאל ממשי לשינוי התוצאה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'בית המשפט יאריך את המועד רק אם התובע הסכים לכך, שכן תשלום הקנס מסיים את ההליך.', false, 'בחירה זו שגויה. הסכמת התובע אינה תנאי הכרחי, אלא שיקול דעת בית המשפט בהתאם לתנאים הקבועים בסעיף 230 לחוק סדר הדין הפלילי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'בית המשפט יאריך את המועד אם ציון יוכיח כי התשלום בוצע על ידי אדם אחר ללא ידיעתו.', false, 'בחירה זו שגויה. אף שזו טענה רלוונטית, היא אינה מהווה כשלעצמה עילה מספקת להארכת מועד, ובית המשפט אינו אמור להתחקות אחר זהות המשלם או נסיבות התשלום.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'עליו להגיש בקשה לביטול הקנס לתובע בתוך 90 יום מיום ההמצאה, ורק אם בקשתו תידחה, יוכל להישפט.', false, 'בחירה זו שגויה. המועד להגשת בקשה לביטול קנס הוא 30 יום, ולא 90 יום.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'עליו להגיש בקשה לביטול הקנס לתובע בתוך 30 יום מיום ההמצאה. אם בקשתו תידחה, הוא רשאי להודיע על רצונו להישפט בתוך 30 יום מיום המצאת ההודעה על הדחייה.', true, 'בחירה זו נכונה. סעיף 229(א)(1) לחוק סדר הדין הפלילי קובע את המועדים להגשת בקשה לביטול קנס ולהודעה על רצון להישפט לאחר דחייה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'עליו להודיע על רצונו להישפט בתוך 90 יום מיום ההמצאה, ואין צורך להגיש בקשה לביטול קנס.', false, 'בחירה זו שגויה. אף שזו אפשרות, היא אינה הדרך ל''ביטול'' הקנס, אלא ל''הישפט'' עליו. הגשת בקשה לביטול היא הליך נפרד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'עליו לשלם את הקנס במועד, ולאחר מכן להגיש בקשה לביטול הקנס לתובע.', false, 'בחירה זו שגויה. הגשת בקשה לביטול קנס אינה דוחה את המועד לתשלום, אך תשלום הקנס כמוהו כהודאה באשמה ומקשה על ביטולו.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'עבירת ברירת משפט היא במסלול הפלילי, ואי-תשלום הקנס מוביל להליך פלילי. עבירה מינהלית היא במסלול המינהלי, ואי-תשלום הקנס מוביל לגבייה מינהלית, אלא אם הנקנס בוחר להישפט.', true, 'בחירה זו נכונה. זהו ההבדל המהותי בין שני סוגי העבירות, כפי שהובהר בפסיקה ובספרות המשפטית, ומשפיע על אופי ההליך והסנקציות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'בשני סוגי העבירות, אי-תשלום הקנס מוביל אוטומטית להליך פלילי, אך בעבירה מינהלית ניתן להגיש בקשה לביטול הקנס במועד ארוך יותר.', false, 'בחירה זו שגויה. אי-תשלום קנס מינהלי אינו מוביל אוטומטית להליך פלילי, והמועדים להגשת בקשה לביטול קנס דומים בשני הסוגים.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'עבירת ברירת משפט ניתנת לביטול רק על ידי התובע, בעוד שעבירה מינהלית ניתנת לביטול גם על ידי בית המשפט.', false, 'בחירה זו שגויה. בשני המקרים, התובע הוא הגורם המוסמך לבטל את הקנס, ובית המשפט דן בעבירה רק אם הנקנס בחר להישפט.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בשני סוגי העבירות, תשלום הקנס כמוהו כהודאה באשמה, הרשעה ונשיאת עונש, אך בעבירה מינהלית ניתן להפחית את הקנס בקלות רבה יותר.', false, 'בחירה זו שגויה. בעבירה מינהלית, תשלום הקנס כמוהו כ''כפירת העבירה'' ולא כהודאה באשמה פלילית, והפחתת קנסות כפופה לתנאים דומים.', 4);

END $$;

-- ============================================================
-- Q35 — 2019-S-Q35 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q35';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q35 skipped: external_id % already exists', '2019-S-Q35';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q35', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'רוני הורשע בעבירת האיומים בבית משפט השלום. הוגש בעניינו תסקיר קצין מבחן מטעם שירות המבחן למבוגרים. רוני אינו מיוצג בידי סנגור, וקצין המבחן לא הביע כל עמדה באשר למסירת התסקיר. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 35}'::jsonb,
    'השאלה עוסקת בכללים למסירת תסקיר קצין מבחן לנאשם בגיר שאינו מיוצג על ידי סנגור. היא מתמקדת בסעיף 191 לחוק סדר הדין הפלילי, הקובע את ברירת המחדל למסירת התסקיר לתובע ולסנגור, ואת שיקול הדעת של בית המשפט למסור אותו גם לנאשם עצמו, תוך איזון בין זכות הנאשם לדעת את החומר בעניינו לבין סודיות התסקיר.',
    'סעיף 191 לחוק סדר הדין הפלילי [נוסח משולב], התשמ"ב-1982, קובע כי "העתק התסקיר של קצין מבחן... יימסרו לתובע ולסניגורו של הנאשם, אם יש לו סניגור... אולם רשאי בית המשפט לצוות שהעתק כאמור יימסר גם לנאשם, ורשאי בית המשפט, על פי הצעה מנומקת של קצין המבחן או על פי יזמתו הוא, לצוות מטעמים מיוחדים שאין לגלות את תכנם, כולו או מקצתו, לבעלי הדין" (Law: חוק סדר הדין הפלילי [נוסח משולב], תשמ"ב-1982, סעיף 191). במקרה של רוני, שאינו מיוצג על ידי סנגור, העתק התסקיר יימסר לתובעת. לגבי רוני עצמו, בית המשפט רשאי לצוות על מסירת העתק התסקיר אליו, אך אין זו חובה. ברירת המחדל היא שהנאשם אינו מקבל את התסקיר, אלא ברשות בית המשפט (Verdict: ת"פ (שלום ק"ג) 39116-06-16 מדינת ישראל נ'' איוון פידבירניי- ז"ל (22.8.2021), Reference 7, 14). הכלל הוא שלנאשם זכות טיעון באשר לכתוב בתסקיר, ובית המשפט רשאי להורות שהעתק התסקיר יימסר גם לנאשם (Literature: יצחק עמית, חסיונות ואינטרסים מוגנים - הליכי גילוי ועיון במשפט האזרחי והפלילי (2021) | א. המסגרת הנורמטיבית, עמ'' 1).',
    'הסטודנט עלול לטעות ולחשוב שהתסקיר נמסר אוטומטית לנאשם, או שאינו נמסר כלל לתובע, מבלי להבחין בין זכות המסירה לתובע ולסנגור לבין שיקול הדעת של בית המשפט במסירה לנאשם.',
    '["תסקיר קצין מבחן", "מסירת תסקיר", "סעיף 191 לחוק סדר הדין הפלילי", "נאשם לא מיוצג", "שיקול דעת בית המשפט", "חיסיון יחסי"]'::jsonb,
    '**וריאציה 1 — מסירה לתובע ולסנגור:** למי נמסר העתק תסקיר קצין מבחן כברירת מחדל? ← לתובע ולסנגורו של הנאשם (סעיף 191 לחוק סדר הדין הפלילי). **וריאציה 2 — מסירה לנאשם:** האם העתק התסקיר נמסר לנאשם עצמו? ← בית המשפט רשאי לצוות על מסירתו לנאשם, אך זו אינה חובה (סעיף 191 לחוק סדר הדין הפלילי). **וריאציה 3 — מניעת גילוי:** מתי רשאי בית המשפט למנוע גילוי התסקיר? ← מטעמים מיוחדים, על פי הצעת קצין המבחן או מיוזמתו (סעיף 191 לחוק סדר הדין הפלילי).',
    'העתק תסקיר קצין מבחן יימסר לתובעת, ובית המשפט רשאי לצוות על מסירתו לרוני, הנאשם, גם אם אינו מיוצג, אך אין זו חובה (סעיף 191 לחוק סדר הדין הפלילי).',
    '["חוק סדר הדין הפלילי [נוסח משולב], תשמ\"ב-1982, סעיף 191", "תקנות סדר הדין הפלילי, תשל\"ד-1974, סעיף 27", "ת\"פ (שלום ק\"ג) 39116-06-16 מדינת ישראל נ'' איוון פידבירניי- ז\"ל (22.8.2021)", "יצחק עמית, חסיונות ואינטרסים מוגנים - הליכי גילוי ועיון במשפט האזרחי והפלילי (2021) | א. המסגרת הנורמטיבית, עמ'' 1"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'התסקיר יימסר לבית המשפט ולתובעת, ובית המשפט רשאי לצוות שהתסקיר יימסר גם לרוני.', true, 'בחירה זו נכונה. סעיף 191 לחוק סדר הדין הפלילי קובע כי העתק התסקיר יימסר לתובע ולסנגורו של הנאשם. במקרה שאין סנגור, התסקיר יימסר לתובע בלבד, ובית המשפט רשאי לצוות על מסירתו לנאשם.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'התסקיר יימסר לבית המשפט, לתובעת ולרוני, אולם בית המשפט רשאי לצוות שהתסקיר לא יימסר לרוני.', false, 'בחירה זו שגויה. ברירת המחדל היא שהתסקיר אינו נמסר לנאשם עצמו, אלא אם בית המשפט הורה אחרת. בית המשפט רשאי למנוע מסירה לנאשם רק מטעמים מיוחדים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'התסקיר יימסר לבית המשפט, אולם בית המשפט רשאי לצוות שהתסקיר יימסר לתובעת ולרוני.', false, 'בחירה זו שגויה. התסקיר נמסר תמיד לתובע (ולסנגור אם ישנו), ואינו נתון לשיקול דעת בית המשפט בעניין זה. רק מסירתו לנאשם עצמו נתונה לשיקול דעת בית המשפט.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'התסקיר יימסר לבית המשפט, לתובעת ולרוני.', false, 'בחירה זו שגויה. אין חובה למסור את התסקיר לנאשם עצמו, אלא אם בית המשפט מורה על כך. ברירת המחדל היא שהנאשם אינו מקבל את התסקיר.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'מסירת תסקיר קצין מבחן לקטין', 1, 'דני, קטין בן 16, הורשע בעבירת גניבה. הוגש בעניינו תסקיר קצין מבחן לנוער. דני מיוצג על ידי סנגור. מה הדין לגבי מסירת התסקיר?',
    'שאלה זו בוחנת את ההסדר הייחודי למסירת תסקיר קצין מבחן בעניינם של קטינים, השונה מההסדר החל על בגירים. היא מדגישה את ההגנה המיוחדת על פרטיות הקטין, תוך שמירה על זכות העיון של התובע והסנגור.',
    'סעיף 23 לחוק הנוער (שפיטה, ענישה ודרכי טיפול), התשל"א-1971, קובע הסדר שונה לגבי קטינים. לפיו, "העתק התסקיר של קצין המבחן... לא יימסרו לבעלי הדין ולבאי כוחם אלא אם בית המשפט הורה הוראה אחרת, אולם רשאים התובע והסניגור של הנאשם לעיין במסמכים האמורים בתיק בית המשפט" (Law: חוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל"א-1971, סעיף 23). כלומר, ברירת המחדל היא אי-מסירת העתק התסקיר לבעלי הדין ובאי כוחם, אך התובע והסנגור רשאים לעיין בו בתיק בית המשפט (Verdict: ע"פ 3472/11 פלוני נ'' מדינת ישראל (3.9.2012), Reference 1; Verdict: (מחוזי ירושלים) 15357-04-18 מדינת ישראל נ'' נ׳ ו׳ (20.4.2018), Reference 9). הסדר זה מבטא את הרצון להגן על פרטיות הקטין, תוך מתן אפשרות לסנגור ולתובע למלא את תפקידם בהליך (Literature: נבו - המתמחה, סדר הדין הפלילי (2026) | חוק הנוער (שפיטה, ענישה ודרכי טיפול), עמ'' 123).',
    'הסטודנט עלול לטעות וליישם את הכללים החלים על בגירים (סעיף 191 לחסד"פ) גם על קטינים, מבלי להבחין בהסדר הייחודי הקבוע בחוק הנוער.',
    '["תסקיר קצין מבחן לנוער", "חוק הנוער", "הגנת פרטיות קטין", "זכות עיון", "מסירת תסקיר", "סעיף 23 לחוק הנוער"]'::jsonb,
    '**וריאציה 1 — מסירת תסקיר לקטין:** האם העתק תסקיר קצין מבחן לקטין נמסר לסנגור ולתובע? ← לא, אלא אם בית המשפט הורה אחרת (סעיף 23 לחוק הנוער). **וריאציה 2 — זכות עיון לקטין:** האם התובע והסנגור של קטין רשאים לעיין בתסקיר? ← כן, הם רשאים לעיין בו בתיק בית המשפט (סעיף 23 לחוק הנוער). **וריאציה 3 — הבדל מבגיר:** מה ההבדל העיקרי בין קטין לבגיר בעניין מסירת תסקיר? ← אצל בגיר העתק נמסר לסנגור ולתובע כברירת מחדל, אצל קטין לא נמסר העתק אלא רק זכות עיון (ע"פ 3472/11 פלוני, רפרנס 1; (מחוזי ירושלים) 15357-04-18 מדינת ישראל נ'' נ׳ ו׳, רפרנס 9).',
    'העתק תסקיר קצין מבחן בעניינו של קטין לא יימסר לבעלי הדין, אך התובע והסנגור רשאים לעיין בו בתיק בית המשפט, אלא אם בית המשפט הורה אחרת (סעיף 23 לחוק הנוער).',
    '["חוק הנוער (שפיטה, ענישה ודרכי טיפול), תשל\"א-1971, סעיף 23", "ע\"פ 3472/11 פלוני נ'' מדינת ישראל (3.9.2012)", "(מחוזי ירושלים) 15357-04-18 מדינת ישראל נ'' נ׳ ו׳ (20.4.2018)", "נבו - המתמחה, סדר הדין הפלילי (2026) | חוק הנוער (שפיטה, ענישה ודרכי טיפול), עמ'' 123"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'מעמד תסקיר קצין מבחן כראיה', 2, 'האם תסקיר קצין מבחן נחשב לראיה בהליך הפלילי, והאם קצין המבחן יכול להיחקר עליו?',
    'שאלה זו עוסקת במעמדו הייחודי של תסקיר קצין המבחן בהליך הפלילי, ובשאלת קבילותו כראיה ואפשרות חקירת קצין המבחן. היא מדגישה את תפקידו של קצין המבחן כ''קצין בית המשפט'' ואת חובת האמון שלו כלפי בית המשפט.',
    'הפסיקה קבעה כי מעמדו של קצין המבחן מיוחד: "הוא אינו שופר של מי מהצדדים, אינו עד או עד מומחה, אלא הוא גורם מקצועי ממליץ, החב חובת אמון לבית המשפט ומשמש כ''קצין בית המשפט'' (Officer of the Court)" (Verdict: ע"פ 3472/11 פלוני נ'' מדינת ישראל (3.9.2012), Reference 1, 19). לפיכך, קצין המבחן אינו נחקר על תסקירו, והתסקיר אינו בגדר ראיה, ואינו בהכרח מבוסס על מידע העומד בתנאי הקבילות המקובלים (Verdict: ע"פ 3472/11 פלוני נ'' מדינת ישראל (3.9.2012), Reference 1, 19). בית המשפט המחוזי אף סבר כי "אין מקום להתיר חקירת קצין המבחן ע"י מי מהצדדים וככלל, למעט מקרים חריגים ויוצאי דופן, גם אין מקום להפנות אליו שאלות הבהרה" (Verdict: ת"פ (מחוזי חיפה) 6104/07 מדינת ישראל נ'' איברהים בן עבדאללה כליל (24.4.2008), Reference 4).',
    'הסטודנט עלול לטעות ולייחס לתסקיר קצין המבחן מעמד של חוות דעת מומחה רגילה, ובכך להסיק שקצין המבחן ניתן לחקירה נגדית ככל עד מומחה.',
    '["קצין בית המשפט", "תסקיר קצין מבחן", "מעמד ראייתי", "חקירה נגדית", "חובת אמון", "ע\"פ 3472/11 פלוני"]'::jsonb,
    '**וריאציה 1 — מעמד קצין המבחן:** מה מעמדו של קצין המבחן? ← הוא ''קצין בית המשפט'', לא עד או עד מומחה (ע"פ 3472/11 פלוני, רפרנס 1). **וריאציה 2 — מעמד התסקיר:** האם התסקיר הוא ראיה? ← לא, התסקיר אינו בגדר ראיה (ע"פ 3472/11 פלוני, רפרנס 1). **וריאציה 3 — חקירת קצין המבחן:** האם קצין המבחן נחקר על תסקירו? ← לא, ככלל אינו נחקר, למעט מקרים חריגים ויוצאי דופן (ת"פ (מחוזי חיפה) 6104/07 מדינת ישראל נ'' איברהים בן עבדאללה כליל, רפרנס 4).',
    'תסקיר קצין מבחן אינו נחשב לראיה בהליך הפלילי, וקצין המבחן אינו נחקר על תסקירו, שכן הוא משמש כ''קצין בית המשפט'' וחב חובת אמון לבית המשפט (ע"פ 3472/11 פלוני).',
    '["ע\"פ 3472/11 פלוני נ'' מדינת ישראל (3.9.2012)", "ת\"פ (מחוזי חיפה) 6104/07 מדינת ישראל נ'' איברהים בן עבדאללה כליל (24.4.2008)", "רע\"פ 486/18 סאבר סועאד נ'' מדינת ישראל (4.3.2018)", "ת\"פ (שלום ת\"א) 1752/09 פלוני נ'' מדינת ישראל (5.6.2023)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'חיסיון חומר הגלם של התסקיר', 3, 'הסנגור של נאשם מבקש לקבל לעיונו את חומרי הגלם ששימשו את שירות המבחן להכנת התסקיר, לרבות אבחונים פסיכולוגיים ופסיכיאטריים. האם בקשתו תתקבל?',
    'שאלה זו עוסקת בהבחנה בין חיסיון התסקיר עצמו לבין חיסיון חומרי הגלם ששימשו להכנתו. היא מדגישה את החיסיון המוחלט החל על חומרי הגלם, מתוך חשש לפגיעה ביכולת שירות המבחן לתפקד באופן יעיל ומהימן.',
    'פסיקת בית המשפט העליון קבעה "חיסיון מוחלט לגבי תרשומות פנימיות ולגבי חומר המונח בבסיס תסקיריו של שירות המבחן, כדוגמת חוות-דעת מקצועיות ואבחונים פסיכולוגיים אשר שימשו את שירות המבחן לצורך הכנת תסקירייו" (Verdict: (מחוזי ירושלים) 15357-04-18 מדינת ישראל נ'' נ׳ ו׳ (20.4.2018), Reference 8). נפסק כי חומרים אלה לא יימסרו לעיון הסנגוריה כלל (Verdict: (מחוזי ירושלים) 15357-04-18 מדינת ישראל נ'' נ׳ ו׳ (20.4.2018), Reference 8; Verdict: ע"פ 3472/11 פלוני נ'' מדינת ישראל (3.9.2012), Reference 1). הרציונל לכך הוא שחשיפת חומרי הגלם עלולה "להביא לפגיעה אנושה ביכולתו של שירות המבחן לאסוף מידע מהימן ומקיף על נאשם וליתן המלצה מושכלת בעניינו, תוך הפעלת שיקול דעת עצמאי ובלתי תלוי, בהתחשב במעמדו המיוחד כקצין בית המשפט" (Verdict: רע"פ 486/18 סאבר סועאד נ'' מדינת ישראל (4.3.2018), Reference 22).',
    'הסטודנט עלול לטעות ולחשוב שכל חומר הקשור לתסקיר הוא ''חומר חקירה'' שחובה למסור לסנגור, מבלי להבחין בין התסקיר עצמו לחומרי הגלם שעליו חל חיסיון מוחלט.',
    '["חיסיון מוחלט", "חומרי גלם", "תסקיר קצין מבחן", "אבחונים פסיכולוגיים", "זכות עיון", "רע\"פ 486/18 סאבר סועאד"]'::jsonb,
    '**וריאציה 1 — חיסיון חומרי גלם:** האם חומרי הגלם של התסקיר חסויים? ← כן, חל עליהם חיסיון מוחלט ולא יימסרו לסנגוריה (ע"פ 3472/11 פלוני, רפרנס 8). **וריאציה 2 — רציונל החיסיון:** מדוע חומרי הגלם חסויים? ← כדי למנוע פגיעה ביכולת שירות המבחן לאסוף מידע מהימן ולתת המלצה מושכלת (רע"פ 486/18 סאבר סועאד, רפרנס 22). **וריאציה 3 — הבחנה בין תסקיר לחומר גלם:** מה ההבחנה בין חיסיון התסקיר לחיסיון חומרי הגלם? ← התסקיר עצמו חסוי באופן יחסי, חומרי הגלם חסויים באופן מוחלט (ע"פ 3472/11 פלוני, רפרנס 8).',
    'על חומרי הגלם ששימשו להכנת תסקיר קצין מבחן, כגון אבחונים פסיכולוגיים, חל חיסיון מוחלט, והם לא יימסרו לעיון הסנגוריה, כדי למנוע פגיעה ביכולת שירות המבחן לתפקד (ע"פ 3472/11 פלוני).',
    '["ע\"פ 3472/11 פלוני נ'' מדינת ישראל (3.9.2012)", "(מחוזי ירושלים) 15357-04-18 מדינת ישראל נ'' נ׳ ו׳ (20.4.2018)", "רע\"פ 486/18 סאבר סועאד נ'' מדינת ישראל (4.3.2018)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'שימוש בתסקיר בהליך אזרחי', 4, 'נאשם שהורשע בהליך פלילי, והוגש בעניינו תסקיר קצין מבחן, הגיש תביעה אזרחית נגד גורם אחר. האם ניתן להשתמש בתסקיר קצין המבחן מההליך הפלילי כראיה בהליך האזרחי?',
    'שאלה זו עוסקת בהיקף החיסיון והסודיות החלים על תסקיר קצין מבחן, ובפרט על האפשרות להשתמש בו בהליכים משפטיים שונים מההליך הפלילי שלשמו הוכן. היא מדגישה את העיקרון של הגבלת השימוש בתסקיר למטרתו המקורית.',
    'תקנה 28(א) לתקנות סדר הדין הפלילי, התשל"ד-1974, קובעת הוראת סודיות מפורשת: "מי שהגיע לידיו תסקיר לצורך הליך משפטי לא ישתמש בתסקיר או בתוצאות של הבדיקות והחקירות האחרות שנמסרו לפי תקנות אלה ולא יגלה ידיעות שהגיעו לידו באמצעות התסקיר, אלא לצורך ההליך המשפטי שבקשר אליו נמסר התסקיר" (Law: תקנות סדר הדין הפלילי, תשל"ד-1974, סעיף 28). איסור זה מתייחס לכלל הגורמים המצויים במגע עם שירות המבחן, לרבות התביעה, הסנגור ובית המשפט (Verdict: ת"פ (שלום ק"ג) 39116-06-16 מדינת ישראל נ'' איוון פידבירניי- ז"ל (22.8.2021), Reference 14). הפסיקה הדגישה כי חשיפת התסקיר ושימוש בו לצורך הליך חיצוני להליך הפלילי עלולה לפגוע באמון הציבור בקציני המבחן ולסכל הכנת תסקירים מקצועיים בעתיד (Verdict: ת"פ (שלום ת"א) 1752/09 פלוני נ'' מדינת ישראל (5.6.2023), Reference 19). עם זאת, בית המשפט האזרחי הדן בתובענה רשאי לעיין בתסקירים או לתת הוראות לעניין דרך עיון הצדדים בהם, ככל שהוא רואה בהם מסמכים רלוונטיים (Verdict: ת"פ (שלום ת"א) 53249-07-18 לבנה-לוסי מור נ'' מדינת ישראל (3.4.2022), Reference 13).',
    'הסטודנט עלול לטעות ולחשוב שמרגע שהתסקיר הוגש לבית המשפט, הוא הופך למסמך ציבורי שניתן לעשות בו שימוש חופשי בכל הליך, מבלי להכיר את מגבלות הסודיות והשימוש הקבועות בתקנות ובפסיקה.',
    '["חיסיון יחסי", "סודיות תסקיר", "שימוש בתסקיר", "הליך אזרחי", "תקנה 28 לתקנות סדר הדין הפלילי", "אינטרס ציבורי"]'::jsonb,
    '**וריאציה 1 — איסור שימוש בהליך אחר:** האם מותר להשתמש בתסקיר קצין מבחן מהליך פלילי בהליך אזרחי? ← לא, תקנה 28(א) לתקנות סדר הדין הפלילי אוסרת שימוש בתסקיר שלא לצורך ההליך שלשמו נמסר. **וריאציה 2 — רציונל האיסור:** מדוע אסור להשתמש בתסקיר בהליך אחר? ← כדי למנוע פגיעה באמון הציבור בקציני המבחן וביכולתם להכין תסקירים מקצועיים (ת"פ (שלום ת"א) 1752/09 פלוני, רפרנס 19). **וריאציה 3 — סמכות בית המשפט האזרחי:** האם בית המשפט האזרחי יכול לעיין בתסקיר? ← כן, אם הוא רואה בו מסמך רלוונטי, הוא רשאי לעיין בו או לתת הוראות לעניין דרך עיון הצדדים (ת"פ (שלום ת"א) 53249-07-18 לבנה-לוסי מור, רפרנס 13).',
    'תסקיר קצין מבחן שהוגש בהליך פלילי אינו יכול לשמש כראיה בהליך אזרחי, שכן תקנה 28(א) לתקנות סדר הדין הפלילי אוסרת שימוש בתסקיר שלא לצורך ההליך שלשמו נמסר, מתוך הגנה על סודיות ומעמד שירות המבחן.',
    '["תקנות סדר הדין הפלילי, תשל\"ד-1974, סעיף 28", "ת\"פ (שלום ק\"ג) 39116-06-16 מדינת ישראל נ'' איוון פידבירניי- ז\"ל (22.8.2021)", "ת\"פ (שלום ת\"א) 1752/09 פלוני נ'' מדינת ישראל (5.6.2023)", "ת\"פ (שלום ת\"א) 53249-07-18 לבנה-לוסי מור נ'' מדינת ישראל (3.4.2022)", "יצחק עמית, חסיונות ואינטרסים מוגנים - הליכי גילוי ועיון במשפט האזרחי והפלילי (2021) | פרק כד תסקיר שירות מבחן ותסקיר נפגע עבירה, עמ'' 13"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'העתק התסקיר יימסר לתובע ולסנגורו של דני, ובית המשפט רשאי לצוות על מסירתו לדני עצמו.', false, 'בחירה זו שגויה. זהו הכלל החל על בגירים. לגבי קטינים, ההסדר שונה וקובע ברירת מחדל של אי-מסירה לבעלי הדין.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'העתק התסקיר לא יימסר לבעלי הדין ולבאי כוחם, אלא אם בית המשפט הורה אחרת, אולם התובע והסנגור רשאים לעיין בו בתיק בית המשפט.', true, 'בחירה זו נכונה. סעיף 23 לחוק הנוער קובע הסדר מיוחד לקטינים, לפיו העתק התסקיר לא יימסר לבעלי הדין, אך התובע והסנגור רשאים לעיין בו בתיק בית המשפט.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'התסקיר יימסר רק לבית המשפט, ורק אם בית המשפט יורה על כך, הוא יימסר לתובע ולסנגור.', false, 'בחירה זו שגויה. התובע והסנגור רשאים לעיין בתסקיר בתיק בית המשפט גם ללא הוראה מפורשת, אלא אם בית המשפט שלל זאת מטעמים מיוחדים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'התסקיר יימסר לדני עצמו, לסנגורו ולתובע, שכן זכותו של קטין לדעת את תוכן התסקיר גבוהה יותר.', false, 'בחירה זו שגויה. ההסדר לגבי קטינים מחמיר יותר מבחינת מסירת העתק התסקיר, ואינו מאפשר מסירה אוטומטית לדני עצמו.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'כן, התסקיר הוא ראיה לכל דבר ועניין, וקצין המבחן יכול להיחקר עליו כעד מומחה.', false, 'בחירה זו שגויה. מעמדו של קצין המבחן מיוחד, והתסקיר אינו נחשב לראיה במובן הקלאסי, וקצין המבחן אינו נחקר עליו ככל עד מומחה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'לא, התסקיר אינו בגדר ראיה, וקצין המבחן אינו נחקר על תסקירו, שכן הוא משמש כ''קצין בית המשפט'' וחב חובת אמון לבית המשפט.', true, 'בחירה זו נכונה. הפסיקה קבעה כי קצין המבחן הוא ''קצין בית המשפט'', ותסקירו אינו ראיה, ולכן אינו נחקר עליו.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'התסקיר הוא ראיה, אך קצין המבחן יכול להיחקר עליו רק ברשות בית המשפט ומטעמים מיוחדים.', false, 'בחירה זו שגויה. התסקיר אינו ראיה, וחקירת קצין המבחן היא חריג נדיר ביותר, ולא רק ברשות בית המשפט.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'התסקיר אינו ראיה, אך קצין המבחן יכול להיחקר עליו על ידי הסנגור בלבד, כדי להבטיח את זכות הנאשם להליך הוגן.', false, 'בחירה זו שגויה. קצין המבחן אינו נחקר על תסקירו, גם לא על ידי הסנגור, למעט מקרים חריגים ויוצאי דופן ביותר.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'כן, חומרי הגלם הם חלק מחומר החקירה, ועל הסנגור לקבלם כדי להכין הגנה הולמת.', false, 'בחירה זו שגויה. הפסיקה קבעה חיסיון מוחלט על חומרי הגלם של התסקיר, והם אינם נחשבים לחומר חקירה שחובה למסור לסנגור.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'לא, פסיקת בית המשפט העליון קבעה חיסיון מוחלט לגבי חומר המונח בבסיס תסקירי שירות המבחן, והם לא יימסרו לעיון הסנגוריה כלל.', true, 'בחירה זו נכונה. הלכת פלוני (ע"פ 3472/11) קבעה חיסיון מוחלט על חומרי הגלם, מתוך חשש לפגיעה ביכולת שירות המבחן לאסוף מידע מהימן.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'כן, אך רק אם בית המשפט ימצא כי הדבר חיוני להגנת הנאשם, וזאת לאחר איזון בין האינטרסים.', false, 'בחירה זו שגויה. איזון אינטרסים רלוונטי לחיסיון יחסי של התסקיר עצמו, אך לא לחומרי הגלם עליהם חל חיסיון מוחלט.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לא, אלא אם קצין המבחן ימליץ על מסירתם, וזאת מטעמים מיוחדים שיירשמו.', false, 'בחירה זו שגויה. קצין המבחן אינו הגורם המוסמך להחליט על הסרת חיסיון מחומרי הגלם, והחיסיון עליהם הוא מוחלט.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'כן, התסקיר הוא מסמך רשמי של בית המשפט, וניתן להשתמש בו כראיה בכל הליך משפטי רלוונטי.', false, 'בחירה זו שגויה. התסקיר אינו ראיה במובן הקלאסי, ושימוש בו מוגבל להליך הספציפי שלשמו הוכן, בשל החיסיון והסודיות החלים עליו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'לא, מי שהגיע לידיו תסקיר לצורך הליך משפטי לא ישתמש בו אלא לצורך ההליך המשפטי שבקשר אליו נמסר התסקיר, וזאת בהתאם לתקנות סדר הדין הפלילי.', true, 'בחירה זו נכונה. תקנה 28(א) לתקנות סדר הדין הפלילי אוסרת שימוש בתסקיר שלא לצורך ההליך המשפטי שבקשר אליו נמסר.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'כן, אך רק אם בית המשפט האזרחי יורה על כך, לאחר ששקל את הרלוונטיות של התסקיר ואת הפגיעה בפרטיות.', false, 'בחירה זו שגויה. אף שבית המשפט האזרחי יכול לעיין בתסקיר, הכלל הוא איסור שימוש בו בהליך אחר, והסרת החיסיון היא חריג נדיר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'לא, אלא אם כן הנאשם עצמו הסכים לשימוש בתסקיר בהליך האזרחי.', false, 'בחירה זו שגויה. הסכמת הנאשם אינה מספיקה כדי להתיר שימוש בתסקיר בהליך אחר, שכן האיסור נובע גם מהגנה על אינטרסים ציבוריים ועל מעמד שירות המבחן.', 4);

END $$;

-- ============================================================
-- Q36 — 2019-S-Q36 — chapter=evidence subtopic=admissibility
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q36';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q36 skipped: external_id % already exists', '2019-S-Q36';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'admissibility';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'admissibility';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q36', 'f75683b1-e83a-47da-ba16-b35a95c536d0', v_subtopic_id,
    'אילו מן הראיות הבאות ניתנות להוכחה באמצעות הגשת ההעתק הבדוק, גם אם המקור נמצא בידיו של בעל הדין המעוניין להגיש את הראיה?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 36}'::jsonb,
    'השאלה עוסקת בדרכי ההוכחה של ראיות בכתב, ובפרט באפשרות להגיש ''העתק בדוק'' במקום המקור. היא מתמקדת בהבחנה בין סוגי מסמכים שונים, כאשר התשובה הנכונה מתייחסת לתעודה ציבורית, אשר לגביה קובע סעיף 32 לפקודת הראיות כי ניתן להוכיחה באמצעות העתק בדוק, גם אם המקור זמין.',
    'סעיף 32 לפקודת הראיות [נוסח חדש], תשל"א-1971, קובע כי "תעודה ציבורית ניתן להוכיח בהגשת אחת מאלה, בלי לפגוע בדרכי הוכחה אחרים: (1) המקור; (2) העתקו הבדוק" (Law: פקודת הראיות [נוסח חדש], תשל"א-1971, סעיף 32). הוראה זו מהווה חריג לכלל הראיה הטובה ביותר, הדורש הגשת מסמך מקורי, ומאפשרת להגיש העתק בדוק של תעודה ציבורית גם כאשר המקור נמצא בידי בעל הדין (Verdict: ע"פ 347/88 איוון (ג''והן) דמיאניוק נ'' מדינת ישראל (29.7.1993), Reference 4; Verdict: ת"א (מחוזי חי'') 53276-06-23 הנא נג''אר נ'' מדינת-ישראל - משרד הבריאות (19.8.2025), Reference 6). תכלית החריג היא לייעל את ההליכים המשפטיים ולחסוך את הצורך בזימון פקידי ציבור להעיד על תוכן המסמכים, תוך הסתמכות על חזקת המהימנות של תעודות ציבוריות (Literature: יניב ואקי, דיני ראיות כרך ב (2020) | פרק 36 תעודות ציבוריות, עמ'' 4).',
    'הסטודנט עלול לטעות ולחשוב שכלל הראיה הטובה ביותר חל באופן גורף על כל סוגי המסמכים, מבלי להכיר את החריג המפורש הקבוע בסעיף 32 לפקודת הראיות לגבי תעודות ציבוריות.',
    '["תעודה ציבורית", "העתק בדוק", "כלל הראיה הטובה ביותר", "פקודת הראיות", "קבילות ראיות", "סעיף 32 לפקודה"]'::jsonb,
    '**וריאציה 1 — הוכחת תעודה ציבורית:** האם ניתן להוכיח תעודה ציבורית באמצעות העתק בדוק? ← כן, סעיף 32 לפקודת הראיות מאפשר זאת. **וריאציה 2 — זמינות המקור:** האם זמינות המקור משנה את הכלל? ← לא, ניתן להגיש העתק בדוק גם אם המקור נמצא בידי בעל הדין (סעיף 32 לפקודת הראיות). **וריאציה 3 — רציונל החריג:** מדוע קיים חריג זה? ← לייעול הליכים ולחסכון בזמן פקידי ציבור, תוך הסתמכות על מהימנות התעודה הציבורית (יניב ואקי, דיני ראיות כרך ב, עמ'' 4).',
    'תעודה ציבורית ניתנת להוכחה באמצעות הגשת העתק בדוק שלה, גם אם המקור נמצא בידי בעל הדין, וזאת בהתאם לסעיף 32 לפקודת הראיות, המהווה חריג לכלל הראיה הטובה ביותר.',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 32", "ע\"פ 347/88 איוון (ג''והן) דמיאניוק נ'' מדינת ישראל (29.7.1993)", "ת\"א (מחוזי חי'') 53276-06-23 הנא נג''אר נ'' מדינת-ישראל - משרד הבריאות (19.8.2025)", "יניב ואקי, דיני ראיות כרך ב (2020) | פרק 36 תעודות ציבוריות, עמ'' 4"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'תעודת עובד ציבור.', false, 'בחירה זו שגויה. תעודת עובד ציבור היא דרך להגשת ראיה מסוימת, אך אינה סוג ראיה בפני עצמה הניתנת להוכחה באמצעות העתק בדוק במקום המקור.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'רשומה מוסדית.', false, 'בחירה זו שגויה. רשומה מוסדית ניתנת להוכחה באמצעות העתק צילומי, אך לא בהכרח ''העתק בדוק'' כפי שמוגדר בסעיף 32 לפקודת הראיות, והכללים שונים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'רשומה בנקאית.', false, 'בחירה זו שגויה. רשומה בנקאית היא סוג של רשומה מוסדית, ולכן חלים עליה הכללים של רשומה מוסדית, ולא הכללים הייחודיים לתעודה ציבורית.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'תעודה ציבורית.', true, 'בחירה זו נכונה. סעיף 32 לפקודת הראיות קובע במפורש כי תעודה ציבורית ניתנת להוכחה בהגשת העתק בדוק, גם אם המקור נמצא בידי בעל הדין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'הוכחת רשומה מוסדית באמצעות העתק', 1, 'חברה מסחרית מבקשת להגיש לבית המשפט פלט ממערכת המחשוב שלה, המהווה רשומה מוסדית, כדי להוכיח את אמיתות תוכנו. האם ניתן להגיש העתק צילומי של הפלט במקום המקור?',
    'שאלה זו עוסקת בדרכי ההוכחה של רשומה מוסדית, ובפרט באפשרות להגיש העתק צילומי שלה במקום המקור. היא מדגישה את ההסדר הייחודי הקבוע בפקודת הראיות לגבי רשומות מוסדיות, המקל על הגשתן כראיה.',
    'סעיף 41א לפקודת הראיות [נוסח חדש], תשל"א-1971, קובע במפורש כי "ניתן להוכיח תוכנה של רשומה מוסדית על ידי העתק צילומי של הרשומה" (Law: פקודת הראיות [נוסח חדש], תשל"א-1971, סעיף 41א). בנוסף, סעיף 41ב לפקודה קובע כי "לענין סימן זה לא ייחשב פלט שהוא רשומה מוסדית כהעתק המסמך שעל בסיסו הופק, אלא כמקור" (Law: פקודת הראיות [נוסח חדש], תשל"א-1971, סעיף 41ב). הוראות אלו מהוות חריג לכלל הראיה הטובה ביותר, הדורש הגשת מסמך מקורי, ומטרתן לייעל את ההליכים המשפטיים ולאפשר הגשת ראיות מסוג זה בקלות רבה יותר, תוך שמירה על אמינותן (Literature: נבו - המתמחה, דיני ראיות (2026) | ו - עדות שמיעה (עדות מפי השמועה), עמ'' 56).',
    'הסטודנט עלול לטעות וליישם את כלל הראיה הטובה ביותר באופן גורף, מבלי להבחין בחריג המפורש הקבוע בחוק לגבי רשומות מוסדיות המוגשות באמצעות העתק צילומי.',
    '["רשומה מוסדית", "העתק צילומי", "כלל הראיה הטובה ביותר", "פקודת הראיות", "קבילות ראיות", "פלט מחשב"]'::jsonb,
    '**וריאציה 1 — הוכחת רשומה מוסדית:** האם ניתן להוכיח רשומה מוסדית באמצעות העתק צילומי? ← כן, סעיף 41א לפקודת הראיות מאפשר זאת. **וריאציה 2 — מעמד פלט:** האם פלט מחשב שהוא רשומה מוסדית נחשב למקור או להעתק? ← כמקור, לעניין סימן זה (סעיף 41ב לפקודת הראיות). **וריאציה 3 — חריג לכלל הראיה הטובה ביותר:** האם סעיף 41א הוא חריג לכלל הראיה הטובה ביותר? ← כן, הוא מאפשר הגשת העתק צילומי במקום המקור (נבו - המתמחה, דיני ראיות, עמ'' 56).',
    'ניתן להוכיח תוכנה של רשומה מוסדית באמצעות העתק צילומי שלה, ופלט מחשב שהוא רשומה מוסדית ייחשב כמקור לעניין זה (סעיפים 41א ו-41ב לפקודת הראיות).',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 41א", "פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 41ב", "פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 35", "נבו - המתמחה, דיני ראיות (2026) | ו - עדות שמיעה (עדות מפי השמועה), עמ'' 56"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'תנאים לקבילות תעודה ציבורית לאמיתות תוכנה', 2, 'כאשר תעודה ציבורית מוגשת כראיה לאמיתות תוכנה (ולא רק לעצם קיומה), אילו תנאים מצטברים, בנוסף לדרישות סעיף 29 לפקודת הראיות, צריכים להתקיים בה על פי הפסיקה?',
    'שאלה זו עוסקת בתנאים המהותיים לקבילות תעודה ציבורית כראיה לאמיתות תוכנה, מעבר לדרישות הפורמליות של סעיף 29 לפקודת הראיות. היא מתייחסת להלכת פרידמן כפי שפורשה בהלכת דמיאניוק, המציבה ארבעה תנאים מצטברים לשם כך.',
    'כאשר תעודה ציבורית מוגשת כראיה לאמיתות תוכנה, היא מהווה חריג לכלל הפוסל עדות שמיעה. לשם כך, ובנוסף לעמידה בתנאי סעיף 29 לפקודת הראיות, עליה לעמוד בארבעה תנאים מצטברים שנקבעו בפסיקה (הלכת פרידמן, כפי שפורשה בדמיאניוק): (1) המסמך נערך על פי חובה סטטוטורית; (2) הוא בעל אופי ציבורי (שלציבור יש עניין בעריכתו); (3) הוא מכוון לשימור תוכנו בעתיד (לא לשימוש חד פעמי); (4) הוא פתוח לעיון הציבור המעוניין (Verdict: ע"פ 347/88 איוון (ג''והן) דמיאניוק נ'' מדינת ישראל (29.7.1993), Reference 2, 4; Verdict: ת"א (מחוזי חי'') 53276-06-23 הנא נג''אר נ'' מדינת-ישראל - משרד הבריאות (19.8.2025), Reference 6; Verdict: ת"א (מחוזי י-ם) 20975-06-24 פלוני נ'' הרשות הפלסטינית (19.1.2026), Reference 20). תנאים אלו נועדו להבטיח את מהימנות התעודה, שכן היא מתקבלת כראיה לתוכנה ללא חקירה נגדית של עורכה (Literature: נבו - המתמחה, דיני ראיות (2026) | ו - עדות שמיעה (עדות מפי השמועה), עמ'' 55).',
    'הסטודנט עלול לבלבל בין התנאים הפורמליים להגדרת תעודה ציבורית (סעיף 29) לבין התנאים המהותיים לקבילותה כראיה לאמיתות תוכנה, או לייחס את התנאים הללו לכל סוגי הראיות.',
    '["תעודה ציבורית", "קבילות ראיות", "אמיתות תוכן", "הלכת פרידמן", "הלכת דמיאניוק", "חריג לעדות שמיעה"]'::jsonb,
    '**וריאציה 1 — תנאים לאמיתות תוכן:** מהם ארבעת התנאים לקבילות תעודה ציבורית לאמיתות תוכנה? ← חובה סטטוטורית, אופי ציבורי, שימור לעתיד, פתוח לעיון הציבור (ע"פ 347/88 דמיאניוק, רפרנס 2). **וריאציה 2 — חריג לעדות שמיעה:** מדוע תעודה ציבורית היא חריג לעדות שמיעה? ← בשל ההנחה שפקיד ציבור מדייק במילוי תפקידו והאינטרס הציבורי (יניב ואקי, דיני ראיות כרך ב, עמ'' 4). **וריאציה 3 — הבחנה בין קבילות למשקל:** האם ארבעת התנאים הם תנאי קבילות או משקל? ← הם תנאי קבילות כאשר מדובר באמיתות תוכן, אך יכולים לשמש גם אמות מידה למשקל ראייתי (ע"פ 347/88 דמיאניוק, רפרנס 5).',
    'כדי שתעודה ציבורית תהיה קבילה כראיה לאמיתות תוכנה, עליה לעמוד בארבעה תנאים מצטברים: נערכה על פי חובה סטטוטורית, בעלת אופי ציבורי, מכוונת לשימור תוכנה בעתיד, ופתוחה לעיון הציבור המעוניין (הלכת דמיאניוק).',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 29", "ע\"פ 347/88 איוון (ג''והן) דמיאניוק נ'' מדינת ישראל (29.7.1993)", "ת\"א (מחוזי חי'') 53276-06-23 הנא נג''אר נ'' מדינת-ישראל - משרד הבריאות (19.8.2025)", "ת\"א (מחוזי י-ם) 20975-06-24 פלוני נ'' הרשות הפלסטינית (19.1.2026)", "נבו - המתמחה, דיני ראיות (2026) | ו - עדות שמיעה (עדות מפי השמועה), עמ'' 55", "יניב ואקי, דיני ראיות כרך ב (2020) | פרק 36 תעודות ציבוריות, עמ'' 4"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'הוכחת תעודה ציבורית זרה', 3, 'חברה ישראלית מבקשת להגיש לבית המשפט תעודת רישום חברה ממצרים, המהווה תעודה ציבורית. האם נדרש אישור מיוחד כדי להוכיח את קבילותה של תעודה זו?',
    'שאלה זו עוסקת בהסדר הייחודי להוכחת תעודות ציבוריות שהוצאו בחוץ לארץ. היא מדגישה את הדרישה לאישור נוסף, כגון אישור נציג דיפלומטי או קונסולרי ישראלי, או אישור אפוסטיל, על מנת להבטיח את מהימנותן וקבילותן בבתי המשפט בישראל.',
    'כאשר מדובר בתעודה ציבורית זרה, יש צורך בתעודת אישור של נציג דיפלומטי או קונסולרי ישראלי, על פי סעיף 33 לפקודת הראיות [נוסח חדש], תשל"א-1971, או באישור אפוסטיל על פי תקנה 3 לתקנות לביצוע אמנת האג (ביטול אימות מסמכי חוץ ציבוריים), התשל"ז-1977 (Literature: יניב ואקי, דיני ראיות כרך ב (2020) | פרק 36 תעודות ציבוריות, עמ'' 9). אישור זה מהווה ראיה מספקת לעובדות כגון שהתעודה הודפסה בידי המדפיס הרשמי של אותה מדינה, או שחותם או חתימה פלונית הם חותמו וחתימתו הרשמיים של הפקיד הנחזה כבעל החותם או החתימה (Law: פקודת הראיות [נוסח חדש], תשל"א-1971, סעיף 33). בית המשפט המחוזי קבע כי תדפיסי רשם החברות המצרי מהווים תעודה ציבורית, וכי אין האישור של נציג ישראלי תנאי מוקדם לקבילות תעודה ציבורית מחוץ לארץ, אך זהו אישור למהימנותה (Verdict: ת"א (מחוזי נצ'') 33968-05-11 אמאד - אראביה מיוזיק לניהול והפצה בע"מ נ'' אחמד (בן מוסטפא) ענבתאוי (6.5.2015), Reference 23).',
    'הסטודנט עלול לטעות ולחשוב שכללי הקבילות של תעודה ציבורית זהים בין תעודה מקומית לתעודה זרה, מבלי להכיר את הדרישות הנוספות לאימות תעודות זרות.',
    '["תעודה ציבורית זרה", "אישור נציג דיפלומטי", "אפוסטיל", "פקודת הראיות", "קבילות ראיות", "אמנת האג"]'::jsonb,
    '**וריאציה 1 — אישור לתעודה זרה:** מה נדרש כדי להוכיח תעודה ציבורית זרה? ← אישור של נציג דיפלומטי/קונסולרי ישראלי או אישור אפוסטיל (סעיף 33 לפקודת הראיות; יניב ואקי, דיני ראיות כרך ב, עמ'' 9). **וריאציה 2 — מטרת האישור:** מה מטרת האישור לתעודה זרה? ← להוכיח עובדות כמו שהתעודה הודפסה בידי מדפיס רשמי או שהחותמת רשמית (סעיף 33 לפקודת הראיות). **וריאציה 3 — קבילות תדפיס רשם חברות זר:** האם תדפיס רשם חברות זר הוא תעודה ציבורית? ← כן, והוא קביל גם ללא אישור נציג ישראלי, אך האישור נועד למהימנות (ת"א (מחוזי נצ'') 33968-05-11 אמאד, רפרנס 23).',
    'הוכחת תעודה ציבורית זרה דורשת אישור של נציג דיפלומטי או קונסולרי ישראלי, או אישור אפוסטיל, המעיד על מהימנותה ועל עובדות הקשורות לעריכתה (סעיף 33 לפקודת הראיות).',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 33", "יניב ואקי, דיני ראיות כרך ב (2020) | פרק 36 תעודות ציבוריות, עמ'' 9", "ת\"א (מחוזי נצ'') 33968-05-11 אמאד - אראביה מיוזיק לניהול והפצה בע\"מ נ'' אחמד (בן מוסטפא) ענבתאוי (6.5.2015)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'הבחנה בין תעודה ציבורית לרשומה מוסדית', 4, 'מהו ההבדל המהותי העיקרי בין ''תעודה ציבורית'' לבין ''רשומה מוסדית'' בהקשר של דיני ראיות?',
    'שאלה זו בוחנת את ההבחנה המהותית בין ''תעודה ציבורית'' ל''רשומה מוסדית'', שהן שתי קטגוריות חשובות של ראיות בכתב. ההבדל טמון בעיקר באופי הגוף העורך ובמהות הרישום, ומשפיע על כללי הקבילות וההוכחה של כל אחת מהן.',
    'ההבדל המהותי העיקרי בין תעודה ציבורית לרשומה מוסדית טמון בהגדרתן ובאופי הגוף העורך. ''תעודה ציבורית'' היא תעודה המבטאת פעילות שלטונית של אחד ממוסדות השלטון (מדינה, רשות מקומית, בית משפט, נוטריון וכדומה), בין שהיא מעשה חקיקה, שיפוט או ביצוע, ובין שהיא חלק מהרשומות הרשמיות (Law: פקודת הראיות [נוסח חדש], תשל"א-1971, סעיף 29; Literature: יניב ואקי, דיני ראיות כרך ב (2020) | פרק 36 תעודות ציבוריות, עמ'' 2). לעומת זאת, ''רשומה מוסדית'' היא מסמך, לרבות פלט, אשר נערך על ידי מוסד (הכולל גם עסק פרטי או כל מי שמספק שירות לציבור) במהלך פעילותו הרגילה של המוסד (Law: פקודת הראיות [נוסח חדש], תשל"א-1971, סעיף 35; Literature: יניב ואקי, דיני ראיות כרך ב (2020) | פרק 37 רשומה מוסדית, עמ'' 3). בעוד שתעודה ציבורית נהנית מחזקת מהימנות גבוהה בשל ההנחה שפקיד ציבור מדייק בתפקידו, רשומה מוסדית דורשת עמידה בתנאים נוספים להוכחת אמיתות תוכנה, כגון עריכה בסמוך לאירוע ודרך איסוף נתונים המעידה על אמיתות (Law: פקודת הראיות [נוסח חדש], תשל"א-1971, סעיף 36).',
    'הסטודנט עלול לבלבל בין ההגדרות והתנאים של תעודה ציבורית ורשומה מוסדית, או לייחס להן את אותם כללי קבילות והוכחה, מבלי להבין את ההבדלים המהותיים ביניהן.',
    '["תעודה ציבורית", "רשומה מוסדית", "הגדרות", "אופי הגוף העורך", "קבילות ראיות", "סעיף 29 לפקודת הראיות", "סעיף 35 לפקודת הראיות"]'::jsonb,
    '**וריאציה 1 — הגדרת תעודה ציבורית:** מהי תעודה ציבורית? ← תעודה המבטאת פעילות שלטונית של מוסד ציבורי (סעיף 29 לפקודת הראיות; יניב ואקי, דיני ראיות כרך ב, עמ'' 2). **וריאציה 2 — הגדרת רשומה מוסדית:** מהי רשומה מוסדית? ← מסמך שנערך על ידי מוסד (כולל עסק פרטי) במהלך פעילותו הרגילה (סעיף 35 לפקודת הראיות; יניב ואקי, דיני ראיות כרך ב, עמ'' 3). **וריאציה 3 — זכות חקירה נגדית:** האם יש זכות לחקירה נגדית של עורך התעודה/רשומה? ← בתעודה ציבורית אין זכות לחקירה נגדית של עורך התעודה. ברשומה מוסדית, הצד שכנגד זכאי לחקור עדים הקשורים לבעל הדין שהגיש את הרשומה (נבו - המתמחה, דיני ראיות, עמ'' 57).',
    'תעודה ציבורית מבטאת פעילות שלטונית של גוף ציבורי, בעוד שרשומה מוסדית היא מסמך שנערך במהלך פעילות רגילה של מוסד (כולל פרטי). ההבדל משפיע על כללי הקבילות וזכות החקירה הנגדית (סעיפים 29 ו-35 לפקודת הראיות).',
    '["פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 29", "פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 35", "פקודת הראיות [נוסח חדש], תשל\"א-1971, סעיף 36", "יניב ואקי, דיני ראיות כרך ב (2020) | פרק 36 תעודות ציבוריות, עמ'' 2", "יניב ואקי, דיני ראיות כרך ב (2020) | פרק 37 רשומה מוסדית, עמ'' 3", "נבו - המתמחה, דיני ראיות (2026) | ו - עדות שמיעה (עדות מפי השמועה), עמ'' 57"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'כן, ניתן להוכיח תוכנה של רשומה מוסדית על ידי העתק צילומי של הרשומה, ואין צורך להגיש את המקור.', true, 'בחירה זו נכונה. סעיף 41א לפקודת הראיות קובע במפורש כי ניתן להוכיח תוכנה של רשומה מוסדית על ידי העתק צילומי שלה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'לא, רשומה מוסדית, בדומה לכל מסמך אחר, חייבת להיות מוגשת במקורה, אלא אם הוכח שהמקור אבד או הושמד.', false, 'בחירה זו שגויה. סעיף 41א לפקודת הראיות קובע חריג לכלל הראיה הטובה ביותר עבור רשומות מוסדיות, ומאפשר הגשת העתק צילומי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'כן, אך רק אם העתק הצילומי מאושר בחותמת רשמית של המוסד שערך את הרשומה.', false, 'בחירה זו שגויה. דרישת אישור בחותמת רשמית רלוונטית לדרכי הוכחה מסוימות של תעודה ציבורית, אך לא להעתק צילומי של רשומה מוסדית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לא, פלט מחשב אינו נחשב למסמך, ולכן לא ניתן להגיש העתק שלו כראיה.', false, 'בחירה זו שגויה. סעיף 35 לפקודת הראיות מגדיר ''רשומה מוסדית'' ככוללת ''פלט'', וסעיף 41ב קובע כי פלט שהוא רשומה מוסדית ייחשב כמקור.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'המסמך נערך על פי חובה סטטוטורית, הוא בעל אופי ציבורי, הוא מכוון לשימור תוכנו בעתיד, והוא פתוח לעיון הציבור המעוניין.', true, 'בחירה זו נכונה. אלו הם ארבעת התנאים המצטברים שנקבעו בהלכת פרידמן ופורשו בהלכת דמיאניוק, הנדרשים לקבילות תעודה ציבורית כראיה לאמיתות תוכנה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'המסמך נערך על ידי עובד ציבור, הוא חתום בחותמת רשמית, והוא הוגש באמצעות עד מומחה.', false, 'בחירה זו שגויה. אלו אינם התנאים המצטברים שנקבעו בפסיקה לקבילות תעודה ציבורית לאמיתות תוכנה. תעודה ציבורית אינה דורשת הגשה באמצעות עד מומחה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'המסמך נערך בסמוך לאירוע, דרך עריכתו מעידה על אמיתותו, והוא פלט מחשב המוגן מפני חדירה.', false, 'בחירה זו שגויה. אלו הם התנאים לקבילות רשומה מוסדית, ולא תעודה ציבורית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'המסמך הוא מקורי, הוא אינו עדות שמיעה, ואין עליו חסיון.', false, 'בחירה זו שגויה. תעודה ציבורית היא חריג לכלל הפוסל עדות שמיעה, והתנאים לקבילותה לאמיתות תוכנה ספציפיים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'כן, יש לצרף לתעודה אישור של נציג דיפלומטי או קונסולרי ישראלי, או אישור אפוסטיל, על מנת להוכיח את מהימנותה.', true, 'בחירה זו נכונה. סעיף 33 לפקודת הראיות ותקנות אמנת האג קובעים דרישות מיוחדות להוכחת תעודות ציבוריות זרות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'לא, תעודה ציבורית זרה קבילה כראיה ללא צורך באישור נוסף, כל עוד היא עומדת בהגדרת תעודה ציבורית לפי סעיף 29 לפקודה.', false, 'בחירה זו שגויה. סעיף 33 לפקודת הראיות קובע דרישות ספציפיות לתעודות ציבוריות זרות, מעבר להגדרת סעיף 29.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'כן, אך רק אם התעודה אינה מודפסת בידי מדפיס רשמי של המדינה הזרה.', false, 'בחירה זו שגויה. דרישת האישור חלה גם אם התעודה מודפסת בידי מדפיס רשמי, והיא נוגעת לאימות עצם התעודה והחותמות עליה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לא, תעודת רישום חברה אינה נחשבת לתעודה ציבורית, ולכן אין צורך באישור מיוחד.', false, 'בחירה זו שגויה. תעודת רישום חברה, במיוחד מרשם רשמי, נחשבת לתעודה ציבורית (ת"א (מחוזי נצ'') 33968-05-11 אמאד, רפרנס 23).', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'תעודה ציבורית היא רשומה המבטאת פעילות שלטונית של מוסד ציבורי, בעוד שרשומה מוסדית היא מסמך שנערך במהלך פעילותו הרגילה של מוסד, שיכול להיות גם עסק פרטי.', true, 'בחירה זו נכונה. זהו ההבדל המהותי בהגדרה ובאופי הגוף העורך, המשפיע על כללי הקבילות וההוכחה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'תעודה ציבורית קבילה כראיה לאמיתות תוכנה ללא חקירה נגדית, בעוד שרשומה מוסדית קבילה כראיה לאמיתות תוכנה רק אם עורך הרשומה נחקר בחקירה נגדית.', false, 'בחירה זו שגויה. בשני המקרים אין זכות לחקירה נגדית של עורך התעודה/רשומה ככלל, אך ברשומה מוסדית יש זכות לחקור עדים הקשורים לבעל הדין שהגיש אותה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'תעודה ציבורית חייבת להיות מקורית, בעוד שרשומה מוסדית ניתנת להוכחה באמצעות העתק צילומי בלבד.', false, 'בחירה זו שגויה. תעודה ציבורית ניתנת להוכחה גם באמצעות העתק בדוק, ורשומה מוסדית יכולה להיות גם מקורית.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'תעודה ציבורית חלה רק בהליכים פליליים, ורשומה מוסדית חלה רק בהליכים אזרחיים.', false, 'בחירה זו שגויה. שני סוגי הראיות חלים הן בהליכים פליליים והן בהליכים אזרחיים.', 4);

END $$;

