  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q37', 'ed89ea85-f137-4877-90ab-7c7d56ff3cc2', v_subtopic_id,
    'הכנסת מעוניינת לתקן כמה חוקי יסוד. לצורך ביצוע המהלך הצליחה הקואליציה לגייס תמיכה של 58 חברי כנסת לעומת מספר קטן יותר של מתנגדים. איזה חוק מהבאים תוכל הכנסת לתקן ברוב האמור?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 37}'::jsonb,
    'השאלה עוסקת בדרישות הרוב השונות לתיקון חוקי יסוד בישראל, ובפרט בהבחנה בין חוקי יסוד משוריינים לבין אלו שאינם משוריינים. היא בוחנת את היכרות הסטודנט עם סוגי השריון השונים והרוב הנדרש לכל אחד מהם, כפי שנקבע בחוקי היסוד עצמם ובפסיקת בית המשפט העליון.',
    'בישראל, המצב החוקתי מורכב, ומרבית חוקי היסוד אינם משוריינים, ולכן ניתנים לשינוי על ידי הכנסת ברוב רגיל בהליכי חקיקה רגילים (Verdict: בג"ץ 4908/10 ח"כ רוני בר-און נ'' כנסת ישראל (7.4.2011), Reference 17). עם זאת, חלק מחוקי היסוד משוריינים ודורשים רוב מיוחד לשינויים. לדוגמה, חוק יסוד: ישראל - מדינת הלאום של העם היהודי (סעיף 11), חוק יסוד: משאל עם (סעיף 5), וחוק יסוד: חופש העיסוק (סעיף 7) קובעים כי אין לשנותם אלא בחוק יסוד שהתקבל ברוב של חברי הכנסת, כלומר 61 ח"כים (Law: חוק-יסוד: ישראל – מדינת הלאום של העם היהודי, סעיף 11; Law: חוק-יסוד: משאל עם, סעיף 5; Law: חוק-יסוד: חופש העיסוק, סעיף 7). לעומת זאת, חוק יסוד: כבוד האדם וחירותו אינו כולל הוראת שריון פורמלי, ולכן ניתן לשנותו בחוק יסוד שנתקבל ברוב רגיל (Book: נבו - המתמחה, חוקי יסוד (2026) | הקדמה, עמ'' 10). רוב רגיל משמעו רוב דעות של המשתתפים בהצבעה, כשהנמנעים אינם באים במניין המשתתפים (Law: חוק-יסוד: הכנסת, סעיף 25). במקרה הנדון, 58 חברי כנסת תומכים בתיקון, וזהו רוב מספיק לתיקון חוק יסוד שאינו משוריין, כמו חוק יסוד: כבוד האדם וחירותו, בהנחה שמתקיים קוורום ואין יותר מתנגדים מתומכים. (Book: נבו - המתמחה, חוקי יסוד (2026) | כיצד נזכור את הרוב הדרוש בחוקי יסוד?, עמ'' 74).',
    'הסטודנט עלול לטעות ולחשוב שכל חוקי היסוד דורשים רוב מיוחד לשינויים, או לבלבל בין סוגי הרוב השונים (רגיל, חברי כנסת, מיוחס) הנדרשים לתיקון חוקי יסוד שונים.',
    '["חוקי יסוד", "שריון פורמלי", "רוב רגיל", "רוב חברי הכנסת", "תיקון חוק יסוד", "חוק יסוד: כבוד האדם וחירותו"]'::jsonb,
    '**וריאציה 1 — רוב לתיקון חוק יסוד לא משוריין:** איזה רוב נדרש לתיקון חוק יסוד שאינו משוריין? ← רוב רגיל (נבו - המתמחה, חוקי יסוד, עמ'' 10). **וריאציה 2 — חוק יסוד: כבוד האדם וחירותו:** האם חוק יסוד: כבוד האדם וחירותו משוריין? ← לא, הוא אינו כולל הוראת שריון פורמלי (נבו - המתמחה, חוקי יסוד, עמ'' 10). **וריאציה 3 — רוב של 58 ח"כים:** האם 58 חברי כנסת מספיקים לתיקון חוק יסוד משוריין ברוב חברי הכנסת? ← לא, נדרשים 61 ח"כים (נבו - המתמחה, חוקי יסוד, עמ'' 10).',
    'הכנסת תוכל לתקן את חוק יסוד: כבוד האדם וחירותו ברוב של 58 חברי כנסת, שכן חוק יסוד זה אינו משוריין פורמלית וניתן לשינוי בחוק יסוד שנתקבל ברוב רגיל (נבו - המתמחה, חוקי יסוד, עמ'' 10).',
    '["חוק-יסוד: ישראל – מדינת הלאום של העם היהודי, סעיף 11", "חוק-יסוד: משאל עם, סעיף 5", "חוק-יסוד: חופש העיסוק, סעיף 7", "נבו - המתמחה, חוקי יסוד (2026) | הקדמה, עמ'' 10", "חוק-יסוד: הכנסת, סעיף 25", "נבו - המתמחה, חוקי יסוד (2026) | כיצד נזכור את הרוב הדרוש בחוקי יסוד?, עמ'' 74", "בג\"ץ 4908/10 ח\"כ רוני בר-און נ'' כנסת ישראל (7.4.2011)"]'::jsonb,
    'needs_review=true | subtopic_mapping_review: original=''חוקי יסוד'' → mapped=''bgz_jurisdiction_revocation''',
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'חוק יסוד: ישראל - מדינת הלאום של העם היהודי.', false, 'בחירה זו שגויה. סעיף 11 לחוק יסוד: ישראל – מדינת הלאום של העם היהודי קובע כי אין לשנות חוק יסוד זה אלא בחוק יסוד שהתקבל ברוב של חברי הכנסת (61 ח"כים).', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'חוק יסוד: משאל עם.', false, 'בחירה זו שגויה. סעיף 5 לחוק יסוד: משאל עם קובע כי אין לשנות חוק יסוד זה אלא בחוק יסוד שהתקבל ברוב של חברי הכנסת (61 ח"כים).', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'חוק יסוד: כבוד האדם וחירותו.', true, 'בחירה זו נכונה. חוק יסוד: כבוד האדם וחירותו אינו משוריין פורמלית, ולכן ניתן לשנותו בחוק יסוד שנתקבל ברוב רגיל, כלומר ברוב של המשתתפים בהצבעה, ו-58 חברי כנסת המהווים רוב כזה מספיקים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'חוק יסוד: חופש העיסוק.', false, 'בחירה זו שגויה. סעיף 7 לחוק יסוד: חופש העיסוק קובע כי אין לשנות חוק יסוד זה אלא בחוק יסוד שהתקבל ברוב של חברי הכנסת (61 ח"כים).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'רוב מיוחס לשינוי חוק יסוד', 1, 'הכנסת מעוניינת לתקן סעיף בחוק יסוד הדורש רוב של 80 חברי כנסת. הקואליציה הצליחה לגייס 70 חברי כנסת שתומכים בתיקון, לעומת 20 מתנגדים. מה הדין?',
    'שאלה זו בוחנת את היכרות הסטודנט עם דרישות הרוב המיוחדות לתיקון סעיפים ספציפיים בחוקי יסוד, המהוות שריון פורמלי. היא מדגישה את ההבחנה בין רוב רגיל, רוב חברי הכנסת, ורוב מיוחס גבוה יותר.',
    'חוקי יסוד מסוימים, או סעיפים בתוכם, משוריינים ודורשים רוב מיוחד לשינויים. לדוגמה, סעיפים 9א, 44 ו-45 לחוק יסוד: הכנסת, הנוגעים לדחיית הבחירות וגריעה של תקנות שעת חירום, דורשים רוב של 80 חברי כנסת לתיקונם (Law: חוק-יסוד: הכנסת, סעיף 45; Law: חוק-יסוד: הכנסת, סעיף 46). גם סעיפים 6 ו-7 לחוק יסוד: ירושלים בירת ישראל, הנוגעים להעברת שטח מהעיר לגורם זר, דורשים רוב של 80 חברי כנסת (Law: חוק-יסוד: ירושלים בירת ישראל, סעיף 7). במקרה זה, מכיוון שהקואליציה גייסה רק 70 חברי כנסת, היא אינה עומדת בדרישת הרוב המיוחס של 80 חברי כנסת, ולכן התיקון לא יתקבל (Book: נבו - המתמחה, חוקי יסוד (2026) | כיצד נזכור את הרוב הדרוש בחוקי יסוד?, עמ'' 74).',
    'הסטודנט עלול לבלבל בין דרישות הרוב השונות לתיקון חוקי יסוד, ולא לזכור אילו סעיפים דורשים רוב של 80 חברי כנסת לעומת רוב של 61 חברי כנסת או רוב רגיל.',
    '["רוב מיוחס", "שריון פורמלי", "חוק יסוד: הכנסת", "חוק יסוד: ירושלים בירת ישראל", "תיקון חוק יסוד", "רוב של 80 ח\"כים"]'::jsonb,
    '**וריאציה 1 — רוב לתיקון סעיף 45 לחוק יסוד הכנסת:** מהו הרוב הדרוש לתיקון סעיף 45 לחוק יסוד: הכנסת? ← 80 חברי כנסת (סעיף 45 לחוק יסוד: הכנסת). **וריאציה 2 — רוב לתיקון סעיף 7 לחוק יסוד ירושלים:** מהו הרוב הדרוש לתיקון סעיף 7 לחוק יסוד: ירושלים בירת ישראל? ← 80 חברי כנסת (סעיף 7 לחוק יסוד: ירושלים בירת ישראל). **וריאציה 3 — רוב להארכת כהונת הכנסת:** מהו הרוב הדרוש לחוק להארכת תקופת כהונתה של הכנסת? ← 80 חברי כנסת (נבו - המתמחה, חוקי יסוד, עמ'' 71).',
    'תיקון סעיפים מסוימים בחוקי יסוד, כמו אלה הנוגעים לדחיית בחירות או העברת שטחים בירושלים, דורש רוב מיוחס של 80 חברי כנסת, ו-70 חברי כנסת אינם מספיקים לכך (סעיפים 45 לחוק יסוד: הכנסת ו-7 לחוק יסוד: ירושלים בירת ישראל).',
    '["חוק-יסוד: הכנסת, סעיף 45", "חוק-יסוד: הכנסת, סעיף 46", "חוק-יסוד: ירושלים בירת ישראל, סעיף 7", "נבו - המתמחה, חוקי יסוד (2026) | שריון חוקי יסוד, עמ'' 70", "נבו - המתמחה, חוקי יסוד (2026) | כיצד נזכור את הרוב הדרוש בחוקי יסוד?, עמ'' 74"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'משמעות "רוב חברי הכנסת"', 2, 'מהי המשמעות המשפטית של הדרישה ל"רוב חברי הכנסת" לצורך שינוי חוק יסוד?',
    'שאלה זו מבהירה את ההבחנה הקריטית בין סוגי רוב שונים הנדרשים בחקיקה, ובפרט בחקיקת יסוד. היא מתמקדת במונח ''רוב חברי הכנסת'' ומשמעותו כרוב מוחלט של 61 חברי כנסת, לעומת רוב רגיל או רוב מיוחס גבוה יותר.',
    'הצירוף "רוב חברי הכנסת" המופיע בחיקוק, משמעו רוב של 61 ח"כים, להבדיל מרוב רגיל (לדוגמה: 30 קולות תומכים נגד 29 קולות מתנגדים) (Book: נבו - המתמחה, חוקי יסוד (2026) | הקדמה, עמ'' 10). דרישה זו של רוב מוחלט של חברי הכנסת היא סוג של שריון פורמלי, המקשה על שינוי חוקי יסוד מסוימים ומבטיח יציבות רבה יותר (Verdict: ע"א 6821/93 בנק המזרחי המאוחד בע"מ נ'' מגדל כפר שיתופי (9.11.1995), Reference 11). חוק יסוד: הכנסת קובע בסעיף 25 כי הכנסת תחליט ברוב דעות של המשתתפים בהצבעה, כשהנמנעים אינם באים במניין המשתתפים, אלא אם כן יש בחוק הוראה אחרת לעניין זה (Law: חוק-יסוד: הכנסת, סעיף 25). הדרישה ל"רוב חברי הכנסת" היא דוגמה ל"הוראה אחרת" כזו, המצריכה רוב מוחלט של 61 חברי כנסת (Book: נבו - המתמחה, חוקי יסוד (2026) | שריון חוקי יסוד, עמ'' 70).',
    'הסטודנט עלול לבלבל בין ''רוב רגיל'' (רוב מבין הנוכחים והמצביעים) לבין ''רוב חברי הכנסת'' (רוב מוחלט של 61 ח"כים), טעות שעלולה להוביל למסקנה שגויה לגבי תוקף חקיקה.',
    '["רוב חברי הכנסת", "רוב רגיל", "שריון פורמלי", "חוק יסוד", "הליכי חקיקה", "סעיף 25 לחוק יסוד: הכנסת"]'::jsonb,
    '**וריאציה 1 — הגדרת רוב חברי הכנסת:** מהי המשמעות של ''רוב חברי הכנסת''? ← 61 חברי כנסת לפחות (נבו - המתמחה, חוקי יסוד, עמ'' 10). **וריאציה 2 — הבדל מרוב רגיל:** מה ההבדל בין ''רוב חברי הכנסת'' ל''רוב רגיל''? ← רוב חברי הכנסת הוא 61 ח"כים, בעוד שרוב רגיל הוא רוב מבין המשתתפים בהצבעה (נבו - המתמחה, חוקי יסוד, עמ'' 10). **וריאציה 3 — חוק יסוד: הכנסת סעיף 25:** מה קובע סעיף 25 לחוק יסוד: הכנסת לגבי רוב? ← הכנסת תחליט ברוב דעות של המשתתפים בהצבעה, אלא אם כן יש בחוק הוראה אחרת לעניין זה (סעיף 25 לחוק יסוד: הכנסת).',
    'הדרישה ל"רוב חברי הכנסת" לצורך שינוי חוק יסוד משמעותה רוב מוחלט של 61 חברי כנסת לפחות, וזאת בניגוד לרוב רגיל שהוא רוב מבין המשתתפים בהצבעה (נבו - המתמחה, חוקי יסוד, עמ'' 10).',
    '["נבו - המתמחה, חוקי יסוד (2026) | הקדמה, עמ'' 10", "חוק-יסוד: הכנסת, סעיף 25", "נבו - המתמחה, חוקי יסוד (2026) | שריון חוקי יסוד, עמ'' 70", "ע\"א 6821/93 בנק המזרחי המאוחד בע\"מ נ'' מגדל כפר שיתופי (9.11.1995)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'שינוי חוק יסוד בהוראת שעה', 3, 'הכנסת חוקקה חוק יסוד בהוראת שעה, המשנה הוראה קבועה בחוק יסוד קיים. מהי עמדת בית המשפט העליון לגבי תוקפו של חוק יסוד בהוראת שעה?',
    'שאלה זו עוסקת במעמדם של חוקי יסוד שנחקקו כהוראת שעה, ובביקורת השיפוטית של בית המשפט העליון על תופעה זו. היא מדגישה את המתח בין הצורך ביציבות חוקתית לבין השימוש בהוראות שעה לשינוי חוקי יסוד.',
    'בית המשפט העליון קבע כי במשטר החוקתי הייחודי הישראלי, ובהיעדר מסגרת הולמת המתווה הליכי חקיקה או שינוי של חוקי יסוד, עצם העובדה שתיקון לחוק יסוד נחקק בדרך של הוראת שעה, אינה פוסלת אותו מעיקרו ואף אינה מעמידה אותו במדרג נורמטיבי נמוך מזה של חוק רגיל (Verdict: בג"ץ 5969/20 סתיו שפיר נ'' הכנסת (23.5.2021), Reference 18; Verdict: בג"ץ 4908/10 ח"כ רוני בר-און נ'' כנסת ישראל (7.4.2011), Reference 16). עם זאת, בית המשפט הדגיש כי חוק יסוד נועד לעצב נורמות יסוד חוקתיות ומשטריות שאמורות לעמוד בתוקפן לאורך שנים רבות, ולכן החיבור בין חוק יסוד ובין הוראת שעה אינו טבעי (Verdict: בג"ץ 4199121 המרכז האקדמי למשפט ולעסקים נ'' כנסת ישראל (6.9.2017), Reference 16). השימוש התכוף בהוראות שעה לתיקון חוקי יסוד, במיוחד לצרכים פוליטיים נקודתיים, גורם לשחיקה ולזילות במעמדם של חוקי היסוד (Verdict: בג"ץ 8948/22 אילן שיינפלד נ'' הכנסת (18.1.2023), Reference 19). בית המשפט קרא לכנסת לפעול בריסון בהפעלת סמכותה המכוננת (Verdict: בג"ץ 5658/23 התנועה למען איכות השלטון בישראל נ'' הכנסת (1.1.2024), Reference 6).',
    'הסטודנט עלול לטעות ולחשוב שחוק יסוד בהוראת שעה בטל אוטומטית, מבלי להבין את הגישה המורכבת של בית המשפט, המכירה באפשרות קיומו אך מותחת ביקורת על השימוש בו.',
    '["חוק יסוד בהוראת שעה", "שימוש לרעה בסמכות המכוננת", "יציבות חוקתית", "ביקורת שיפוטית", "ריסון שיפוטי", "בג\"ץ בר-און"]'::jsonb,
    '**וריאציה 1 — קבילות חוק יסוד בהוראת שעה:** האם חוק יסוד בהוראת שעה בטל מעיקרו? ← לא, עצם העובדה שתיקון לחוק יסוד נחקק בדרך של הוראת שעה אינה פוסלת אותו מעיקרו (בג"ץ בר-און, רפרנס 16). **וריאציה 2 — ביקורת על חוק יסוד בהוראת שעה:** מהי הביקורת העיקרית על חוקי יסוד בהוראת שעה? ← הם מעוררים קשיים חוקתיים וגורמים לשחיקה וזילות במעמדם של חוקי היסוד (בג"ץ שיינפלד, רפרנס 19). **וריאציה 3 — דרישת ריסון:** מה דורש בית המשפט מהכנסת בהקשר זה? ← לפעול בריסון בהפעלת סמכותה המכוננת, ולא לנצל את הקלות לצרכים פוליטיים נקודתיים (בג"ץ איכות השלטון, רפרנס 6).',
    'חוק יסוד בהוראת שעה אינו בטל מעיקרו, אך בית המשפט העליון רואה בו תופעה בעייתית המערערת את היציבות החוקתית ודורש מהכנסת ריסון בהפעלת סמכותה המכוננת (בג"ץ בר-און, בג"ץ שיינפלד).',
    '["בג\"ץ 4908/10 ח\"כ רוני בר-און נ'' כנסת ישראל (7.4.2011)", "בג\"ץ 5969/20 סתיו שפיר נ'' הכנסת (23.5.2021)", "בג\"ץ 8948/22 אילן שיינפלד נ'' הכנסת (18.1.2023)", "בג\"ץ 5658/23 התנועה למען איכות השלטון בישראל נ'' הכנסת (1.1.2024)", "בג\"ץ 4199121 המרכז האקדמי למשפט ולעסקים נ'' כנסת ישראל (6.9.2017)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'ביקורת שיפוטית על חוקי יסוד', 4, 'בית המשפט העליון דן בעתירה נגד חוק יסוד חדש, בטענה שהכנסת עשתה ''שימוש לרעה בסמכותה המכוננת''. מהי עמדת בית המשפט העליון לגבי ביקורת שיפוטית על חוקי יסוד?',
    'שאלה זו עוסקת באחת הסוגיות המורכבות והרגישות ביותר במשפט החוקתי בישראל – היקף הביקורת השיפוטית על חוקי יסוד. היא בוחנת את הדוקטרינות של ''שימוש לרעה בסמכות המכוננת'' ו''תיקון חוקתי שאינו חוקתי'', ואת גבולותיהן כפי שנקבעו בפסיקת בית המשפט העליון.',
    'בית המשפט העליון הכיר בסמכותו לבקר חוקי יסוד, אך הדגיש כי מדובר בסמכות שתופעל במקרים נדירים וחריגים ביותר (Verdict: בג"ץ 8948/22 אילן שיינפלד נ'' הכנסת (18.1.2023), Reference 19). הביקורת מתבצעת במסגרת דוקטרינות של ''שימוש לרעה בסמכות המכוננת'' או ''תיקון חוקתי שאינו חוקתי'' (Verdict: בג"ץ 5658/23 התנועה למען איכות השלטון בישראל נ'' הכנסת (1.1.2024), Reference 9). ההלכה הפסוקה קובעת כי כל עוד אין בישראל חוקה מלאה, חלה על הכנסת כרשות מכוננת מגבלה אחת, צרה ביותר, והיא שאין ביכולתה לשלול בחוק יסוד את עצם היותה של ישראל מדינה יהודית ודמוקרטית, מכיוון שמדובר ב''חריגה מהסמכות המכוננת'' (Verdict: בג"ץ 5658/23 התנועה למען איכות השלטון בישראל נ'' הכנסת (1.1.2024), Reference 9; Verdict: בג"ץ 5555/18 ח"כ אכרם חסון ו-11 אח'' נ'' כנסת ישראל (8.7.2021), Reference 23). ככל שהרשות המכוננת אינה מפגינה ריסון בחקיקת חוקי יסוד, כך גדל הצורך בביקורת שיפוטית (Verdict: בג"ץ 5658/23 התנועה למען איכות השלטון בישראל נ'' הכנסת (1.1.2024), Reference 5).',
    'הסטודנט עלול לטעות ולחשוב שאין כלל ביקורת שיפוטית על חוקי יסוד, או לחילופין, שביקורת זו רחבה כמו הביקורת על חוקים רגילים, מבלי להבין את האיזון העדין והמצומצם שנקבע בפסיקה.',
    '["ביקורת שיפוטית", "חוקי יסוד", "שימוש לרעה בסמכות המכוננת", "תיקון חוקתי שאינו חוקתי", "מדינה יהודית ודמוקרטית", "ריסון שיפוטי"]'::jsonb,
    '**וריאציה 1 — סמכות ביקורת על חוקי יסוד:** האם בית המשפט מוסמך לבקר חוקי יסוד? ← כן, במקרים נדירים וחריגים ביותר, במסגרת דוקטרינות של ''שימוש לרעה בסמכות המכוננת'' או ''תיקון חוקתי שאינו חוקתי'' (בג"ץ איכות השלטון, רפרנס 9). **וריאציה 2 — מגבלת הליבה:** מהי המגבלה הצרה ביותר על הכנסת כרשות מכוננת? ← אין ביכולתה לשלול בחוק יסוד את עצם היותה של ישראל מדינה יהודית ודמוקרטית (בג"ץ חסון, רפרנס 23). **וריאציה 3 — יחסי גומלין ריסון:** מהם יחסי הגומלין בין ריסון הרשות המכוננת לריסון השיפוטי? ← ככל שהרשות המכוננת אינה מפגינה ריסון, כך גדל הצורך בביקורת שיפוטית (בג"ץ איכות השלטון, רפרנס 5).',
    'בית המשפט העליון מוסמך לבקר חוקי יסוד במקרים נדירים וחריגים ביותר, כאשר מדובר ב''שימוש לרעה בסמכות המכוננת'' או ''תיקון חוקתי שאינו חוקתי'', ובפרט אם הם שוללים את אופייה של ישראל כמדינה יהודית ודמוקרטית (בג"ץ איכות השלטון, בג"ץ חסון).',
    '["בג\"ץ 5658/23 התנועה למען איכות השלטון בישראל נ'' הכנסת (1.1.2024)", "בג\"ץ 5555/18 ח\"כ אכרם חסון ו-11 אח'' נ'' כנסת ישראל (8.7.2021)", "בג\"ץ 8948/22 אילן שיינפלד נ'' הכנסת (18.1.2023)", "בג\"ץ 4199121 המרכז האקדמי למשפט ולעסקים נ'' כנסת ישראל (6.9.2017)", "ע\"א 6821/93 בנק המזרחי המאוחד בע\"מ נ'' מגדל כפר שיתופי (9.11.1995)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'התיקון יתקבל, שכן 70 חברי כנסת מהווים רוב מיוחס מספיק.', false, 'בחירה זו שגויה. אף ש-70 חברי כנסת הם רוב משמעותי, הם אינם עומדים בדרישת הרוב המיוחס של 80 חברי כנסת הנדרש לתיקון סעיפים מסוימים בחוקי יסוד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'התיקון לא יתקבל, שכן נדרש רוב של 80 חברי כנסת.', true, 'בחירה זו נכונה. סעיפים מסוימים בחוקי יסוד, כמו סעיפים 9א, 44 ו-45 לחוק יסוד: הכנסת, וסעיף 7 לחוק יסוד: ירושלים בירת ישראל, משוריינים ברוב של 80 חברי כנסת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'התיקון יתקבל אם יתמכו בו לפחות 61 חברי כנסת.', false, 'בחירה זו שגויה. רוב של 61 חברי כנסת נדרש לתיקון חוקי יסוד משוריינים אחרים, אך לא לתיקון סעיפים הדורשים רוב של 80 חברי כנסת.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'התיקון לא יתקבל, שכן נדרש רוב של 90 חברי כנסת.', false, 'בחירה זו שגויה. רוב של 90 חברי כנסת נדרש רק במקרים חריגים ביותר, כמו הדחת מבקר המדינה או נשיא המדינה מכהונתם בשל התנהגות בלתי הולמת.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'רוב של חברי הכנסת הנוכחים בהצבעה, ללא קשר למספרם הכולל.', false, 'בחירה זו מתארת ''רוב רגיל'', שאינו זהה ל''רוב חברי הכנסת''. רוב רגיל דורש רוב מבין המשתתפים בהצבעה, כשהנמנעים אינם נמנים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'רוב של 61 חברי כנסת לפחות, מתוך 120 חברי הכנסת.', true, 'בחירה זו נכונה. הצירוף ''רוב חברי הכנסת'' משמעו רוב מוחלט של חברי הכנסת, כלומר 61 ח"כים לפחות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'רוב של שני שלישים מחברי הכנסת הנוכחים בהצבעה.', false, 'בחירה זו שגויה. ''רוב של שני שלישים'' הוא רוב מיוחס גבוה יותר, ואינו זהה ל''רוב חברי הכנסת''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'רוב של 80 חברי כנסת לפחות.', false, 'בחירה זו שגויה. רוב של 80 חברי כנסת הוא רוב מיוחס גבוה יותר, הנדרש רק לסעיפים ספציפיים ביותר בחוקי יסוד.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'חוק יסוד בהוראת שעה בטל מעיקרו, שכן חוק יסוד נועד ליציבות ולא לארעיות.', false, 'בחירה זו שגויה. בית המשפט העליון קבע כי חוק יסוד בהוראת שעה אינו בטל מעיקרו, אך הוא מעורר קשיים חוקתיים ומחייב בחינה קפדנית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'חוק יסוד בהוראת שעה אינו פוסל אותו מעיקרו, אך הוא מעורר קשיים חוקתיים ומחייב בחינה קפדנית.', true, 'בחירה זו נכונה. בית המשפט העליון הכיר באפשרות של חוק יסוד בהוראת שעה, אך הדגיש את הקשיים החוקתיים ואת הצורך בריסון מצד הכנסת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'חוק יסוד בהוראת שעה קביל רק אם הוא משוריין ברוב מיוחס של 80 חברי כנסת.', false, 'בחירה זו שגויה. השריון אינו התנאי היחיד או המכריע לקבילות חוק יסוד בהוראת שעה, ובית המשפט בוחן את מכלול הנסיבות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'חוק יסוד בהוראת שעה קביל רק אם הוא עוסק בעניינים טכניים ולא מהותיים.', false, 'בחירה זו שגויה. אף שרצוי שחוקי יסוד בהוראת שעה יעסקו בעניינים טכניים, בית המשפט לא פסל אותם מעיקרו גם בעניינים מהותיים, אלא בחן את השימוש לרעה בסמכות המכוננת.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'בית המשפט אינו מוסמך כלל לבקר חוקי יסוד, שכן הם ביטוי לסמכות המכוננת של העם.', false, 'בחירה זו שגויה. בית המשפט העליון הכיר בסמכותו לבקר חוקי יסוד, גם אם בזהירות ובמקרים חריגים ביותר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'בית המשפט מוסמך לבקר חוקי יסוד במקרים נדירים וחריגים ביותר, כאשר מדובר ב''שימוש לרעה בסמכות המכוננת'' או ''תיקון חוקתי שאינו חוקתי''.', true, 'בחירה זו נכונה. זוהי ההלכה המקובלת בפסיקת בית המשפט העליון, המאפשרת ביקורת שיפוטית מצומצמת על חוקי יסוד.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'בית המשפט מוסמך לבקר חוקי יסוד רק אם הם פוגעים בזכויות אדם המעוגנות בחוקי יסוד אחרים.', false, 'בחירה זו שגויה. אף שפגיעה בזכויות אדם יכולה להיות עילה לביקורת, הדוקטרינה רחבה יותר וכוללת פגיעה בעקרונות יסוד של השיטה, כמו אופייה היהודי והדמוקרטי של המדינה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בית המשפט מוסמך לבקר חוקי יסוד כפי שהוא מבקר חוקים רגילים, ללא הבחנה.', false, 'בחירה זו שגויה. הביקורת השיפוטית על חוקי יסוד מצומצמת בהרבה מזו המופעלת על חוקים רגילים, בשל מעמדם החוקתי העליון.', 4);

END $$;

-- ============================================================
-- Q38 — 2019-S-Q38 — chapter=constitutional_intl subtopic=bgz_jurisdiction_revocation
