  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'bgz_jurisdiction_revocation';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'bgz_jurisdiction_revocation';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q38', 'ed89ea85-f137-4877-90ab-7c7d56ff3cc2', v_subtopic_id,
    'ח"כ דניאל הורשע בפסק דין סופי בעבירה פלילית. האם תיפסק חברותו בכנסת?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 38}'::jsonb,
    'השאלה עוסקת בתנאים להפסקת חברותו של חבר כנסת מכהן עקב הרשעה בעבירה פלילית. היא מתמקדת בסעיף 42א לחוק יסוד: הכנסת, הקובע כי הפסקת החברות מותנית בהרשעה בפסק דין סופי וקביעת בית המשפט כי יש עם העבירה קלון, ללא קשר למועד ביצוע העבירה או לעונש מאסר בפועל.',
    'סעיף 42א(א) לחוק יסוד: הכנסת קובע כי "חבר הכנסת שהורשע בפסק דין סופי בעבירה פלילית וקבע בית המשפט, ביוזמתו או לבקשת היועץ המשפטי לממשלה, שיש עם העבירה קלון, תיפסק חברותו בכנסת ביום שפסק הדין נעשה סופי, ואין נפקא מינה אם העבירה נעברה בזמן שהיה חבר אותה הכנסת, חבר כנסת קודמת או לפני שהיה לחבר הכנסת" (Law: חוק-יסוד: הכנסת, סעיף 42א). כלומר, הפסקת חברותו של חבר כנסת מותנית בשני תנאים מצטברים: (1) הרשעה בפסק דין סופי בעבירה פלילית, ו-(2) קביעת בית המשפט כי יש עם העבירה קלון. אין דרישה לעונש מאסר בפועל, ואין חשיבות למועד ביצוע העבירה (Verdict: ת"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח"כ צחי הנגבי (9.11.2010), Reference 3). הוראה זו מבטאת את הרצון לשמור על טוהר המידות של נבחרי הציבור (Literature: יורם רבין, יניב ואקי, דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 18 קלון, עמ'' 3).',
    'הסטודנט עלול לטעות ולחשוב שכל הרשעה פלילית מביאה להפסקת חברות, או לבלבל בין התנאים להפסקת חברות (סעיף 42א) לבין התנאים להשעיה (סעיף 42ב) או לתנאי כשירות להיבחר (סעיף 6).',
    '["חוק יסוד: הכנסת", "סעיף 42א", "קלון", "פסק דין סופי", "הפסקת חברות", "נבחרי ציבור"]'::jsonb,
    '**וריאציה 1 — תנאי הפסקת חברות:** מהם התנאים להפסקת חברות חבר כנסת? ← הרשעה בפסק דין סופי בעבירה פלילית וקביעת בית המשפט שיש עם העבירה קלון (סעיף 42א(א) לחוק יסוד: הכנסת). **וריאציה 2 — חשיבות קביעת קלון:** האם הרשעה לבדה מספיקה? ← לא, נדרשת קביעת בית המשפט שיש עם העבירה קלון (סעיף 42א(א) לחוק יסוד: הכנסת). **וריאציה 3 — מועד ביצוע העבירה:** האם מועד ביצוע העבירה משנה? ← לא, אין נפקא מינה אם העבירה נעברה בזמן שהיה חבר כנסת או לפני כן (סעיף 42א(א) לחוק יסוד: הכנסת).',
    'חברותו של ח"כ דניאל בכנסת תיפסק רק אם הורשע בפסק דין סופי בעבירה פלילית ובית המשפט קבע כי יש עם העבירה קלון, ללא קשר למועד ביצוע העבירה או לעונש מאסר בפועל (סעיף 42א לחוק יסוד: הכנסת).',
    '["חוק-יסוד: הכנסת, סעיף 42א", "ת\"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח\"כ צחי הנגבי (9.11.2010)", "יורם רבין, יניב ואקי, דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 18 קלון, עמ'' 3"]'::jsonb,
    'needs_review=true | subtopic_mapping_review: original=''חוקי יסוד'' → mapped=''bgz_jurisdiction_revocation''',
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'כן. די בהרשעה בפסק דין סופי כדי להביא להפסקת הכהונה.', false, 'בחירה זו שגויה. הרשעה בפסק דין סופי לבדה אינה מספיקה להפסקת חברות בכנסת; נדרש גם שבית המשפט יקבע כי יש עם העבירה קלון.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'כן, רק אם קבע בית המשפט כי יש עם העבירה קלון.', true, 'בחירה זו נכונה. סעיף 42א(א) לחוק יסוד: הכנסת קובע כי חבר כנסת שהורשע בפסק דין סופי בעבירה פלילית, וחברותו תיפסק רק אם בית המשפט קבע שיש עם העבירה קלון.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'כן, רק אם קבע בית המשפט כי יש עם העבירה קלון והעבירה נעברה בזמן שהיה חבר כנסת.', false, 'בחירה זו שגויה. סעיף 42א(א) לחוק יסוד: הכנסת קובע במפורש כי אין נפקא מינה אם העבירה נעברה בזמן שהיה חבר אותה הכנסת, חבר כנסת קודמת או לפני שהיה לחבר הכנסת.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'כן, רק אם נידון חבר הכנסת למאסר.', false, 'בחירה זו שגויה. אף שבעבר נדרש עונש מאסר בפועל, הנוסח הנוכחי של סעיף 42א(א) לחוק יסוד: הכנסת אינו דורש מאסר בפועל כתנאי להפסקת חברות, אלא רק קביעת קלון.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'השעיית חבר כנסת בשל הרשעה', 1, 'ח"כ דניאל הורשע בעבירה פלילית ונגזר עליו עונש מאסר בפועל. האם יושעה מכהונתו בכנסת?',
    'שאלה זו בוחנת את ההוראות הנוגעות להשעיית חבר כנסת מכהונתו עקב הרשעה פלילית ועונש מאסר בפועל. היא מדגישה את ההבחנה בין השעיה זמנית לבין הפסקת חברות קבועה, ואת התנאים הספציפיים לכל אחת מהן הקבועים בחוק יסוד: הכנסת.',
    'סעיף 42ב לחוק יסוד: הכנסת קובע שני מקרים עיקריים להשעיית חבר כנסת: (א) חבר הכנסת שהורשע בעבירה פלילית ובית המשפט קבע, ביוזמתו או לבקשת היועץ המשפטי לממשלה, שיש עם העבירה קלון, יושעה מכהונתו בכנסת מיום קביעת בית המשפט ועד למועד שבו פסק הדין נעשה סופי. (ב) חבר הכנסת שהורשע בעבירה פלילית ונידון למאסר יושעה מכהונתו בכנסת למשך הזמן שהוא נושא את עונש המאסר (Law: חוק-יסוד: הכנסת, סעיף 42ב). במקרה הנדון, ח"כ דניאל נידון למאסר בפועל, ולכן יושעה מכהונתו למשך תקופת המאסר. הוראות אלו חלות גם אם העבירה נעברה לפני היותו חבר כנסת (Law: חוק-יסוד: הכנסת, סעיף 42ב(ב1)). ההשעיה היא אמצעי זמני שנועד למנוע מחבר כנסת שאינו ראוי למלא את תפקידו מלכהן בו, עד שפסק הדין יהיה סופי (Verdict: בג"ץ 306/81 שמואל פלאטו שרון נ'' ועדת הכנסת (30.7.1981), Reference 18).',
    'הסטודנט עלול לבלבל בין התנאים להשעיה (סעיף 42ב) לבין התנאים להפסקת חברות (סעיף 42א), או לחשוב שרק קביעת קלון מובילה להשעיה, מבלי להבחין בהוראה הספציפית לגבי מאסר בפועל.',
    '["השעיה", "חבר כנסת", "מאסר בפועל", "חוק יסוד: הכנסת", "סעיף 42ב", "פסק דין סופי"]'::jsonb,
    '**וריאציה 1 — השעיה עקב מאסר:** חבר כנסת נידון למאסר בפועל. האם יושעה? ← כן, למשך תקופת המאסר (סעיף 42ב(ב) לחוק יסוד: הכנסת). **וריאציה 2 — השעיה עקב קלון:** חבר כנסת הורשע בעבירה שיש עמה קלון, אך טרם ניתן פסק דין סופי. האם יושעה? ← כן, מיום קביעת בית המשפט ועד לפסק דין סופי (סעיף 42ב(א) לחוק יסוד: הכנסת). **וריאציה 3 — מטרת ההשעיה:** מהי מטרת ההשעיה? ← למנוע מחבר כנסת שאינו ראוי למלא את תפקידו מלכהן בו, עד שפסק הדין יהיה סופי (בג"ץ 306/81 פלאטו שרון, רפרנס 18).',
    'חבר כנסת שהורשע בעבירה פלילית ונידון למאסר בפועל יושעה מכהונתו בכנסת למשך תקופת המאסר, וזאת בהתאם לסעיף 42ב(ב) לחוק יסוד: הכנסת.',
    '["חוק-יסוד: הכנסת, סעיף 42ב", "ת\"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח\"כ צחי הנגבי (9.11.2010)", "בג\"ץ 306/81 שמואל פלאטו שרון נ'' ועדת הכנסת (30.7.1981)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'הגדרת "עבירה שיש עמה קלון"', 2, 'מהם הקריטריונים שבית המשפט בוחן בקביעת קלון בעבירה פלילית של חבר כנסת?',
    'שאלה זו עוסקת בפרשנות המונח ''עבירה שיש עמה קלון'' בפסיקה הישראלית, ובשיקולים המנחים את בית המשפט בקביעת קלון. היא מדגישה את האופי הערכי-מוסרי של הקלון ואת הצורך באיזון בין אינטרסים שונים, במיוחד בהקשר של נבחרי ציבור.',
    'המונח ''קלון'' אינו מוגדר בחקיקה, ומלאכת יציקת התוכן למושג זה היא יציר כפיה של הפסיקה (Literature: יורם רבין, יניב ואקי, דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 18 קלון, עמ'' 5). בית המשפט קבע כי ''קלון'' מבטא פגם מוסרי, הניזון מתפיסות ערכיות ומאמות מידה מוסריות הרווחות בחברה (Verdict: ת"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח"כ צחי הנגבי (9.11.2010), Reference 3). בקביעת קלון, בית המשפט בוחן את אופי העבירה, נסיבות ביצועה, והאם היא מבטאת פגם מוסרי חמור. בהקשר של נבחרי ציבור, נשקלת גם הפגיעה באמון הציבור ובטוהר המידות של משרתי הציבור (Verdict: בג"ץ 7367/97 התנועה למען איכות השלטון בישראל נ'' היועץ המשפטי לממשלה (19.10.1998), Reference 6). עם זאת, קביעת הקלון אינה עניין ערטילאי, אלא כפופה להקשר ולנסיבות הקונקרטיות (Verdict: ת"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח"כ צחי הנגבי (9.11.2010), Reference 4).',
    'הסטודנט עלול לטעות ולחשוב שקלון הוא רשימה סגורה של עבירות, או שהוא נקבע באופן אוטומטי ללא שיקול דעת שיפוטי, מבלי להבין את האופי הגמיש והערכי של המונח.',
    '["קלון", "פגם מוסרי", "יושרה ציבורית", "שיקול דעת שיפוטי", "נבחרי ציבור", "אמון הציבור"]'::jsonb,
    '**וריאציה 1 — הגדרת קלון:** מהו קלון? ← פגם מוסרי חמור בעבירה, הניזון מתפיסות ערכיות ומאמות מידה מוסריות הרווחות בחברה (ת"פ (שלום י-ם) 4063/06 הנגבי, רפרנס 3). **וריאציה 2 — שיקולי בית המשפט:** אילו שיקולים מנחים את בית המשפט בקביעת קלון? ← אופי העבירה, נסיבות ביצועה, תפקידו הציבורי של הנאשם והפגיעה באמון הציבור (בג"ץ 7367/97 התנועה למען איכות השלטון, רפרנס 6). **וריאציה 3 — קלון ככלי סינון:** מהי מטרת קביעת קלון? ← מנגנון סינון לשמירה על היגיינה ציבורית וטוהר מידות של משרתי ציבור (ת"פ (שלום י-ם) 4063/06 הנגבי, רפרנס 3).',
    'בית המשפט בוחן האם עבירה פלילית מבטאת פגם מוסרי חמור, תוך התחשבות באופי העבירה, נסיבותיה, ותפקידו הציבורי של הנאשם, כדי לקבוע אם יש עמה קלון, וזאת לשם שמירה על טוהר המידות בשירות הציבורי.',
    '["ת\"פ (שלום י-ם) 4063/06 מדינת ישראל נ'' ח\"כ צחי הנגבי (9.11.2010)", "בג\"ץ 7367/97 התנועה למען איכות השלטון בישראל נ'' היועץ המשפטי לממשלה (19.10.1998)", "יורם רבין, יניב ואקי, דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 18 קלון, עמ'' 5", "יורם רבין, יניב ואקי, דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 18 קלון, עמ'' 7"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'התפטרות למניעת קלון', 3, 'ח"כ אריה דרעי התפטר מהכנסת לפני מתן גזר דין בעבירות מס. האם בית המשפט יכול לקבוע קלון בעבירותיו לעניין הפסקת חברותו בכנסת?',
    'שאלה זו עוסקת בתרחיש ''הדלת המסתובבת'' ובאופן שבו התפטרות חבר כנסת מכהונתו משפיעה על סמכות בית המשפט לקבוע קלון בעבירותיו, בהקשר של הפסקת חברות בכנסת. היא מדגישה את הפרשנות המצמצמת של סעיף 42א(א) לחוק יסוד: הכנסת.',
    'בג"ץ 8948/22 אילן שיינפלד נ'' הכנסת דן במקרה של ח"כ אריה דרעי, שהתפטר מהכנסת עובר לאישור הסדר הטיעון ומתן גזר הדין בעניינו. בית המשפט קבע כי התפטרותו של דרעי מהכנסת השילה מבית המשפט את סמכותו למצוא קלון בעבירות בהן דרעי נמצא אשם, לעניין הפסקת חברותו בכנסת (Verdict: בג"ץ 8948/22 אילן שיינפלד נ'' הכנסת (18.1.2023), Reference 10). זאת, מכיוון שסעיף 42א(א) לחוק יסוד: הכנסת קובע כי "חבר הכנסת שהורשע... וקבע בית המשפט... שיש עם העבירה קלון, תיפסק חברותו בכנסת..." (Law: חוק-יסוד: הכנסת, סעיף 42א). כלומר, הסעיף חל רק על חבר כנסת מכהן. מרגע שדרעי התפטר, הוא לא היה עוד "חבר הכנסת", ולכן בית המשפט לא היה מוסמך לקבוע קלון לעניין הפסקת חברותו בכנסת (Verdict: בג"ץ 8948/22 אילן שיינפלד נ'' הכנסת (18.1.2023), Reference 11, 12).',
    'הסטודנט עלול לטעות ולחשוב שקביעת קלון היא סמכות כללית של בית המשפט, מבלי להבין שהיא מוגבלת למקרים בהם הנאשם הוא חבר כנסת מכהן, וכי התפטרות יכולה למנוע את הפעלת סמכות זו לעניין הפסקת חברות.',
    '["קלון", "התפטרות מחברות כנסת", "סעיף 42א לחוק יסוד: הכנסת", "סמכות בית המשפט", "הלכת דרעי", "דלת מסתובבת"]'::jsonb,
    '**וריאציה 1 — התפטרות למניעת קלון:** האם התפטרות חבר כנסת לפני גזר דין מונעת קביעת קלון? ← כן, לעניין הפסקת חברותו בכנסת, שכן סעיף 42א(א) חל רק על חבר כנסת מכהן (בג"ץ 8948/22 שיינפלד, רפרנס 10). **וריאציה 2 — סמכות בית המשפט לאחר התפטרות:** האם בית המשפט מוסמך לקבוע קלון לאחר התפטרות חבר כנסת? ← לא, לעניין הפסקת חברותו בכנסת, שכן הנאשם אינו עוד ''חבר הכנסת'' (בג"ץ 8948/22 שיינפלד, רפרנס 10). **וריאציה 3 — תרחיש "הדלת המסתובבת":** מהו החשש מ''הדלת המסתובבת''? ← שנאשם יתפטר, ימנע קביעת קלון, וישוב וייבחר לכנסת מבלי ששאלת הקלון עמדה להכרעה (בג"ץ 8948/22 שיינפלד, רפרנס 10).',
    'התפטרות חבר כנסת מכהונתו לפני מתן פסק דין סופי בעבירה פלילית מונעת מבית המשפט לקבוע קלון לעניין הפסקת חברותו בכנסת, שכן סעיף 42א(א) לחוק יסוד: הכנסת חל רק על חבר כנסת מכהן (בג"ץ 8948/22 שיינפלד).',
    '["בג\"ץ 8948/22 אילן שיינפלד נ'' הכנסת (18.1.2023)", "חוק-יסוד: הכנסת, סעיף 42א", "בג\"ץ 5668959 התנועה למען איכות השלטון בישראל נ'' היועץ המשפטי לממשלה (17.1.2022)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'פסילת מועמד לכנסת בשל קלון', 4, 'אדם שהורשע בפסק דין סופי בעבירה פלילית שיש עמה קלון וריצה עונש מאסר בפועל של 6 חודשים, מבקש להתמודד בבחירות לכנסת 5 שנים לאחר שסיים לרצות את עונשו. האם הוא כשיר להיבחר?',
    'שאלה זו עוסקת בתנאי הכשירות להיבחר לכנסת, ובפרט במגבלות החלות על מועמד שהורשע בעבירה פלילית שיש עמה קלון וריצה עונש מאסר. היא מתמקדת בסעיף 6(א) לחוק יסוד: הכנסת ובתפקידו של יו"ר ועדת הבחירות המרכזית בהקשר זה.',
    'סעיף 6(א) לחוק יסוד: הכנסת קובע כי "כל אזרח ישראלי... זכאי להיבחר לכנסת, זולת אם... נידון, בפסק דין סופי, לעונש מאסר בפועל לתקופה העולה על שלושה חודשים וביום הגשת רשימת המועמדים טרם עברו שבע שנים מהיום שגמר לרצות את עונש המאסר בפועל, אלא אם כן קבע יושב ראש ועדת הבחירות המרכזית כי אין עם העבירה שבה הורשע, בנסיבות הענין, משום קלון" (Law: חוק-יסוד: הכנסת, סעיף 6). במקרה הנדון, המועמד ריצה מאסר בפועל של 6 חודשים (העולה על 3 חודשים), וטרם חלפו שבע שנים מיום ריצוי העונש (חלפו רק 5 שנים). לפיכך, הוא אינו כשיר להיבחר, אלא אם יו"ר ועדת הבחירות המרכזית יקבע שאין עם העבירה קלון (Verdict: בג"ץ 797/20 עמוס דב סילבר נ'' יו"ר ועדת הבחירות לכנסת ה-23 (6.2.2020), Reference 24). הוראות דומות קיימות גם בחוקי בחירות לרשויות המקומיות (Law: חוק הרשויות המקומיות (בחירות), תשכ"ה-1965, סעיף 7א).',
    'הסטודנט עלול לבלבל בין תקופות הפסילה השונות (7 שנים, 3 חודשים מאסר), או להתעלם מהאפשרות של יו"ר ועדת הבחירות המרכזית לקבוע שאין קלון, או לבלבל בין תנאי כשירות למועמד (סעיף 6) לבין תנאי הפסקת חברות לחבר כנסת מכהן (סעיף 42א).',
    '["זכות להיבחר", "קלון", "סעיף 6 לחוק יסוד: הכנסת", "יו\"ר ועדת הבחירות המרכזית", "מאסר בפועל", "פסילת מועמד"]'::jsonb,
    '**וריאציה 1 — תנאי פסילת מועמד:** מהם התנאים לפסילת מועמד לכנסת עקב הרשעה? ← מאסר בפועל מעל 3 חודשים, וטרם חלפו 7 שנים מריצוי העונש (סעיף 6(א) לחוק יסוד: הכנסת). **וריאציה 2 — תפקיד יו"ר ועדת הבחירות:** מה תפקידו של יו"ר ועדת הבחירות המרכזית בהקשר זה? ← הוא רשאי לקבוע שאין עם העבירה קלון, ובכך להכשיר את המועמד (סעיף 6(א) לחוק יסוד: הכנסת). **וריאציה 3 — הבדל בין סעיף 6 ל-42א:** מה ההבדל בין סעיף 6 ל-42א לחוק יסוד: הכנסת? ← סעיף 6 עוסק בכשירות להיבחר, וסעיף 42א עוסק בהפסקת חברות של חבר כנסת מכהן (נבו - המתמחה, חוקי יסוד, עמ'' 58).',
    'מועמד לכנסת שהורשע בפסק דין סופי בעבירה שיש עמה קלון ונידון למאסר בפועל העולה על שלושה חודשים, אינו כשיר להיבחר אם טרם חלפו שבע שנים מיום שגמר לרצות את עונש המאסר, אלא אם יו"ר ועדת הבחירות המרכזית קבע שאין קלון (סעיף 6(א) לחוק יסוד: הכנסת).',
    '["חוק-יסוד: הכנסת, סעיף 6", "בג\"ץ 797/20 עמוס דב סילבר נ'' יו\"ר ועדת הבחירות לכנסת ה-23 (6.2.2020)", "חוק הרשויות המקומיות (בחירות), תשכ\"ה-1965, סעיף 7א", "יורם רבין, יניב ואקי, דיני עונשין - כרך ג: הענישה הפלילית (2022) | פרק 18 קלון, עמ'' 7", "נבו - המתמחה, חוקי יסוד (2026) | סיום כהונה של נושאי משרה עקב התפטרות והרשעה - טבלת השוואה, עמ'' 58"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'כן, יושעה מכהונתו למשך הזמן שהוא נושא את עונש המאסר.', true, 'בחירה זו נכונה. סעיף 42ב(ב) לחוק יסוד: הכנסת קובע כי חבר כנסת שהורשע בעבירה פלילית ונידון למאסר יושעה מכהונתו למשך הזמן שהוא נושא את עונש המאסר.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'לא, השעיה מתרחשת רק אם בית המשפט קבע שיש עם העבירה קלון.', false, 'בחירה זו שגויה. קביעת קלון רלוונטית להשעיה לפי סעיף 42ב(א) עד לפסק דין סופי, אך מאסר בפועל מוביל להשעיה אוטומטית למשך תקופת המאסר לפי סעיף 42ב(ב).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'כן, יושעה מכהונתו עד למתן פסק דין סופי בעניינו, ללא קשר למשך המאסר.', false, 'בחירה זו שגויה. השעיה עד לפסק דין סופי מתרחשת כאשר נקבע קלון אך טרם ניתן פסק דין סופי. במקרה של מאסר בפועל, ההשעיה היא למשך תקופת המאסר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לא, חבר כנסת אינו מושעה מכהונתו אלא רק חברותו נפסקת לאחר פסק דין סופי.', false, 'בחירה זו שגויה. חוק יסוד: הכנסת מבחין בין השעיה (סעיף 42ב) לבין הפסקת חברות (סעיף 42א), ושניהם יכולים להתרחש בהתקיים התנאים הרלוונטיים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'בית המשפט בוחן האם העבירה מבטאת פגם מוסרי חמור, תוך התחשבות באופי העבירה, נסיבותיה, ותפקידו הציבורי של הנאשם.', true, 'בחירה זו נכונה. הפסיקה קבעה כי קלון מבטא פגם מוסרי, ובית המשפט שוקל את מכלול הנסיבות, כולל תפקידו הציבורי של הנאשם, בקביעת קלון.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'בית המשפט בוחן רשימה סגורה של עבירות שהוגדרו בחוק כעבירות קלון, ואינו רשאי לחרוג ממנה.', false, 'בחירה זו שגויה. המונח ''קלון'' אינו מוגדר בחקיקה, ומלאכת יציקת התוכן למושג זה היא יציר כפיה של הפסיקה, ללא רשימה סגורה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'בית המשפט מתמקד אך ורק בחומרת העונש שנגזר על הנאשם, ולא באופי העבירה עצמה.', false, 'בחירה זו שגויה. חומרת העונש היא שיקול נפרד, אך הקלון מתייחס לפגם המוסרי שבעבירה עצמה ובנסיבותיה, ולא רק לעונש.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'בית המשפט אינו רשאי לשקול שיקולים הנוגעים לנסיבותיו האישיות של הנאשם, אלא רק שיקולים הנוגעים לעבירה ולתחום העיסוק.', false, 'בחירה זו שגויה. אף שהמאשימה עשויה לטעון כך, הפסיקה קובעת כי בית המשפט שוקל את מכלול הנסיבות, כולל נסיבותיו האישיות של הנאשם, בקביעת קלון.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'כן, בית המשפט תמיד מוסמך לקבוע קלון, ללא קשר למעמדו של הנאשם.', false, 'בחירה זו שגויה. סמכות בית המשפט לקבוע קלון לעניין הפסקת חברות בכנסת מוגבלת למקרים בהם הנאשם הוא חבר כנסת מכהן.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'לא, התפטרותו של דרעי מהכנסת השילה מבית המשפט את סמכותו למצוא קלון בעבירותיו לעניין הפסקת חברותו בכנסת, שכן סעיף 42א(א) לחוק יסוד: הכנסת חל רק על חבר כנסת מכהן.', true, 'בחירה זו נכונה. הלכת דרעי קבעה כי התפטרות חבר כנסת לפני מתן גזר הדין מונעת מבית המשפט לקבוע קלון לעניין הפסקת חברותו בכנסת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'כן, אך רק אם היועץ המשפטי לממשלה יבקש זאת מבית המשפט.', false, 'בחירה זו שגויה. גם אם היועץ המשפטי לממשלה יבקש, סמכות בית המשפט מוגבלת למקרים בהם הנאשם הוא חבר כנסת מכהן.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לא, אלא אם כן דרעי התחייב שלא לחזור לחיים הפוליטיים.', false, 'בחירה זו שגויה. אף שהתחייבות כזו עשויה להשפיע על שיקולי העונש, היא אינה משפיעה על סמכות בית המשפט לקבוע קלון לעניין הפסקת חברות בכנסת.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'כן, הוא כשיר להיבחר, שכן חלפו 5 שנים מיום שסיים לרצות את עונשו.', false, 'בחירה זו שגויה. סעיף 6(א) לחוק יסוד: הכנסת דורש שבע שנים מיום ריצוי המאסר, ולא חמש שנים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'לא, הוא אינו כשיר להיבחר, שכן טרם חלפו שבע שנים מיום שגמר לרצות את עונש המאסר בפועל.', true, 'בחירה זו נכונה. סעיף 6(א) לחוק יסוד: הכנסת קובע כי אדם שנידון למאסר בפועל העולה על שלושה חודשים, וטרם עברו שבע שנים מיום ריצוי העונש, אינו זכאי להיבחר, אלא אם יו"ר ועדת הבחירות קבע שאין קלון.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'כן, הוא כשיר להיבחר, שכן עונש המאסר שריצה היה פחות משנה.', false, 'בחירה זו שגויה. סעיף 6(א) לחוק יסוד: הכנסת קובע רף של שלושה חודשי מאסר בפועל, ולא שנה, כתנאי לפסילה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'לא, הוא אינו כשיר להיבחר, שכן הורשע בעבירה שיש עמה קלון, ואין אפשרות להסיר פסילה זו.', false, 'בחירה זו שגויה. קיימת אפשרות שיו"ר ועדת הבחירות המרכזית יקבע שאין עם העבירה קלון, ובכך יסיר את הפסילה.', 4);

END $$;

-- ============================================================
-- Q39 — 2019-S-Q39 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q39';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q39 skipped: external_id % already exists', '2019-S-Q39';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q39', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'במהלך ניהול הוכחות בבית המשפט המחוזי בתיק אזרחי התנהג בא כוח התובע בחוצפה כלפי בית המשפט וכלפי בעל הדין שכנגד. השופט שישב בדין ביקשו להירגע. משלא נרגע, החליט השופט לחייב את התובע בהוצאות משפט. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 39}'::jsonb,
    'השאלה עוסקת בסוגיית הערעור על החלטות ביניים בתיקים אזרחיים, ובפרט על החלטות הנוגעות להוצאות משפט. היא בוחנת את תחולתו של צו בתי המשפט (סוגי החלטות שלא תינתן בהן רשות ערעור), התשס"ט-2009, הקובע אילו החלטות אינן ניתנות לערעור מיידי, ואת האפשרות להשיג עליהן במסגרת הערעור על פסק הדין הסופי.',
    'סעיף 1(8) לצו בתי המשפט (סוגי החלטות שלא תינתן בהן רשות ערעור), התשס"ט-2009, קובע כי לא תינתן רשות ערעור על "החלטה בעניין הטלת הוצאות משפט ושכר טרחת עורך דין ושיעורם, למעט אם ניתנה לאחר מתן פסק הדין ואינה נבלעת בו" (Law: צו בתי המשפט (סוגי החלטות שלא תינתן בהן רשות ערעור), תשס"ט-2009, סעיף 1(8)). במקרה הנדון, החיוב בהוצאות ניתן במהלך ניהול ההוכחות, כלומר, מדובר בהחלטת ביניים שאינה ניתנת לאחר מתן פסק הדין. לפיכך, לא ניתן לערער על החלטה זו באופן מיידי. עם זאת, סעיף 2 לצו מבהיר כי הגבלה זו אינה גורעת מזכותו של בעל דין לערער על החלטות אלה במסגרת ערעור על פסק הדין הסופי (Law: צו בתי המשפט (סוגי החלטות שלא תינתן בהן רשות ערעור), תשס"ט-2009, סעיף 2). מטרת הצו היא למנוע סרבול וסחבת בהליכים המשפטיים על ידי הגבלת האפשרות לערער על החלטות דיוניות-ניהוליות שאינן מהותיות (Literature: יעקב שקד, סדר הדין האזרחי (2026) | 13.7.1 מטרתו של צו בתי המשפט, עמ'' 26).',
    'הסטודנט עלול לטעות ולחשוב שכל החלטה על הוצאות ניתנת לערעור מיידי, או לחילופין, שאין כלל אפשרות להשיג על החלטה כזו, מבלי להבחין בין ערעור מיידי לבין השגה במסגרת ערעור על פסק הדין הסופי.',
    '["צו בתי המשפט", "הוצאות משפט", "החלטת ביניים", "רשות ערעור", "ערעור על פסק דין", "סדר דין אזרחי"]'::jsonb,
    '**וריאציה 1 — ערעור על הוצאות במהלך הליך אזרחי:** האם ניתן לערער מיידית על חיוב בהוצאות במהלך הליך אזרחי? ← לא, סעיף 1(8) לצו בתי המשפט אוסר זאת. **וריאציה 2 — השגה על הוצאות:** כיצד ניתן להשיג על חיוב בהוצאות שניתן במהלך הליך אזרחי? ← במסגרת הערעור על פסק הדין הסופי (סעיף 2 לצו בתי המשפט). **וריאציה 3 — חריג לכלל ההוצאות:** מתי ניתן לערער על הוצאות באופן מיידי? ← רק אם ההחלטה ניתנה לאחר מתן פסק הדין ואינה נבלעת בו (סעיף 1(8) לצו בתי המשפט).',
    'התובע אינו רשאי לערער על החלטת חיוב בהוצאות משפט שניתנה במהלך הליך אזרחי באופן מיידי, שכן זוהי החלטת ביניים שצו בתי המשפט אוסר על ערעור מיידי עליה. עם זאת, הוא רשאי להשיג על החלטה זו במסגרת הערעור על פסק הדין הסופי.',
    '["צו בתי המשפט (סוגי החלטות שלא תינתן בהן רשות ערעור), תשס\"ט-2009, סעיף 1(8)", "צו בתי המשפט (סוגי החלטות שלא תינתן בהן רשות ערעור), תשס\"ט-2009, סעיף 2", "יעקב שקד, סדר הדין האזרחי (2026) | 13.7.1 מטרתו של צו בתי המשפט, עמ'' 26", "רע\"א 1689/24 דמיטרי ינקילוב נ'' מרינה נחשונוב שמ (21.3.2024)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'התובע רשאי לערער ברשות לפני בית המשפט העליון בתוך 30 יום מיום מתן ההחלטה.', false, 'בחירה זו שגויה. סעיף 1(8) לצו בתי המשפט אוסר על מתן רשות ערעור על החלטה בעניין הוצאות משפט שניתנה במהלך ההליך ואינה נבלעת בפסק הדין.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'התובע רשאי לערער בזכות לפני בית המשפט העליון בתוך 45 יום מיום מתן ההחלטה.', false, 'בחירה זו שגויה. החלטה על הוצאות משפט במהלך הליך אזרחי אינה פסק דין סופי, ולכן לא ניתן לערער עליה בזכות באופן מיידי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'התובע אינו רשאי לערער באמצע ההליך על החלטה זו אלא רק במסגרת הערעור על פסק הדין.', true, 'בחירה זו נכונה. סעיף 1(8) לצו בתי המשפט קובע כי לא תינתן רשות ערעור על החלטה בעניין הטלת הוצאות משפט ושכר טרחת עורך דין ושיעורם, למעט אם ניתנה לאחר מתן פסק הדין ואינה נבלעת בו. עם זאת, ניתן להשיג על החלטה זו במסגרת ערעור על פסק הדין הסופי.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'התובע אינו רשאי כלל לערער על החלטה זו.', false, 'בחירה זו שגויה. אף שלא ניתן לערער על ההחלטה באופן מיידי, סעיף 2 לצו בתי המשפט קובע כי אין באמור בסעיף 1 כדי לגרוע מזכותו של בעל דין לערער על החלטות אלה במסגרת ערעור על פסק הדין.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'ערעור על החלטה בעניין מועדים', 1, 'במהלך דיון בבית משפט השלום, הגיש הנתבע בקשה להארכת מועד להגשת תצהירי עדות ראשית. בית המשפט דחה את הבקשה. האם הנתבע רשאי להגיש בקשת רשות ערעור על החלטה זו באופן מיידי?',
    'שאלה זו בוחנת את תחולתו של צו בתי המשפט (סוגי החלטות שלא תינתן בהן רשות ערעור) על החלטות דיוניות הנוגעות למועדים. היא מדגישה את הכלל לפיו החלטות אלו אינן ניתנות לערעור מיידי, אך ניתן להשיג עליהן במסגרת הערעור על פסק הדין הסופי.',
    'סעיף 1(1) לצו בתי המשפט (סוגי החלטות שלא תינתן בהן רשות ערעור), התשס"ט-2009, קובע במפורש כי לא תינתן רשות ערעור על "החלטה בעניין קביעה ושינוי של מועדי דיון ומועדים להגשת בקשות, תגובות, כתבי טענות, מסמכים, סיכומים ותצהירים" (Law: צו בתי המשפט (סוגי החלטות שלא תינתן בהן רשות ערעור), תשס"ט-2009, סעיף 1(1)). מטרת הצו היא למנוע סרבול וסחבת בהליכים המשפטיים על ידי הגבלת האפשרות לערער על החלטות דיוניות-ניהוליות שאינן מהותיות (Literature: יעקב שקד, סדר הדין האזרחי (2026) | 13.7.1 מטרתו של צו בתי המשפט, עמ'' 26). עם זאת, סעיף 2 לצו מבהיר כי הגבלה זו אינה גורעת מזכותו של בעל דין לערער על החלטות אלה במסגרת ערעור על פסק הדין הסופי (Law: צו בתי המשפט (סוגי החלטות שלא תינתן בהן רשות ערעור), תשס"ט-2009, סעיף 2).',
    'הסטודנט עלול לטעות ולחשוב שכל החלטה המשפיעה על ניהול ההליך ניתנת לערעור מיידי, מבלי להכיר את ההגבלות הקבועות בצו בתי המשפט ואת ההבחנה בין ערעור מיידי לערעור על פסק דין סופי.',
    '["צו בתי המשפט", "החלטת ביניים", "רשות ערעור", "מועדים", "סדר דין אזרחי", "ערעור על פסק דין"]'::jsonb,
    '**וריאציה 1 — ערעור על דחיית מועד להגשת תצהירים:** האם ניתן לערער מיידית על דחיית בקשה להארכת מועד להגשת תצהירים? ← לא, סעיף 1(1) לצו בתי המשפט אוסר זאת. **וריאציה 2 — השגה על החלטת מועדים:** כיצד ניתן להשיג על החלטה בעניין מועדים? ← במסגרת הערעור על פסק הדין הסופי (סעיף 2 לצו בתי המשפט). **וריאציה 3 — חריג להארכת מועד:** מתי ניתן לערער על החלטה בבקשה להארכת מועד הקבוע בחיקוק? ← רק אם משמעותה שלילת האפשרות לפתוח בהליך (סעיף 1(2) לצו בתי המשפט).',
    'החלטה הדוחה בקשה להארכת מועד להגשת תצהירי עדות ראשית אינה ניתנת לערעור מיידי לפי צו בתי המשפט, אך ניתן להשיג עליה במסגרת הערעור על פסק הדין הסופי.',
    '["צו בתי המשפט (סוגי החלטות שלא תינתן בהן רשות ערעור), תשס\"ט-2009, סעיף 1(1)", "צו בתי המשפט (סוגי החלטות שלא תינתן בהן רשות ערעור), תשס\"ט-2009, סעיף 2", "יעקב שקד, סדר הדין האזרחי (2026) | 13.7.1 מטרתו של צו בתי המשפט, עמ'' 26"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'מבחני מתן רשות ערעור על החלטת ביניים', 2, 'כאשר צו בתי המשפט אינו חל על החלטת ביניים מסוימת בתיק אזרחי, מהם השיקולים המרכזיים שבית המשפט שלערעור יבחן בבואו להחליט אם ליתן רשות ערעור על החלטה זו?',
    'שאלה זו מתמקדת בקריטריונים הכלליים למתן רשות ערעור על ''החלטה אחרת'' (החלטת ביניים) בתיק אזרחי, במקרים שאינם נכללים ברשימת ההחלטות שבצו בתי המשפט. היא בוחנת את הבנת השיקולים המנחים את בית המשפט שלערעור, כפי שנקבעו בחוק בתי המשפט.',
    'סעיפים 41(ב) ו-52(ב) לחוק בתי המשפט [נוסח משולב], התשמ"ד-1984, קובעים את הקריטריונים למתן רשות ערעור על ''החלטה אחרת'' (החלטת ביניים) בעניין אזרחי. רשות כאמור תינתן "אם שוכנע בית המשפט כי אם הערעור על ההחלטה יידון במסגרת הערעור על פסק הדין ולא באופן מיידי, יהיה בכך כדי להשפיע באופן ממשי על זכויות הצדדים או שעלול להיגרם לצד להליך נזק של ממש, או שעלול להתנהל הליך מיותר או בדרך שגויה" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 41(ב); Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 52(ב)). שיקולים אלו נועדו לאזן בין הרצון לייעל את ההליכים ולמנוע סחבת לבין הצורך להגן על זכויות מהותיות של בעלי הדין ולאפשר תיקון טעויות דיוניות חמורות בזמן אמת (Literature: יעקב שקד, סדר הדין האזרחי (2026) | 13.7.1 מטרתו של צו בתי המשפט, עמ'' 26).',
    'הסטודנט עלול לבלבל בין הקריטריונים למתן רשות ערעור על החלטות ביניים לבין המבחנים לסיווג החלטה כ''פסק דין'' או ''החלטת ביניים'' לצורך ערעור בזכות, או לייחס את כללי צו בתי המשפט לכל החלטות הביניים.',
    '["רשות ערעור", "החלטה אחרת", "חוק בתי המשפט", "סדר דין אזרחי", "השפעה מהותית על זכויות", "נזק של ממש"]'::jsonb,
    '**וריאציה 1 — קריטריונים למתן רשות ערעור:** מהם הקריטריונים למתן רשות ערעור על החלטת ביניים אזרחית? ← השפעה ממשית על זכויות, נזק של ממש, או הליך מיותר/שגוי אם לא יתערבו מיידית (סעיפים 41(ב) ו-52(ב) לחוק בתי המשפט). **וריאציה 2 — מטרת הקריטריונים:** מהי מטרת הקריטריונים הללו? ← לאזן בין יעילות ההליך להגנה על זכויות מהותיות (יעקב שקד, סדר הדין האזרחי, עמ'' 26). **וריאציה 3 — החלטות שצו בתי המשפט לא חל עליהן:** האם הקריטריונים הללו חלים גם על החלטות שצו בתי המשפט אוסר לערער עליהן? ← לא, הקריטריונים הללו חלים על החלטות שצו בתי המשפט אינו אוסר לערער עליהן, אך עדיין דורשות רשות ערעור (יעקב שקד, סדר הדין האזרחי, עמ'' 26).',
    'בית המשפט ייתן רשות ערעור על החלטת ביניים אזרחית (שצו בתי המשפט אינו חל עליה) אם שוכנע כי אי-ערעור מיידי ישפיע מהותית על זכויות הצדדים, יגרום נזק של ממש, או יוביל להליך מיותר/שגוי (סעיפים 41(ב) ו-52(ב) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 41(ב)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 52(ב)", "יעקב שקד, סדר הדין האזרחי (2026) | 13.7.1 מטרתו של צו בתי המשפט, עמ'' 26"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'חריג לצו בתי המשפט בהוצאות', 3, 'בית משפט השלום קיבל בקשה לביטול פסק דין שניתן בהיעדר הגנה, אך התנה את הביטול בתשלום הוצאות משפט בסך 50,000 ש"ח. הנתבע טוען כי סכום זה מונע ממנו, הלכה למעשה, לקיים את ההליך. האם הנתבע רשאי להגיש בקשת רשות ערעור על החלטה זו באופן מיידי?',
    'שאלה זו עוסקת בחריג חשוב לכלל הקבוע בסעיף 1(8) לצו בתי המשפט, האוסר על ערעור מיידי על החלטות בעניין הוצאות. היא מתייחסת למקרים בהם החיוב בהוצאות מהווה תנאי להמשך ההליך ועלול לפגוע בזכות הגישה לערכאות, כפי שנקבע בהלכת מגדלי שינקין.',
    'הלכת בית המשפט העליון ברע"א 8256/13 מגדלי שינקין יזום ובניה והשקעות בע"מ נ'' יחזקאל קוצר קבעה כי המחסום הדיוני המעוגן בסעיף 1(8) לצו בתי המשפט אינו חל בנסיבות שבהן מי שניתן נגדו פסק דין בהיעדר הגנה מבקש רשות לערער על החלטה אשר מתנה את ביטולו של פסק הדין שניתן נגדו בתשלום הוצאות (Verdict: רע"א 3494/15 טפטה באביי נ'' מגדל חברה לביטוח בע"מ (27.8.2015), Reference 27; Verdict: רע"א 3020024 מגדלי שינקין יזום ובניה והשקעות בע"מ נ'' יחזקאל קוצר (16.1.2014), Reference 21). זאת, מכיוון ש''הוצאות המושתות במסגרת החלטה לביטול פסק דין'' אינן נבלעות בפסק הדין, ו''עצם החיוב בהוצאות מהווה תנאי להמשך קיום ההליך ועשוי למנוע מבעל דין את הגישה לערכאות'' (Verdict: רע"א 3494/15 טפטה באביי נ'' מגדל חברה לביטוח בע"מ (27.8.2015), Reference 27). במובן המהותי, עניינה של החלטה כזו הוא הצבת תנאי לביטולו של פסק הדין שניתן בהיעדר הגנה, ולהחלטה שכזו עשויות להיות השלכות משמעותיות על זכות הגישה לערכאות (Verdict: רע"א 3494/15 טפטה באביי נ'' מגדל חברה לביטוח בע"מ (27.8.2015), Reference 27).',
    'הסטודנט עלול ליישם את הכלל שבסעיף 1(8) לצו בתי המשפט באופן גורף, מבלי להכיר את החריג שנקבע בפסיקה במקרים בהם החיוב בהוצאות מונע גישה לערכאות.',
    '["צו בתי המשפט", "הוצאות משפט", "ביטול פסק דין", "זכות גישה לערכאות", "הלכת מגדלי שינקין", "רשות ערעור"]'::jsonb,
    '**וריאציה 1 — התניית ביטול פסק דין בהוצאות:** האם ניתן לערער על החלטה המתנה ביטול פסק דין בתשלום הוצאות גבוהות? ← כן, אם זה מונע גישה לערכאות, זה חריג לסעיף 1(8) לצו בתי המשפט (רע"א 3494/15 באביי, רפרנס 27). **וריאציה 2 — רציונל החריג:** מדוע קיים חריג זה? ← כי החיוב בהוצאות מהווה תנאי להמשך ההליך ועלול לפגוע בזכות הגישה לערכאות (רע"א 3494/15 באביי, רפרנס 27). **וריאציה 3 — סיווג ההוצאות:** האם הוצאות אלו נבלעות בפסק הדין? ← לא, הן אינן נבלעות בפסק הדין שבוטל, והן קשורות לתנאי הביטול ולא לתוצאות ההליך (רע"א 3494/15 באביי, רפרנס 27).',
    'הנתבע רשאי להגיש בקשת רשות ערעור על החלטה המתנה ביטול פסק דין בתשלום הוצאות משפט גבוהות, שכן במקרה כזה החיוב בהוצאות עלול למנוע ממנו את הגישה לערכאות, וזהו חריג לכלל הקבוע בסעיף 1(8) לצו בתי המשפט (הלכת מגדלי שינקין).',
    '["צו בתי המשפט (סוגי החלטות שלא תינתן בהן רשות ערעור), תשס\"ט-2009, סעיף 1(8)", "רע\"א 3020024 מגדלי שינקין יזום ובניה והשקעות בע\"מ נ'' יחזקאל קוצר (16.1.2014)", "רע\"א 3494/15 טפטה באביי נ'' מגדל חברה לביטוח בע\"מ (27.8.2015)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'ערעור על הוצאות בהליך פלילי', 4, 'נאשם בהליך פלילי חויב בהוצאות בסך 10,000 ש"ח לקופת בית המשפט, בשל דחיית דיון הוכחות שנגרמה עקב שינוי עמדתו לגבי ייצוג. הנאשם זוכה בסופו של ההליך. האם הוא רשאי לערער על חיוב ההוצאות?',
    'שאלה זו עוסקת בסוגיית הערעור על חיוב בהוצאות בהליך פלילי, ובפרט במקרה בו הנאשם זוכה. היא בוחנת את ההלכה שנקבעה בעניין כליפה כהן, המבחינה בין החלטות ביניים הנוגעות לאשמה לבין החלטות על הוצאות, וקובעת את מועד וסוג הערעור האפשרי.',
    'בפסק הדין ער"פ 8481/21 כליפה כהן נ'' מדינת ישראל, קבע בית המשפט העליון (ברוב דעות) כי החלטת בית המשפט המחוזי לחייב נאשם בהוצאות מכוח תקנה 21 לתקנות סדר הדין הפלילי היא ''החלטת ביניים'' שאינה ניתנת לערעור מיידי (Verdict: ער"פ 8481/21 כליפה כהן נ'' מדינת ישראל (11.9.2022), Reference 1, 2, 4). עם זאת, השופט מינץ (בדעת רוב) קבע כי החלטות בדבר פסיקת הוצאות מכוח תקנה 21 אינן נוגעות במישרין לשאלת אשמתו של הנאשם, ולכן קבלת עמדתו של בעל דין בסוף ההליך (זיכוי) אינה מייתרת את טענותיו כלפי ההחלטה להטיל עליו הוצאות (Verdict: ער"פ 8481/21 כליפה כהן נ'' מדינת ישראל (11.9.2022), Reference 3, 5). לפיכך, בעל דין שחויב בהוצאות במסגרת ההליך, רשאי להגיש בסוף ההליך ערעור על ההחלטה, אף מקום בו הוא אינו רשאי או מעוניין להגיש ערעור על פסק הדין הסופי, והערעור יסווג כערעור פלילי (Verdict: ער"פ 8481/21 כליפה כהן נ'' מדינת ישראל (11.9.2022), Reference 3, 6).',
    'הסטודנט עלול לטעות ולחשוב שזיכוי נאשם מבטל אוטומטית את כל החלטות הביניים, כולל חיוב בהוצאות, או לבלבל בין סיווג ההחלטה כ''החלטת ביניים'' לבין זכות הערעור עליה בסוף ההליך.',
    '["הוצאות בהליך פלילי", "תקנה 21 לתקנות סדר הדין הפלילי", "החלטת ביניים", "ערעור פלילי", "זיכוי נאשם", "הלכת כליפה כהן"]'::jsonb,
    '**וריאציה 1 — ערעור על הוצאות לאחר זיכוי:** נאשם זוכה, אך חויב בהוצאות מכוח תקנה 21. האם יכול לערער על ההוצאות? ← כן, בסוף ההליך, אף אם אינו מערער על הזיכוי, והערעור יסווג כפלילי (ער"פ 8481/21 כליפה כהן, רפרנס 3, 5). **וריאציה 2 — סיווג החלטת הוצאות פלילית:** האם חיוב בהוצאות מכוח תקנה 21 הוא ''פסק דין'' או ''החלטת ביניים''? ← ''החלטת ביניים'', שאינה ניתנת לערעור מיידי (ער"פ 8481/21 כליפה כהן, רפרנס 1, 2). **וריאציה 3 — רציונל הערעור לאחר זיכוי:** מדוע זיכוי אינו מייתר את הערעור על הוצאות? ← כי החלטות על הוצאות אינן נוגעות במישרין לשאלת אשמתו של הנאשם (ער"פ 8481/21 כליפה כהן, רפרנס 5).',
    'נאשם שחויב בהוצאות בהליך פלילי מכוח תקנה 21 וזוכה בסופו של ההליך, רשאי לערער על חיוב ההוצאות לאחר מתן פסק הדין הסופי, אף אם אינו מערער על הזיכוי, והערעור יסווג כערעור פלילי (הלכת כליפה כהן).',
    '["ער\"פ 8481/21 כליפה כהן נ'' מדינת ישראל (11.9.2022)", "דנ\"פ 6453/22 כליפה כהן נ'' מדינת ישראל (9.1.2023)", "רע\"פ 8277/20 כליפה כהן נ'' מדינת ישראל (7.11.2021)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'כן, הנתבע רשאי להגיש בקשת רשות ערעור, שכן דחיית בקשה להארכת מועד פוגעת בזכותו לנהל את הגנתו.', false, 'בחירה זו שגויה. אף שדחיית בקשה להארכת מועד עשויה להשפיע על ניהול ההגנה, סעיף 1(1) לצו בתי המשפט אוסר על מתן רשות ערעור על החלטות בעניין קביעה ושינוי של מועדים להגשת כתבי טענות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'לא, הנתבע אינו רשאי להגיש בקשת רשות ערעור על החלטה זו באופן מיידי, אלא רק במסגרת הערעור על פסק הדין הסופי.', true, 'בחירה זו נכונה. סעיף 1(1) לצו בתי המשפט קובע כי לא תינתן רשות ערעור על החלטה בעניין קביעה ושינוי של מועדי דיון ומועדים להגשת כתבי טענות. עם זאת, סעיף 2 לצו מאפשר להשיג על החלטה זו במסגרת ערעור על פסק הדין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'כן, אך רק אם דחיית הבקשה להארכת מועד שוללת מהנתבע את האפשרות לפתוח בהליך.', false, 'בחירה זו שגויה. החריג בסעיף 1(2) לצו בתי המשפט מתייחס להארכת מועד הקבוע בחיקוק שמשמעותה שלילת האפשרות לפתוח בהליך, ולא להארכת מועד להגשת תצהירים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לא, הנתבע אינו רשאי כלל לערער על החלטה זו, גם לא במסגרת הערעור על פסק הדין.', false, 'בחירה זו שגויה. סעיף 2 לצו בתי המשפט מאפשר להשיג על החלטות המנויות בסעיף 1 במסגרת ערעור על פסק הדין הסופי.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'האם הערעור על ההחלטה, אם יידון במסגרת הערעור על פסק הדין ולא באופן מיידי, ישפיע באופן ממשי על זכויות הצדדים, יגרום נזק של ממש, או יוביל להליך מיותר או שגוי.', true, 'בחירה זו נכונה. אלו הם הקריטריונים המפורטים בסעיפים 41(ב) ו-52(ב) לחוק בתי המשפט למתן רשות ערעור על החלטה אחרת בעניין אזרחי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'האם ההחלטה סיימה את ההתדיינות בעניין מסוים ונפרד מההליך המרכזי, גם אם לא סיימה את כל המחלוקת.', false, 'בחירה זו שגויה. מבחן זה רלוונטי לסיווג החלטה כ''פסק דין'' לצורך ערעור בזכות, ולא למתן רשות ערעור על ''החלטה אחרת''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'האם ההחלטה ניתנה על ידי שופט מחוזי או שופט שלום, שכן רק החלטות של בית המשפט המחוזי ניתנות לערעור ברשות.', false, 'בחירה זו שגויה. סעיפים 41(ב) ו-52(ב) לחוק בתי המשפט מתייחסים למתן רשות ערעור הן על החלטות של בית משפט מחוזי והן על החלטות של בית משפט שלום.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'האם ההחלטה ניתנה לאחר מתן פסק הדין ואינה נבלעת בו, שכן רק אז ניתן לערער עליה ברשות.', false, 'בחירה זו שגויה. תנאי זה הוא חריג ספציפי בסעיף 1(8) לצו בתי המשפט לגבי הוצאות, ואינו המבחן הכללי למתן רשות ערעור על החלטות ביניים שצו בתי המשפט אינו חל עליהן.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'לא, סעיף 1(8) לצו בתי המשפט אוסר על מתן רשות ערעור על החלטה בעניין הוצאות משפט.', false, 'בחירה זו שגויה. אף שסעיף 1(8) אוסר על ערעור על הוצאות, הפסיקה קבעה חריג למקרים בהם החיוב בהוצאות מהווה תנאי להמשך קיום ההליך ומונע גישה לערכאות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'כן, הנתבע רשאי להגיש בקשת רשות ערעור, שכן במקרה זה החיוב בהוצאות מהווה תנאי לביטול פסק הדין ועלול למנוע ממנו את הגישה לערכאות.', true, 'בחירה זו נכונה. הפסיקה קבעה כי המחסום הדיוני בסעיף 1(8) לצו בתי המשפט אינו חל כאשר החיוב בהוצאות מהווה תנאי להמשך קיום ההליך ועשוי למנוע מבעל דין את הגישה לערכאות (הלכת מגדלי שינקין).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'לא, הנתבע אינו רשאי לערער על החלטה זו, שכן היא נחשבת ל''החלטה אחרת'' שאינה ניתנת לערעור מיידי.', false, 'בחירה זו שגויה. אף שמדובר ב''החלטה אחרת'', הפסיקה יצרה חריג לכלל במקרים של פגיעה בזכות הגישה לערכאות.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'כן, אך רק אם סכום ההוצאות עולה על 75,000 ש"ח.', false, 'בחירה זו שגויה. אין רף כספי קבוע בחוק או בפסיקה המגדיר מתי החיוב בהוצאות מונע גישה לערכאות, אלא מדובר בבחינה מהותית של נסיבות המקרה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'לא, נאשם שזוכה אינו רשאי לערער על החלטות ביניים שניתנו במהלך ההליך, שכן טענותיו מתייתרות עם זיכויו.', false, 'בחירה זו שגויה. אף שטענות רבות מתייתרות עם זיכוי, הפסיקה קבעה כי חיוב בהוצאות מכוח תקנה 21 אינו נוגע לאשמה, ולכן אינו מתייתר עם זיכוי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'כן, הוא רשאי לערער על החלטת ההוצאות לאחר מתן פסק הדין הסופי, אף אם אינו מערער על הזיכוי, והערעור יסווג כערעור פלילי.', true, 'בחירה זו נכונה. הפסיקה קבעה כי החלטות על הוצאות מכוח תקנה 21 אינן נוגעות לאשמת הנאשם, ולכן ניתן לערער עליהן בסוף ההליך, גם אם הנאשם זוכה, והערעור יסווג כפלילי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'כן, הוא רשאי לערער על החלטת ההוצאות באופן מיידי, שכן מדובר בהחלטה בעלת אופי אזרחי.', false, 'בחירה זו שגויה. דעת הרוב בפסיקה קבעה כי החלטה זו היא ''החלטת ביניים'' בהליך פלילי, ובהיעדר הוראה מפורשת, לא ניתן לערער עליה באופן מיידי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'לא, אלא אם כן בית המשפט קבע במפורש כי מדובר בהחלטה הניתנת לערעור מיידי.', false, 'בחירה זו שגויה. בהיעדר הוראת דין מפורשת, לא ניתן לערער על החלטת ביניים בהליך פלילי באופן מיידי, גם אם בית המשפט היה קובע זאת.', 4);

END $$;

-- ============================================================
-- Q40 — 2019-S-Q40 — chapter=civil_proc subtopic=proceedings
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q40';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q40 skipped: external_id % already exists', '2019-S-Q40';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'proceedings';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'proceedings';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q40', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'רשם בכיר בבית משפט השלום דחה בקשה לצו עיכוב יציאה מן הארץ בדיון במעמד שני הצדדים במסגרת תביעה בסדר דין מהיר. כיצד ניתן לערער על החלטתו?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 40}'::jsonb,
    'השאלה עוסקת בדרכי הערעור על החלטות רשם בכיר בבית משפט השלום, ובפרט על החלטות המסווגות כ"החלטה אחרת". היא בוחנת את ההבחנה בין סמכויות הערעור על החלטות רשם רגיל לבין רשם בכיר, ואת הכלל לפיו החלטה אחרת של רשם בכיר ניתנת לערעור ברשות לבית המשפט המחוזי.',
    'סעיף 96(א1) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "החלטה אחרת של רשם בכיר, דינה, לעניין ערעור, כדין החלטה אחרת של בית המשפט שבו הוא משמש רשם בכיר" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 96(א1)). החלטה אחרת של בית משפט השלום ניתנת לערעור לפני בית המשפט המחוזי, אם ניתנה רשות לכך (סעיף 52(ב) לחוק בתי המשפט). לפיכך, החלטה אחרת של רשם בכיר בבית משפט השלום, כמו דחיית בקשה לצו עיכוב יציאה מן הארץ, ניתנת לערעור ברשות לבית המשפט המחוזי (Verdict: ע"ר (שלום עפ'') 17074-03-12 תעשיות מתכת לייזר אל.פי.סי בע"מ נ'' אבירם פ. תעשיות בע"מ (15.7.2012), Reference 5, 7; Verdict: ע"ר (שלום י-ם) 29113-05-14 בסד.ע.ב. פיתוח עסקי בע"מ נ'' י.ח. מט"ח ישיר בע"מ (14.7.2014), Reference 26, 27; Verdict: רע"א (מחוזי ת"א) 21147-10-15 בנק הפועלים בע"מ נ'' מדלן בוקובזה (3.11.2015), Reference 50). סמכותו של רשם בכיר לדון בתובענות אזרחיות מסוימות מוגדרת בסעיף 85א לחוק בתי המשפט (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 85א).',
    'הסטודנט עלול לבלבל בין דרכי הערעור על החלטות רשם בכיר לבין החלטות רשם שאינו בכיר, או בין ''החלטה אחרת'' ל''פסק דין'', מה שיוביל לבחירת ערכאת ערעור או דרך ערעור שגויה.',
    '["רשם בכיר", "החלטה אחרת", "רשות ערעור", "חוק בתי המשפט", "סעיף 96(א1)", "סמכות עניינית"]'::jsonb,
    '**וריאציה 1 — ערעור על החלטה אחרת של רשם בכיר:** רשם בכיר דחה בקשה לצו עיכוב יציאה מהארץ. כיצד מערערים? ← ברשות, לבית המשפט המחוזי (סעיף 96(א1) לחוק בתי המשפט). **וריאציה 2 — ערעור על פסק דין של רשם בכיר:** רשם בכיר נתן פסק דין בתביעה בסדר דין מהיר. כיצד מערערים? ← בזכות, לבית המשפט המחוזי (סעיף 96(א) לחוק בתי המשפט). **וריאציה 3 — ערעור על החלטה אחרת של רשם רגיל:** רשם (שאינו בכיר) דחה בקשה להארכת מועד. כיצד מערערים? ← בזכות, לבית המשפט השלום (סעיף 96(ב) לחוק בתי המשפט).',
    'החלטה אחרת של רשם בכיר בבית משפט השלום, כמו דחיית בקשה לצו עיכוב יציאה מן הארץ, ניתנת לערעור ברשות לבית המשפט המחוזי, שכן דינה כדין החלטה אחרת של שופט באותה ערכאה (סעיף 96(א1) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 96(א1)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 85א", "ע\"ר (שלום עפ'') 17074-03-12 תעשיות מתכת לייזר אל.פי.סי בע\"מ נ'' אבירם פ. תעשיות בע\"מ (15.7.2012)", "ע\"א (מחוזי ת\"א) 36903-05-20 אורי זוהר נ'' גל שמיע (28.6.2020)", "ע\"ר (שלום י-ם) 29113-05-14 בסד.ע.ב. פיתוח עסקי בע\"מ נ'' י.ח. מט\"ח ישיר בע\"מ (14.7.2014)", "רע\"א (מחוזי י-ם) 16461-02-26 יניב דרוויש נ'' פרץ כהן משכנתאות פ.כ.מ (18.2.2026)", "רע\"א (מחוזי ת\"א) 21147-10-15 בנק הפועלים בע\"מ נ'' מדלן בוקובזה (3.11.2015)", "רע\"א (מחוזי ת\"א) 38440-11-17 נילי וינברג נ'' יהושוע איטח (10.12.2017)", "רע\"א (מחוזי י-ם) 34885-01-26 רייסדור בנייה בע\"מ נ'' שטרן ו-65 נוספים (17.11.2025)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'ברשות, לבית המשפט המחוזי.', true, 'בחירה זו נכונה. סעיף 96(א1) לחוק בתי המשפט קובע כי החלטה אחרת של רשם בכיר דינה, לעניין ערעור, כדין החלטה אחרת של בית המשפט שבו הוא משמש רשם בכיר, ולכן הערעור עליה הוא ברשות לבית המשפט המחוזי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בזכות, לבית המשפט המחוזי.', false, 'בחירה זו שגויה. ערעור בזכות לבית המשפט המחוזי מתייחס לפסק דין של רשם (סעיף 96(א) לחוק בתי המשפט), ולא ל''החלטה אחרת'' של רשם בכיר.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בזכות, לבית משפט השלום.', false, 'בחירה זו שגויה. ערעור בזכות לבית משפט השלום מתייחס ל''החלטה אחרת'' של רשם שאינו בכיר (סעיף 96(ב) לחוק בתי המשפט), ולא לרשם בכיר.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'זו החלטה אחרת שלא ניתן לערער עליה במהלך הדיון אלא במסגרת הערעור על פסק הדין כולו.', false, 'בחירה זו שגויה. אף שמדובר ב''החלטה אחרת'', ניתן לערער עליה ברשות באופן מיידי לבית המשפט המחוזי, ואין צורך להמתין לפסק הדין הסופי.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'ערעור על החלטת רשם שאינו בכיר', 1, 'רשם (שאינו בכיר) בבית משפט השלום דחה בקשה לביטול עיקול זמני. כיצד ניתן לערער על החלטתו?',
    'שאלה זו בוחנת את ההבחנה בין ערעור על החלטה אחרת של רשם שאינו בכיר לבין החלטה אחרת של רשם בכיר, ומדגישה את הערכאה והדרך (בזכות/ברשות) לערעור על כל אחת מהן.',
    'סעיף 96(ב) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "החלטה אחרת של רשם שאינו רשם בכיר ניתנת לערעור לפני בית המשפט שבו הוא משמש רשם, ורשאי בית המשפט לדון בו בשופט אחד" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 96(ב)). בקשה לביטול עיקול זמני נחשבת לרוב כ"החלטה אחרת" (Verdict: ע"ר (שלום עפ'') 17074-03-12 תעשיות מתכת לייזר אל.פי.סי בע"מ נ'' אבירם פ. תעשיות בע"מ (15.7.2012), Reference 5). לכן, במקרה זה, הערעור יוגש בזכות לשופט בבית משפט השלום.',
    'בלבול בין סמכויות הערעור על החלטות רשם רגיל לבין רשם בכיר, או בין החלטה אחרת לפסק דין.',
    '["רשם", "רשם בכיר", "החלטה אחרת", "ערעור בזכות", "חוק בתי המשפט", "סעיף 96(ב)"]'::jsonb,
    '**וריאציה 1 — ערעור על החלטת רשם רגיל:** רשם (שאינו בכיר) דחה בקשה לביטול עיקול. כיצד מערערים? ← בזכות, לבית המשפט השלום (סעיף 96(ב) לחוק בתי המשפט). **וריאציה 2 — ערעור על החלטת רשם בכיר:** רשם בכיר דחה בקשה לביטול עיקול. כיצד מערערים? ← ברשות, לבית המשפט המחוזי (סעיף 96(א1) לחוק בתי המשפט). **וריאציה 3 — מטרת ההבחנה:** מדוע יש הבחנה בין רשם לרשם בכיר? ← המחוקק קבע היררכיית ערעור מיוחדת ושונה לרשם בכיר בשל סמכויותיו המורחבות (ע"ר (שלום עפ'') 17074-03-12, רפרנס 5).',
    'החלטה אחרת של רשם שאינו בכיר ניתנת לערעור בזכות בפני שופט באותו בית משפט שבו הוא מכהן כרשם (סעיף 96(ב) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 96(ב)", "ע\"ר (שלום עפ'') 17074-03-12 תעשיות מתכת לייזר אל.פי.סי בע\"מ נ'' אבירם פ. תעשיות בע\"מ (15.7.2012)", "ע\"א (מחוזי ת\"א) 2129/02 חן נגה נ'' עז'' מזרחי יצחק (16.8.2004)", "ע\"ר (שלום חי'') 20441-09-09 מוני מרום נ'' בנק דיסקונט סניף בית הקרנות (21.1.2010)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'סיווג החלטת רשם כ"פסק דין" או "החלטה אחרת"', 2, 'רשם בכיר בבית משפט השלום דחה בקשת רשות להתגונן ובעקבות זאת ניתן פסק דין. כיצד ניתן לערער על החלטת הרשם?',
    'שאלה זו עוסקת בסיווג החלטות רשם כ"פסק דין" או "החלטה אחרת" לצורך ערעור, ובפרט במקרה של דחיית בקשת רשות להתגונן שבעקבותיה ניתן פסק דין. היא בוחנת את הלכת "ההחלטה הנבלעת" ואת דרך הערעור הנכונה במצב זה.',
    'הלכה פסוקה היא כי החלטה הדוחה בקשה למתן רשות להתגונן נחשבת ל"החלטה אחרת" (Verdict: ע"א (מחוזי ת"א) 2878-10-10 שלמה אבניאל נ'' אפרים פולק (18.12.2011), Reference 28). אולם, כאשר בעקבות דחיית בקשת רשות להתגונן ניתן פסק דין, ההחלטה הדוחה את הבקשה "נבלעת" בפסק הדין, והערעור עליה מקומו במסגרת הערעור על פסק הדין (Verdict: ע"א (מחוזי תל אביב-יפו) 1662/05 קליברה החברה לקידום מכירות בע"מ נ'' בנק מזרחי המאוחד בע"מ (23.2.2006), Reference 42, 43; Verdict: ע"ר (שלום חי'') 20441-09-09 מוני מרום נ'' בנק דיסקונט סניף בית הקרנות (21.1.2010), Reference 60). פסק דין של רשם בכיר בבית משפט השלום דינו, לעניין ערעור, כדין פסק דין של בית המשפט שבו הוא משמש רשם (סעיף 96(א) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984). לכן, הערעור על פסק דין זה הוא בזכות לבית המשפט המחוזי (Verdict: ע"ר (שלום חד'') 15991-05-13 עומר אל חאלילה נ'' HENRY SCHEIN ESPANA ITD (10.9.2013), Reference 51; Verdict: ע"ר (שלום נצ'') 53858-09-14 יוסף גואטה נ'' שגית ראש (16.11.2014), Reference 52; Verdict: ע"ר (מחוזי ת"א) 21167-03-18 מ.ע.ג.ן - יעוץ וניהול נכסים בע"מ נ'' בוטיק - שימור מבנים בע"מ (1.5.2018), Reference 30, 31).',
    'הסטודנט עלול לטעות ולסווג את החלטת הרשם לדחות רשות להתגונן כ"החלטה אחרת" הניתנת לערעור ברשות, מבלי להבין את השלכות מתן פסק הדין בעקבותיה ואת הלכת "ההחלטה הנבלעת".',
    '["החלטה אחרת", "פסק דין", "הלכת ההחלטה הנבלעת", "רשות להתגונן", "ערעור בזכות", "סעיף 96(א) לחוק בתי המשפט"]'::jsonb,
    '**וריאציה 1 — דחיית רשות להתגונן ופסק דין:** רשם דחה בקשת רשות להתגונן וניתן פסק דין. כיצד מערערים? ← בזכות, לבית המשפט המחוזי, על פסק הדין, וההחלטה נבלעת בו (ע"א (מחוזי ת"א) 1662/05 קליברה, רפרנס 42, 43). **וריאציה 2 — דחיית התנגדות לביצוע שטר:** רשם דחה התנגדות לביצוע שטר. כיצד מערערים? ← בזכות, לבית המשפט המחוזי, שכן דחיית התנגדות כמוה כפסק דין (ע"ר (שלום נצ'') 53858-09-14 גואטה, רפרנס 52). **וריאציה 3 — החלטה אחרת שאינה נבלעת:** רשם דחה בקשה להארכת מועד להגשת התנגדות. האם זו החלטה נבלעת? ← לא, זו ''החלטה אחרת'' שאינה נבלעת, והערעור עליה הוא בזכות לבית משפט השלום (ע"א (מחוזי ת"א) 34618-11-09 סידה, רפרנס 32).',
    'כאשר רשם בכיר דוחה בקשת רשות להתגונן ובעקבות זאת ניתן פסק דין, החלטת הרשם נבלעת בפסק הדין, והערעור על פסק הדין הוא בזכות לבית המשפט המחוזי (סעיף 96(א) לחוק בתי המשפט והלכת ההחלטה הנבלעת).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 96(א)", "ע\"א (מחוזי ת\"א) 2878-10-10 שלמה אבניאל נ'' אפרים פולק (18.12.2011)", "ע\"א (מחוזי תל אביב-יפו) 1662/05 קליברה החברה לקידום מכירות בע\"מ נ'' בנק מזרחי המאוחד בע\"מ (23.2.2006)", "ע\"ר (שלום חי'') 20441-09-09 מוני מרום נ'' בנק דיסקונט סניף בית הקרנות (21.1.2010)", "ע\"ר (שלום חד'') 15991-05-13 עומר אל חאלילה נ'' HENRY SCHEIN ESPANA ITD (10.9.2013)", "ע\"ר (שלום נצ'') 53858-09-14 יוסף גואטה נ'' שגית ראש (16.11.2014)", "ע\"ר (מחוזי ת\"א) 21167-03-18 מ.ע.ג.ן - יעוץ וניהול נכסים בע\"מ נ'' בוטיק - שימור מבנים בע\"מ (1.5.2018)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'ערעור על החלטת רשם בענייני בוררות', 3, 'רשם בית משפט מחוזי אישר פסק בוררות. כיצד ניתן לערער על החלטתו?',
    'שאלה זו עוסקת בהסדר הערעור המיוחד על החלטות רשם בענייני בוררות, כפי שנקבע בחוק הבוררות. היא מדגישה את העדיפות של ההוראה הספציפית בחוק הבוררות על פני ההוראות הכלליות בחוק בתי המשפט.',
    'סעיף 38 לחוק הבוררות, תשכ"ח-1968, קובע כי "החלטה של בית המשפט לפי חוק זה ניתנת לערעור ברשות לפי סעיף 19(ב) לחוק בתי המשפט, התשי"ז-1957; החלטה של רשם לפי חוק זה ניתנת לערעור לפי סעיף 8(ב) ו-(ד) לפקודת הרשמים, 1936" (Verdict: ע"א (מחוזי תל אביב-יפו) 2976/01 דלתא ישיר יבוא בע"מ נ'' שובל רפאל (31.12.2001), Reference 15). סעיפים 8(ב) ו-8(ד) לפקודת הרשמים הם כיום סעיפים 96(ב) ו-96(ד) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984. סעיף 96(ב) קובע כי "החלטה אחרת של רשם ניתנת לערעור לפני בית המשפט שבו הוא משמש רשם" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 96(ב)). הפסיקה קבעה כי מכוח העדיפות המוקנית לסעיף 38 לחוק הבוררות על פני הוראות הדין הכללי, כל החלטת רשם בענייני בוררות, בין אם היא פסק דין ובין אם היא החלטה אחרת, ניתנת לערעור בזכות לבית המשפט בו הרשם משמש (Verdict: ע"א (מחוזי תל אביב-יפו) 2976/01 דלתא ישיר יבוא בע"מ נ'' שובל רפאל (31.12.2001), Reference 16). במקרה של רשם בית משפט מחוזי, הערעור הוא בזכות לבית המשפט העליון (Verdict: עמ"ש (מחוזי תל אביב-יפו) 37508-01-13 י.ש נ'' מ.י. (קטין) (11.3.2013), Reference 3).',
    'הסטודנט עלול לטעות וליישם את הכללים הכלליים של ערעור על החלטות רשם (סעיף 96 לחוק בתי המשפט) מבלי להתחשב בהוראה הספציפית והגוברת של חוק הבוררות.',
    '["חוק הבוררות", "סעיף 38 לחוק הבוררות", "ערעור בזכות", "החלטת רשם", "פסק בוררות", "עדיפות דין ספציפי"]'::jsonb,
    '**וריאציה 1 — ערעור על אישור פסק בוררות על ידי רשם מחוזי:** רשם מחוזי אישר פסק בוררות. כיצד מערערים? ← בזכות, לבית המשפט העליון (סעיף 38 לחוק הבוררות, המפנה לסעיף 96(ב) לחוק בתי המשפט). **וריאציה 2 — ערעור על אישור פסק בוררות על ידי שופט:** שופט מחוזי אישר פסק בוררות. כיצד מערערים? ← ברשות, לבית המשפט העליון (סעיף 38 לחוק הבוררות). **וריאציה 3 — סמכות רשם בענייני בוררות:** אילו סמכויות יש לרשם בענייני בוררות? ← מינוי בורר, הארכת מועדים, אישור פסק בוררות כשאין בקשה לביטולו (סעיף 37 לחוק הבוררות).',
    'על החלטת רשם בית משפט מחוזי המאשרת פסק בוררות ניתן לערער בזכות לבית המשפט העליון, מכוח הוראת סעיף 38 לחוק הבוררות המפנה לסעיף 96(ב) לחוק בתי המשפט.',
    '["חוק הבוררות, תשכ\"ח-1968, סעיף 38", "חוק הבוררות, תשכ\"ח-1968, סעיף 37", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 96(ב)", "ע\"א (מחוזי תל אביב-יפו) 2976/01 דלתא ישיר יבוא בע\"מ נ'' שובל רפאל (31.12.2001)", "עמ\"ש (מחוזי תל אביב-יפו) 37508-01-13 י.ש נ'' מ.י. (קטין) (11.3.2013)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'ערעור על החלטת רשם הוצאה לפועל', 4, 'רשם הוצאה לפועל דחה בקשת חייב בטענת ''פרעתי''. החייב ערער לבית משפט השלום, וערעורו נדחה. כיצד ניתן לערער על פסק דינו של בית משפט השלום?',
    'שאלה זו עוסקת בהיררכיית הערעור על החלטות רשם ההוצאה לפועל, ובפרט על החלטות הנוגעות לטענת ''פרעתי''. היא מדגישה את ההבחנה בין סוגי החלטות שונות של רשם ההוצאה לפועל ואת דרך הערעור המתאימה לכל אחת מהן.',
    'סעיף 80 לחוק ההוצאה לפועל, תשכ"ז-1967, קובע את דרכי הערעור על החלטות רשם ההוצאה לפועל. על החלטות רשם ההוצאה לפועל בעניינים מהותיים, כגון טענת ''פרעתי'' (סעיף 19 לחוק ההוצאה לפועל), הערעור לבית משפט השלום הוא בזכות (Verdict: ע"א (מחוזי ת"א) 13870-12-09 יניב רון נ'' משה דוד בן אבו (8.2.2011), Reference 28, 29; Verdict: רע"א (מחוזי מרכז) 41364-04-10 עדו עמרם נ'' פי. אס. אי אקולוגיה בע"מ (8.11.2010), Reference 21, 22). כאשר בית משפט השלום דן בערעור על החלטת רשם ההוצאה לפועל בטענת ''פרעתי'', פסק דינו של בית משפט השלום ניתן לערעור בזכות לבית המשפט המחוזי (Verdict: רע"א (מחוזי מרכז) 41364-04-10 עדו עמרם נ'' פי. אס. אי אקולוגיה בע"מ (8.11.2010), Reference 23). זאת, מכיוון שהחלטות אלו קובעות זכויות וחובות מהותיות (Verdict: רע"א (מחוזי מרכז) 41364-04-10 עדו עמרם נ'' פי. אס. אי אקולוגיה בע"מ (8.11.2010), Reference 22).',
    'הסטודנט עלול לבלבל בין ערעור על החלטות רשם הוצאה לפועל בעניינים מהותיים (בזכות) לבין החלטות אחרות (ברשות), וכן בין הערכאות השונות ב''גלגול השני'' של הערעור.',
    '["חוק ההוצאה לפועל", "סעיף 80 לחוק ההוצאה לפועל", "טענת פרעתי", "ערעור בזכות", "רשם הוצאה לפועל", "גלגול שני"]'::jsonb,
    '**וריאציה 1 — ערעור על החלטת רשם הוצל"פ בטענת ''פרעתי'':** רשם הוצל"פ דחה טענת ''פרעתי''. כיצד מערערים? ← בזכות, לבית משפט השלום (סעיף 80(ב) לחוק ההוצאה לפועל). **וריאציה 2 — ערעור על פסק דין של שלום בערעור על רשם הוצל"פ בטענת ''פרעתי'':** בית משפט השלום דחה ערעור על טענת ''פרעתי''. כיצד מערערים? ← בזכות, לבית המשפט המחוזי (רע"א (מחוזי מרכז) 41364-04-10 עמרם, רפרנס 23). **וריאציה 3 — ערעור על החלטת רשם הוצל"פ שאינה ''פרעתי'':** רשם הוצל"פ דחה בקשה אחרת (שאינה בסעיפים 19, 25, 48, 58). כיצד מערערים? ← ברשות, לבית משפט השלום (סעיף 80(ב) לחוק ההוצאה לפועל).',
    'על פסק דינו של בית משפט השלום שדחה ערעור על החלטת רשם הוצאה לפועל בטענת ''פרעתי'' (סעיף 19 לחוק ההוצאה לפועל) ניתן לערער בזכות לבית המשפט המחוזי, שכן מדובר בהחלטה מהותית הקובעת זכויות וחובות.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 80", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 19", "ע\"א (מחוזי ת\"א) 13870-12-09 יניב רון נ'' משה דוד בן אבו (8.2.2011)", "רע\"א (מחוזי מרכז) 41364-04-10 עדו עמרם נ'' פי. אס. אי אקולוגיה בע\"מ (8.11.2010)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'ברשות, לבית המשפט המחוזי.', false, 'בחירה זו שגויה. החלטה אחרת של רשם שאינו בכיר ניתנת לערעור בזכות לבית המשפט שבו הוא משמש רשם, ולא ברשות לבית המשפט המחוזי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'בזכות, לבית משפט השלום.', true, 'בחירה זו נכונה. סעיף 96(ב) לחוק בתי המשפט קובע כי החלטה אחרת של רשם שאינו רשם בכיר ניתנת לערעור בזכות לפני בית המשפט שבו הוא משמש רשם.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'בזכות, לבית המשפט המחוזי.', false, 'בחירה זו שגויה. ערעור בזכות לבית המשפט המחוזי מתייחס לפסק דין של רשם, לא להחלטה אחרת של רשם שאינו בכיר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'זו החלטה אחרת שלא ניתן לערער עליה כלל.', false, 'בחירה זו שגויה. ניתן לערער על החלטה אחרת של רשם, אך הדרך והערכאה שונות.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'על החלטת הרשם לדחות את הבקשה לרשות להתגונן ניתן לערער בזכות לבית המשפט המחוזי, שכן היא נבלעת בפסק הדין שניתן בעקבותיה.', true, 'בחירה זו נכונה. כאשר החלטה הדוחה בקשת רשות להתגונן מובילה למתן פסק דין, היא נבלעת בו, והערעור על פסק הדין הוא בזכות לבית המשפט המחוזי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'על החלטת הרשם לדחות את הבקשה לרשות להתגונן ניתן לערער ברשות לבית המשפט המחוזי, שכן היא ''החלטה אחרת'' של רשם בכיר.', false, 'בחירה זו שגויה. אף שהיא ''החלטה אחרת'' של רשם בכיר, מרגע שניתן פסק דין בעקבותיה, היא נבלעת בו, והערעור הוא על פסק הדין בזכות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'על החלטת הרשם לדחות את הבקשה לרשות להתגונן ניתן לערער בזכות לבית משפט השלום, שכן היא ''החלטה אחרת'' של רשם.', false, 'בחירה זו שגויה. אפשרות זו רלוונטית רק אם לא ניתן פסק דין בעקבות דחיית הבקשה, וגם אז רק לרשם שאינו בכיר.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'לא ניתן לערער על החלטת הרשם לדחות את הבקשה לרשות להתגונן, אלא רק על פסק הדין הסופי.', false, 'בחירה זו שגויה. ניתן לערער על פסק הדין הסופי, ובמסגרת ערעור זה ניתן להשיג גם על החלטת הביניים שנבלעה בו.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'בזכות, לבית המשפט העליון.', true, 'בחירה זו נכונה. סעיף 38 לחוק הבוררות, המפנה לסעיף 96(ב) לחוק בתי המשפט, קובע כי כל החלטת רשם בענייני בוררות, בין אם היא פסק דין ובין אם היא החלטה אחרת, ניתנת לערעור בזכות לבית המשפט בו הרשם משמש.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'ברשות, לבית המשפט העליון.', false, 'בחירה זו שגויה. אף שערעור על החלטת שופט בענייני בוררות הוא ברשות לבית המשפט העליון, על החלטת רשם בענייני בוררות הערעור הוא בזכות.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בזכות, לבית המשפט המחוזי.', false, 'בחירה זו שגויה. ערעור בזכות לבית המשפט המחוזי מתייחס לפסק דין של רשם בית משפט השלום, לא של רשם בית משפט מחוזי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'לא ניתן לערער על החלטה המאשרת פסק בוררות, שכן היא סופית.', false, 'בחירה זו שגויה. ניתן לערער על החלטה המאשרת פסק בוררות, אך הדרך והערכאה נקבעות לפי חוק הבוררות וחוק בתי המשפט.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'בזכות, לבית המשפט המחוזי.', true, 'בחירה זו נכונה. כאשר רשם ההוצאה לפועל דן בטענת ''פרעתי'' (סעיף 19 לחוק ההוצאה לפועל), הערעור לבית משפט השלום הוא בזכות, ופסק דינו של בית משפט השלום בערעור זה ניתן לערעור בזכות לבית המשפט המחוזי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'ברשות, לבית המשפט המחוזי.', false, 'בחירה זו שגויה. ערעור ברשות לבית המשפט המחוזי מתייחס להחלטות רשם הוצאה לפועל שאינן עוסקות בסעיפים המהותיים כמו ''פרעתי''.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'בזכות, לבית המשפט העליון.', false, 'בחירה זו שגויה. הערעור לבית המשפט העליון יהיה רק ב''גלגול שלישי'' וברשות, ולא בזכות ב''גלגול שני''.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'לא ניתן לערער על פסק דינו של בית משפט השלום, שכן מדובר ב''גלגול שני'' של ערעור.', false, 'בחירה זו שגויה. ניתן לערער על פסק דינו של בית משפט השלום, והשאלה היא האם בזכות או ברשות.', 4);

END $$;

-- ============================================================
-- Q41 — 2019-S-Q41 — chapter=civil_proc subtopic=jurisdiction_subject
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q41';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q41 skipped: external_id % already exists', '2019-S-Q41';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'jurisdiction_subject';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'jurisdiction_subject';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q41', '34781415-6c5e-4e9c-9550-d65a9d3e1d90', v_subtopic_id,
    'ראובן הגיש לבית משפט השלום תביעה לסלק את ידו של שמעון מנכס בשווי של 3 מיליון ש"ח בטענה שהנכס הוא בבעלותו של ראובן. שמעון הגיש כתב הגנה, ובד בבד הגיש תביעה שכנגד ובה עתר לבית משפט השלום לסעד הצהרתי כי הוא הבעלים של הנכס. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 41}'::jsonb,
    'השאלה עוסקת בסמכותו העניינית של בית משפט השלום לדון בתביעה שכנגד לסעד הצהרתי בעלות במקרקעין, כאשר התביעה העיקרית היא לסילוק יד. היא בוחנת את תחולת סעיף 51(א)(4) לחוק בתי המשפט, המרחיב את סמכות בית משפט השלום לדון בתביעות שכנגד החורגות מסמכותו הרגילה, בתנאי שקיים קשר מהותי בין התביעות.',
    'סעיף 51(א)(4) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי בית משפט השלום מוסמך לדון ב"תביעה-שכנגד לתביעה אזרחית שנושאן אחד או שהן נובעות מאותן הנסיבות, יהיה שוויו של נושא התביעה-שכנגד אשר יהיה" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 51(א)(4)). הפסיקה פירשה הוראה זו באופן מרחיב, כך שהיא חלה גם על סעדים במקרקעין הנתונים בדרך כלל לסמכות בית המשפט המחוזי, ובלבד שמתקיים הקשר הנדרש בין התביעות (Verdict: רע"א 3749/12 ששון בר-עוז נ'' דניאל סטר (1.8.2013), Reference 27; Verdict: ת"א (שלום ת"א) 29135-07-19 צפית קצובר נ'' שהרוך מוראד (5.11.2020), Reference 41; Verdict: ת"א (שלום ראשל"צ) 78718-01-23 יורם סגרון נ'' נעמי אלכאוי (18.4.2024), Reference 51). במקרה זה, התביעה העיקרית לסילוק יד (שהיא תביעת חזקה ושימוש בסמכות השלום לפי סעיף 51(א)(3) לחוק בתי המשפט) והתביעה שכנגד לסעד הצהרתי בעלות נוגעות לאותו נכס ולאותן נסיבות, ולכן בית משפט השלום קונה סמכות לדון בתביעה שכנגד. ההכרעה של בית משפט השלום בשאלת הבעלות במסגרת תביעה שכנגד זו תהיה בעלת תוקף של מעשה בית דין לכל דבר ועניין, בניגוד להכרעה אגבית בשאלת בעלות במסגרת תביעה לחזקה ושימוש (Verdict: ת"א (שלום ת"א) 29135-07-19 צפית קצובר נ'' שהרוך מוראד (5.11.2020), Reference 41).',
    'הסטודנט עלול לבלבל בין סמכות אגבית (סעיף 76 לחוק בתי המשפט), שבה הכרעה בשאלת בעלות אינה מהווה מעשה בית דין, לבין סמכות לדון בתביעה שכנגד לבעלות מכוח סעיף 51(א)(4), שבה הכרעה זו כן מהווה מעשה בית דין.',
    '["סמכות עניינית", "תביעה שכנגד", "סעיף 51(א)(4) לחוק בתי המשפט", "מקרקעין", "סילוק יד", "סעד הצהרתי", "בעלות", "מעשה בית דין"]'::jsonb,
    '**וריאציה 1 — תביעה שכנגד לבעלות במקרקעין:** ראובן תובע סילוק יד בבית משפט השלום. שמעון תובע שכנגד לבעלות. האם בית משפט השלום מוסמך? ← כן, מכוח סעיף 51(א)(4) לחוק בתי המשפט, והכרעתו תהיה לכל עניין (ת"א (שלום ת"א) 29135-07-19 קצובר, רפרנס 41). **וריאציה 2 — תנאי לסמכות בתביעה שכנגד:** מה התנאי שבית משפט השלום יקנה סמכות בתביעה שכנגד לבעלות? ← שנושא התביעה העיקרית והשכנגד אחד או שהן נובעות מאותן נסיבות (סעיף 51(א)(4) לחוק בתי המשפט). **וריאציה 3 — תוקף הכרעה בתביעה שכנגד:** האם הכרעת בית משפט השלום בתביעה שכנגד לבעלות מהווה מעשה בית דין? ← כן, בניגוד להכרעה אגבית (ת"א (שלום ת"א) 29135-07-19 קצובר, רפרנס 41).',
    'בית משפט השלום מוסמך לדון בתביעה שכנגד לסעד הצהרתי בעלות במקרקעין, גם אם סעד זה חורג מסמכותו הרגילה, וזאת מכוח סעיף 51(א)(4) לחוק בתי המשפט, כאשר התביעה העיקרית והשכנגד נושאן אחד או נובעות מאותן נסיבות, והכרעתו תהווה מעשה בית דין לכל עניין.',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 51(א)(4)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 51(א)(3)", "רע\"א 3749/12 ששון בר-עוז נ'' דניאל סטר, פ\"ד סו(1) 678 (2013)", "ת\"א (שלום ת\"א) 29135-07-19 צפית קצובר נ'' שהרוך מוראד (5.11.2020)", "ת\"א (שלום ראשל\"צ) 78718-01-23 יורם סגרון נ'' נעמי אלכאוי (18.4.2024)", "רע\"א 8996/08 עיזבון נאסר נ'' הקרן הקיימת לישראל (22.8.2011)", "ע\"א 289/65 רובינשטיין נ'' רון, פ\"ד כ(1) 505 (1966)", "ת\"א (שלום בת ים) 58482-05-23 רשות מקרקעי ישראל נ'' בית ארלוזורוב חברה בע\"מ (12.1.2026)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'שמעון לא היה רשאי להגיש תביעה שכנגד זו בבית משפט השלום הואיל והוא מבקש סעד הצהרתי של בעלות במקרקעין.', false, 'בחירה זו שגויה. סעיף 51(א)(4) לחוק בתי המשפט מרחיב את סמכות בית משפט השלום לדון בתביעה שכנגד לבעלות במקרקעין, אם נושאן אחד או נובעות מאותן נסיבות.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'בית משפט השלום רשאי לדון בתביעתו של שמעון, אך החלטתו תהא טובה רק לצורך אותו עניין.', false, 'בחירה זו שגויה. הכרעה בשאלת בעלות במסגרת תביעה שכנגד מכוח סעיף 51(א)(4) לחוק בתי המשפט מהווה מעשה בית דין לכל דבר ועניין, בניגוד להכרעה אגבית מכוח סעיף 76.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'בית משפט השלום רשאי לדון בתביעתו של שמעון, והחלטתו תהא טובה לכל עניין.', true, 'בחירה זו נכונה. סעיף 51(א)(4) לחוק בתי המשפט מקנה לבית משפט השלום סמכות לדון בתביעה שכנגד לבעלות במקרקעין, והכרעתו תהווה מעשה בית דין לכל עניין, שכן התביעות נושאן אחד או נובעות מאותן נסיבות.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'התביעה של ראובן הייתה אמורה להיות מוגשת בבית המשפט המחוזי, ושם היה שמעון רשאי להגיש את תביעתו שכנגד.', false, 'בחירה זו שגויה. תביעה לסילוק יד היא תביעה לחזקה ושימוש במקרקעין, הנתונה לסמכות בית משפט השלום, ללא קשר לשווי המקרקעין (סעיף 51(א)(3) לחוק בתי המשפט).', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'סמכות בתביעת בעלות במקרקעין לא רשומים', 1, 'ראובן הגיש לבית משפט השלום תביעה לסעד הצהרתי כי הוא הבעלים של מקרקעין שאינם רשומים בלשכת רישום המקרקעין, ושווים מוערך ב-1.5 מיליון ש"ח. מה הדין לעניין הסמכות העניינית?',
    'שאלה זו בוחנת את הסמכות העניינית בתביעות הנוגעות למקרקעין שאינם רשומים. היא מתמקדת במחלוקת הפסיקתית לגבי סיווג זכויות אלו כקנייניות או אובליגטוריות, וכיצד סיווג זה משפיע על קביעת הסמכות העניינית לפי מבחן הסעד או השווי.',
    'הפסיקה חלוקה בשאלה האם זכויות במקרקעין שאינן רשומות בלשכת רישום המקרקעין (זכויות אובליגטוריות) נחשבות ל"מקרקעין" לעניין סעיף 51(א)(3) לחוק בתי המשפט. הגישה המסתמנת בפסיקת בית המשפט העליון, כפי שבאה לידי ביטוי בעניין אלוש (Verdict: רע"א 4890/15 אהרן אלוש נ'' עירית טבריה (31.12.2015), Reference 21, 26, 30, 35, 40, 45, 57, 67, 68, 77), היא כי תביעה "הנוגעת למקרקעין" היא תביעה בה מדובר בקיום זכות קניינית או התחייבות להעביר זכות קניינית. לעומת זאת, בתביעה העוסקת בזכות חוזית בלבד במקרקעין, תיקבע הסמכות העניינית לפי שווי התביעה (Verdict: ת"א (מחוזי מרכז) 44936-06-11 פלד לירן נ'' בנק לאומי לישראל בע"מ (22.1.2012), Reference 10; Verdict: ת"א (שלום ת"א) 14486/07 סונווקס אמריקה בע"מ נ'' בנק הפועלים בע"מ (30.7.2007), Reference 66). במקרה הנדון, המקרקעין אינם רשומים, ולכן הזכויות בהם הן אובליגטוריות. מאחר ששווי התביעה (1.5 מיליון ש"ח) אינו עולה על תקרת הסמכות הכספית של בית משפט השלום (2.5 מיליון ש"ח, לפי סעיף 51(א)(2) לחוק בתי המשפט), הסמכות העניינית נתונה לבית משפט השלום (Verdict: ת"א (שלום נצ'') 73-12-19 עומר זועבי נ'' אחמד זועבי (6.5.2020), Reference 68).',
    'הסטודנט עלול לטעות ולחשוב שכל תביעה לבעלות במקרקעין, גם אם אינם רשומים, נתונה אוטומטית לסמכות בית המשפט המחוזי, מבלי להבחין בין זכויות קנייניות לזכויות אובליגטוריות.',
    '["סמכות עניינית", "מקרקעין לא רשומים", "זכויות אובליגטוריות", "מבחן השווי", "סעיף 51(א)(2) לחוק בתי המשפט", "הלכת אלוש"]'::jsonb,
    '**וריאציה 1 — בעלות במקרקעין לא רשומים (שווי נמוך):** תביעה לבעלות במקרקעין לא רשומים בשווי 1.5 מיליון ש"ח. סמכות? ← בית משפט השלום, לפי שווי, כי זו זכות אובליגטורית (רע"א 4890/15 אלוש, רפרנס 21). **וריאציה 2 — בעלות במקרקעין לא רשומים (שווי גבוה):** תביעה לבעלות במקרקעין לא רשומים בשווי 3 מיליון ש"ח. סמכות? ← בית המשפט המחוזי, לפי שווי, כי זו זכות אובליגטורית שחורגת מסמכות השלום (סעיף 51(א)(2) לחוק בתי המשפט). **וריאציה 3 — בעלות במקרקעין רשומים:** תביעה לבעלות במקרקעין רשומים. סמכות? ← בית המשפט המחוזי, כי זו זכות קניינית (סעיף 51(א)(3) לחוק בתי המשפט).',
    'בתביעה לסעד הצהרתי לבעלות במקרקעין שאינם רשומים, הסמכות העניינית נקבעת לפי שווי התביעה, שכן מדובר בזכויות אובליגטוריות. אם השווי אינו עולה על 2.5 מיליון ש"ח, הסמכות לבית משפט השלום (סעיף 51(א)(2) לחוק בתי המשפט והלכת אלוש).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 51(א)(2)", "רע\"א 4890/15 אהרן אלוש נ'' עירית טבריה (31.12.2015)", "ת\"א (מחוזי מרכז) 44936-06-11 פלד לירן נ'' בנק לאומי לישראל בע\"מ (22.1.2012)", "ת\"א (שלום ת\"א) 14486/07 סונווקס אמריקה בע\"מ נ'' בנק הפועלים בע\"מ (30.7.2007)", "ת\"א (שלום נצ'') 73-12-19 עומר זועבי נ'' אחמד זועבי (6.5.2020)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'מבחן הסעד מול מהות הסכסוך במקרקעין בהליכי הסדר', 2, 'ראובן הגיש לבית משפט השלום תביעה לסילוק ידו של שמעון ממקרקעין הנמצאים בהליכי הסדר, בטענה לשמירה על חזקתו. שמעון טוען כי המחלוקת האמיתית היא בשאלת הבעלות על המקרקעין. מה הדין לעניין הסמכות העניינית?',
    'שאלה זו בוחנת את החריג לכלל "מבחן הסעד" בקביעת סמכות עניינית במקרקעין, כאשר מדובר במקרקעין הנמצאים בהליכי הסדר. היא מדגישה את חשיבות "מהות הסכסוך" במקרים אלו, במיוחד כאשר המחלוקת האמיתית היא על בעלות.',
    'ככלל, הסמכות העניינית נקבעת לפי מבחן הסעד המבוקש בכתב התביעה (Verdict: רע"א 3749/12 ששון בר-עוז נ'' דניאל סטר (1.8.2013), Reference 27, 30, 38, 45, 50, 52, 53, 54, 57, 58, 61, 62, 69, 72, 76, 77). תביעה לסילוק יד היא תביעה לחזקה ושימוש במקרקעין, הנתונה לסמכות בית משפט השלום (סעיף 51(א)(3) לחוק בתי המשפט). אולם, הפסיקה קבעה חריג לכלל זה כאשר מדובר במקרקעין הנמצאים בהליכי הסדר. במקרים אלו, הסמכות העניינית אינה נקבעת רק לפי הסעד הפורמלי, אלא לפי מהות התביעה. אם מהותה היא הכרעה בסוגיית הבעלות, הרי שהסמכות אינה נתונה לבית משפט השלום, אלא לבית המשפט המחוזי (Verdict: ת"א (שלום ירושלים) 11269-02-22 אברהים טהה נ'' כמאל טהה (6.3.2022), Reference 1, 2; Verdict: ת"א (שלום נצרת) 12441-06-21 עאיד דיאב נ'' רשות מקרקעי ישראל (9.11.2023), Reference 4, 5; Verdict: ת"א (שלום י-ם) 26584-10-12 יורשי המנוח עבדאללה דרוויש ז"ל נ'' עיסא שוויקי (2.11.2021), Reference 38). זאת, מכיוון שבתביעות אלו, תביעת החזקה או השימוש משמשת לעיתים כ"כסות עיניים" לניסיון להשיג הכרה בבעלות, תוך עקיפת פקיד ההסדר ובית המשפט המחוזי, שלהם הסמכות הבלעדית להכריע בסוגיית הבעלות במקרקעין בהליכי הסדר (Verdict: ת"א (שלום י-ם) 26584-10-12 יורשי המנוח עבדאללה דרוויש ז"ל נ'' עיסא שוויקי (2.11.2021), Reference 38).',
    'הסטודנט עלול ליישם את מבחן הסעד באופן גורף, מבלי להכיר את החריג הספציפי למקרקעין בהליכי הסדר, שבו נבחנת גם מהות הסכסוך.',
    '["סמכות עניינית", "מבחן הסעד", "מהות הסכסוך", "מקרקעין בהליכי הסדר", "בעלות במקרקעין", "סילוק יד"]'::jsonb,
    '**וריאציה 1 — סילוק יד במקרקעין בהליכי הסדר (מהות בעלות):** תביעה לסילוק יד במקרקעין בהליכי הסדר, כשהמחלוקת האמיתית היא בעלות. סמכות? ← בית המשפט המחוזי (ת"א (שלום ירושלים) 11269-02-22 טהה, רפרנס 1, 2). **וריאציה 2 — סילוק יד במקרקעין בהליכי הסדר (מהות חזקה):** תביעה לסילוק יד במקרקעין בהליכי הסדר, כשהמחלוקת היא אכן רק חזקה. סמכות? ← בית משפט השלום (ת"א (שלום י-ם) 26584-10-12 דרוויש, רפרנס 38). **וריאציה 3 — תביעה לחזקה נוגדת:** תביעה לסעד הצהרתי לזכות במקרקעין מסוג ''חזקה נוגדת''. סמכות? ← בית המשפט המחוזי, כי זה גורע מזכות הבעלות (ת"א (שלום נצרת) 12441-06-21 דיאב, רפרנס 4, 5).',
    'במקרקעין הנמצאים בהליכי הסדר, אם תביעה לסילוק יד היא למעשה "כסות עיניים" למחלוקת בעלות, הסמכות העניינית נתונה לבית המשפט המחוזי, ולא לבית משפט השלום, וזאת בניגוד לכלל הרגיל של מבחן הסעד (ת"א (שלום ירושלים) 11269-02-22 טהה).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 51(א)(3)", "ת\"א (שלום ירושלים) 11269-02-22 אברהים טהה נ'' כמאל טהה (6.3.2022)", "ת\"א (שלום נצרת) 12441-06-21 עאיד דיאב נ'' רשות מקרקעי ישראל (9.11.2023)", "ת\"א (שלום י-ם) 26584-10-12 יורשי המנוח עבדאללה דרוויש ז\"ל נ'' עיסא שוויקי (2.11.2021)", "רע\"א 3749/12 ששון בר-עוז נ'' דניאל סטר, פ\"ד סו(1) 678 (2013)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'סמכות נגררת והכרעה אגבית בשאלת בעלות', 3, 'ראובן הגיש לבית משפט השלום תביעה לסילוק ידו של שמעון ממקרקעין. שמעון טוען להגנתו כי הוא הבעלים של המקרקעין. בית משפט השלום נדרש להכריע בשאלת הבעלות לצורך הכרעה בתביעת סילוק היד. מה תוקפה של הכרעה זו בשאלת הבעלות?',
    'שאלה זו עוסקת בסמכות הנגררת (או האגבית) של בית משפט השלום, המעוגנת בסעיף 76 לחוק בתי המשפט. היא בוחנת את היקף סמכות זו, ובפרט את תוקפה של הכרעה בשאלת בעלות במקרקעין כאשר היא ניתנת אגב אורחא לצורך הכרעה בתביעת חזקה ושימוש.',
    'סעיף 76 לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי "כל בית משפט שהוגשה לו תובענה אזרחית מוסמך לדון בכל שאלה המתעוררת אגב אורחא, והנוגעת לעניין שאינו בסמכותו העניינית, ובלבד שההכרעה באותה שאלה דרושה לפתרון הסכסוך" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 76). סמכות זו מכונה "סמכות נגררת" או "סמכות אגבית". כאשר בית משפט השלום דן בתביעת חזקה ושימוש (כמו סילוק יד), והנתבע מעלה טענת בעלות כהגנה, בית משפט השלום מוסמך להכריע בשאלת הבעלות אגב אורחא לצורך ההכרעה בתביעת החזקה. אולם, הכרעה זו תהיה תקפה רק לצורך אותו עניין (תביעת סילוק היד), ולא תהווה מעשה בית דין לעניין הבעלות עצמה (Verdict: ת"א (שלום י-ם) 11269-02-22 אברהים טהה נ'' כמאל טהה (6.3.2022), Reference 1, 3; Verdict: ת"א (שלום י-ם) 26584-10-12 יורשי המנוח עבדאללה דרוויש ז"ל נ'' עיסא שוויקי (2.11.2021), Reference 38; Verdict: ת"א (שלום אש'') 25159-08-22 נדרה יחיאל נ'' משה ברונו בן שלוש (26.2.2025), Reference 61). כלומר, הצדדים לא יהיו מנועים מלהעלות את שאלת הבעלות מחדש בתביעה נפרדת בבית המשפט המחוזי.',
    'הסטודנט עלול לבלבל בין סמכות אגבית (סעיף 76) לבין סמכות לדון בתביעה שכנגד (סעיף 51(א)(4)), ולחשוב שהכרעה אגבית בשאלת בעלות מהווה מעשה בית דין לכל דבר ועניין.',
    '["סמכות נגררת", "סמכות אגבית", "סעיף 76 לחוק בתי המשפט", "מעשה בית דין", "הכרעה אגבית", "תביעת חזקה ושימוש"]'::jsonb,
    '**וריאציה 1 — הכרעה אגבית בבעלות:** בית משפט השלום דן בתביעת סילוק יד וצריך להכריע בבעלות אגב אורחא. מה תוקף הכרעתו? ← תקפה רק לצורך תביעת סילוק היד, לא מעשה בית דין לבעלות (סעיף 76 לחוק בתי המשפט). **וריאציה 2 — סמכות אגבית מול סמכות בתביעה שכנגד:** מה ההבדל בין סמכות אגבית לסמכות בתביעה שכנגד לבעלות? ← הכרעה אגבית אינה מעשה בית דין, הכרעה בתביעה שכנגד כן (ת"א (שלום ת"א) 29135-07-19 קצובר, רפרנס 41). **וריאציה 3 — מטרת הסמכות האגבית:** מדוע קיימת סמכות אגבית? ← למנוע פיצול דיון ולאפשר לבית המשפט להכריע בשאלות נלוות הדרושות לפתרון הסכסוך שבסמכותו (סעיף 76 לחוק בתי המשפט).',
    'כאשר בית משפט השלום נדרש להכריע בשאלת בעלות במקרקעין אגב אורחא לצורך תביעת חזקה ושימוש שבסמכותו, הכרעתו תהיה תקפה רק לצורך אותו עניין ולא תהווה מעשה בית דין לעניין הבעלות עצמה (סעיף 76 לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 76", "ת\"א (שלום ירושלים) 11269-02-22 אברהים טהה נ'' כמאל טהה (6.3.2022)", "ת\"א (שלום י-ם) 26584-10-12 יורשי המנוח עבדאללה דרוויש ז\"ל נ'' עיסא שוויקי (2.11.2021)", "ת\"א (שלום אש'') 25159-08-22 נדרה יחיאל נ'' משה ברונו בן שלוש (26.2.2025)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'סמכות עניינית בתביעה לאכיפת הסכם מכר מקרקעין', 4, 'ראובן הגיש תביעה לאכיפת הסכם מכר מקרקעין, במסגרתה הוא עותר לרישום הבעלות על שמו בלשכת רישום המקרקעין. שווי המקרקעין הוא 2 מיליון ש"ח. לאיזה בית משפט נתונה הסמכות העניינית לדון בתביעה?',
    'שאלה זו עוסקת בסמכות העניינית בתביעות לאכיפת הסכם מכר מקרקעין ורישום בעלות. היא מדגישה את ההבחנה בין תביעות לחזקה ושימוש (בסמכות השלום) לבין תביעות אחרות הנוגעות למקרקעין, ובפרט תביעות לזכויות קנייניות (בסמכות המחוזי).',
    'סעיף 51(א)(3) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי בית משפט השלום מוסמך לדון ב"תביעות בדבר חזקה או שימוש במקרקעין או בדבר חלוקתם או חלוקת השימוש בהם", אך "לא ידון בתביעות בדבר חכירה לדורות ובתביעות אחרות הנוגעות למקרקעין" (Law: חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 51(א)(3)). תביעה לאכיפת הסכם מכר מקרקעין ורישום בעלות נחשבת ל"תביעה אחרת הנוגעת למקרקעין", שכן היא עוסקת בזכות קניינית. לכן, הסמכות לדון בה נתונה לבית המשפט המחוזי מכוח סמכותו השיורית (סעיף 40(1) לחוק בתי המשפט) (Verdict: ת"א (מחוזי ת"א) 70565-03-22 רותם פייס נ'' בנימין זיגדון בע"מ (28.9.2023), Reference 19, 20; Verdict: ת"א (שלום ת"א) 17583-03-25 מטילדה ענב נ'' ויקטור חלילי (29.7.2025), Reference 29; Verdict: ת"א (שלום חד'') 14684-01-24 נחמה זיתוני נ'' שלום דידי (19.3.2024), Reference 22; Verdict: ת"א (מחוזי נצרת) 49826-02-24 גוזיף ספדי נ'' אחסאן אבו עראר (21.5.2024), Reference 31; Verdict: ת"א (שלום עכו) 34181-10-16 עזבון המנוח מוחמד אסדי נ'' סעיד סנעאללה ואח'' (1.3.2018), Reference 59; Verdict: ת"א (שלום ת"א) 9867-09-22 בזק החברה הישראלית לתקשורת בע"מ נ'' רשות מקרקעי ישראל (11.7.2024), Reference 50; Verdict: ת"א (שלום קריות) 15575-05-23 רחמתי נעים נ'' אסתר יצחקי (23.7.2023), Reference 72). שווי המקרקעין אינו רלוונטי לקביעת הסמכות במקרה זה, שכן מדובר בסעד קנייני ולא כספי (Verdict: רע"א 4890/15 אהרן אלוש נ'' עירית טבריה (31.12.2015), Reference 21).',
    'הסטודנט עלול לטעות ולחשוב ששווי המקרקעין הוא הקובע את הסמכות העניינית בתביעות אכיפת הסכם מכר, מבלי להבחין בין סעדים קנייניים לסעדים כספיים או אובליגטוריים.',
    '["סמכות עניינית", "אכיפת הסכם מכר מקרקעין", "רישום בעלות", "זכות קניינית", "סעיף 51(א)(3) לחוק בתי המשפט", "סמכות שיורית"]'::jsonb,
    '**וריאציה 1 — אכיפת הסכם מכר ורישום בעלות:** תביעה לאכיפת הסכם מכר מקרקעין ורישום בעלות. סמכות? ← בית המשפט המחוזי (סעיף 51(א)(3) לחוק בתי המשפט, ת"א (מחוזי ת"א) 70565-03-22 פייס, רפרנס 19). **וריאציה 2 — תביעה לביטול הסכם מכר:** תביעה לביטול הסכם מכר מקרקעין. סמכות? ← בית המשפט המחוזי (ת"א (שלום חד'') 14684-01-24 זיתוני, רפרנס 22). **וריאציה 3 — תביעה כספית בגין הפרת הסכם מכר:** תביעה כספית לפיצויים בגין הפרת הסכם מכר מקרקעין. סמכות? ← בית משפט השלום, אם הסכום אינו עולה על 2.5 מיליון ש"ח (סעיף 51(א)(2) לחוק בתי המשפט).',
    'תביעה לאכיפת הסכם מכר מקרקעין הכוללת עתירה לרישום בעלות על שם התובע, נתונה לסמכותו העניינית של בית המשפט המחוזי, שכן היא נחשבת ל"תביעה אחרת הנוגעת למקרקעין" העוסקת בזכות קניינית, ללא קשר לשווי המקרקעין (סעיף 51(א)(3) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 51(א)(3)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 40(1)", "ת\"א (מחוזי ת\"א) 70565-03-22 רותם פייס נ'' בנימין זיגדון בע\"מ (28.9.2023)", "ת\"א (שלום ת\"א) 17583-03-25 מטילדה ענב נ'' ויקטור חלילי (29.7.2025)", "ת\"א (שלום חד'') 14684-01-24 נחמה זיתוני נ'' שלום דידי (19.3.2024)", "רע\"א 4890/15 אהרן אלוש נ'' עירית טבריה (31.12.2015)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'בית משפט השלום חסר סמכות עניינית לדון בתביעה, שכן סעד הצהרתי לבעלות במקרקעין נתון תמיד לסמכות בית המשפט המחוזי.', false, 'בחירה זו שגויה. אף שסעד הצהרתי לבעלות במקרקעין רשומים נתון למחוזי, במקרקעין לא רשומים יש לבחון את מהות הזכות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'בית משפט השלום מוסמך לדון בתביעה, שכן מדובר בזכויות אובליגטוריות במקרקעין, והסמכות נקבעת לפי שווי התביעה שאינו עולה על סמכותו הכספית.', true, 'בחירה זו נכונה. הפסיקה קבעה כי תביעה לזכויות אובליגטוריות במקרקעין, שאינן רשומות, תיקבע לפי שווי התביעה, ובמקרה זה היא בסמכות השלום.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'בית משפט השלום חסר סמכות עניינית לדון בתביעה, שכן מקרקעין שאינם רשומים נחשבים תמיד ל"תביעות אחרות הנוגעות למקרקעין" בסמכות בית המשפט המחוזי.', false, 'בחירה זו שגויה. קיימת גישה בפסיקה הרואה בזכויות לא רשומות כזכויות אובליגטוריות, ולכן הסמכות נקבעת לפי שווי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'בית משפט השלום מוסמך לדון בתביעה, אך רק אם התובע יוכיח כי אין מחלוקת על עצם הבעלות, אלא רק על היקף הזכויות.', false, 'בחירה זו שגויה. תנאי זה אינו רלוונטי לקביעת הסמכות העניינית במקרקעין לא רשומים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'בית משפט השלום מוסמך לדון בתביעה, שכן מבחן הסעד הוא הקובע, ותביעה לסילוק יד היא תביעת חזקה ושימוש.', false, 'בחירה זו שגויה. אף שמבחן הסעד הוא הכלל, במקרקעין בהליכי הסדר, הפסיקה קבעה חריג לפיו יש לבחון את מהות הסכסוך.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'בית משפט השלום חסר סמכות עניינית לדון בתביעה, שכן במקרקעין בהליכי הסדר, אם מהות הסכסוך היא בעלות, הסמכות נתונה לבית המשפט המחוזי.', true, 'בחירה זו נכונה. במקרקעין בהליכי הסדר, אם מהות הסכסוך היא הכרעה בסוגיית הבעלות, הסמכות אינה נתונה לבית משפט השלום, גם אם הסעד הפורמלי הוא חזקה או שימוש.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'בית משפט השלום מוסמך לדון בתביעה, אך הכרעתו בשאלת הבעלות לא תהווה מעשה בית דין.', false, 'בחירה זו שגויה. במקרה זה, בית משפט השלום חסר סמכות עניינית לדון במהות הסכסוך שהוא בעלות, ולכן לא ידון כלל.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'הסמכות העניינית נתונה לפקיד ההסדר, ולא לבית המשפט.', false, 'בחירה זו שגויה. פקיד ההסדר עוסק ברישום זכויות, אך סכסוכי בעלות נדונים בבית המשפט המחוזי.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'הכרעת בית משפט השלום בשאלת הבעלות תהווה מעשה בית דין לכל דבר ועניין, שכן היא הכרעה מהותית.', false, 'בחירה זו שגויה. הכרעה אגבית בשאלת בעלות מכוח סעיף 76 לחוק בתי המשפט אינה מהווה מעשה בית דין לעניין הבעלות עצמה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'הכרעת בית משפט השלום בשאלת הבעלות תהיה תקפה רק לצורך תביעת סילוק היד, ולא תהווה מעשה בית דין לעניין הבעלות עצמה.', true, 'בחירה זו נכונה. סעיף 76 לחוק בתי המשפט מקנה סמכות אגבית לבית משפט השלום להכריע בשאלת בעלות לצורך ההליך שבסמכותו, אך הכרעה זו אינה מהווה מעשה בית דין.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בית משפט השלום חסר סמכות לדון בשאלת הבעלות, ועליו להעביר את התיק לבית המשפט המחוזי.', false, 'בחירה זו שגויה. בית משפט השלום מוסמך לדון בשאלת הבעלות אגב אורחא מכוח סמכותו הנגררת (סעיף 76 לחוק בתי המשפט).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'בית משפט השלום מוסמך לדון בשאלת הבעלות רק אם שווי המקרקעין אינו עולה על סמכותו הכספית.', false, 'בחירה זו שגויה. סמכות אגבית אינה תלויה בשווי, והיא נועדה לאפשר לבית המשפט להכריע בשאלות נלוות לצורך ההליך העיקרי שבסמכותו.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'לבית משפט השלום, שכן שווי המקרקעין אינו עולה על סמכותו הכספית.', false, 'בחירה זו שגויה. תביעה לאכיפת הסכם מכר מקרקעין ורישום בעלות היא תביעה לזכות קניינית, הנתונה לסמכות בית המשפט המחוזי, ללא קשר לשווי.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'לבית המשפט המחוזי, שכן מדובר בתביעה לאכיפת זכות קניינית במקרקעין.', true, 'בחירה זו נכונה. תביעה לאכיפת הסכם מכר מקרקעין ורישום בעלות נחשבת ל"תביעה אחרת הנוגעת למקרקעין" הנתונה לסמכותו השיורית של בית המשפט המחוזי.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'לבית משפט השלום, שכן הסעד המבוקש הוא אכיפת חוזה, וזו אינה תביעה ל"חזקה או שימוש".', false, 'בחירה זו שגויה. אף שזו אינה תביעת חזקה או שימוש, אכיפת הסכם מכר מקרקעין ורישום בעלות היא תביעה לזכות קניינית, הנתונה למחוזי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'לבית המשפט המחוזי, אך רק אם שווי המקרקעין עולה על 2.5 מיליון ש"ח.', false, 'בחירה זו שגויה. בתביעות לזכויות קנייניות במקרקעין, הסמכות נקבעת לפי מהות הסעד ולא לפי שווי.', 4);

END $$;

-- ============================================================
-- Q42 — 2019-S-Q42 — chapter=execution subtopic=file_opening
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q42';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q42 skipped: external_id % already exists', '2019-S-Q42';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'file_opening';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'file_opening';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q42', 'b3904dc7-882d-48fc-9f3c-ba89fc453003', v_subtopic_id,
    'גדעון הוא חייב שתלויים ועומדים נגדו כמה תיקים בהוצאה לפועל. גדעון הוכרז חייב מוגבל באמצעים. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 42}'::jsonb,
    'השאלה עוסקת במעמדו של חייב שהוכרז ''מוגבל באמצעים'' ובהשלכות הכרזה זו על הליכי איחוד תיקים. היא בוחנת את הוראת סעיף 69ו לחוק ההוצאה לפועל, הקובעת חובה על רשם ההוצאה לפועל לאחד תיקים של חייב מוגבל באמצעים, תוך ויתור על דרישות כספיות מסוימות החלות על איחוד תיקים רגיל.',
    'סעיף 69ו(א) לחוק ההוצאה לפועל, תשכ"ז-1967, קובע כי "הוכרז חייב כמוגבל באמצעים, והיו תלויים ועומדים נגדו מספר תיקים, יתן רשם ההוצאה לפועל צו לאיחוד התיקים, לפי פרק ז''3, בשינויים המחויבים, אף אם לא נתקיימו ההוראות שבסעיפים 74ו ו-74ט" (Law: חוק ההוצאה לפועל, תשכ"ז-1967, סעיף 69ו(א)). הוראות סעיפים 74ו ו-74ט מתייחסות לדרישות כספיות שחייב המבקש איחוד תיקים נדרש לעמוד בהן, כגון יכולת לפרוע את החובות תוך פרקי זמן מרביים ותשלום אחוז מסוים מיתרת החוב (Verdict: ע"א 2097/02 איטונג בע"מ נ'' פואד חדיד, נז(4) 211 (2003), Reference 5, 6). מאחר שחייב מוגבל באמצעים אינו יכול לקיים דרישות אלו, המחוקק קבע כי במקרה זה, רשם ההוצאה לפועל חייב לתת צו לאיחוד התיקים, גם ללא עמידה בתנאים הכספיים הללו (Verdict: ע"א 2097/02 איטונג בע"מ נ'' פואד חדיד, נז(4) 211 (2003), Reference 5, 6; Literature: דוד בר-אופיר, הוצאה לפועל הליכים והלכות - כרך ב (2025) | 201. ריבוי תיקים של חייב מוגבל באמצעים - צו איחוד תיקים (סעיף 69ו לחוק), עמ'' 9).',
    'הסטודנט עלול לטעות ולחשוב שתנאי איחוד תיקים רגילים חלים גם על חייב מוגבל באמצעים, או שמתן צו האיחוד נתון לשיקול דעתו של הרשם, מבלי להבחין בין סוגי החייבים וההוראות הספציפיות החלות עליהם.',
    '["חייב מוגבל באמצעים", "איחוד תיקים", "חוק ההוצאה לפועל", "סעיף 69ו", "סעיף 74ו", "סעיף 74ט"]'::jsonb,
    '**וריאציה 1 — חובת איחוד תיקים:** האם רשם ההוצאה לפועל חייב לאחד תיקים של חייב מוגבל באמצעים? ← כן, סעיף 69ו(א) לחוק ההוצאה לפועל קובע ''ייתן''. **וריאציה 2 — תנאים כספיים:** האם חייב מוגבל באמצעים צריך לעמוד בתנאים הכספיים הרגילים לאיחוד תיקים? ← לא, סעיף 69ו(א) פוטר אותו מכך (ע"א 2097/02 איטונג, רפרנס 5, 6). **וריאציה 3 — תיק נוסף:** אם נפתח תיק נוסף נגד חייב מוגבל באמצעים, האם הוא יצורף לצו האיחוד? ← כן, זו הוראה מחייבת ואין לרשם שיקול דעת בעניין (דוד בר-אופיר, הוצאה לפועל הליכים והלכות, עמ'' 9).',
    'רשם ההוצאה לפועל חייב לתת צו לאיחוד תיקים לחייב שהוכרז מוגבל באמצעים, גם אם החייב אינו עומד בדרישות הכספיות הרגילות לאיחוד תיקים הקבועות בסעיפים 74ו ו-74ט לחוק ההוצאה לפועל (סעיף 69ו(א) לחוק).',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 69ו(א)", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 74ו", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 74ט", "ע\"א 2097/02 איטונג בע\"מ נ'' פואד חדיד, נז(4) 211 (2003)", "דוד בר-אופיר, הוצאה לפועל הליכים והלכות - כרך ב (2025) | 201. ריבוי תיקים של חייב מוגבל באמצעים - צו איחוד תיקים (סעיף 69ו לחוק), עמ'' 9"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'גדעון רשאי לבקש את איחודם של כל התיקים, ורשם ההוצאה לפועל רשאי להיעתר לבקשה רק אם מתקיימים כל התנאים הקבועים בחוק לצורך איחוד התיקים.', false, 'בחירה זו שגויה. במקרה של חייב מוגבל באמצעים, רשם ההוצאה לפועל חייב לאחד את התיקים, ואינו רשאי רק להיעתר לבקשה, וזאת גם אם לא מתקיימים כל התנאים הכספיים הרגילים לאיחוד תיקים.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'הזוכים רשאים לבקש את איחודם של כל התיקים, ורשם ההוצאה לפועל רשאי להיעתר לבקשה רק אם מתקיימים כל התנאים הקבועים בחוק לצורך איחוד התיקים.', false, 'בחירה זו שגויה. איחוד תיקים הוא הליך המיועד בעיקר לחייב, ורשם ההוצאה לפועל חייב לאחד תיקים של חייב מוגבל באמצעים, ללא תלות בבקשת הזוכים או בעמידה בכל התנאים הכספיים הרגילים.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'רשם ההוצאה לפועל רשאי לתת צו לאיחוד התיקים מיוזמתו רק אם מתקיימים כל התנאים הקבועים בחוק לצורך איחוד התיקים.', false, 'בחירה זו שגויה. רשם ההוצאה לפועל חייב לתת צו לאיחוד תיקים לחייב מוגבל באמצעים, וזאת גם אם לא מתקיימים התנאים הכספיים הרגילים לאיחוד תיקים.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'רשם ההוצאה לפועל חייב לתת צו לאיחוד התיקים גם אם לא מתקיימים תנאים מסוימים הקבועים בחוק לצורך איחוד התיקים.', true, 'בחירה זו נכונה. סעיף 69ו(א) לחוק ההוצאה לפועל קובע כי משמוכרז חייב כמוגבל באמצעים, רשם ההוצאה לפועל ''ייתן'' צו לאיחוד תיקיו, ''אף אם לא נתקיימו ההוראות שבסעיפים 74ו ו-74ט'', שהן דרישות כספיות.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'ביטול איחוד תיקים של חייב מוגבל באמצעים', 1, 'גדעון, חייב מוגבל באמצעים שתיקיו אוחדו, לא עמד בתשלומי צו האיחוד שנקבעו לו. האם רשם ההוצאה לפועל רשאי לבטל את צו האיחוד?',
    'שאלה זו בוחנת את סמכותו של רשם ההוצאה לפועל לבטל צו איחוד תיקים שניתן לחייב מוגבל באמצעים, במקרה של אי עמידה בתנאי הצו. היא מדגישה את ההבחנה בין דרישות כספיות ראשוניות (שנמנעות מחייב מוגבל באמצעים) לבין דרישות התנהגותיות ועמידה בתשלומים שוטפים.',
    'הלכת בית המשפט העליון בעניין ע"א 2097/02 איטונג בע"מ נ'' פואד חדיד קבעה כי אף שחייבים מוגבלים באמצעים פטורים מדרישות כספיות מסוימות לצורך איחוד תיקים (סעיפים 74ו ו-74ט לחוק ההוצאה לפועל), אין כל בסיס להבחנה בינם לבין חייבים אחרים בכל הנוגע לדרישות ההתנהגותיות המוטלות על חייב שניתן צו איחוד לתיקיו (Verdict: ע"א 2097/02 איטונג בע"מ נ'' פואד חדיד, נז(4) 211 (2003), Reference 2, 6). צו האיחוד הוא הטבה המותנית ב"מחיר" התנהגותי מסוים, ואין סיבה שלא לדרוש זאת אף מחייבים מוגבלים באמצעים (Verdict: ע"א 2097/02 איטונג בע"מ נ'' פואד חדיד, נז(4) 211 (2003), Reference 2, 6). לפיכך, רשם ההוצאה לפועל מוסמך לבטל צו איחוד תיקים של חייב מוגבל באמצעים אם החייב אינו עומד בדרישות ההתנהגותיות הקבועות בחוק, לרבות אי עמידה בתנאי התשלום שנקבעו (Verdict: ע"א 2097/02 איטונג בע"מ נ'' פואד חדיד, נז(4) 211 (2003), Reference 2, 6; Literature: דוד בר-אופיר, הוצאה לפועל הליכים והלכות - כרך ב (2025) | 213. ביטול הצו - מעמדו של חייב מוגבל באמצעים (סעיף 74טו לחוק), עמ'' 16).',
    'הסטודנט עלול לטעות ולחשוב שהכרזה כחייב מוגבל באמצעים מעניקה חסינות מוחלטת מפני ביטול צו איחוד, מבלי להבחין בין תנאים כספיים לתנאים התנהגותיים.',
    '["חייב מוגבל באמצעים", "איחוד תיקים", "ביטול צו איחוד", "דרישות התנהגותיות", "חוק ההוצאה לפועל", "סעיף 74טו"]'::jsonb,
    '**וריאציה 1 — אי עמידה בתשלומים:** חייב מוגבל באמצעים לא עמד בתשלומי צו האיחוד. האם ניתן לבטל את הצו? ← כן, רשם ההוצאה לפועל רשאי לבטל את הצו (ע"א 2097/02 איטונג, רפרנס 2, 6). **וריאציה 2 — דרישות התנהגותיות:** האם חייב מוגבל באמצעים פטור מדרישות התנהגותיות? ← לא, הוא כפוף לדרישות אלו כמו כל חייב אחר (ע"א 2097/02 איטונג, רפרנס 2, 6). **וריאציה 3 — מעמד החייב לאחר ביטול הצו:** אם צו האיחוד בוטל, האם החייב נותר מוגבל באמצעים? ← כן, החייב נותר מוגבל באמצעים למרות ביטול צו האיחוד (דוד בר-אופיר, הוצאה לפועל הליכים והלכות, עמ'' 16).',
    'רשם ההוצאה לפועל מוסמך לבטל צו איחוד תיקים של חייב מוגבל באמצעים אם החייב אינו עומד בדרישות ההתנהגותיות הקבועות בחוק, לרבות תנאי התשלום, שכן הטבת האיחוד מותנית בעמידה בדרישות אלו (ע"א 2097/02 איטונג).',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 74טו", "ע\"א 2097/02 איטונג בע\"מ נ'' פואד חדיד, נז(4) 211 (2003)", "דוד בר-אופיר, הוצאה לפועל הליכים והלכות - כרך ב (2025) | 213. ביטול הצו - מעמדו של חייב מוגבל באמצעים (סעיף 74טו לחוק), עמ'' 16"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'תכליות חוק ההוצאה לפועל ואיזונן', 2, 'מהן שתי התכליות העיקריות העומדות בבסיס חוק ההוצאה לפועל, וכיצד הן באות לידי ביטוי בהליכי איחוד תיקים והכרזה על חייב מוגבל באמצעים?',
    'שאלה זו עוסקת בתכליות המנחות את חוק ההוצאה לפועל, כפי שפורשו בפסיקה, ובאופן שבו תכליות אלו משפיעות על הליכי איחוד תיקים והכרזה על חייב מוגבל באמצעים. היא מדגישה את הצורך באיזון בין אינטרסים מנוגדים של זוכים וחייבים.',
    'בית המשפט העליון קבע בעניין ע"א 2097/02 איטונג בע"מ נ'' פואד חדיד כי בבסיס חוק ההוצאה לפועל עומדות שתי תכליות עיקריות: האחת, יצירת מנגנון לגביית חובות ומימוש פסקי דין ביעילות ובזריזות; והשנייה, הגנה על חייבים שמצבם הכלכלי אינו מאפשר להם לפרוע את חובותיהם, כדי למנוע מהם להפוך לחסרי כל ולנטל על החברה (Verdict: ע"א 2097/02 איטונג בע"מ נ'' פואד חדיד, נז(4) 211 (2003), Reference 1, 9). בין שתי תכליות אלו קיים מתח מתמיד, ולכן יש צורך לאזן ביניהן, תוך מתן משקל נכבד לאינטרס של הזוכה בביצוע פסק הדין (Verdict: ע"א 2097/02 איטונג בע"מ נ'' פואד חדיד, נז(4) 211 (2003), Reference 1, 9). הליכי איחוד תיקים והכרזה על חייב מוגבל באמצעים נועדו ליתן פתרון למצוקת חייב עם מספר נושים, ולאפשר גבייה קולקטיבית תוך התחשבות ביכולתו הכלכלית, ובכך לשרת את שתי התכליות (Verdict: ע"א 2097/02 איטונג בע"מ נ'' פואד חדיד, נז(4) 211 (2003), Reference 1, 9; Literature: דוד בר-אופיר, הוצאה לפועל הליכים והלכות - כרך ב (2025) | 197. הכרזה על חייב מוגבל באמצעים (סעיף 69ג לחוק), עמ'' 3).',
    'הסטודנט עלול לטעות ולחשוב שיש להעדיף תכלית אחת על פני השנייה באופן מוחלט, במקום להבין את הצורך באיזון בין התכליות המנוגדות.',
    '["תכליות חוק ההוצאה לפועל", "איזון אינטרסים", "גביית חובות", "הגנה על חייבים", "חייב מוגבל באמצעים", "איחוד תיקים"]'::jsonb,
    '**וריאציה 1 — תכליות החוק:** מהן שתי התכליות העיקריות של חוק ההוצאה לפועל? ← גבייה יעילה לזוכים והגנה על חייבים במצוקה (ע"א 2097/02 איטונג, רפרנס 1). **וריאציה 2 — איזון תכליות:** כיצד מאזנים בין התכליות? ← מתן משקל נכבד לאינטרס הזוכה (ע"א 2097/02 איטונג, רפרנס 1). **וריאציה 3 — תכלית איחוד תיקים:** כיצד איחוד תיקים משרת את התכליות? ← מאפשר גבייה קולקטיבית תוך התחשבות ביכולת החייב, ובכך מגן עליו ומייעל את הגבייה (בר"ע (מחוזי תל אביב-יפו) 1562/06 החברה הדרומית לשיווק בע"מ נ'' ליאור פחימה, רפרנס 13).',
    'חוק ההוצאה לפועל מאזן בין תכלית גביית חובות יעילה לזוכים לבין הגנה על חייבים במצוקה כלכלית. בהליכי איחוד תיקים והכרזה על חייב מוגבל באמצעים, יש לאזן בין תכליות אלו תוך מתן משקל נכבד לאינטרס הזוכה (ע"א 2097/02 איטונג).',
    '["ע\"א 2097/02 איטונג בע\"מ נ'' פואד חדיד, נז(4) 211 (2003)", "דוד בר-אופיר, הוצאה לפועל הליכים והלכות - כרך ב (2025) | 197. הכרזה על חייב מוגבל באמצעים (סעיף 69ג לחוק), עמ'' 3", "בר\"ע (מחוזי תל אביב-יפו) 1562/06 החברה הדרומית לשיווק בע\"מ נ'' ליאור פחימה (24.6.2008)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'איחוד תיקים לאחר חוק חדלות פירעון', 3, 'לאחר כניסתו לתוקף של חוק חדלות פירעון ושיקום כלכלי (ספטמבר 2019), ראובן, חייב חדש שאין באפשרותו לפרוע את חובותיו, מבקש להכריז עליו מוגבל באמצעים ולאחד את תיקיו. מה הדין?',
    'שאלה זו עוסקת בשינוי המהותי שחל בדיני ההוצאה לפועל עם כניסתו לתוקף של חוק חדלות פירעון ושיקום כלכלי, ובפרט בביטול האפשרות להכריז על חייבים חדשים כמוגבלים באמצעים. היא מדגישה את המעבר להליכי חדלות פירעון כפתרון קולקטיבי לחייבים.',
    'סעיף 69י1 לחוק ההוצאה לפועל, תשכ"ז-1967, קובע במפורש כי "מיום התחילה של חוק חדלות פירעון ושיקום כלכלי, לא יוכרז חייב מוגבל באמצעים לפי סימן זה" (Law: חוק ההוצאה לפועל, תשכ"ז-1967, סעיף 69י1). חוק חדלות פירעון ושיקום כלכלי נכנס לתוקף בספטמבר 2019. משמעות הדבר היא שלא ניתן עוד להכריז על חייב חדש כמוגבל באמצעים ולאחד את תיקיו מכוח חוק ההוצאה לפועל (Verdict: רער"צ (שלום עכו) 5809-09-21 ג''מינה מוסא נ'' גל בדארנה בע"מ (10.4.2022), Reference 11; Verdict: רער"צ (שלום ת"א) 22248-08-19 אילן פז אביטן נ'' אפרים אפי מלכה (6.10.2020), Reference 7, 12). המצב הנורמטיבי החדש מכוון חייבים שאינם יכולים לפרוע את חובותיהם לפנות להליך הקולקטיבי היחיד שנותר עבורם, והוא הליך חדלות פירעון (Verdict: רער"צ (שלום עכו) 5809-09-21 ג''מינה מוסא נ'' גל בדארנה בע"מ (10.4.2022), Reference 11).',
    'הסטודנט עלול לטעות וליישם את הדין הישן לגבי הכרזה על חייב מוגבל באמצעים, מבלי להתחשב בשינוי שחל עם כניסתו לתוקף של חוק חדלות פירעון ושיקום כלכלי.',
    '["חוק חדלות פירעון ושיקום כלכלי", "חייב מוגבל באמצעים", "איחוד תיקים", "סעיף 69י1 לחוק ההוצאה לפועל", "שינוי חקיקה", "הליכי חדלות פירעון"]'::jsonb,
    '**וריאציה 1 — בקשה להכרזה לאחר 2019:** חייב מבקש להכריז עליו מוגבל באמצעים ב-2020. האם אפשרי? ← לא, סעיף 69י1 לחוק ההוצאה לפועל ביטל זאת (רער"צ (שלום עכו) 5809-09-21 מוסא, רפרנס 11). **וריאציה 2 — חייבים שהוכרזו לפני 2019:** מה דינם של חייבים שהוכרזו מוגבלים באמצעים לפני ספטמבר 2019? ← הם ממשיכים להתנהל ככאלה, כל עוד עומדים בצו התשלומים (רער"צ (שלום ת"א) 38953-12-21 פינטו, רפרנס 12). **וריאציה 3 — חלופה לחייבים חדשים:** מהי החלופה לחייבים חדשים שאינם יכולים לפרוע חובותיהם? ← לפנות להליכי חדלות פירעון (רער"צ (שלום עכו) 5809-09-21 מוסא, רפרנס 11).',
    'לאחר כניסתו לתוקף של חוק חדלות פירעון ושיקום כלכלי (ספטמבר 2019), לא ניתן עוד להכריז על חייב חדש כמוגבל באמצעים ולאחד את תיקיו, אלא עליו לפנות להליכי חדלות פירעון (סעיף 69י1 לחוק ההוצאה לפועל).',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 69י1", "רער\"צ (שלום עכו) 5809-09-21 ג''מינה מוסא נ'' גל בדארנה בע\"מ (10.4.2022)", "רער\"צ (שלום ת\"א) 22248-08-19 אילן פז אביטן נ'' אפרים אפי מלכה (6.10.2020)", "רער\"צ (שלום ת\"א) 38953-12-21 דוד אריאל פינטו נ'' בנק מזרחי טפחות בע\"מ (27.3.2022)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'הגבלות על חייב מוגבל באמצעים', 4, 'גדעון הוכרז חייב מוגבל באמצעים. אילו הגבלות רשאי רשם ההוצאה לפועל להטיל עליו?',
    'שאלה זו בוחנת את ההגבלות שרשם ההוצאה לפועל רשאי להטיל על חייב שהוכרז מוגבל באמצעים. היא מתמקדת בסעיף 69ד לחוק ההוצאה לפועל, המפרט את מגוון ההגבלות שנועדו להבטיח את פירעון החוב ולמנוע יצירת חובות נוספים.',
    'סעיף 69ד(א) לחוק ההוצאה לפועל, תשכ"ז-1967, מפרט את ההגבלות שרשם ההוצאה לפועל רשאי להטיל על חייב שהוכרז מוגבל באמצעים. הגבלות אלו כוללות: (1) עיכוב יציאתו של החייב מן הארץ; (2) הגבלת החייב כלקוח מוגבל מיוחד, כמשמעותו בחוק שיקים ללא כיסוי; (3) הגבלת החייב מלעשות שימוש בכרטיס חיוב (Law: חוק ההוצאה לפועל, תשכ"ז-1967, סעיף 69ד(א)). בנוסף, סעיף 69ד(ב) קובע כי חייב מוגבל באמצעים לא ייסד תאגיד ולא יהיה בעל עניין בתאגיד, אלא באישור רשם ההוצאה לפועל (Law: חוק ההוצאה לפועל, תשכ"ז-1967, סעיף 69ד(ב)). הגבלות אלו נועדו להבטיח את פירעון החוב ולמנוע יצירת חובות נוספים, והן נרשמות במרשם חייבים מוגבלים באמצעים הפתוח לעיון הציבור (Literature: דוד בר-אופיר, הוצאה לפועל הליכים והלכות - כרך ב (2025) | 199. מרשם חייבים מוגבלים באמצעים (סעיף 69ה לחוק), עמ'' 6).',
    'הסטודנט עלול לבלבל בין הגבלות ספציפיות לחייב מוגבל באמצעים לבין הליכי גבייה כלליים בהוצאה לפועל, או לכלול הגבלות שאינן מנויות בחוק.',
    '["חייב מוגבל באמצעים", "הגבלות", "עיכוב יציאה מן הארץ", "לקוח מוגבל מיוחד", "כרטיס חיוב", "סעיף 69ד לחוק ההוצאה לפועל"]'::jsonb,
    '**וריאציה 1 — הגבלות עיקריות:** אילו הגבלות עיקריות ניתן להטיל על חייב מוגבל באמצעים? ← עיכוב יציאה מהארץ, לקוח מוגבל מיוחד, הגבלה על שימוש בכרטיס חיוב (סעיף 69ד(א) לחוק ההוצאה לפועל). **וריאציה 2 — הגבלות נוספות:** האם יש הגבלות נוספות? ← כן, איסור על ייסוד תאגיד או היותו בעל עניין בתאגיד ללא אישור (סעיף 69ד(ב) לחוק ההוצאה לפועל). **וריאציה 3 — מטרת ההגבלות:** מהי מטרת ההגבלות הללו? ← להבטיח את פירעון החוב ולמנוע יצירת חובות נוספים (סעיף 69ד(א) לחוק ההוצאה לפועל).',
    'רשם ההוצאה לפועל רשאי להטיל על חייב שהוכרז מוגבל באמצעים הגבלות שונות, כגון עיכוב יציאה מן הארץ, הגבלתו כלקוח מוגבל מיוחד, והגבלתו מלעשות שימוש בכרטיס חיוב, וכן איסור על ייסוד תאגיד או היותו בעל עניין בו (סעיף 69ד לחוק ההוצאה לפועל).',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 69ד", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 69ה", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 69ח", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 69ט", "דוד בר-אופיר, הוצאה לפועל הליכים והלכות - כרך ב (2025) | 199. מרשם חייבים מוגבלים באמצעים (סעיף 69ה לחוק), עמ'' 6"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'לא, מרגע שחייב הוכרז מוגבל באמצעים ותיקיו אוחדו, לא ניתן לבטל את צו האיחוד כל עוד הוא נותר מוגבל באמצעים.', false, 'בחירה זו שגויה. אף שחייב מוגבל באמצעים נהנה מהקלות מסוימות, הוא עדיין כפוף לדרישות התנהגותיות, ואי עמידה בהן עלולה להוביל לביטול צו האיחוד.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'כן, רשם ההוצאה לפועל מוסמך לבטל צו איחוד של חייב מוגבל באמצעים אם החייב אינו עומד בדרישות ההתנהגותיות הקבועות בחוק, לרבות תנאי התשלום.', true, 'בחירה זו נכונה. הפסיקה קבעה כי רשם ההוצאה לפועל רשאי לבטל צו איחוד של חייב מוגבל באמצעים אם החייב אינו עומד בדרישות ההתנהגותיות, כגון אי עמידה בתשלומי הצו (ע"א 2097/02 איטונג בע"מ נ'' חדיד, פסקאות 223ה-ו, 224ג-ד).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'כן, אך רק אם הזוכים הוכיחו כי החייב פעל בחוסר תום לב וניסה לסכל את ביצוע צו האיחוד.', false, 'בחירה זו שגויה. חוסר תום לב הוא עילה אפשרית לביטול, אך אי עמידה בתנאי התשלום לבדה מספיקה לביטול, גם ללא הוכחת חוסר תום לב מובהק.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לא, אלא אם כן חל שינוי יסודי במצבו הכלכלי של החייב המצדיק את ביטול ההכרזה כמוגבל באמצעים.', false, 'בחירה זו שגויה. שינוי נסיבות יכול להוביל לביטול, אך אי עמידה בתשלומים היא עילה עצמאית לביטול צו האיחוד, גם אם החייב נותר מוגבל באמצעים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'התכלית האחת היא גבייה יעילה של חובות לזוכים, והשנייה היא הגנה על חייבים במצוקה כלכלית. בהליכי איחוד תיקים והכרזה על חייב מוגבל באמצעים, יש לאזן בין תכליות אלו תוך מתן משקל נכבד לאינטרס הזוכה.', true, 'בחירה זו נכונה. בית המשפט העליון קבע כי חוק ההוצאה לפועל מאזן בין שתי תכליות אלו, וכי במסגרת האיזון יינתן משקל נכבד לאינטרס הזוכה (ע"א 2097/02 איטונג בע"מ נ'' חדיד, פסקאות 216ב-ג, 216ה-ו, 216ז).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'התכלית האחת היא גבייה יעילה של חובות לזוכים, והשנייה היא שיקום כלכלי של חייבים. בהליכים אלו, התכלית העיקרית היא שיקום החייב, וגביית החובות כפופה לה.', false, 'בחירה זו שגויה. אף ששיקום כלכלי הוא תכלית חשובה, במיוחד בחוק חדלות פירעון, חוק ההוצאה לפועל נותן משקל נכבד לאינטרס הזוכה, ואינו כפוף באופן מוחלט לשיקום החייב.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'התכלית האחת היא מניעת סרבול מערכת ההוצאה לפועל, והשנייה היא אחידות הדין. הליכים אלו נועדו לייעל את המערכת ולמנוע פיצול דיונים.', false, 'בחירה זו שגויה. אף שיעילות המערכת היא תוצאה רצויה, היא אינה התכלית העיקרית של החוק, והתכליות המרכזיות נוגעות ליחסי זוכה-חייב.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'התכלית האחת היא הגנה על קניינם של הזוכים, והשנייה היא הגנה על כבוד האדם וחירותו של החייב. בהליכים אלו, יש להעדיף תמיד את כבוד האדם וחירותו של החייב.', false, 'בחירה זו שגויה. אף שאלו תכליות כלליות התומכות בתכליות המיוחדות של החוק, אין העדפה מוחלטת של כבוד החייב, אלא איזון בין הזכויות (ע"א 2097/02 איטונג בע"מ נ'' חדיד, פסקאות 216ז, 217).', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'רשם ההוצאה לפועל חייב להכריז עליו מוגבל באמצעים ולאחד את תיקיו, שכן זו זכותו של חייב במצוקה כלכלית.', false, 'בחירה זו שגויה. עם כניסתו לתוקף של חוק חדלות פירעון, בוטלה האפשרות להכריז על חייבים חדשים כמוגבלים באמצעים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'לא ניתן להכריז על ראובן כמוגבל באמצעים ולאחד את תיקיו, שכן מוסד זה בוטל עם כניסתו לתוקף של חוק חדלות פירעון ושיקום כלכלי, והוא צריך לפנות להליכי חדלות פירעון.', true, 'בחירה זו נכונה. סעיף 69י1 לחוק ההוצאה לפועל קובע כי מיום תחילתו של חוק חדלות פירעון, לא יוכרז חייב מוגבל באמצעים לפי סימן זה (רער"צ (שלום עכו) 5809-09-21 ג''מינה מוסא נ'' גל בדארנה בע"מ, פסקה 15).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'רשם ההוצאה לפועל רשאי להכריז עליו מוגבל באמצעים ולאחד את תיקיו, אך רק אם סכום חובותיו אינו עולה על 150,000 ש"ח.', false, 'בחירה זו שגויה. הגבלת הסכום ל-150,000 ש"ח רלוונטית להליכי חדלות פירעון מסוימים, אך לא משנה את העובדה שלא ניתן עוד להכריז על חייב חדש כמוגבל באמצעים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'הכרזה על חייב מוגבל באמצעים ואיחוד תיקים אפשריים רק אם כל הזוכים מסכימים לכך.', false, 'בחירה זו שגויה. הסכמת הזוכים אינה תנאי להכרזה על חייב מוגבל באמצעים או לאיחוד תיקיו, ובכל מקרה, מוסד זה בוטל עבור חייבים חדשים.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'עיכוב יציאה מן הארץ, הגבלתו כלקוח מוגבל מיוחד, והגבלתו מלעשות שימוש בכרטיס חיוב.', true, 'בחירה זו נכונה. סעיף 69ד(א) לחוק ההוצאה לפועל מפרט הגבלות אלו שרשם ההוצאה לפועל רשאי להטיל על חייב מוגבל באמצעים.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'מאסר, עיקול נכסים, ומינוי כונס נכסים.', false, 'בחירה זו שגויה. אלו הליכי גבייה כלליים בהוצאה לפועל, אך אינם הגבלות ספציפיות המוטלות על חייב מוגבל באמצעים מכוח סעיף 69ד.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'איסור על הקמת תאגיד או היותו בעל עניין בתאגיד, ואיסור על קבלת אשראי מבנקים.', false, 'בחירה זו שגויה חלקית. איסור על הקמת תאגיד הוא הגבלה נכונה (סעיף 69ד(ב)), אך איסור על קבלת אשראי מבנקים אינו מנוי במפורש בסעיף זה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'הגבלתו מלהיות מיוצג על ידי עורך דין, ואיסור על הגשת בקשות נוספות לבית המשפט.', false, 'בחירה זו שגויה. הגבלות אלו פוגעות בזכויות יסוד ואינן נמנות עם ההגבלות שרשם ההוצאה לפועל רשאי להטיל על חייב מוגבל באמצעים.', 4);

END $$;

-- ============================================================
-- Q43 — 2019-S-Q43 — chapter=execution subtopic=exit_ban
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q43';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q43 skipped: external_id % already exists', '2019-S-Q43';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'exit_ban';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'exit_ban';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q43', 'b3904dc7-882d-48fc-9f3c-ba89fc453003', v_subtopic_id,
    'רשם ההוצאה לפועל התרשם כי מוחמד הוא חייב בעל יכולת המשתמט מתשלום חובותיו. לאחר ששקל את השיקולים הרלוונטיים כדין החליט רשם ההוצאה לפועל להטיל על מוחמד מגבלה של עיכוב יציאה מן הארץ. ההחלטה התקבלה בנוכחותו של מוחמד, ומוחמד לא פרע את החוב. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 43}'::jsonb,
    'השאלה עוסקת במועד כניסתן לתוקף של הגבלות המוטלות על חייב בהוצאה לפועל, ובפרט במקרה שבו ההחלטה על הטלת ההגבלה ניתנה במעמד החייב. היא מתמקדת בהוראת סעיף 66ג(ג) לחוק ההוצאה לפועל, המבחינה בין מקרים שבהם נדרשת המצאת התראה לבין מקרים שבהם החייב נוכח בעת הטלת ההגבלה.',
    'סעיף 66ג לחוק ההוצאה לפועל, תשכ"ז-1967, קובע את מועד כניסתן לתוקף של הגבלות המוטלות על חייב. ככלל, לפי סעיף 66ג(א), הגבלה תיכנס לתוקף בחלוף 30 ימים מיום המצאת ההתראה לחייב (Law: חוק ההוצאה לפועל, תשכ"ז-1967, סעיף 66ג(א)). אולם, סעיף 66ג(ג) קובע חריג לכלל זה: "על אף האמור בסעיפים קטנים (א) ו-(ב), הטיל רשם ההוצאה לפועל הגבלה במעמד החייב כאמור בסעיף 66ב(א)(1), לא תישלח לחייב התראה, וההגבלה תיכנס לתוקף בתום 30 ימים מיום הטלת ההגבלה, אלא אם כן ייפרע החוב או שתינתן החלטה אחרת בידי רשם ההוצאה לפועל" (Law: חוק ההוצאה לפועל, תשכ"ז-1967, סעיף 66ג(ג)). במקרה הנדון, ההחלטה על הטלת עיכוב היציאה מן הארץ התקבלה בנוכחותו של מוחמד, ולכן חל סעיף 66ג(ג). משמעות הדבר היא שההגבלה תיכנס לתוקף בתום 30 ימים מיום הטלתה, ללא צורך במשלוח התראה נפרדת (Verdict: ת"א (שלום תל אביב-יפו) 24964-06-19 פלוני נ'' מדינת ישראל (12.9.2023), Reference 1, 2).',
    'הסטודנט עלול לבלבל בין הכלל הקבוע בסעיף 66ג(א) (הדורש המצאת התראה) לבין החריג הקבוע בסעיף 66ג(ג) (החל כאשר ההחלטה ניתנת במעמד החייב), ולחשוב שבכל מקרה נדרשת המצאת התראה.',
    '["עיכוב יציאה מן הארץ", "הגבלות על חייב", "חוק ההוצאה לפועל", "סעיף 66ג", "החלטה במעמד החייב", "מועד כניסה לתוקף"]'::jsonb,
    '**וריאציה 1 — הגבלה במעמד החייב:** רשם הטיל הגבלה במעמד החייב. מתי תיכנס לתוקף? ← 30 ימים מיום הטלת ההגבלה (סעיף 66ג(ג) לחוק ההוצאה לפועל). **וריאציה 2 — הגבלה ללא נוכחות החייב:** רשם הטיל הגבלה ללא נוכחות החייב. מתי תיכנס לתוקף? ← 30 ימים מיום המצאת ההתראה (סעיף 66ג(א) לחוק ההוצאה לפועל). **וריאציה 3 — מטרת תקופת ההמתנה:** מדוע קיימת תקופת המתנה של 30 ימים? ← לאפשר לחייב לפרוע את החוב או להתייצב לחקירת יכולת ולשכנע שאינו משתמט, ובכך למנוע את כניסת ההגבלה לתוקף (סעיף 66ג(ב) לחוק ההוצאה לפועל).',
    'כאשר רשם ההוצאה לפועל מטיל הגבלה על חייב במעמד החייב, ההגבלה תיכנס לתוקף בתום 30 ימים מיום הטלתה, ללא צורך במשלוח התראה נפרדת (סעיף 66ג(ג) לחוק ההוצאה לפועל).',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 66ג", "ת\"א (שלום תל אביב-יפו) 24964-06-19 פלוני נ'' מדינת ישראל (12.9.2023)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'ההגבלה תיכנס לתוקף מיד כדי למנוע את סיכול הליכי ההוצאה לפועל אם ייצא מוחמד מן הארץ.', false, 'בחירה זו שגויה. גם כאשר ההחלטה ניתנת במעמד החייב, החוק קובע תקופת המתנה של 30 ימים לכניסת ההגבלה לתוקף, ואינה נכנסת לתוקף באופן מיידי.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'ההגבלה תיכנס לתוקף במועד המוסכם על הזוכה.', false, 'בחירה זו שגויה. מועד כניסת ההגבלה לתוקף קבוע בחוק ואינו נתון להסכמת הזוכה, אלא אם כן ניתנה החלטה אחרת של רשם ההוצאה לפועל.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'ההגבלה תיכנס לתוקף בתוך 7 ימים מיום הטלתה, ובלבד שמוחמד יפקיד את דרכונו בלשכת ההוצאה לפועל.', false, 'בחירה זו שגויה. תקופת 7 הימים רלוונטית לחזקת המצאה בדואר רגיל (תקנה 24(ב) לתקנות ההוצאה לפועל), אך אינה המועד לכניסת ההגבלה לתוקף במקרה זה.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'ההגבלה תיכנס לתוקף בתוך 30 יום מיום הטלתה.', true, 'בחירה זו נכונה. סעיף 66ג(ג) לחוק ההוצאה לפועל קובע כי אם רשם ההוצאה לפועל הטיל הגבלה במעמד החייב, ההגבלה תיכנס לתוקף בתום 30 ימים מיום הטלתה, ללא צורך במשלוח התראה.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'כניסת הגבלה לתוקף ללא נוכחות החייב', 1, 'רשם ההוצאה לפועל הטיל מגבלת עיכוב יציאה מן הארץ על חייב שלא נכח בדיון. ההתראה על הטלת ההגבלה נשלחה לחייב בדואר רגיל ביום 1.1.2024, והגיעה לתיבת הדואר שלו ביום 3.1.2024. מתי תיכנס ההגבלה לתוקף?',
    'שאלה זו בוחנת את מועד כניסתה לתוקף של הגבלה שהוטלה על חייב שלא נכח בדיון, תוך התייחסות להוראות סעיף 66ג(א) לחוק ההוצאה לפועל ולכללי המצאת התראות בדואר רגיל.',
    'סעיף 66ג(א) לחוק ההוצאה לפועל, תשכ"ז-1967, קובע כי "לא תיכנס הגבלה לפי פרק זה לתוקף אלא לאחר שמנהל לשכת ההוצאה לפועל שלח לחייב בדואר התראה וחלפו 30 ימים מיום המצאת ההתראה" (Law: חוק ההוצאה לפועל, תשכ"ז-1967, סעיף 66ג). במקרה זה, ההחלטה לא ניתנה במעמד החייב, ולכן חל סעיף קטן (א). מועד ההמצאה הוא המועד שבו ההתראה הגיעה בפועל לידי החייב, או לתיבת הדואר שלו (Verdict: ת"א (שלום תל אביב-יפו) 24964-06-19 פלוני נ'' מדינת ישראל (12.9.2023), Reference 2, 3). במקרה הנדון, ההתראה הגיעה לתיבת הדואר של החייב ביום 3.1.2024. לכן, ההגבלה תיכנס לתוקף בחלוף 30 ימים מיום זה, כלומר ביום 3.2.2024. חשוב להבחין בין מועד המשלוח למועד ההמצאה, וכן בין חזקת המצאה (תקנה 24(ב) לתקנות ההוצאה לפועל) לבין המועד הקובע לכניסת ההגבלה לתוקף (Verdict: עת"מ (מינהליים ת"א) 15200-09-16 רוני גואטה נ'' משרד התחבורה-רשות הרישוי (26.9.2016), Reference 19; Verdict: עת"מ (מינהליים נצ'') 24303-04-16 אלכסנדר מולר נ'' מדינת ישראל משרד התחבורה, רשות הרישוי (19.8.2016), Reference 50).',
    'בלבול בין מועד משלוח ההתראה למועד המצאתה, או בין חזקת ההמצאה (6 ימים לאחר המשלוח) לבין תקופת 30 הימים לכניסת ההגבלה לתוקף.',
    '["הגבלות על חייב", "עיכוב יציאה מן הארץ", "סעיף 66ג(א) לחוק ההוצאה לפועל", "המצאת התראה", "דואר רגיל", "חזקת המצאה"]'::jsonb,
    '**וריאציה 1 — הגבלה ללא נוכחות החייב:** רשם הטיל הגבלה ללא נוכחות החייב. מתי תיכנס לתוקף? ← 30 ימים מיום המצאת ההתראה (סעיף 66ג(א) לחוק ההוצאה לפועל). **וריאציה 2 — הגבלה במעמד החייב:** רשם הטיל הגבלה במעמד החייב. מתי תיכנס לתוקף? ← 30 ימים מיום הטלת ההגבלה (סעיף 66ג(ג) לחוק ההוצאה לפועל). **וריאציה 3 — הטלה חוזרת של הגבלה:** אם הגבלה בוטלה והוטלה מחדש, האם נדרשת התראה חדשה? ← לא, במקרים מסוימים (כמו אי עמידה בצו תשלומים) ניתן להטיל מחדש ללא התראה חדשה (תקנה 22ב(ג) לתקנות ההוצאה לפועל; Verdict: רע"צ (שלום פ"ת) 16975-12-10 שמואלי נ'' גדלי (17.1.2011), Reference 33, 34).',
    'כאשר הגבלה מוטלת על חייב שלא נכח בדיון, היא תיכנס לתוקף בחלוף 30 ימים מיום המצאת ההתראה לחייב (סעיף 66ג(א) לחוק ההוצאה לפועל).',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 66ג(א)", "תקנות ההוצאה לפועל, תש\"ם-1979, תקנה 24(ב)", "ת\"א (שלום תל אביב-יפו) 24964-06-19 פלוני נ'' מדינת ישראל (12.9.2023)", "עת\"מ (מינהליים ת\"א) 15200-09-16 רוני גואטה נ'' משרד התחבורה-רשות הרישוי (26.9.2016)", "עת\"מ (מינהליים נצ'') 24303-04-16 אלכסנדר מולר נ'' מדינת ישראל משרד התחבורה, רשות הרישוי (19.8.2016)", "רע\"צ (שלום פ\"ת) 16975-12-10 שלומית שמואלי נ'' חיים גדלי (17.1.2011)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'שיקולי רשם ההוצאה לפועל בהטלת הגבלות', 2, 'מהם השיקולים שרשם ההוצאה לפועל צריך לשקול לפני הטלת הגבלה על חייב, כגון עיכוב יציאה מן הארץ?',
    'שאלה זו עוסקת בשיקול הדעת של רשם ההוצאה לפועל בהטלת הגבלות על חייב, כפי שמעוגן בסעיף 66א לחוק ההוצאה לפועל. היא מדגישה את הצורך באיזון בין זכויות הזוכה לגביית חובו לבין זכויות החייב, תוך הפעלת עקרון המידתיות.',
    'סעיף 66א לחוק ההוצאה לפועל, תשכ"ז-1967, קובע כי רשם ההוצאה לפועל רשאי להטיל הגבלות על חייב "התקיימו לגבי החייב התנאים כאמור בסעיף 66ב, ושוכנע רשם ההוצאה לפועל כי הדבר מוצדק בנסיבות העניין, בהתחשב בפגיעה בחייב ובהליכים אחרים שננקטו לשם גביית החוב, לרבות הליכים לקבלת מידע על החייב, ככל הנדרש" (Verdict: רע"א 5137/11 פלוני נ'' עו"ד עודד הכהן (25.10.2011), Reference 40; Verdict: רע"צ (שלום נצ'') 41658-03-18 אדיב חילו נ'' מרכנתיל דיסקונט תל אביב סניף אבן גבירול (12.4.2018), Reference 52). התנאים בסעיף 66ב מתייחסים, בין היתר, לכך שהחייב הוא בעל יכולת המשתמט מתשלום חובותיו (Verdict: עש"א (שלום קריות) 5094-07-21 מיכאל מייק בן אהרון נ'' בנק לאומי לישראל בע"מ-סניף חצור הגלילית (16.5.2022), Reference 10). הפסיקה מדגישה כי הטלת הגבלות אלו נועדה לאזן בין שתי תכליות מתנגשות: גבייה יעילה של חובות והגנה על זכויות החייב, תוך הפעלת עקרון המידתיות (Verdict: רע"א 5137/11 פלוני נ'' עו"ד עודד הכהן (25.10.2011), Reference 39; Verdict: (רשם ההוצאה לפועל ירושלים) החייב נ'' הזוכה (17.5.2011), Reference 29, 31).',
    'הסטודנט עלול להתמקד רק באחד מהשיקולים (למשל, השתמטות החייב) מבלי להבין את מכלול השיקולים הנדרשים, ובפרט את הצורך באיזון ומידתיות.',
    '["הגבלות על חייב", "סעיף 66א לחוק ההוצאה לפועל", "חייב משתמט", "איזון אינטרסים", "עקרון המידתיות", "שיקול דעת רשם ההוצאה לפועל"]'::jsonb,
    '**וריאציה 1 — תנאים להטלת הגבלה:** מהם התנאים להטלת הגבלה? ← התקיימות תנאי 66ב (חייב משתמט), הצדקה בנסיבות העניין, התחשבות בפגיעה בחייב והליכים אחרים (סעיף 66א לחוק ההוצאה לפועל). **וריאציה 2 — תכליות ההגבלות:** מהי תכלית ההגבלות? ← אמצעי לחץ על חייב משתמט לדרבן אותו לפרוע את חובו, כלי אכיפה עקיף (Verdict: עש"א (שלום קריות) 5094-07-21 בן אהרון נ'' בנק לאומי לישראל בע"מ-סניף חצור הגלילית (16.5.2022), Reference 11). **וריאציה 3 — איזון זכויות:** כיצד מאזנים בין זכויות הזוכה והחייב? ← מתן משקל נכבד לאינטרס הזוכה בביצוע פסק הדין, תוך התחשבות בחייב ומניעת הפיכתו לנטל על החברה (Verdict: רע"א 5137/11 פלוני נ'' עו"ד עודד הכהן (25.10.2011), Reference 39).',
    'רשם ההוצאה לפועל רשאי להטיל הגבלות על חייב אם התקיימו התנאים בסעיף 66ב (חייב משתמט), ושוכנע שהדבר מוצדק בנסיבות העניין, תוך התחשבות בפגיעה בחייב ובהליכים אחרים שננקטו לגביית החוב (סעיף 66א לחוק ההוצאה לפועל).',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 66א", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 66ב", "רע\"א 5137/11 פלוני נ'' עו\"ד עודד הכהן (25.10.2011)", "עש\"א (שלום קריות) 5094-07-21 מיכאל מייק בן אהרון נ'' בנק לאומי לישראל בע\"מ-סניף חצור הגלילית (16.5.2022)", "(רשם ההוצאה לפועל ירושלים) החייב נ'' הזוכה (17.5.2011)", "רע\"צ (שלום נצ'') 41658-03-18 אדיב חילו נ'' מרכנתיל דיסקונט תל אביב סניף אבן גבירול (12.4.2018)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'ביטול הגבלת יציאה מן הארץ מטעמי בריאות', 3, 'חייב שהוטלה עליו הגבלת יציאה מן הארץ מבקש לבטלה עקב צורך בטיפול רפואי דחוף בחו"ל. מה הדין?',
    'שאלה זו מתמקדת בחריג הספציפי להטלת הגבלות יציאה מן הארץ, המעוגן בסעיף 66א(1) לחוק ההוצאה לפועל, הנוגע למקרים של צורך רפואי. היא בוחנת את שיקול הדעת של רשם ההוצאה לפועל במקרים אלו ואת האיזון בין זכות הקניין של הזוכה לזכות לבריאות של החייב.',
    'סעיף 66א(1) לחוק ההוצאה לפועל, תשכ"ז-1967, קובע כי הגבלה על קבלת דרכון או תעודת מעבר, החזקתם או הארכת תוקפם, וכן הגבלה בדבר יציאה מן הארץ, "לא תוטל אם שוכנע רשם ההוצאה לפועל שהיציאה מישראל דרושה מטעמי בריאותו של החייב או של בן משפחה התלוי בו" (Verdict: רע"א 5137/11 פלוני נ'' עו"ד עודד הכהן (25.10.2011), Reference 40; Verdict: ע"א (מחוזי ת"א) 2640-04-15 מנחם רגב נ'' אלברט בן סימון (18.1.2016), Reference 15). הוראה זו משקפת את האיזון בין זכות הקניין של הזוכה לבין זכויות יסוד של החייב, ובפרט הזכות לבריאות. על החייב להוכיח את הצורך הרפואי ואת הקשר בין הצורך ליציאה מן הארץ (Verdict: רע"צ (שלום פ"ת) 71721-12-25 אלי מנטל נ'' יצחק רחמים (28.12.2025), Reference 26, 28). רשם ההוצאה לפועל מוסמך לבטל הגבלה שהטיל, מיוזמתו או לבקשת החייב, ורשאי להתנות את הביטול במתן ערובה, אך במקרה של צורך רפואי, החריג הוא מפורש (סעיף 66ד(ב) לחוק ההוצאה לפועל).',
    'הסטודנט עלול להתעלם מהחריג הספציפי הקבוע בחוק למקרים רפואיים, וליישם את הכללים הכלליים לביטול הגבלות הדורשים ערובה או עמידה בצו תשלומים.',
    '["עיכוב יציאה מן הארץ", "סעיף 66א(1) לחוק ההוצאה לפועל", "טעמי בריאות", "ביטול הגבלה", "איזון זכויות", "נטל הוכחה"]'::jsonb,
    '**וריאציה 1 — ביטול הגבלה מטעמי בריאות:** חייב מבקש לבטל עיכוב יציאה מן הארץ לצורך טיפול רפואי. האם יבוטל? ← כן, אם רשם ההוצאה לפועל שוכנע שהיציאה דרושה מטעמי בריאות (סעיף 66א(1) לחוק ההוצאה לפועל). **וריאציה 2 — ביטול הגבלה מטעמי עיסוק:** חייב מבקש לבטל הגבלת רישיון נהיגה כי הוא נהג מונית. האם יבוטל? ← כן, אם רשם ההוצאה לפועל שוכנע שההגבלה תפגע פגיעה ממשית בעיסוקו וביכולתו לשלם את החוב (סעיף 66א(6) לחוק ההוצאה לפועל; Verdict: (רשם ההוצאה לפועל ירושלים) החייב נ'' הזוכה (17.5.2011), Reference 32). **וריאציה 3 — ביטול הגבלה עקב עמידה בתשלומים:** חייב עומד בצו תשלומים ומבקש לבטל הגבלה. האם יבוטל? ← כן, רשם ההוצאה לפועל יורה על ביטול הגבלה אם נוכח שהחייב מקיים הוראות צו תשלומים (סעיף 66ד(ג) לחוק ההוצאה לפועל; Verdict: רע"צ (שלום קריות) 28560-02-16 חוארי נ'' בנק מזרחי טפחות בע"מ (3.3.2016), Reference 48).',
    'רשם ההוצאה לפועל יבטל הגבלת יציאה מן הארץ אם שוכנע שהיציאה דרושה מטעמי בריאותו של החייב או של בן משפחה התלוי בו, וזאת כחריג מפורש הקבוע בסעיף 66א(1) לחוק ההוצאה לפועל.',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 66א(1)", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 66א(6)", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 66ד(ב)", "חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 66ד(ג)", "רע\"א 5137/11 פלוני נ'' עו\"ד עודד הכהן (25.10.2011)", "ע\"א (מחוזי ת\"א) 2640-04-15 מנחם רגב נ'' אלברט בן סימון (18.1.2016)", "רע\"צ (שלום פ\"ת) 71721-12-25 אלי מנטל נ'' יצחק רחמים (28.12.2025)", "(רשם ההוצאה לפועל ירושלים) החייב נ'' הזוכה (17.5.2011)", "רע\"צ (שלום קריות) 28560-02-16 מג''די חוארי נ'' בנק מזרחי טפחות בע\"מ (3.3.2016)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'חזקת המצאה ו"חריג הידיעה"', 4, 'חייב טוען כי לא קיבל התראה על הטלת הגבלות, אך הזוכה טוען שהחייב ידע בפועל על ההגבלות. מה הדין לעניין מועד כניסת ההגבלות לתוקף?',
    'שאלה זו עוסקת במורכבות של דיני ההמצאה בהוצאה לפועל, ובפרט ביישום "חריג הידיעה" במקרים של המצאת התראה על הטלת הגבלות. היא בוחנת את האיזון בין דרישות פורמליות של המצאה לבין ידיעה בפועל של החייב, ואת נטל ההוכחה לסתירת חזקת המצאה.',
    'סעיף 66ג(א) לחוק ההוצאה לפועל קובע כי הגבלה תיכנס לתוקף 30 ימים מיום המצאת ההתראה. תקנה 24(א) לתקנות ההוצאה לפועל מאפשרת לשלוח התראה בדואר רגיל, ותקנה 24(ב) קובעת חזקת המצאה לפיה דואר שנשלח יראוהו כאילו הומצא כדין ביום השישי שלאחר משלוחו (Verdict: ת"א (שלום תל אביב-יפו) 24964-06-19 פלוני נ'' מדינת ישראל (12.9.2023), Reference 4, 5). אולם, חזקה זו אינה חלוטה וניתנת לסתירה (Verdict: עת"מ (מינהליים נצ'') 24303-04-16 אלכסנדר מולר נ'' מדינת ישראל משרד התחבורה, רשות הרישוי (19.8.2016), Reference 50). הפסיקה הכירה ב"חריג הידיעה", לפיו במצבים מסוימים ניתן להעדיף את הידיעה בפועל של החייב על פני כלל ההמצאה הפורמלי, במיוחד כאשר מדובר בהמצאת התראה על הגבלות (ולא אזהרה ראשונית) (Verdict: ת"א (שלום תל אביב-יפו) 24964-06-19 פלוני נ'' מדינת ישראל (12.9.2023), Reference 5, 6). זאת, בין היתר, לאור הקושי האינהרנטי בהוכחת מועד המצאה מדויק בדואר רגיל, ולאור העובדה שהחייב כבר יודע על קיום תיק ההוצאה לפועל (Verdict: ת"א (שלום תל אביב-יפו) 24964-06-19 פלוני נ'' מדינת ישראל (12.9.2023), Reference 6). במקרים אלו, בית המשפט רשאי למנות את 30 הימים ממועד הידיעה בפועל (Verdict: ת"א (שלום תל אביב-יפו) 24964-06-19 פלוני נ'' מדינת ישראל (12.9.2023), Reference 5, 7).',
    'הסטודנט עלול לבלבל בין חזקת המצאה לבין חריג הידיעה, או ליישם את הכללים באופן נוקשה מבלי להתחשב בנסיבות הספציפיות ובמהות המסמך המומצא (אזהרה מול התראה).',
    '["חזקת המצאה", "חריג הידיעה", "המצאת התראה", "סעיף 66ג לחוק ההוצאה לפועל", "תקנה 24 לתקנות ההוצאה לפועל", "נטל הוכחה"]'::jsonb,
    '**וריאציה 1 — ידיעה בפועל מול המצאה פורמלית:** חייב טוען שלא קיבל התראה, אך ידע בפועל. מתי נכנסת ההגבלה לתוקף? ← 30 ימים ממועד הידיעה בפועל, מכוח חריג הידיעה (Verdict: ת"א (שלום תל אביב-יפו) 24964-06-19 פלוני נ'' מדינת ישראל (12.9.2023), Reference 5). **וריאציה 2 — חזקת המצאה בדואר רגיל:** התראה נשלחה בדואר רגיל. מתי נחשבת הומצאה? ← ביום השישי שלאחר משלוחה, אלא אם הוכח אחרת (תקנה 24(ב) לתקנות ההוצאה לפועל). **וריאציה 3 — חובת עדכון כתובת:** חייב לא עדכן כתובת. האם חזקת המצאה חלה? ← כן, חובת עדכון כתובת מוטלת על החייב, ובמחדלו רואים כל דואר שנשלח לכתובתו הקודמת ככזה שהגיע לידיו (Verdict: ע"א (מחוזי ת"א) 2640-04-15 מנחם רגב נ'' אלברט בן סימון (18.1.2016), Reference 16).',
    'כאשר חייב טוען כי לא קיבל התראה על הטלת הגבלות, אך ניתן להוכיח ידיעה בפועל, בית המשפט רשאי להחיל את ''חריג הידיעה'' ולמנות את 30 הימים לכניסת ההגבלה לתוקף ממועד הידיעה בפועל, במיוחד בהקשר של התראות על הגבלות (Verdict: ת"א (שלום תל אביב-יפו) 24964-06-19 פלוני נ'' מדינת ישראל).',
    '["חוק ההוצאה לפועל, תשכ\"ז-1967, סעיף 66ג(א)", "תקנות ההוצאה לפועל, תש\"ם-1979, תקנה 24(א)", "תקנות ההוצאה לפועל, תש\"ם-1979, תקנה 24(ב)", "ת\"א (שלום תל אביב-יפו) 24964-06-19 פלוני נ'' מדינת ישראל (12.9.2023)", "ע\"א (מחוזי ת\"א) 2640-04-15 מנחם רגב נ'' אלברט בן סימון (18.1.2016)", "עת\"מ (מינהליים נצ'') 24303-04-16 אלכסנדר מולר נ'' מדינת ישראל משרד התחבורה, רשות הרישוי (19.8.2016)", "(רשם ההוצאה לפועל ירושלים) ‏03-13430-98-5 ‏/ ג.ר. נ'' בנק הפועלים בע\"מ (9.5.2018)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'ההגבלה תיכנס לתוקף ביום 1.2.2024.', false, 'בחירה זו שגויה. המועד נקבע לפי יום המצאת ההתראה, ולא יום משלוח ההתראה.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'ההגבלה תיכנס לתוקף ביום 3.2.2024.', true, 'בחירה זו נכונה. סעיף 66ג(א) לחוק ההוצאה לפועל קובע כי ההגבלה תיכנס לתוקף בחלוף 30 ימים מיום המצאת ההתראה. במקרה של דואר רגיל, מועד ההמצאה הוא מועד קבלת הדואר בפועל, או לפי חזקת המצאה אם לא הוכח אחרת.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'ההגבלה תיכנס לתוקף ביום 7.1.2024.', false, 'בחירה זו שגויה. 7 ימים מיום המשלוח (או 6 ימים לאחר המשלוח) הוא מועד חזקת ההמצאה לפי תקנה 24(ב) לתקנות ההוצאה לפועל, אך לא מועד כניסת ההגבלה לתוקף.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'ההגבלה תיכנס לתוקף מיד עם הטלתה.', false, 'בחירה זו שגויה. כניסה מיידית לתוקף אינה מתרחשת במקרה של הטלת הגבלה ללא נוכחות החייב, אלא נדרשת התראה ותקופת המתנה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'האם החייב משתמט מתשלום חובותיו, האם הדבר מוצדק בנסיבות העניין בהתחשב בפגיעה בחייב, והאם ננקטו הליכים אחרים לגביית החוב.', true, 'בחירה זו נכונה. סעיף 66א לחוק ההוצאה לפועל מפרט את השיקולים שעל רשם ההוצאה לפועל לשקול, לרבות התקיימות התנאים בסעיף 66ב, הצדקת ההגבלה בנסיבות העניין, והתחשבות בפגיעה בחייב ובהליכים אחרים שננקטו.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'רק האם החייב משתמט מתשלום חובותיו, ללא צורך בשקילת הפגיעה בו או בהליכים אחרים.', false, 'בחירה זו שגויה. החוק דורש שקילה רחבה יותר של נסיבות העניין, כולל איזון בין זכויות הזוכה והחייב ועקרון המידתיות (Verdict: רע"א 5137/11 פלוני נ'' עו"ד עודד הכהן (25.10.2011), Reference 39).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'רק גובה החוב והוותק של תיק ההוצאה לפועל.', false, 'בחירה זו שגויה. אף שאלו נתונים רלוונטיים, הם אינם השיקולים היחידים או המרכזיים להטלת הגבלות, ויש לשקול גם את התנהלות החייב והפגיעה בו.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'האם החייב הוכרז כחייב מוגבל באמצעים, ורק אז ניתן להטיל עליו הגבלות.', false, 'בחירה זו שגויה. הגבלות לפי פרק ו''1 לחוק ההוצאה לפועל (סעיף 66א) מוטלות על חייב משתמט, בעוד שהגבלות על חייב מוגבל באמצעים (סעיף 69ד) הן מסוג אחר ומוטלות בנסיבות שונות (Verdict: רע"צ (שלום קריות) 4404856 עלי שאדי נ'' בנק הפועלים בע"מ (12.3.2018), Reference 38).', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'רשם ההוצאה לפועל יבטל את ההגבלה אם שוכנע שהיציאה דרושה מטעמי בריאותו של החייב או של בן משפחה התלוי בו.', true, 'בחירה זו נכונה. סעיף 66א(1) לחוק ההוצאה לפועל קובע חריג מפורש להטלת הגבלת דרכון/יציאה מהארץ מטעמי בריאות.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'רשם ההוצאה לפועל רשאי לבטל את ההגבלה רק אם החייב יפקיד ערובה מספקת להבטחת החוב.', false, 'בחירה זו שגויה. הפקדת ערובה היא אפשרות לביטול הגבלה (סעיף 66ד(ב)), אך במקרה של צורך רפואי, החוק קובע חריג ספציפי שאינו דורש ערובה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'רשם ההוצאה לפועל אינו מוסמך לבטל הגבלת יציאה מן הארץ, אלא רק בית המשפט המחוזי.', false, 'בחירה זו שגויה. רשם ההוצאה לפועל מוסמך לבטל הגבלות שהטיל, לרבות עיכוב יציאה מן הארץ (סעיף 66ד לחוק ההוצאה לפועל).', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'ההגבלה לא תבוטל, שכן מטרתה למנוע מהחייב להשתמט מתשלום חובותיו.', false, 'בחירה זו שגויה. החוק מכיר בחריגים להטלת הגבלות, ובריאות היא אחד מהם, המעיד על איזון בין זכויות החייב לזכויות הזוכה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'ההגבלות לא ייכנסו לתוקף כלל, שכן נדרשת המצאה בפועל של ההתראה.', false, 'בחירה זו שגויה. אף שנדרשת המצאה, קיימת חזקת המצאה וכן ''חריג הידיעה'' המאפשר להתגבר על היעדר המצאה פורמלית.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'בית המשפט רשאי להחיל את חריג הידיעה ולמנות את 30 הימים ממועד הידיעה בפועל של החייב על ההגבלות, במיוחד כאשר מדובר בהמצאת התראה ולא אזהרה ראשונית.', true, 'בחירה זו נכונה. הפסיקה מכירה ב''חריג הידיעה'' במקרים של המצאת התראה על הגבלות, ומאפשרת למנות את 30 הימים ממועד הידיעה בפועל, במיוחד לאור הקושי להוכיח מועד המצאה מדויק בדואר רגיל (Verdict: ת"א (שלום תל אביב-יפו) 24964-06-19 פלוני נ'' מדינת ישראל (12.9.2023), Reference 5, 6).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'ההגבלות ייכנסו לתוקף 6 ימים לאחר משלוח ההתראה בדואר, מכוח חזקת המצאה חלוטה.', false, 'בחירה זו שגויה. חזקת המצאה (תקנה 24(ב) לתקנות ההוצאה לפועל) אינה חלוטה וניתנת לסתירה, וגם אם קמה, יש למנות 30 ימים ממועד ההמצאה, לא 6 ימים.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'הזוכה חייב לשלוח התראה חדשה בדואר רשום עם אישור מסירה, ורק אז יימנו 30 הימים.', false, 'בחירה זו שגויה. הדין מאפשר משלוח התראה בדואר רגיל (תקנה 24(א) לתקנות ההוצאה לפועל), ואין חובה לשלוח בדואר רשום עם אישור מסירה, אלא אם כן נקבע אחרת.', 4);

END $$;

-- ============================================================
-- Q45 — 2019-S-Q45 — chapter=constitutional_intl subtopic=foreign_judgment_enforcement
-- ============================================================
DO $$
DECLARE
  v_sq_id uuid := gen_random_uuid();
  v_group_id uuid := gen_random_uuid();
  v_subtopic_id uuid;
  v_existing_id uuid;
  v_ang_a uuid := gen_random_uuid();
  v_ang_b uuid := gen_random_uuid();
  v_ang_c uuid := gen_random_uuid();
  v_ang_d uuid := gen_random_uuid();
BEGIN
  SELECT id INTO v_existing_id FROM public.source_questions WHERE external_id = '2019-S-Q45';
  IF v_existing_id IS NOT NULL THEN
    RAISE NOTICE 'Q45 skipped: external_id % already exists', '2019-S-Q45';
    RETURN;
  END IF;

  SELECT id INTO v_subtopic_id FROM public.subtopics WHERE code = 'foreign_judgment_enforcement';
  IF v_subtopic_id IS NULL THEN
    RAISE EXCEPTION 'Subtopic code % not found', 'foreign_judgment_enforcement';
  END IF;

  INSERT INTO public.source_questions (
    id, question_group_id, version, is_current, external_id, chapter_id, subtopic_id,
    question_text, source_metadata, legal_topic_analysis, full_explanation, common_pitfall,
    concepts_and_skills, quick_thinking_360, summary_for_memory, references_list,
    notes_for_admin, status, created_by
  ) VALUES (
    v_sq_id, v_group_id, 1, true,
    '2019-S-Q45', 'ed89ea85-f137-4877-90ab-7c7d56ff3cc2', v_subtopic_id,
    'אורית הגישה תובענה כספית נגד בתיה בבית המשפט המוסמך בצרפת בגין נזקי גוף בסכום שווה ערך ל-5,000,000 ש"ח. בית המשפט בצרפת קיבל את התובענה באופן חלקי בלבד ופסק לטובתה של אורית פיצוי בסכום שווה ערך ל-1,000,000 ש"ח. אורית מבקשת לבצע את פסק הדין בישראל. מה הדין?',
    '{"exam_year": 2019, "exam_season": "summer", "exam_part": 2, "exam_question_number": 45}'::jsonb,
    'השאלה עוסקת בסמכות העניינית של בתי המשפט בישראל לדון בבקשה לאכיפת פסק חוץ. היא מתמקדת במבחן הסעד כקובע את הסמכות, ובפרט בהבחנה בין הסכום שנתבע במקור לבין הסכום שנפסק בפועל, לצורך קביעת האם הסמכות נתונה לבית משפט השלום או לבית המשפט המחוזי.',
    'חוק אכיפת פסקי-חוץ, תשי"ח-1958, קובע את התנאים לאכיפת פסק דין זר בישראל (חוק אכיפת פסקי-חוץ, תשי"ח-1958, סעיף 3). הסמכות העניינית לדון בבקשה לאכיפת פסק חוץ נקבעת לפי מבחן הסעד, כלומר, לפי שווי הסעד שנפסק בפועל בפסק הדין הזר, ולא לפי הסכום שנתבע במקור (ת"א (שלום חי'') 21060-07-13 פרומר, רפרנס 23, 24). סעיף 51(א)(2) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, קובע כי בית משפט השלום מוסמך לדון בתביעות אזרחיות שסכומן או שווי נושאן אינו עולה על 2,500,000 ש"ח (חוק בתי המשפט [נוסח משולב], תשמ"ד-1984, סעיף 51). במקרה הנדון, הסכום שנפסק לטובת אורית הוא 1,000,000 ש"ח, אשר נמוך מתקרת הסמכות של בית משפט השלום. לפיכך, הסמכות העניינית לדון בבקשה לאכיפת פסק הדין נתונה לבית משפט השלום (ת"א (שלום ראשל"צ) 31593-09-11 רוזנברג, רפרנס 15, 16; ת"א (שלום נת'') 1003/05 SMS Financial V, רפרנס 25, 26).',
    'הסטודנט עלול לטעות ולחשוב שהסמכות העניינית נקבעת לפי הסכום המקורי שנתבע בחו"ל, ולא לפי הסכום שנפסק בפועל, או לבלבל בין הליך אכיפת פסק חוץ לבין הליך הוצאה לפועל רגיל.',
    '["אכיפת פסק חוץ", "סמכות עניינית", "מבחן הסעד", "חוק בתי המשפט סעיף 51", "חוק אכיפת פסקי חוץ", "שווי נושא התביעה"]'::jsonb,
    '**וריאציה 1 — סכום שנפסק קובע:** תביעה בחו"ל על 5 מיליון ש"ח, נפסק 1 מיליון ש"ח. סמכות אכיפה בישראל? ← בית משפט השלום, לפי הסכום שנפסק (1 מיליון ש"ח) (סעיף 51(א)(2) לחוק בתי המשפט). **וריאציה 2 — סכום שנפסק מעל 2.5 מיליון:** תביעה בחו"ל על 5 מיליון ש"ח, נפסק 3 מיליון ש"ח. סמכות אכיפה בישראל? ← בית המשפט המחוזי, לפי הסכום שנפסק (3 מיליון ש"ח) (סעיף 40(1) לחוק בתי המשפט). **וריאציה 3 — אכיפה ישירה בהוצאה לפועל:** האם ניתן לפנות ישירות להוצאה לפועל עם פסק חוץ? ← לא, יש להגיש בקשה לבית המשפט להכריז עליו כאכיף תחילה (ת"א (שלום חי'') 21060-07-13 פרומר, רפרנס 23, 24).',
    'הסמכות העניינית לדון בבקשה לאכיפת פסק חוץ נקבעת לפי שווי הסעד שנפסק בפועל בפסק הדין הזר. אם הסכום שנפסק אינו עולה על 2,500,000 ש"ח, הסמכות נתונה לבית משפט השלום (סעיף 51(א)(2) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 51(א)(2)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 40(1)", "חוק אכיפת פסקי-חוץ, תשי\"ח-1958, סעיף 3", "ת\"א (שלום ראשל\"צ) 31593-09-11 שמואל רוזנברג נ'' אמיר פישביין (1.3.2016)", "ת\"א (שלום נת'') 1003/05 SMS Financial V נ'' דוד הרו (6.3.2006)", "ת\"א (שלום חי'') 21060-07-13 שמואל פרומר נ'' MOX TELECOM AG (27.11.2013)", "ת\"א (שלום ת\"א) 24751-07-16 ביו-ויו בע\"מ נ'' MEDIMIKS MEDIKAL HIZMETLER SAN.VE TIC.LTD (24.3.2017)"]'::jsonb,
    NULL,
    'active',
    'b9ecdde2-d07e-4761-96ab-05f0ad32d4e3'
  );

  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'א', 'על אורית להגיש את בקשתה לבית משפט השלום.', true, 'בחירה זו נכונה. הסמכות העניינית לאכיפת פסק חוץ נקבעת לפי שווי הסעד שנפסק בפועל בפסק הדין הזר. מאחר שהסכום שנפסק הוא 1,000,000 ש"ח, והוא אינו עולה על 2,500,000 ש"ח, הסמכות נתונה לבית משפט השלום, בהתאם לסעיף 51(א)(2) לחוק בתי המשפט.', 1);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ב', 'על אורית להגיש את בקשתה לבית המשפט המחוזי.', false, 'בחירה זו שגויה. הסמכות העניינית נקבעת לפי הסכום שנפסק בפועל, ולא לפי הסכום שנתבע במקור. מאחר שהסכום שנפסק הוא 1,000,000 ש"ח, הסמכות אינה לבית המשפט המחוזי.', 2);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ג', 'על אורית להגיש את בקשתה ללשכת ההוצאה לפועל.', false, 'בחירה זו שגויה. פסק חוץ אינו אכיף בישראל באופן אוטומטי. יש להגיש בקשה לבית המשפט המוסמך (שלום או מחוזי, לפי הסכום שנפסק) להכריז עליו כאכיף, ורק לאחר מכן ניתן יהיה לפנות ללשכת ההוצאה לפועל.', 3);
  INSERT INTO public.source_choices (source_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_sq_id, 'ד', 'לא ניתן לבצע את פסק הדין בישראל.', false, 'בחירה זו שגויה. חוק אכיפת פסקי-חוץ, תשי"ח-1958, מאפשר אכיפת פסקי דין זרים בישראל, בכפוף לעמידה בתנאים הקבועים בחוק.', 4);

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_a, v_sq_id, 'א', 'הגדרת "פסק דין" בחוק אכיפת פסקי חוץ', 1, 'חברה ישראלית מבקשת לאכוף בישראל החלטת ביניים שניתנה בבית משפט באיטליה, המחייבת את הנתבע בתשלום סכום כסף. ההחלטה אינה ניתנת עוד לערעור לפי הדין האיטלקי. האם ניתן לאכוף החלטה זו בישראל?',
    'שאלה זו בוחנת את הפרשנות המרחיבה של המונח "פסק דין" בחוק אכיפת פסקי חוץ, תשי"ח-1958, כפי שנקבעה בפסיקה. היא מדגישה כי גם החלטות ביניים יכולות להיחשב כ"פסק דין" לצורך אכיפה, ובלבד שהן עומדות בתנאי הסופיות (אינן ניתנות עוד לערעור) לפי הדין הזר.',
    'סעיף 1 לחוק אכיפת פסקי-חוץ, תשי"ח-1958, מגדיר "פסק חוץ" כ"פסק דין שניתן בבית משפט במדינה זרה בעניין אזרחי". הפסיקה קבעה כי הפרשנות הראויה למונח "פסק דין" בחוק אינה פרשנות מצמצמת אלא מרחיבה, דהיינו, כי המונח כולל כל החלטה של בית משפט זר (ת"א (שלום ת"א) 56751-09-11 ריש, רפרנס 1, 2, 3). המבחן הקובע לעניין סופיות הדיון הוא האם פסק החוץ אינו ניתן עוד לערעור לפי הדין הזר (סעיף 3(2) לחוק אכיפת פסקי חוץ) (ת"א (שלום ת"א) 56751-09-11 ריש, רפרנס 2, 3). אין דרישה שהפסק לא יהיה ניתן לביטול או לשינוי על ידי בית המשפט הזר שנתן אותו, אלא רק שלא יהיה ניתן לערעור (ת"א (שלום ת"א) 56751-09-11 ריש, רפרנס 3). במקרה הנדון, ההחלטה היא החלטת ביניים אך אינה ניתנת עוד לערעור לפי הדין האיטלקי, ולכן היא עומדת בתנאי הסופיות הנדרש לאכיפה (ת"א (שלום ת"א) 56751-09-11 ריש, רפרנס 3, 4).',
    'הסטודנט עלול לטעות וליישם את ההבחנה בין "פסק דין" ל"החלטה אחרת" מהמשפט הישראלי על המשפט הבינלאומי הפרטי, מבלי להבין את הפרשנות המרחיבה של המונח "פסק דין" בחוק אכיפת פסקי חוץ.',
    '["אכיפת פסק חוץ", "פסק דין זר", "החלטת ביניים", "סופיות הדיון", "סעיף 1 לחוק אכיפת פסקי חוץ", "סעיף 3(2) לחוק אכיפת פסקי חוץ"]'::jsonb,
    '**וריאציה 1 — אכיפת החלטת ביניים:** האם ניתן לאכוף החלטת ביניים זרה? ← כן, אם היא אינה ניתנת עוד לערעור לפי הדין הזר (ת"א (שלום ת"א) 56751-09-11 ריש, רפרנס 2, 3). **וריאציה 2 — אכיפת צו ביניים:** האם ניתן לאכוף צו ביניים זר? ← לא, אלא אם מדובר בענייני מזונות (ת"א (שלום ת"א) 58219-02-24 ARVEN CONSULTING&INVESTMENTS, רפרנס 36, 37). **וריאציה 3 — פסק דין שניתן לשינוי:** האם פסק חוץ שניתן לשינוי על ידי בית המשפט הזר יכול להיות אכיף? ← כן, כל עוד אינו ניתן עוד לערעור (ת"א (שלום ת"א) 56751-09-11 ריש, רפרנס 3).',
    'המונח "פסק דין" בחוק אכיפת פסקי חוץ מתפרש באופן מרחיב וכולל גם החלטות ביניים, ובלבד שהן אינן ניתנות עוד לערעור לפי הדין הזר (סעיף 3(2) לחוק אכיפת פסקי חוץ).',
    '["חוק אכיפת פסקי-חוץ, תשי\"ח-1958, סעיף 1", "חוק אכיפת פסקי-חוץ, תשי\"ח-1958, סעיף 3(2)", "חוק אכיפת פסקי-חוץ, תשי\"ח-1958, סעיף 8", "ת\"א (שלום ת\"א) 56751-09-11 צבי ריש נ'' יעקב שרב-שטרית (23.2.2016)", "ת\"א (שלום ת\"א) 58219-02-24 ARVEN CONSULTING&INVESTMENTS נ'' קד-איט מערכות בע\"מ (23.9.2024)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_b, v_sq_id, 'ב', 'נטל ההוכחה באכיפת פסק חוץ', 2, 'חברה ישראלית מבקשת לאכוף פסק דין שניתן לטובתה בגרמניה. הנתבע מתנגד לאכיפה בטענה שהפסק הושג במרמה. על מי מוטל נטל ההוכחה לגבי התקיימות התנאים לאכיפה ולגבי טענת המרמה?',
    'שאלה זו עוסקת בחלוקת נטל ההוכחה בהליכי אכיפת פסקי חוץ בישראל. היא מדגישה את ההבחנה בין התנאים המצטברים לאכיפה הקבועים בסעיף 3 לחוק אכיפת פסקי חוץ, לבין טענות ההגנה המנויות בסעיף 6 לאותו חוק, ועל מי מוטל הנטל להוכיח כל אחד מהם.',
    'חוק אכיפת פסקי-חוץ, תשי"ח-1958, קובע שני שלבים בבחינת בקשה לאכיפת פסק חוץ. בשלב הראשון, על מבקש האכיפה מוטל הנטל להוכיח את קיומם של ארבעת התנאים המצטברים הקבועים בסעיף 3 לחוק (ת"א (שלום הרצ'') 42972-11-16 אוחנה, רפרנס 5, 6, 7; ת"א (שלום ת"א) 31925-09-12 גוויצארדי, רפרנס 20, 21). תנאים אלו כוללים, בין היתר, שהפסק ניתן במדינה שבית המשפט שלה היה מוסמך לתתו, שהוא אינו ניתן עוד לערעור, שהחיוב ניתן לאכיפה בישראל ואינו סותר את תקנת הציבור, ושהפסק בר-ביצוע במדינה בה ניתן (חוק אכיפת פסקי-חוץ, תשי"ח-1958, סעיף 3). רק לאחר שהמבקש עמד בנטל זה, עוברים לשלב השני, שבו על המתנגד לאכיפה (הנתבע) מוטל הנטל להוכיח את קיומה של אחת ההגנות המנויות בסעיף 6 לחוק, כגון שהפסק הושג במרמה (ת"א (שלום הרצ'') 42972-11-16 אוחנה, רפרנס 5, 6, 7; ת"א (שלום י-ם) 9490-04-14 גרינברגר, רפרנס 9, 10).',
    'הסטודנט עלול לטעות ולחשוב שנטל ההוכחה לגבי כלל הטענות מוטל על צד אחד בלבד, או לבלבל בין נטל ההוכחה הראשוני לבין הנטל המשני (המעבר).',
    '["אכיפת פסק חוץ", "נטל ההוכחה", "סעיף 3 לחוק אכיפת פסקי חוץ", "סעיף 6 לחוק אכיפת פסקי חוץ", "טענת מרמה", "תנאים מצטברים"]'::jsonb,
    '**וריאציה 1 — נטל הוכחת תנאי סעיף 3:** על מי מוטל הנטל להוכיח את התנאים לאכיפה (סעיף 3)? ← על מבקש האכיפה (ת"א (שלום הרצ'') 42972-11-16 אוחנה, רפרנס 7). **וריאציה 2 — נטל הוכחת הגנות סעיף 6:** על מי מוטל הנטל להוכיח את ההגנות מפני אכיפה (סעיף 6)? ← על המתנגד לאכיפה (ת"א (שלום הרצ'') 42972-11-16 אוחנה, רפרנס 7). **וריאציה 3 — תצהיר המבקש:** האם תצהיר של המבקש המאמת את התנאים מספיק? ← כן, בדרך כלל תצהיר כזה מעביר את הנטל המשני למשיב (בש"א (שלום תל אביב-יפו) 179046/04 משרד השילומים של ריינלנד, רפרנס 66).',
    'הנטל להוכיח את התקיימות התנאים המצטברים לאכיפת פסק חוץ (סעיף 3 לחוק) מוטל על מבקש האכיפה, ואילו הנטל להוכיח את קיומה של אחת ההגנות מפני אכיפה (סעיף 6 לחוק) מוטל על המתנגד לאכיפה.',
    '["חוק אכיפת פסקי-חוץ, תשי\"ח-1958, סעיף 3", "חוק אכיפת פסקי-חוץ, תשי\"ח-1958, סעיף 6", "ת\"א (שלום הרצ'') 42972-11-16 רפאל אוחנה נ'' אלכסנדר בנימין זלמנוביץ (11.12.2017)", "ת\"א (שלום י-ם) 9490-04-14 רוברט מ. גרינברגר נ'' צבי דוד פרידלנד (5.5.2016)", "ת\"א (שלום ת\"א) 31925-09-12 דניאלה גוויצארדי נ'' יהודית לוי (31.3.2015)", "בש\"א (שלום תל אביב-יפו) 179046/04 משרד השילומים של ריינלנד - פפאלץ מסארבורג נ'' ד\"ר אסתר שטיימן (לבית לוין) (12.2.2006)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_c, v_sq_id, 'ג', 'אכיפת פסק חוץ שניתן במעמד צד אחד', 3, 'חברה ישראלית מבקשת לאכוף פסק דין שניתן נגד חייב בבית משפט בארה"ב. החייב טוען כי פסק הדין ניתן במעמד צד אחד, ללא שהומצאו לו המסמכים כדין, ולכן לא ניתנה לו הזדמנות סבירה לטעון טענותיו. מה הדין?',
    'שאלה זו עוסקת באחת ההגנות המרכזיות מפני אכיפת פסק חוץ – אי מתן הזדמנות סבירה לנתבע לטעון טענותיו (סעיף 6(א)(2) לחוק אכיפת פסקי חוץ). היא מדגישה כי עצם העובדה שפסק הדין ניתן במעמד צד אחד אינה מספיקה, אלא יש לבחון את סבירות ההמצאה וההזדמנות להתגונן, תוך הטלת נטל ההוכחה על החייב.',
    'סעיף 6(א)(2) לחוק אכיפת פסקי-חוץ, תשי"ח-1958, קובע כי פסק חוץ לא יוכרז אכיף אם הוכח לבית המשפט כי "האפשרות שניתנה לנתבע לטעון טענותיו ולהביא ראיותיו לפני מתן הפסק לא היתה, לדעת בית המשפט, סבירה" (חוק אכיפת פסקי-חוץ, תשי"ח-1958, סעיף 6(א)(2)). הפסיקה קבעה כי העובדה שפסק הדין ניתן במעמד צד אחד ובהיעדר הגנה אינה מהווה כשלעצמה הגנה מפני אכיפה (ת"א (שלום י-ם) 9490-04-14 גרינברגר, רפרנס 9, 10; ת"א (שלום ת"א) 5708562 צסרסקי, רפרנס 12, 13). המבחן הוא אובייקטיבי – האם פעולת בית המשפט הזר חרגה מכללי הצדק הטבעי (ת"א (שלום י-ם) 9490-04-14 גרינברגר, רפרנס 9). נטל ההוכחה לקיומה של הגנה זו מוטל על החייב המתנגד לאכיפה, ועליו לבסס חשש ממשי שזכויותיו נפגעו (ה"פ (שלום ת"א) 23261-06-13 Silver, Garvett & Henkel P.A., רפרנס 48). בית המשפט בישראל אינו משמש ערכאת ערעור על פסק החוץ, אך הוא כן בוחן את קיומן של ההגנות הפרוצדורליות הקבועות בסעיף 6 (ת"א (שלום הרצ'') 42972-11-16 אוחנה, רפרנס 5, 6).',
    'הסטודנט עלול לטעות ולחשוב שפסק דין שניתן במעמד צד אחד אינו אכיף בישראל באופן אוטומטי, מבלי להבין את הצורך להוכיח חוסר סבירות בהזדמנות להתגונן.',
    '["אכיפת פסק חוץ", "פסק דין במעמד צד אחד", "הגנות מפני אכיפה", "סעיף 6(א)(2) לחוק אכיפת פסקי חוץ", "הזדמנות סבירה לטעון", "נטל הוכחה"]'::jsonb,
    '**וריאציה 1 — פסק דין בהיעדר הגנה:** האם פסק חוץ שניתן בהיעדר הגנה אכיף? ← כן, אם ניתנה לחייב הזדמנות סבירה להתגונן (ת"א (שלום י-ם) 9490-04-14 גרינברגר, רפרנס 9). **וריאציה 2 — נטל הוכחת חוסר סבירות:** על מי מוטל הנטל להוכיח חוסר סבירות בהזדמנות להתגונן? ← על החייב המתנגד לאכיפה (ה"פ (שלום ת"א) 23261-06-13 Silver, Garvett & Henkel P.A., רפרנס 48). **וריאציה 3 — המצאה כדין:** האם אי המצאה כדין מהווה הגנה? ← כן, אם היא שללה מהחייב הזדמנות סבירה להתגונן (ת"א (שלום עכו) 38673-07-18 עראף, רפרנס 60).',
    'פסק חוץ שניתן במעמד צד אחד אינו נפסל אוטומטית מאכיפה. בית המשפט יבחן האם ניתנה לחייב הזדמנות סבירה לטעון טענותיו, ונטל ההוכחה לכך מוטל על החייב (סעיף 6(א)(2) לחוק אכיפת פסקי חוץ).',
    '["חוק אכיפת פסקי-חוץ, תשי\"ח-1958, סעיף 6(א)(2)", "ת\"א (שלום י-ם) 9490-04-14 רוברט מ. גרינברגר נ'' צבי דוד פרידלנד (5.5.2016)", "ת\"א (שלום הרצ'') 42972-11-16 רפאל אוחנה נ'' אלכסנדר בנימין זלמנוביץ (11.12.2017)", "ה\"פ (שלום ת\"א) 23261-06-13 Silver, Garvett & Henkel P.A. - A Florida Professional Service Corporation נ'' מטרופוליס יזום השקעות ונכסים (1993) בע\"מ (16.9.2014)", "ת\"א (שלום אשד'') 4471094 WYNN LAS VEGAS LLC נ'' אודי סעדה (21.5.2018)", "ת\"א (שלום עכו) 38673-07-18 אשרף עראף נ'' עאדל בשארה (26.10.2023)"]'::jsonb
  );

  INSERT INTO public.angle_questions (
    id, source_question_id, angle_letter, angle_title, display_order, question_text,
    legal_topic_analysis, full_explanation, common_pitfall, concepts_and_skills,
    quick_thinking_360, summary_for_memory, references_list
  ) VALUES (
    v_ang_d, v_sq_id, 'ד', 'סמכות עניינית בתביעה לסעד הצהרתי במקרקעין', 4, 'ראובן הגיש תביעה לבית משפט השלום למתן צו הצהרתי לפיו הוא זכאי להירשם כבעל זכויות בעלות במקרקעין, ולחילופין, סעד כספי בסך 1,500,000 ש"ח. מהי הסמכות העניינית לדון בתביעה זו?',
    'שאלה זו עוסקת בסמכות העניינית של בתי המשפט בתביעות הנוגעות למקרקעין, ובפרט בתביעות לסעד הצהרתי בדבר זכויות קנייניות. היא מדגישה את מבחן הסעד כקובע את הסמכות, ואת ההבחנה בין סעדים קנייניים במקרקעין (מחוזי) לבין סעדים הנוגעים לחזקה או שימוש (שלום), וכן את הכלל לפיו הסמכות נקבעת לפי הסעד העיקרי.',
    'הסמכות העניינית נקבעת לפי מבחן הסעד המבוקש בכתב התביעה (ת"א (שלום ת"א) 5759636 סי.טי.אי גומובייל בע"מ, רפרנס 40, 41; ת"א (שלום י-ם) 8236650 דיויד יהונתן, רפרנס 58). סעיף 51(א)(3) לחוק בתי המשפט [נוסח משולב], תשמ"ד-1984, מקנה לבית משפט השלום סמכות לדון בתביעות בדבר חזקה או שימוש במקרקעין או בדבר חלוקתם או חלוקת השימוש בהם. אולם, תביעות אחרות הנוגעות למקרקעין, ובכלל זה תביעות לזכויות קנייניות כגון בעלות או אכיפת התחייבות להעברת בעלות, נתונות לסמכותו השיורית של בית המשפט המחוזי (ת"א (שלום ת"א) 17583-03-25 ענב, רפרנס 34, 35; ת"א (שלום צפת) 4497-01-22 מדינת ישראל, רפרנס 61, 62; ת"א (שלום ת"א) 4645-05-17 ארז כהן החזקות בע"מ, רפרנס 67). במקרה שלפנינו, הסעד העיקרי המבוקש הוא צו הצהרתי בדבר זכאות לרישום כבעל זכויות בעלות במקרקעין, שהוא סעד קנייני. גם אם נתבע סעד כספי חלופי הנמצא בסמכות בית משפט השלום, הכלל הוא שהסמכות נקבעת לפי הסעד העיקרי (ת"א (שלום ת"א) 17583-03-25 ענב, רפרנס 35; ת"א (שלום י-ם) 56363-10-20 ציטרין, רפרנס 69, 70). לפיכך, הסמכות העניינית נתונה לבית המשפט המחוזי.',
    'הסטודנט עלול לטעות ולחשוב שכל סעד הצהרתי או כל סעד כספי חלופי קובע את הסמכות, מבלי להבחין בין סעדים קנייניים במקרקעין לבין סעדים אחרים, ומבלי להבין את מבחן הסעד העיקרי.',
    '["סמכות עניינית", "מבחן הסעד", "זכויות קנייניות במקרקעין", "סעד הצהרתי", "סעיף 51 לחוק בתי המשפט", "סמכות שיורית"]'::jsonb,
    '**וריאציה 1 — תביעה לבעלות במקרקעין:** ראובן תובע להצהיר על בעלותו במקרקעין. סמכות? ← בית המשפט המחוזי (ת"א (שלום ת"א) 17583-03-25 ענב, רפרנס 34, 35). **וריאציה 2 — תביעה לחזקה במקרקעין:** ראובן תובע להחזיר לו חזקה במקרקעין. סמכות? ← בית משפט השלום (סעיף 51(א)(3) לחוק בתי המשפט). **וריאציה 3 — תביעה לזכות אובליגטורית במקרקעין:** ראובן תובע לאכיפת הסכם אופציה במקרקעין, ללא סעד קנייני ישיר. סמכות? ← בית משפט השלום, אם שווי הזכות אינו עולה על 2.5 מיליון ש"ח (ת"א (שלום ת"א) 4645-05-17 ארז כהן החזקות בע"מ, רפרנס 67).',
    'הסמכות העניינית בתביעה לסעד הצהרתי בדבר זכויות בעלות במקרקעין נתונה לבית המשפט המחוזי, שכן מדובר בסעד קנייני במקרקעין שאינו חזקה או שימוש, וזאת גם אם קיים סעד כספי חלופי בסמכות השלום (סעיף 51(א)(3) לחוק בתי המשפט).',
    '["חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 51(א)(2)", "חוק בתי המשפט [נוסח משולב], תשמ\"ד-1984, סעיף 51(א)(3)", "ת\"א (שלום ת\"א) 17583-03-25 מטילדה ענב נ'' ויקטור חלילי (29.7.2025)", "ת\"א (שלום ת\"א) 5759636 סי.טי.אי גומובייל בע\"מ נ'' עודד קטקו (12.4.2022)", "ת\"א (שלום צפת) 4497-01-22 מדינת ישראל - משרד הבינוי והשיכון נ'' שרה דהן (5.7.2022)", "ת\"א (שלום טב'') 1437-05-21 שביב חלאק נ'' זוהייר חלאק (המנוח) (30.5.2022)", "ת\"א (שלום רח'') 39880-11-21 רשות מקרקעי ישראל נ'' ליהי קלקודה (4.11.2025)", "ת\"א (שלום כ\"ס) 46802-03-16 מאיר שרבט נ'' חדשות 10 ואח'' (29.3.2016)", "ת\"א (שלום ת\"א) 4645-05-17 ארז כהן החזקות בע\"מ נ'' י.צ פנלב בע\"מ (3.6.2019)", "ת\"א (שלום י-ם) 5996-05-19 ד\"ר שמואל סעדיה נ'' יהודה מלאך (16.2.2021)", "ת\"א (שלום י-ם) 29004-03-23 גדעון גלעד נ'' אורלי גולן (24.3.2024)", "ת\"א (שלום פ\"ת) 60656-07-24 ע.סלאח אלדין בניין וחשמל בע\"מ נ'' בנק מזרחי טפחות בע\"מ (30.7.2024)", "ת\"א (שלום י-ם) 56363-10-20 צבי ציטרין ו-37 אח'' נ'' הקרן לגאולת קרקע תכנון ופיתוח ישובים בע\"מ (6.6.2022)", "ת\"א (שלום חי'') 8236650 דיויד יהונתן נ'' משרד החקלאות - היועץ המשפטי (7.3.2025)", "ת\"א (מחוזי ת\"א) 29525-06-17 מרים ציון נ'' עיריית תל אביב יפו (28.3.2018)"]'::jsonb
  );

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'א', 'לא, חוק אכיפת פסקי חוץ מתייחס רק ל"פסק דין" סופי, ולא להחלטות ביניים.', false, 'בחירה זו שגויה. הפסיקה קבעה פרשנות מרחיבה למונח "פסק דין" בחוק אכיפת פסקי חוץ, הכוללת גם החלטות ביניים, ובלבד שהן אינן ניתנות עוד לערעור.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ב', 'כן, המונח "פסק דין" בחוק אכיפת פסקי חוץ כולל גם החלטות ביניים, ובלבד שהן אינן ניתנות עוד לערעור.', true, 'בחירה זו נכונה. הפסיקה קבעה כי הפרשנות הראויה למונח "פסק דין" בסעיף 1 לחוק אכיפת פסקי חוץ היא מרחיבה, וכוללת כל החלטה של בית משפט זר, ובלבד שהיא עומדת בתנאי סעיף 3(2) לחוק, קרי אינה ניתנת עוד לערעור (ת"א (שלום ת"א) 56751-09-11 ריש, רפרנס 1, 2, 3).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ג', 'כן, אך רק אם קיים הסכם הדדיות ספציפי בין ישראל לאיטליה המתייחס לאכיפת החלטות ביניים.', false, 'בחירה זו שגויה. אף שהדדיות היא תנאי כללי לאכיפה, ההגדרה של "פסק דין" אינה תלויה בהסכם ספציפי להחלטות ביניים, אלא בפרשנות החוק הפנימי.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_a, 'ד', 'לא, אלא אם כן ההחלטה ניתנה בעניין מזונות, שאז קיים חריג בחוק.', false, 'בחירה זו שגויה. אכן קיים חריג בענייני מזונות (סעיף 8 לחוק), אך הוא אינו שולל את האפשרות לאכוף החלטות ביניים אחרות שאינן ניתנות לערעור.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'א', 'הנטל להוכיח את התנאים לאכיפה מוטל על המבקשת, והנטל להוכיח את טענת המרמה מוטל על הנתבע.', true, 'בחירה זו נכונה. הנטל להוכיח את התקיימות התנאים המצטברים שבסעיף 3 לחוק אכיפת פסקי חוץ מוטל על מבקש האכיפה. הנטל להוכיח את קיומה של אחת ההגנות שבסעיף 6 לחוק, כגון מרמה, מוטל על המתנגד לאכיפה (ת"א (שלום הרצ'') 42972-11-16 אוחנה, רפרנס 5, 6, 7).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ב', 'הנטל להוכיח את התנאים לאכיפה ואת טענת המרמה מוטל על המבקשת.', false, 'בחירה זו שגויה. הנטל להוכחת טענת מרמה, שהיא הגנה מפני אכיפה, מוטל על המתנגד לאכיפה, ולא על מבקש האכיפה.', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ג', 'הנטל להוכיח את התנאים לאכיפה ואת טענת המרמה מוטל על הנתבע.', false, 'בחירה זו שגויה. הנטל להוכחת התנאים לאכיפה מוטל על מבקש האכיפה, ולא על המתנגד.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_b, 'ד', 'נטל ההוכחה מתחלק באופן שווה בין הצדדים, ובית המשפט יכריע לפי מאזן ההסתברויות.', false, 'בחירה זו שגויה. אף שמאזן ההסתברויות הוא מבחן ההוכחה, חלוקת הנטל בין הצדדים קבועה באופן ברור בחוק ובפסיקה.', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'א', 'העובדה שפסק הדין ניתן במעמד צד אחד מהווה כשלעצמה הגנה מפני אכיפה, ובית המשפט ידחה את הבקשה.', false, 'בחירה זו שגויה. הפסיקה קבעה כי עצם העובדה שפסק הדין ניתן במעמד צד אחד אינה מהווה כשלעצמה הגנה, אלא יש לבחון אם ניתנה לחייב הזדמנות סבירה להתגונן (ת"א (שלום י-ם) 9490-04-14 גרינברגר, רפרנס 9, 10).', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ב', 'בית המשפט יבחן האם ניתנה לחייב הזדמנות סבירה לטעון טענותיו ולהביא ראיותיו, ונטל ההוכחה לכך מוטל על החייב.', true, 'בחירה זו נכונה. סעיף 6(א)(2) לחוק אכיפת פסקי חוץ קובע הגנה מפני אכיפה אם האפשרות שניתנה לנתבע לטעון טענותיו לא הייתה סבירה. נטל ההוכחה לכך מוטל על החייב, והמבחן הוא אובייקטיבי – האם פעולת בית המשפט הזר חרגה מכללי הצדק הטבעי (ת"א (שלום י-ם) 9490-04-14 גרינברגר, רפרנס 9, 10; ת"א (שלום ת"א) 5708562 צסרסקי, רפרנס 12, 13).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ג', 'בית המשפט ידחה את הבקשה רק אם החייב יוכיח כי פסק הדין הושג במרמה.', false, 'בחירה זו שגויה. מרמה היא הגנה נפרדת (סעיף 6(א)(1) לחוק). אי מתן הזדמנות סבירה להתגונן היא הגנה עצמאית, גם ללא מרמה.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_c, 'ד', 'בית המשפט לא ידון בטענות החייב, שכן הוא אינו משמש ערכאת ערעור על פסק החוץ.', false, 'בחירה זו שגויה. אף שבית המשפט אינו ערכאת ערעור, הוא כן בוחן את קיומן של הגנות סעיף 6, לרבות אי מתן הזדמנות סבירה להתגונן, שהיא עניין פרוצדורלי ולא מהותי (ת"א (שלום הרצ'') 42972-11-16 אוחנה, רפרנס 5, 6).', 4);

  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'א', 'בית משפט השלום, שכן הסעד הכספי החלופי מצוי בסמכותו.', false, 'בחירה זו שגויה. כאשר הסעד העיקרי הוא קנייני במקרקעין, הסמכות נתונה לבית המשפט המחוזי, גם אם הסעד החלופי הוא כספי ובסמכות השלום.', 1);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ב', 'בית המשפט המחוזי, שכן הסעד העיקרי הוא קנייני במקרקעין, והוא קובע את הסמכות.', true, 'בחירה זו נכונה. תביעה למתן צו הצהרתי בדבר זכויות בעלות במקרקעין היא תביעה קניינית במקרקעין, שאינה חזקה או שימוש, ולכן הסמכות העניינית לדון בה נתונה לבית המשפט המחוזי מכוח סמכותו השיורית (ת"א (שלום ת"א) 17583-03-25 ענב, רפרנס 34, 35).', 2);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ג', 'בית משפט השלום, שכן מדובר בסעד הצהרתי שאינו ניתן לאומדן כספי.', false, 'בחירה זו שגויה. סעד הצהרתי יכול להיות בסמכות השלום אם הוא ניתן לאומדן כספי, אך במקרה זה מדובר בסעד קנייני במקרקעין, שאינו בסמכות השלום.', 3);
  INSERT INTO public.angle_choices (angle_question_id, letter, choice_text, is_correct, distractor_analysis, display_order) VALUES (v_ang_d, 'ד', 'בית המשפט המחוזי, שכן כל תביעה לסעד הצהרתי נתונה לסמכותו השיורית.', false, 'בחירה זו שגויה. סעד הצהרתי כשלעצמו אינו קובע את הסמכות. יש לבחון את מהות הסעד ההצהרתי. סעד הצהרתי שניתן לאומדן כספי יכול להיות בסמכות השלום (ת"א (שלום ת"א) 36489-05-21 סי.טי.אי גומובייל בע"מ, רפרנס 40, 41).', 4);

END $$;
